pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item (1..100 stream => gap < ~10 is nearly dead)
    // are heavily penalized, non-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Gaps in [10, 25) are "awkward" — usable only by tiny items.
    if post_residual >= 10 && post_residual < 25 {
        score += 8.0 * (25.0 - post_residual as f64) / 15.0;
    }

    // Perfect or near-perfect fills are strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward this bin; if next item cannot fit anywhere else well, keep gap usable.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item won't fit here anyway; slight penalty for wasting a big bin
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a tight
    // fit exists; encourage opening new bins early when stream is young.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    // Prefer bins with residual below the mean (consolidating emptier space
    // into fewer bins), i.e. favor filling the fullest bins.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate handling: an empty bin is attractive when the item is
    // large (would leave awkward gaps elsewhere) or when few bins fit the item.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let mut new_bin_score = 15.0
            - 55.0 * large_item
            - 20.0 * (fitting_bins_count as f64).recip().min(1.0)
            + 5.0 * progress;
        // If the item would leave a dead gap in an existing bin, new bin is better.
        if post_residual < 10 && post_residual > 0 {
            new_bin_score -= 20.0;
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item (<=10) are wasted.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open-bin pressure: penalize spreading across many bins mildly, so tight fits
    // into existing bins beat opening new ones.
    score += open_bins_count as f64 * 0.5;

    // Tightness coupling: reward filling bins that already have low residual.
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.1;

    // New-bin candidate handling: an empty bin gets a moderate default score so it
    // only wins when open-bin fits are genuinely poor (large dead space).
    if bin_residual == bin_capacity {
        score = 45.0 + open_bins_count as f64 * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    if post_residual == 0 { score -= 1000.0 ; }
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 700.0 ;
        } else if next_item_size <= post_residual {
            let chain_waste = post_residual - next_item_size ;
            if chain_waste <= 10 {
                score -= 260.0 - chain_waste as f64 * 1.4 ;
            } else {
                score -= 200.0 - chain_waste as f64 * 0.9 ;
            }
        } else {
            let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64 ;
            score += gap * 0.35 ;
        }
    }
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64) ;
    // stronger dead-space pressure as bins approach fullness
    if fill_ratio > 0.7 && post_residual > 0 {
        score += post_residual as f64 * (0.3 + fill_ratio * 0.25) ;
    }
    // penalize residuals too small to hold any plausible future item
    if post_residual > 0 && post_residual < 18 {
        score += (18 - post_residual) as f64 * 1.8 ;
    }
    // dead-space lookahead: residual cannot hold next item
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.7 ;
    }
    let diff = bin_residual as f64 - mean_residual ;
    score += diff * 0.18 ;
    if fitting_bins_count == 1 && bin_residual != bin_capacity { score -= 130.0 ; }
    let is_new = bin_residual == bin_capacity ;
    if is_new && open_bins_count > 0 {
        let slack = post_residual as f64 / item_size.max(1) as f64 ;
        if item_size <= bin_capacity / 5 {
            score += 200.0 ;
        } else if slack > 1.0 {
            // very loose fit elsewhere: fresh bin is cheap
            score -= 110.0 + (slack - 1.0).min(2.5) * 45.0 ;
        } else {
            score += 70.0 * (1.0 - slack).max(0.0) ;
        }
    }
    if is_new && item_size > bin_capacity / 2 {
        score -= 70.0 ;
    }
    // early stream: consolidate to leave room for later large items
    if step_index < total_items / 3 && !is_new && post_residual > 0 {
        score += post_residual as f64 * 0.12 ;
    }
    // late stream: tighten residual usage, avoid stranding space
    if step_index > total_items * 2 / 3 && post_residual > 0 {
        score += post_residual as f64 * 0.05 ;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits the next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item still fits, reward proportional to tightness.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + slack);
    }
    // Next item cannot follow into this bin: penalize creating dead space.
    else if next_item_size > 0 {
        let waste = next_item_size as f64 - post_residual as f64;
        score += 0.5 * waste.min(60.0);
    }

    // Penalize very small unusable residuals (dead space) harder.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Relative residual coupling: prefer bins below mean residual (tighter packing).
    score += 0.3 * (post_residual as f64 - mean_residual);

    // New-bin candidate: neutral baseline, slightly discouraged unless it beats
    // genuinely poor fits; encourage early in stream when few bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 70.0 + 40.0 * (1.0 - progress) - 5.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    if post_residual == 0 { score -= 1000.0 ; }
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 600.0 ;
        } else if next_item_size <= post_residual {
            let chain_waste = post_residual - next_item_size ;
            if chain_waste <= 12 {
                score -= 240.0 - chain_waste as f64 * 1.2 ;
            } else {
                score -= 200.0 - chain_waste as f64 * 0.8 ;
            }
        } else {
            let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64 ;
            score += gap * (0.3 + progress * 0.3) ;
        }
    }
    // two-item chain anticipation
    if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual > 0 {
        score -= 40.0 ;
        let leftover_after_next = (post_residual as i64 - 2 * next_item_size as i64).max(0) as u32 ;
        if leftover_after_next < next_item_size / 2 {
            score -= (next_item_size / 2 - leftover_after_next) as f64 * 0.8 ;
        }
    }
    // residual just above next item but below 3x: slightly reward tight reuse
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size && post_residual < next_item_size * 3 {
        score -= 15.0 + (next_item_size * 3 - post_residual) as f64 * 0.5 ;
    }
    // dead-space pressure as bins approach fullness
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64) ;
    if fill_ratio > 0.75 && post_residual > 0 {
        score += post_residual as f64 * (0.25 + fill_ratio * 0.2) ;
    }
    // unusable tiny residuals penalized, scaled by stream progress
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * (1.5 - progress * 0.9) ;
    }
    // residual too small for next item: penalize more early, less late
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6 * (1.0 + (1.0 - progress)) ;
    }
    let diff = bin_residual as f64 - mean_residual ;
    score += diff * 0.15 ;
    if fitting_bins_count == 1 && bin_residual != bin_capacity { score -= 120.0 ; }
    if bin_residual == bin_capacity && item_size <= bin_capacity / 4 && open_bins_count > 0 {
        score += 180.0 ;
    }
    if bin_residual == bin_capacity && item_size > bin_capacity / 2 {
        score -= 60.0 ;
    }
    // new-bin lookahead: opening fresh bin may pack both this and next item better
    if bin_residual == bin_capacity && next_item_size > 0 && post_residual < next_item_size {
        score -= 30.0 + progress * 20.0 ;
    }
    // late-stream: strongly prefer closing bins tight
    if progress > 0.85 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 8.0 + progress * 12.0 ;
    }
    // residual far above mean wastes space
    if post_residual > 0 && (post_residual as f64) > mean_residual * 1.5 && bin_residual != bin_capacity {
        score += 6.0 + progress * 4.0 ;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the residual so large waste is heavily penalized.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead-space penalty: leftover space too small for any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item could still fit in the post-residual, this bin
    // remains valuable; reward it. If it cannot fit, penalize slightly so we
    // prefer bins whose leftovers are useless anyway.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 6.0;
        } else {
            score += 3.0;
        }
        // Chain fit: next item exactly fills what remains.
        if next_item_size == post_residual {
            score -= 15.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large relative to capacity or no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / bin_capacity as f64;
        let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        score += 30.0;                     // base cost of a fresh bin
        score -= 20.0 * pressure;          // large items justify new bins
        score -= 5.0 * open_pressure;      // many low-residual bins -> prefer new bin
        if fitting_bins_count == 1 {
            score += 40.0;                 // never open a bin when a last-chance exists
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score += 5.0;                  // avoid wasting fresh bins on small items
        }
    }

    // Time horizon: late in the stream, consolidate more aggressively to avoid
    // leaving many nearly-empty bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (mean_residual / bin_capacity as f64).min(1.0);

    // Mild preference for filling bins below the mean residual (balance avoidance
    // of fragmentation across the open set).
    if bin_residual as f64 > mean_residual && bin_residual < bin_capacity {
        score -= 2.0;
    }

    score
}

