pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible future item (<= 10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // heavy penalty for creating unusable slivers
    }

    // Perfect fit: strongly reward zero post_residual.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Penalize small-but-not-dead gaps that likely can't fit next item.
        if next_item_size > 0 && (post_residual as f64) < (next_item_size as f64) * 0.9 {
            score += 15.0;
        }
        // Reward gaps that comfortably fit the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if existing residuals are poor fits
        // or the pool is strained.
        score += 30.0 - 0.6 * open_bins_count as f64 - 20.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 5.0; // fresh bin trivially fits lookahead
        }
    } else {
        // Mild penalty for using already-fragmented bins.
        score += 0.1 * (mean_residual - post_residual as f64).abs();
    }

    // Coupling: penalize leaving post_residual just below the mean residual,
    // indicating fragmentation spread.
    if post_residual as f64 > 0.0 && (post_residual as f64 - mean_residual).abs() < 5.0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit core: reward tight fits.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;

    // Penalize small dead space that no future item can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    } else if post_residual >= 10 {
        // Reward residuals that could still host typical items.
        score -= 2.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead: if the next item fits perfectly in the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 4.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty for wasting the gap.
            score += 3.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: discourage opening a new bin unless current fit is poor
    // or few bins are open (early stream / spreading load).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = fit_ratio < 0.5;
        let pressure = open_bins_count as f64 * item_size as f64 / bin_capacity as f64;
        if poor_fit || progress < 0.1 {
            score -= 8.0 + 4.0 * (1.0 - progress);
        } else {
            score += 10.0 + pressure;
        }
    }

    // Global state coupling: prefer filling bins above the mean residual
    // (i.e., bins with less space than average) to consolidate load.
    let residual_gap = mean_residual - bin_residual as f64;
    score += 1.5 * residual_gap;

    // Time horizon: as the stream nears its end, tighten packing harder.
    let horizon = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * horizon * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth polynomial emphasis
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Non-linear coupling of post-residual with stream progress:
    // late in the stream, tight fits matter more (penalize large post_residual)
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Reward using up space close to capacity: smooth quadratic bonus on fill ratio
    let fill = item_size as f64 / cap;
    score -= 40.0 * fill * fill;

    // Penalize bins that leave post_residual that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            // dead space relative to lookahead: smooth quadratic penalty
            let gap = (nxt - pr) / cap;
            score += 60.0 * gap * gap * cap;
        } else {
            // reward leaving room exactly for the next item (smooth bell)
            let diff = (pr - nxt) / cap;
            score -= 25.0 * (-diff * diff * 20.0).exp();
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Slight preference for bins with residuals near the mean (smooth coupling)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Late-stream: mildly discourage opening new bins (favor consolidation)
    score += 10.0 * progress * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Dead-space avoidance: slivers below the smallest plausible item are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    if post_residual == 0 {
        score -= 40.0;
    } else if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            // Reward gaps that fit the lookahead item, scaled by tightness.
            let slack = pr - nxt;
            score -= 8.0 * (1.0 - slack / cap);
            if slack < nxt * 0.5 {
                score -= 1.5;
            }
        } else {
            // Quadratic penalty for gaps that cannot hold the next item.
            let gap = nxt - pr;
            score += 10.0 * (gap / cap) * (gap / cap);
            if gap > cap * 0.2 {
                score += 2.0 * (gap / cap);
            }
        }
    }

    // Last-chance bin: strongly prefer the only fitting bin over a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when the open pool is strained
        // or late in the stream with poor residual spread.
        score += 30.0 - 0.6 * open_bins_count as f64 - 20.0 * progress;
        if next_item_size > 0 && (next_item_size as f64) <= cap {
            score += 5.0;
        }
        // Extra penalty early on: opening bins early wastes capacity.
        if open_bins_count > 2 && progress < 0.5 {
            score += 10.0;
        }
    } else {
        // Mild penalty for bins whose residual deviates from the pool mean.
        score += 0.1 * (mean_residual - pr).abs();
    }

    // Fragmentation coupling: penalize residuals hovering near the mean.
    if pr > 0.0 && (pr - mean_residual).abs() < 5.0 {
        score += 6.0;
    }

    // Small residual bonus: near-full bins are good compaction targets.
    if pr < cap * 0.05 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
