    if pr < 10.0 {
        score += (10.0 - pr) * 12.0;
    } else {
        score -= 6.0;
    }

    // Nonlinear waste penalty on the post-placement empty fraction.
    let waste_frac = pr / cap;
    score += waste_frac * waste_frac * 30.0;

    // Tight fits are excellent.
    if item_size > 0 {
        let fit_ratio = pr / item_size as f64;
        score -= (1.0 - fit_ratio.min(1.0)) * 20.0;
    }

