    // unusable gap; otherwise reuse open bins. Late stream slightly favors reuse.
    if bin_residual == bin_capacity {
        score = 45.0 + (step_index as f64 / total_items.max(1) as f64) * 5.0;
        // If next item is large and this item is large, a fresh bin chains well.
        if next_item_size > 0 && (next_item_size as u64 + item_size as u64) <= bin_capacity as u64 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
