    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: reward when next item matches post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 45.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item can't follow here; penalize proportionally to wasted look
            score += 18.0;
        }
    } else {
        // Last item: closing a bin is great
        score -= 20.0;
    }

    // Relative to mean residual: bins with more residual than average are
    // cheaper to fill (their space is less scarce)
    if post_residual as f64 > mean_residual {
        score -= (post_residual as f64 - mean_residual) * 0.6;
    } else {
        score += (mean_residual - post_residual as f64) * 0.6;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin offers a good (near-perfect) fit
    if bin_residual == bin_capacity {
        // default mild penalty; strong fits in open bins will beat this
        score += 15.0;
        // if next item is large, opening fresh may be good
        if next_item_size >= 60 && post_residual as f64 > mean_residual + 20.0 {
            score -= 35.0;
        }
    }

    // Late-stream pressure: consolidate as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits heavily.
    if post_residual == 0 {
