            score += 15.0;
        }

        // Relative to mean residual: prefer bins tighter than average.
        score += (mean_residual - bin_residual as f64) * 0.5;

        // Last-chance bonus: only one bin can fit this item.
        if fitting_bins_count == 1 {
            score -= 60.0;
        }

        // Prefer bins with small residual relative to item size (tight packing).
        let ratio = item_size as f64 / bin_residual as f64;
        score -= ratio * 10.0;
    }

    // Mild new-bin penalty: discourage opening a new bin when reasonable fits exist,
    // but allow it when the item is large and residuals are fragmented.
    if bin_residual == bin_capacity {
        score += 30.0 - (item_size as f64 * 0.2);
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..10)
    // are pure waste; penalize small unusable gaps super-linearly.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    } else if post_residual < 20 {
        // Medium-dead zone: still likely hard to fill.
        score += (20 - post_residual) as f64 * 2.0;
    } else {
        // Larger residual gaps are flexible: mild reward for keeping space.
        score -= 3.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 18.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > post_residual && post_residual < 10 {
        // Next item cannot use the tiny dead space: extra penalty.
        score += 12.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; encourage
    // filling existing bins, but allow a new bin when residuals are large
    // and fragmented (mean residual high means bins are mostly empty).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * progress);
    score += bin_pressure;

    // New-bin candidate logic: an empty bin has full residual; make it
    // attractive only when current bins would leave bad dead space or when
    // open-bin count is low (early stream). Otherwise make it costly.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        } else if post_residual > 20 && open_bins_count < 4 {
            score -= 5.0; // early stream: fresh bin is fine
        } else {
            score += 15.0 + mean_residual * 0.3; // prefer existing bins
        }
    }

    // Slight preference for bins whose residual is close to the mean
    // (keeps the pool of usable gaps homogeneous).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

