    score += norm_pr * progress * 20.0;
    score -= (1.0 - norm_pr).powi(2) * (1.0 - progress) * 10.0;

    // Penalty for leaving dead space that next item can't use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += (nxt - pr).powf(1.3) * (0.5 + progress);
        } else {
            score -= (pr - nxt).min(20.0) * 0.3;
        }
    }

    // Last-chance bin bonus: strongly favor filling the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Discard fragmentation relative to mean residual of open bins
    score += (pr - mean_residual).max(0.0) * 0.4 * (1.0 + progress);
    score -= (mean_residual - pr).max(0.0) * 0.2;

    // New-bin candidate: prefer opening a new bin only when fits are poor
    if bin_residual == bin_capacity {
        score += 5.0 + 25.0 * (1.0 - norm_pr) - 10.0 * progress;
    } else {
        // Favor bins whose fill fraction is high, smoothly
        score -= (1.0 - bin_residual as f64 / cap).powi(3) * 8.0;
    }

    // Mild congestion term: spread load when many bins open
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
