    if post_residual == 0 {
        score -= 12.0;
    }

    // Mild open-bin pressure to avoid needless spreading.
    score += open_bins_count as f64 * 0.2;

    // Mean-residual coupling: bins far below the mean fragment the fleet.
    score += (mean_residual - pr).abs() * 0.1;

