    score += 0.5 * open_bins_count as f64 * (1.0 - fit_norm);

    // New-bin candidate: make empty bin mildly attractive only when current bin leaves large waste
    if bin_residual == bin_capacity {
        score = pr + 10.0 - 4.0 * (1.0 - progress) * (1.0 - tightness);
    }

