    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward; if it cannot fit at all, penalize mildly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * fill;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral baseline; open a new bin only when mean
    // residual across open bins is already fragmented.
    if bin_residual == bin_capacity {
        let base = bin_capacity as f64;
        score = base * 0.5 + (open_bins_count as f64) * 2.0
            - (mean_residual / base) * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 5.0;
        }
    }

    // Mild stream-progress adaptation: later in the stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 20.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio;

    // Last chance: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if next item fits in the post residual, reward leaving that space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize leaving a gap just below the next item size (unusable for lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 25.0 + 5.0 * open_bins_count as f64;
    } else {
        // Slight bonus for using already-open bins to consolidate.
        score -= 2.0 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins deviating from mean toward tight fits.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Progression: later in stream, be more conservative about waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 15.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if post_residual as f64 >= next {
            // Next item fits perfectly or nearly: strong reward.
            score -= 45.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item cannot fit here: penalize proportional to wasted lookahead.
            score += 8.0 * (next - post_residual as f64).min(50.0) / 10.0;
        }
    }

    // Compare against mean residual of open bins: prefer bins whose resulting
    // residual is below the mean (tightening fragmented bins).
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.35 * (pr - mean_residual);
    }

    // Last chance: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current bin is heavily fragmented
    // (large residual) or there are many open bins with low utility.
    if bin_residual == bin_capacity {
        let new_bin_base = bin_capacity as f64 * 0.55;
        let fragmentation_pressure = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        score = new_bin_base + 30.0 * fragmentation_pressure;
        // Late in stream, prefer packing into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    // Mild penalty for creating small unusable dead space (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Dead-space penalty: small residuals are hard to reuse later.
    if post_residual > 0 {
        let frac = post / cap;
        if frac < 0.10 {
            score += (0.10 - frac) * 300.0; // severe penalty for tiny slivers
        } else {
            score += frac * 20.0; // mild preference for tighter fits
        }
    } else {
        score -= 40.0; // perfect closure reward
    }

    // Lookahead coupling: bonus if next item fits in post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0 + 0.15 * (post_residual - next_item_size) as f64;
    } else if next_item_size > post_residual {
        // residual too small for the next item: mild penalty scaled by tightness
        score += 8.0 * (1.0 - post / cap);
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Global state: when many bins are open, discourage spreading; prefer packing into
    // bins below mean residual (consolidation).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.10 * dev;

    // Time horizon: early in the stream, opening bins is cheap; late, consolidation matters.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= t * 15.0;

    // New empty bin candidate: penalize unless it's early or the fit is very poor elsewhere.
    if bin_residual == bin_capacity {
        let base = 45.0 - 40.0 * t;
        // penalize more when good alternatives exist
        score += base + 0.3 * (open_bins_count as f64);
        // if the item is large relative to capacity, a fresh bin is more acceptable
        score -= 0.2 * (item_size as f64);
    }

    // Mild preference for bins that will end up in a "nice" reusable residual (e.g., ~half).
    let half = cap * 0.5;
    score -= 0.05 * (1.0 - ((post - half).abs() / half));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling: residual squared penalizes wasted space,
    // weighted by stream progress (late in stream, dead space matters more).
    let poly = norm_pr * norm_pr * (0.5 + progress) + norm_pr * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits (small post residual) with smooth exponential coupling.
    let tightness = (1.0 - norm_pr).powi(3);
    score -= 25.0 * tightness * (0.6 + 0.4 * progress);

    // Last-chance bonus: only bin that fits -> strong smooth discount.
    if fitting_bins_count == 1 {
        score -= 18.0 + 12.0 * progress;
    }

    // Penalize opening new bins when open bins are plentiful and residual near mean.
    let mean_gap = (mean_residual - pr).abs() / cap;
    score += 6.0 * mean_gap * mean_gap * (open_bins_count as f64).sqrt();

    // Lookahead: if next item fits exactly in post residual, reward; if post residual
    // is awkwardly small vs next item, penalize smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 10.0 * (-8.0 * slack).exp();
        } else {
            let miss = (nxt - pr) / cap;
            score += 8.0 * miss * (1.0 - progress);
        }
    }

    // New-bin candidate: make empty bin attractive only when residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap).powi(2);
        score -= 5.0 + 20.0 * frag * (1.0 - progress);
        score += 15.0 * progress * (1.0 - frag);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into octile bands.
    // Residuals in the lowest band (<= 1/8 of capacity) are nearly perfect fits.
    let eighth = bin_capacity / 8;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    if post_residual <= eighth {
        score -= 25.0; // near-perfect packing: strongly reward
    } else if post_residual <= quarter {
        score -= 10.0;
    } else if post_residual <= half {
        score += 5.0;
    } else {
        score += 15.0; // leaving > half a bin empty is wasteful
    }

    // Dead-space penalty: post_residual too small for the smallest plausible item (1)
    // is fine, but residuals that no future item of harmonic size can use are bad.
    // Reward residuals that are exact multiples of common capacity fractions.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            if next_post <= eighth {
                score -= 12.0;
            } else if next_post > half {
                score += 8.0;
            }
        } else {
            // next item cannot use this residual: slight penalty proportional to waste
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate handling: opening a new bin wastes (capacity - item_size)
    // of potential; only attractive when item is large relative to capacity.
    if bin_residual == bin_capacity {
        let fill_fraction = item_size as f64 / bin_capacity as f64;
        // Prefer new bin for big items filling > 60%; penalize otherwise.
        if fill_fraction > 0.6 {
            score -= 20.0 * fill_fraction;
        } else {
            score += 20.0 * (1.0 - fill_fraction);
        }
    }

    // Mild pressure toward using many open bins efficiently early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64).abs() * 0.1;
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical future items are heavily penalized.
    let pr = post_residual as f64;
    if post_residual > 0 {
        // Gap smaller than the minimum useful size => dead space.
        let dead_threshold = if next_item_size > 0 { next_item_size.min(30) } else { 30 };
        if post_residual < dead_threshold {
            score += (dead_threshold - post_residual) as f64 * 8.0;
        }
        // Non-linear penalty: near-full bins with tiny scraps are worthless.
        score += 40.0 / (1.0 + pr / 10.0);
    }

    // Reward tight fits (small waste relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 12.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // Penalize if post residual can't fit the next item but is still sizable.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise a new bin must be opened.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + progress);

    // New-bin candidate: keep it moderately attractive only when current bins
    // are mostly full (high mean residual usage) or none fit well.
    if bin_residual == bin_capacity {
        let mean_tight = mean_residual / bin_capacity as f64;
        // New bin score baseline; discourage when many bins are still open.
        score = 55.0 + open_bins_count as f64 * 4.0 - mean_tight * 20.0;
        // If this is the only fitting option, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: item + next item exactly fills the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Next item still fits after this placement: strong reward.
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }
    // Next item cannot use the leftover: penalize dead space, worse when tiny.
    else if next_item_size > 0 {
        score += (100.0 - (post_residual as f64)).min(50.0) * 0.5;
    }

    // Penalize residual far below mean residual (creating unusable gap vs pool).
    if (post_residual as f64) < mean_residual {
        score += (mean_residual - post_residual as f64) * 0.6;
    } else {
        score -= (post_residual as f64 - mean_residual) * 0.2;
    }

    // Last-chance bin: reward using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: prefer it only when no open bin gives a tight fit.
    if bin_residual == bin_capacity {
        let tightness = 100 - item_size;
        score += 40.0 + (tightness as f64) * 0.3;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
    }

    // Late in stream: consolidate harder, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 25.0;
    }

    // Reward large fill ratio of the bin.
    score -= (item_size as f64 / bin_capacity as f64) * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };

    // Reward tight fits: penalize proportional waste more strongly as residual shrinks
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 12.0 * fill_ratio * fill_ratio;
    }

    // Penalize very small dead space that nothing (min size 1..100) may reuse
    if post_residual > 0 && post_residual < 15 {
        score += 18.0 * (15.0 - post_residual as f64) / 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted gap
            score += 4.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid opening a new one
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Global state: many open bins with high mean residual -> encourage consolidation
    let pressure = open_bins_count as f64 * mean_residual / bin_capacity as f64;
    score -= 5.0 * pressure.min(10.0);

    // Time horizon: early on, be willing to open bins (explore); late, consolidate tightly
    score += 15.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * progress * (item_size as f64 / bin_capacity as f64);

    // New-bin candidate handling: empty bin should only win when no good fit exists
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more so late in the stream or when other bins fit
        let mut new_bin_penalty = 30.0 + 40.0 * progress;
        if fitting_bins_count > 0 {
            new_bin_penalty += 25.0;
        }
        // If current item is small, new bin wastes capacity
        new_bin_penalty += 20.0 * (1.0 - item_size as f64 / bin_capacity as f64);
        score += new_bin_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let size_norm = item_size as f64 / cap;

    // Base: quadratic penalty on post-residual, modulated by stream progress.
    let mut score = pr * (1.0 + progress * pr_norm);

    // Smooth cubic interaction: large leftovers become costlier as stream advances.
    score += 40.0 * progress * pr_norm * pr_norm * pr_norm;

    // Reward tight fits (small post_residual) more strongly later in the stream.
    score -= 25.0 * progress * (1.0 - pr_norm) * size_norm;

    // Penalize opening new bins early; allow it when stream is far along and fit is bad.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        score += 30.0 * (1.0 - progress) - 10.0 * progress * pr_norm;
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0 * (1.0 - pr_norm);
    }

    // Lookahead coupling: keep room for the next item when it fits smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let gap = (pr_norm - nxt).abs();
        score += 12.0 * gap * (1.0 - progress);
    }

    // Mean-residual deviation term: prefer bins near the average leftover.
    score += 5.0 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by capacity fraction.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let quarter = cap / 4.0;
    let eighth = cap / 8.0;

    // Dead-space penalty grows steeply once post_residual falls below 1/8 capacity
    // (unusable sliver) — but only if it is not exactly zero.
    if post_residual > 0 && (post_residual as u64) % 100 <= 12 {
        score += 18.0;
    }
    if post > 0.0 && post < eighth {
        score += (eighth - post) * 1.5;
    }

    // Reward near-perfect fills (post_residual in the lowest harmonic band but tight).
    if post_residual <= 5 {
        score -= 25.0;
    }

    // Modulo-10 harmonic classes: residuals that are multiples of 10 pair well with
    // typical item sizes; reward them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Integer-division threshold: post_residual / 25 quartile bands.
    let band = post_residual / 25; // 0..4
    score -= match band {
        0 => 8.0,        // very tight residual: good packing
        1 => 4.0,        // can host medium items
        2 => 0.0,
        3 => 2.0,        // large residual: this bin was underfilled
        _ => -3.0,       // nearly full bin reuse is cheap
    };

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            // harmonic class of the leftover after the lookahead item
            if slack % 10 == 0 {
                score -= 10.0;
            }
            if slack <= 8 {
                score -= 7.0;
            } else if slack > 60 {
                score += 5.0; // wasteful: both items leave huge hole
            }
        } else {
            // next item won't fit here; penalize more if this bin is the last chance
            if fitting_bins_count == 1 {
                score += 10.0;
            }
        }
    }

    // Last-chance bonus: only fitting bin -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: fresh empty bin gets a moderate default score so
    // it wins only when all open bins have poor harmonic fits.
    if bin_residual == bin_capacity {
        score += 12.0 + mean_residual * 0.05;
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
    }

    // Mild consolidation pressure when many bins are open.
    score += (open_bins_count as f64) * 0.15;

    // Tie-break: prefer bins whose residual is close to the item (best-fit flavor)
    // via harmonic distance between item class and residual class.
    let item_class = item_size / 10;
    let resid_class = bin_residual / 10;
    let class_gap = (item_class as i32 - resid_class as i32).abs();
    if class_gap == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (<10, min item size) are unusable forever.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps too small for the lookahead item are semi-dead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + (next_item_size - post_residual) as f64 * 0.3;
    }

    // Reward perfect / tight fits.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= tightness * 25.0;
    }

    // Reward using bins that are already fairly full (keeps fresh bins for future items).
    let fill_before = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_before * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; with few, opening is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.6 + 0.4 * progress);
    score += pressure * 0.8;

    // Prefer bins whose residual is near the mean (balanced packing) unless it's a last chance.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate (empty bin): penalize so it's only chosen when open bins fit poorly.
    if bin_residual == bin_capacity {
        let min_open_gap = 100.0;
        score += 30.0 + open_bins_count as f64 * 3.0;
        // Early in stream, new bins are cheaper; late, avoid fragmentation.
        score += (1.0 - progress) * 10.0;
        let _ = min_open_gap;
        // If lookahead item is small, an empty bin preserves flexibility.
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary 2-step lookahead: strongly reward when the next item fits exactly
    // into the post_residual space (perfect chain match).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-item chain
        } else if next_item_size <= post_residual {
            // proportional reward for a feasible follow-up placement
            let fit_ratio = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fit_ratio;
        } else {
            // next item cannot follow here: penalize dead space that is too small
            let gap = (next_item_size - post_residual) as f64;
            if post_residual > 0 && post_residual < 15 {
                score += 25.0; // tiny unusable dead space
            } else {
                score += 5.0 * gap / 50.0;
            }
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average when a good
    // lookahead exists, looser bins otherwise.
    let tightness = (mean_residual - bin_residual as f64) / bin_capacity as f64;
    score += 30.0 * tightness;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 20.0;
        if post_residual <= 5 {
            score -= 15.0; // near-perfect fill, definitely use it
        }
    }

    // New-bin candidate handling: empty bins are only attractive early in the
    // stream or when the current bin would leave an awkward gap.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let awkward = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as u32;
        if awkward && progress > 0.15 {
            score += 35.0; // don't open new bins mid-stream for awkward fits
        } else {
            score += 10.0 * progress; // slight late-stream penalty for new bins
        }
    }

    // Encourage tight overall fits (small waste relative to item size).
    score -= 10.0 * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if the next item fits exactly in the post residual (perfect chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // Next item cannot fit here; penalize proportionally to wasted potential.
            score += 0.35 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 70.0;
    }

    // Prefer bins with residuals below the mean (consolidate small leftovers),
    // but only mildly, to avoid destroying big-space bins early.
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 18.0 * dev;

    // Time horizon: early in the stream, be conservative (favor filling existing bins
    // fully); late in the stream, allow more aggressive consolidation of small gaps.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * tightness;

    // Crowding: with many open bins, favor filling existing ones over opening new.
    let crowding = (open_bins_count as f64).ln() + 1.0;
    score += 4.0 * crowding * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        // Base penalty for opening a new bin; shrinks if current fits are all poor.
        let fit_quality = if bin_residual >= item_size { 1.0 - (post_residual as f64) / (bin_capacity as f64) } else { 0.0 };
        let _ = fit_quality;
        score += 55.0;
        // If this item would leave a big awkward gap in any existing bin, new bin is fine.
        if post_residual == 0 {
            score -= 80.0; // perfect fit into a fresh bin (item == capacity)
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 20.0; // room for the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: tight fit preferred, with non-linear (quadratic) penalty on wasted space
    let mut score = norm_pr * (1.0 + 1.5 * norm_pr);

    // Smooth coupling: waste penalty grows as stream progresses (dead space matters more late)
    score *= 1.0 + 0.8 * progress * (1.0 - norm_pr);

    // Reward bins that can also fit the next item (lookahead synergy)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 0.5 * (1.0 - (next_item_size as f64 / pr).powi(2));
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 1.2;
    }

    // Slight preference to spread load when many bins are open and mean residual is high
    score -= 0.15 * (mean_residual / cap) * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: residues divisible by common
    // item sizes (10, 20, 25, 50) are "usable" dead space, reward them. ---
    let pr = post_residual;
    if pr == 0 {
        score -= 500.0; // perfect fit is always king
    } else {
        if pr % 50 == 0 { score -= 60.0; }
        else if pr % 25 == 0 { score -= 40.0; }
        else if pr % 20 == 0 { score -= 35.0; }
        else if pr % 10 == 0 { score -= 25.0; }
        else if pr % 5 == 0 { score -= 10.0; }
        // small unusable fragments are penalized super-linearly
        if pr < 10 {
            score += (10 - pr) as f64 * 15.0;
        }
    }

    // --- Integer-division thresholds: how many "medium chunks" (size >= 20)
    // could still fit in the leftover space? ---
    let chunks = pr / 20;
    score -= chunks as f64 * 8.0;

    // --- Lookahead coupling: does the next item fit into the post residual? ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits exactly-ish: harmonic match reward
            let slack = pr - next_item_size;
            if slack == 0 {
                score -= 200.0;
            } else if slack <= 10 {
                score -= 80.0;
            } else {
                score -= 30.0;
                // reward if post-residual after the pair stays in a good class
                if slack % 10 == 0 { score -= 20.0; }
            }
        } else {
            // next item won't fit here: penalize, but less if this bin was
            // nearly full anyway (residue class of bin_residual)
            let overflow = next_item_size - pr;
            if overflow > 40 { score += 20.0; }
        }
    }

    // --- Capacity fraction logic: prefer bins whose fill fraction crosses
    // harmonic thresholds (>= 1/2, >= 3/4) with this placement. ---
    let fill = (bin_capacity - pr) as f64 / bin_capacity as f64;
    if fill >= 0.75 { score -= 45.0; }
    else if fill >= 0.5 { score -= 25.0; }
    else if fill >= 0.25 { score -= 5.0; }
    else { score += 15.0; } // leaving a mostly-empty bin untouched is bad

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0; // strongly prefer using the only fitting bin
    }
    if fitting_bins_count > 3 {
        score += 10.0; // plenty of alternatives; be picky
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: base cost plus a term that decreases as the
        // stream progresses (early on, spreading is cheaper; late, consolidate).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 120.0 - 40.0 * progress;
        // If no open bin fits well (large mean residual waste elsewhere),
        // a fresh bin is more attractive.
        if mean_residual < item_size as f64 {
            score -= 30.0;
        }
        // Never open a new bin when a perfect fit exists elsewhere is already
        // handled by the -500 reward on those bins.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // new bin can host the pair
        }
    }

    // --- Mild mean-residual alignment: prefer bins near the mean residual
    // to keep open bins balanced. ---
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Slight tie-breaker noise via deterministic coupling (no RNG).
    score += ((step_index as f64 * 0.6180339887) % 1.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

