    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to what open bins can offer (poor fit elsewhere).
    if bin_residual == bin_capacity {
        score += 80.0;
        // Large items justify a fresh bin more than small ones.
        score -= item_size as f64 * 0.5;
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
    }

    // Prefer bins with small pre-residual (tight fits) slightly.
    score += (bin_residual as f64 - item_size as f64) * 0.1;

