    if bin_residual == bin_capacity {
        let mean_r = if mean_residual.is_finite() { mean_residual } else { 0.0 };
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 55.0 * scarcity * (1.2 - 0.7 * progress);
        // if mean residual across open bins is small, opening new bin is fine
        score += 0.25 * mean_r * (1.0 - progress);
        // late in stream, prefer filling existing bins even imperfectly
        if progress > 0.7 {
