    // later in the stream, waste is penalized more strongly (quadratic ramp).
    let pr = post_residual as f64;
    let waste_weight = 1.0 + 1.5 * progress * progress;
    score += waste_weight * (pr / cap) * (pr / cap) * 20.0;

    // Reward tight fits (small post_residual) with a smooth saturating term
    let tightness = 1.0 - pr / cap;
    score -= 15.0 * tightness * tightness * tightness;

    // Exact fit bonus (smooth, near-zero residual)
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: penalize leaving residual that barely fails next item,
    // reward residual that can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr as f64) >= nxt {
            score -= 8.0 * (1.0 - (pr as f64 - nxt) / cap);
        } else {
            let gap = nxt - pr as f64;
            score += 10.0 * (gap / cap) * (gap / cap);
