    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 10.0 * progress;
    }

    // New empty bin candidate: prefer it only when it is a good split point
    if bin_residual == bin_capacity {
        // Penalize opening new bins early or when many bins are open
        score += 30.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // Reward opening a fresh bin if the item is large relative to capacity
        score -= 20.0 * (item_size as f64 / cap);
        // If no other bin fits well, opening new bin is natural
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
    }

    // Mild preference for bins with below-average residual (keeps large holes available)
    score += 5.0 * ((bin_residual as f64 - mean_residual) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
