    if pr < cap * 0.05 {
        if (item_size as f64) <= pr { score -= 3.5; } else { score -= 3.0; }
    }

    // mild pull toward mean residual to consolidate open space
    score -= 0.15 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let mut score = pr ;
    let is_new_bin = bin_residual == bin_capacity ;
    if is_new_bin {
        // penalize opening a new bin unless the item is large relative to capacity
        let frac = item_size as f64 / cap ;
        score += 6.0 + 10.0 * (1.0 - frac) ;
        if next_item_size > 0 && (pr >= next_item_size as f64) && frac > 0.7 {
            score -= 4.0 ;
        }
    }
    if next_item_size > 0 {
        let nxt = next_item_size as f64 ;
        if pr >= nxt {
            let slack = pr - nxt ;
            score -= 8.0 * (1.0 - slack / cap) ;
            if slack < nxt * 0.5 { score -= 1.5 ; }
            if slack == 0.0 { score -= 2.0 ; } // perfect two-item closure
        } else {
            let gap = nxt - pr ;
            score += 10.0 * (gap / cap) * (gap / cap) ;
            if gap > cap * 0.2 { score += 2.0 * (gap / cap) ; }
            // if many bins fit, a blocked residual is less harmful
            if fitting_bins_count > 3 { score -= 1.0 ; }
        }
    }
    if pr < cap * 0.05 { score -= 3.0 ; }
    if pr == 0.0 { score -= 4.0 ; }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let mut score = pr ;
    if next_item_size > 0 {
        let nxt = next_item_size as f64 ;
        if pr >= nxt {
            let slack = pr - nxt ;
            score -= 8.0 * (1.0 - slack / cap) ;
            if slack < nxt * 0.5 { score -= 1.5 ; }
            // reward near-perfect two-item chains even more when slack tiny
            if slack < cap * 0.02 { score -= 2.0 ; }
        } else {
            let gap = nxt - pr ;
            let gr = gap / cap ;
            score += 10.0 * gr * gr ;
            if gap > cap * 0.2 { score += 2.0 * gr ; }
            // penalize dead space that no plausible future item can use
            if gap > cap * 0.35 { score += 3.0 * (gap - cap * 0.35) / cap ; }
        }
    }
    // near-full bins: strong reward to close them out
    if pr < cap * 0.05 { score -= 3.0 ; }
    if pr < cap * 0.12 { score -= 1.0 * (1.0 - pr / (cap * 0.12)) ; }
    // when many bins can fit the item, prefer tighter fits (encourage consolidation)
    if fitting_bins_count > 4 { score += 0.5 ; }
    // brand-new empty bin: only attractive if open bins are mostly large-residual
    if bin_residual == bin_capacity {
        score += 1.5 + mean_residual * 0.5 ;
        if open_bins_count < 2 { score -= 1.0 ; }
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let mut score = pr ;
    if next_item_size > 0 {
        let nxt = next_item_size as f64 ;
        if pr >= nxt {
            let slack = pr - nxt ;
            score -= 8.0 * (1.0 - slack / cap) ;
            if slack < nxt * 0.5 { score -= 1.5 ; }
            // exact-ish closure bonus: leave nothing dead
            if slack < 2.0 { score -= 2.0 ; }
        } else {
            let gap = nxt - pr ;
            score += 10.0 * (gap / cap) * (gap / cap) ;
            if gap > cap * 0.2 { score += 2.0 * (gap / cap) ; }
        }
    }
    // scarcity pressure: when few bins can host the next item, favor bins
    // whose post-residual stays usable for it
    if fitting_bins_count <= 2 && next_item_size > 0 && pr < next_item_size as f64 {
        score += 4.0 ;
    }
    // prefer keeping mean residual low: penalize bins far above average fullness
    let mr = mean_residual ;
    if pr > mr * 1.5 { score -= 1.0 ; }
    else if pr < mr * 0.5 { score += 1.0 ; }
    // discourage opening a new bin unless open bins are nearly full
    if bin_residual == bin_capacity {
        let fill = 1.0 - pr / cap ;
        if open_bins_count > 0 && fill < 0.9 { score += 6.0 * (0.9 - fill) ; }
    }
    if pr < cap * 0.05 { score -= 3.0 ; }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let mut score = pr ;

    if next_item_size > 0 {
        let nxt = next_item_size as f64 ;
        if pr >= nxt {
            let slack = pr - nxt ;
            score -= 8.0 * (1.0 - slack / cap) ;
            if slack < nxt * 0.5 { score -= 1.5 ; }
            // reward bins whose post-residual still matches the following item's likely size
            if slack >= nxt && slack < nxt * 2.0 { score -= 1.0 ; }
        } else {
            let gap = nxt - pr ;
            score += 10.0 * (gap / cap) * (gap / cap) ;
            if gap > cap * 0.2 { score += 2.0 * (gap / cap) ; }
            // penalize dead space proportional to scarcity of alternatives
            if fitting_bins_count > 1 { score += 0.5 * (gap / cap) ; }
            else { score += 1.5 * (gap / cap) ; }
        }
    }

    if pr < cap * 0.05 { score -= 3.0 ; }

    // prefer compacting into bins with tight residuals when many bins are open
    if open_bins_count > 4 {
        let tight = 1.0 - pr / cap ;
        score -= 0.8 * tight * tight ;
    }

    // discourage opening a new bin when open bins still have usable space
    if bin_residual == bin_capacity && open_bins_count > 0 && mean_residual > item_size as f64 {
        score += 2.0 ;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr == nxt {
            score -= 250.0; // perfect 2-step closure
        } else if pr >= nxt {
            let slack = pr - nxt;
            score -= 8.0 * (1.0 - slack / cap);
            if slack < nxt * 0.5 {
                score -= 1.5;
            }
        } else {
            let gap = nxt - pr;
            score += 10.0 * (gap / cap) * (gap / cap);
            if gap > cap * 0.2 {
                score += 2.0 * (gap / cap);
            }
        }
    }

    // Penalize residual far below mean residual (unusable gap vs pool).
    if pr < mean_residual {
        score += (mean_residual - pr) * 0.6;
    } else {
        score -= (pr - mean_residual) * 0.2;
    }

    // Last-chance bin: reward using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: prefer it only when no open bin gives a tight fit.
    if bin_residual == bin_capacity {
        let tightness = 100 - item_size;
        score += 40.0 + (tightness as f64) * 0.3;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
    }

    // Late in stream: consolidate harder, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 25.0;
    }

    // Reward large fill ratio.
    score -= (item_size as f64 / cap) * 30.0;

    // Tiny residual is nearly closed space: mild reward.
    if pr < cap * 0.05 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: reward using up residual (tight fit preferred).
    score += post_residual as f64;

    // Strict dead-space penalty: residuals that are small (unusable for
    // typical items) are heavily penalized. Treat post_residual in (0, 10]
    // as dead space.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Pressure on number of open bins: with many open bins, prefer packing
    // into existing bins rather than opening new ones.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 / (1.0 + slack);
    }

    // New empty bin candidate: neutral-to-slightly-high baseline so it is
    // only chosen when all fits into open bins are poor (large dead space).
    if bin_residual == bin_capacity {
        score += 12.0 + mean_residual * 0.3;
    }

    // Mean residual coupling: if open bins are generally tight, avoid
    // wasting this bin's larger residual.
    if (bin_residual as f64) > mean_residual * 1.5 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Slight late-stream tightening: as stream progresses, prefer tighter
    // placements marginally more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.2 * progress;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let res = bin_residual as f64 ;
    let mut score = pr ;

    // Prefer bins that end up nearly full: reward small post-residual strongly.
    score -= 0.35 * (1.0 - pr / cap) * (1.0 - pr / cap) * cap * 0.1 ;

    if next_item_size > 0 {
        let nxt = next_item_size as f64 ;
        if pr >= nxt {
            let slack = pr - nxt ;
            score -= 8.0 * (1.0 - slack / cap) ;
            if slack < nxt * 0.5 { score -= 1.5 ; }
            // Two-item lookahead: bonus if bin could also host the item after next.
            if slack >= 2.0 * nxt { score -= 2.0 * (1.0 - slack / (2.0 * cap)) ; }
        } else {
            let gap = nxt - pr ;
            score += 10.0 * (gap / cap) * (gap / cap) ;
            if gap > cap * 0.2 { score += 2.0 * (gap / cap) ; }
        }
    }

    // Dead-space suppression: penalize residual chunks too small for the next item.
    if next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
        score += 1.2 * (1.0 - pr / cap) ;
    }

    // Near-empty bin reward (almost closed).
    if pr < cap * 0.05 { score -= 3.0 ; }

    // New-bin candidate: discourage opening a new bin when decent fits exist,
    // unless the item is large and open bins would waste a lot of space.
    if res == bin_residual && bin_residual == bin_capacity {
        let waste = (res - item_size as f64) / cap ;
        let pressure = if fitting_bins_count > 1 { 6.0 } else { 1.5 } ;
        score += pressure + 4.0 * waste ;
        if item_size as f64 > cap * 0.85 { score -= 4.0 ; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward perfect 2-step matches (next item exactly fills the bin).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // exact 2-item completion
        } else if post_residual > next_item_size {
            // next item fits here; reward leaving a small useful remainder
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit after this placement; penalize dead space
            score += 10.0 + 0.5 * post_residual as f64;
        }
    }

    // Prefer bins whose residual is already tight relative to the fleet mean.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make empty bins mildly unattractive unless the item
    // is huge relative to residual dynamics (encourage filling open bins first).
    if bin_residual == bin_capacity {
        score += 20.0;
        // but if item is large (>60), a fresh bin is reasonable
        if item_size > 60 {
            score -= 30.0;
        }
    }

    // Reward high fill ratio (tight packing).
    score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Late in the stream, be more aggressive about closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let mut score = pr ;
    if next_item_size > 0 {
        let nxt = next_item_size as f64 ;
        if pr >= nxt {
            let slack = pr - nxt ;
            score -= 8.0 * (1.0 - slack / cap) ;
            if slack < nxt * 0.5 { score -= 1.5 ; }
            // reward bins whose leftover after next item is small enough to stay useful
            if slack > 0.0 && slack < cap * 0.12 { score -= 2.0 * (1.0 - slack / (cap * 0.12)) ; }
        } else {
            let gap = nxt - pr ;
            score += 10.0 * (gap / cap) * (gap / cap) ;
            if gap > cap * 0.2 { score += 2.0 * (gap / cap) ; }
        }
    }
    // pressure: when many bins can fit the item, prefer tight fits more strongly
    if fitting_bins_count > 2 {
        let tight = (bin_residual as f64 - item_size as f64) / cap ;
        score += 1.2 * tight ;
    }
    // discourage leaving near-mean dead space in open bins when residual is fragmented
    if open_bins_count > 4 {
        let mr = mean_residual.max(1.0) ;
        let dev = (bin_residual as f64 - mr).abs() / cap ;
        if dev < 0.03 { score += 1.0 ; }
    }
    if pr < cap * 0.05 { score -= 3.0 ; }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual so small leftovers dominate.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Last-chance bin: strongly prefer using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity or existing bins are quite full already.
    if bin_residual == bin_capacity {
        let fill_ratio = mean_residual / (bin_capacity as f64);
        let item_ratio = item_size as f64 / (bin_capacity as f64);
        let mut penalty = 25.0;
        // If the item is big, a fresh bin is more acceptable.
        penalty -= item_ratio * 20.0;
        // If open bins are nearly full on average, new bin is fine.
        penalty -= fill_ratio * 15.0;
        // Early in the stream, prefer consolidating into open bins.
        let t = step_index as f64 / (total_items.max(1) as f64);
        penalty += (1.0 - t) * 10.0;
        // If the next item could pair with the leftover of a fresh bin, soften.
        if next_item_size > 0 && next_item_size <= post_residual {
            penalty -= 8.0;
        }
        score += penalty;
    }

    // Lookahead coupling: penalize leaving a residual that only the next item
    // exactly fits but blocks nothing else — reward creating a usable slot.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // A residual that can host the next item is valuable.
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Residual too small for the next item: dead-space penalty grows
            // the smaller the residual is relative to the next item.
            let gap = (next_item_size - post_residual) as f64;
            score += 3.0 * gap / (bin_capacity as f64);
        }
    }

    // Global congestion: many open bins with large mean residual -> prefer
    // packing into existing space to avoid bin proliferation.
    if open_bins_count > 2 {
        let congestion = (open_bins_count as f64).ln() * (mean_residual / (bin_capacity as f64));
        if bin_residual < bin_capacity {
            score -= congestion * 5.0;
        }
    }

    // Mild time-horizon scaling: late in the stream, waste matters more.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * t;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            score -= 8.0 * (1.0 - slack / cap);
            if slack < nxt * 0.5 {
                score -= 1.5;
            }
            // bonus if this bin can also absorb the item after next (chain lookahead)
            if slack >= nxt * 2.0 {
                score -= 2.0 * (slack / cap);
            }
        } else {
            let gap = nxt - pr;
            score += 10.0 * (gap / cap) * (gap / cap);
            if gap > cap * 0.2 {
                score += 2.0 * (gap / cap);
            }
            // penalize dead space that next item cannot use and is far below mean residual
            if gap > mean_residual.max(1.0) * 1.5 {
                score += 1.0;
            }
        }
    }

    // near-full bins: strong reward to close them out
    if pr < cap * 0.05 {
        score -= 3.0;
    } else if pr < cap * 0.12 {
        score -= 1.5;
    }

    // scarcity pressure: when few bins fit the item, prefer the tightest usable fit
    if fitting_bins_count > 0 && fitting_bins_count <= 2 && bin_residual >= item_size {
        score -= 1.0 * (1.0 - (bin_residual as f64) / cap);
    }

    // discourage opening a new bin when open bins are still loosely filled
    if bin_residual == bin_capacity && open_bins_count > 0 && mean_residual > cap * 0.35 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = post / cap; // normalized post residual
    let mut score = post;

    // Smooth polynomial coupling: dead-space penalty grows non-linearly with progress
    let poly = x * x * (1.0 - x) * (1.0 - x) + x * x * x;
    score += 40.0 * poly * (0.5 + progress);

    // Reward tight fits, more so late in the stream
    score -= 30.0 * (1.0 - x) * (1.0 - x) * (0.3 + 0.7 * progress);

    // Penalize leaving residuals that can't fit the lookahead item
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).min(cap)) * (0.4 + 0.6 * progress);
    } else if next_item_size > 0 {
        // reward leaving space exactly usable by the next item
        let gap = (post_residual - next_item_size) as f64 / cap;
        score -= 8.0 * (1.0 - gap) * (1.0 - gap);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: mildly discourage unless stream is early or post residual is valuable
    if bin_residual == bin_capacity {
        let scarcity = (fitting_bins_count as f64).recip();
        score += 20.0 - 25.0 * progress - 10.0 * scarcity * (1.0 - progress);
    }

    // Coupling with mean residual: prefer bins below the mean residual (filling fuller bins)
    score += 5.0 * ((mean_residual - post) / cap).clamp(-1.0, 1.0);

    // Mild penalty for proliferating open bins late in stream
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let mut score = pr ;
    if next_item_size > 0 {
        let nxt = next_item_size as f64 ;
        if pr >= nxt {
            let slack = pr - nxt ;
            score -= 8.0 * (1.0 - slack / cap) ;
            if slack < nxt * 0.5 { score -= 1.5 ; }
            // exact-ish completion: bin closes fully after next item
            if slack == 0.0 { score -= 4.0 ; }
        } else {
            let gap = nxt - pr ;
            score += 10.0 * (gap / cap) * (gap / cap) ;
            if gap > cap * 0.2 { score += 2.0 * (gap / cap) ; }
            // penalize dead space relative to mean residual: bins far below mean
            // residual are wasteful sinks when the next item cannot join them
            if pr < mean_residual * 0.6 { score += 1.0 ; }
        }
    }
    // near-closed bins get priority to be emptied out of the open set
    if pr < cap * 0.05 { score -= 3.0 ; }
    // when many bins can fit the item, prefer tighter fits (avoid wasting
    // the choice); when only one bin fits, keep it attractive
    if fitting_bins_count > 2 { score += 0.5 ; }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that land in "useful" classes
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: near-zero post residual (tight fit) -> strong reward
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Class B: post_residual divisible by small harmonic steps (5,10) -> reusable space
    if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 4.0;
    }

    // Class C: dead-space penalty: residual in awkward band (1..10) after a large item
    if post_residual < 10 && post_residual > 0 {
        score += 6.0;
    }

    // Lookahead coupling: harmonic relation between post_residual and next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size <= post_residual {
            // next item fits: reward if it fills nicely (post_residual - next small)
            let chain = (post_residual - next_item_size) as f64;
            score -= 10.0 + 0.3 * nx;
            if chain <= 10 { score -= 12.0; }
            if chain % 10 == 0 && chain > 0 { score -= 5.0; }
        } else {
            // next item won't fit here: mild penalty proportional to overflow gap
            score += 0.15 * (nx - pr).min(40.0);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening fresh bins unless current residual is truly bad
    if bin_residual == bin_capacity {
        score = cap * 0.75 + 0.2 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative, must open
        } else if pr <= 15 || pr == 0 {
            // an open bin would become near-perfectly packed; prefer it
            score += 10.0;
        }
    }

    // Fraction-of-capacity thresholds: prefer bins whose post residual is a small fraction
    let frac = pr / cap;
    if frac < 0.1 { score -= 5.0; }
    else if frac > 0.6 { score += 4.0; }

    // Mean-residual coupling: if this bin is well below mean residual, it's a good "filler"
    if (mean_residual - pr) > 20.0 {
        score -= 3.0;
    }

    // Stream progression: late in stream, tighten packing more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            score -= 8.0 * (1.0 - slack / cap);
            if slack < nxt * 0.5 { score -= 1.5; }
            // bonus when the remaining slack after next item is very small (near-perfect chain)
            if slack < cap * 0.03 { score -= 1.0; }
        } else {
            let gap = nxt - pr;
            score += 10.0 * (gap / cap) * (gap / cap);
            if gap > cap * 0.2 { score += 2.0 * (gap / cap); }
            // penalize bins that become dead space: residual too small for average item
            if pr < mean_residual * 0.6 && pr > 0.0 { score += 2.5; }
        }
    }

    // discourage opening new bins when several bins already fit well
    if bin_residual == bin_capacity {
        score += 6.0 + (fitting_bins_count as f64) * 1.5;
    } else if fitting_bins_count <= 1 {
        score -= 0.5; // reward keeping the single viable fit alive
    }

    // slight preference for closing nearly-full bins late in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if pr < cap * 0.05 { score -= 3.0 + 2.0 * progress; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for the smallest plausible item (1..100 unknown,
    // so treat gaps < 10 as near-dead, gaps < next_item_size as dead for the known follower).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead: if the follower fits the resulting gap, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
