    // Last-chance bin pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, prefer packing into existing ones
    // (penalize the empty new-bin candidate relatively).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // New-bin candidate: penalize opening a fresh bin unless current residuals are tight.
    if bin_residual == bin_capacity {
        score += 10.0 + mean_residual * 0.5;
    }

    // Slight preference for bins tighter than average (best-fit style).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
