            // Perfect 2-step match: exact fill.
            score -= 220.0;
        } else if pr >= nxt {
            let slack = pr - nxt;
            // Reward small leftover after next item fits.
            score -= 8.0 * (1.0 - slack / cap);
            if slack < nxt * 0.5 {
                score -= 2.0;
            }
        } else {
            // Next item cannot use leftover: penalize gap quadratically.
            let gap = nxt - pr;
            score += 10.0 * (gap / cap) * (gap / cap);
            if gap > cap * 0.2 {
                score += 2.0 * (gap / cap);
            }
        }
    }

    // Penalize residual far below mean residual (unusable gap vs pool).
    if pr < mean_residual {
        score += (mean_residual - pr) * 0.6;
    } else {
        score -= (pr - mean_residual) * 0.2;
    }

    // Last-chance bin: reward using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: prefer only when no open bin gives a tight fit.
    if bin_residual == bin_capacity {
        let tightness = 100 - item_size;
        score += 40.0 + (tightness as f64) * 0.3;
        if next_item_size > 0 && pr >= next_item_size as f64 {
            score -= 30.0;
        }
        // Late stream: opening new bins is more wasteful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Late in stream: consolidate harder, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 25.0;
    }

    // Reward large fill ratio.
    score -= (item_size as f64 / cap) * 30.0;

    // Nearly-perfect fill bonus.
    if pr < cap * 0.05 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quality via integer division thresholds
    let pr = post_residual;
    let class = pr / 10; // 0..10 harmonic classes
    // Penalize mid-class dead space more than extreme classes
    score += match class {
        0 => -6.0,               // near-perfect fit
        1 => -2.0,
        2 => 1.0,
        3 => 3.0,
        4 => 4.0,
        5 => 4.5,                // half-full leftover: worst harmonic class
        6 => 4.0,
        7 => 3.0,
        8 => 2.0,
        9 => 0.5,
        _ => -3.0,               // near-empty bin, still reusable
    };

    // Modulo coupling: residuals divisible by common item sizes are more reusable
    for m in [10u32, 20, 25, 50] {
        if pr >= m && pr % m == 0 {
            score -= 1.5;
        }
    }

    // Lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 8.0;
        } else if next_item_size <= pr {
            let nxt_class = (pr - next_item_size) / 10;
            score -= 3.0 - 0.3 * nxt_class as f64;
        } else {
            score += 1.0; // next item won't fit here: slight penalty
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate: only attractive when existing bins are crowded
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap;
        score += 12.0 * (1.0 - crowding);
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        if open_bins_count as f64 * cap > (step_index as f64 + 1.0) * item_size as f64 * 1.5 {
            score += 4.0;
        }
    }

    // Progress-driven tightness: late in stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.25 * progress;

    // Deviation from mean residual: prefer bins tighter than average
    score += 0.3 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
