    if post_residual >= 1 && post_residual <= 10 {
        score += 40.0; // heavy penalty for unusable sliver
    } else if post_residual == 0 {
        score -= 25.0; // perfect closure is excellent
    } else if post_residual <= 20 {
        score += 8.0; // mildly risky gap
    }

    // Reward tight fits: small post_residual relative to item size.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 12.0 * tightness;

    // Open-bins pressure: with many open bins, prefer filling existing ones (penalize opening new).
    score += 0.6 * (open_bins_count as f64);

    // Last-chance bin: strongly favor using the only bin that fits to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin is a decent fit
    // or the fit would create dead space.
    if bin_residual == bin_capacity {
        // opening a new bin is penalized by open bin count and mean residual waste
        score += 15.0 + 0.8 * (open_bins_count as f64);
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin
        }
        // if next item is large, a fresh bin is more attractive
        if next_item_size > 50 {
            score -= 10.0;
        }
    } else {
        // existing bin: bonus if it can also fit the next item (lookahead synergy)
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
        // penalize if this placement kills the bin for the known next item
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score += 5.0;
        }
    }

    // Late in the stream, avoid leaving many fragmented bins: prefer high fill.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= 6.0 * progress * (bin_residual - post_residual) as f64 / bin_capacity as f64;

    // Slight alignment with mean residual: prefer bins below mean residual (larger gaps used first)
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
