    // Penalize creating residual too small for the next item (dead space),
    // scaled by how small the dead space is (fragmentation penalty).
    if next_item_size > 0 && post_residual < next_item_size {
        let frag = post_residual as f64;
        score += frag * (1.0 + 2.0 * (1.0 - frag / bin_capacity as f64));
    }

    // Compare against mean residual: prefer bins that stay near/above mean fill efficiency.
    let mean_resid = if mean_residual.is_finite() { mean_residual } else { post_residual as f64 };
    if (post_residual as f64) < mean_resid {
        score -= 15.0 * (mean_resid - post_residual as f64) / bin_capacity as f64;
    } else {
        score += 10.0 * ((post_residual as f64) - mean_resid) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 500.0;
