    if bin_residual == bin_capacity {
        score += 120.0;
        if fitting_bins_count <= 1 {
            score -= 200.0; // opening new bin is fine when nothing else fits well
        }
    }

    // Slight preference early in the stream to consolidate, later to keep flexibility.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 5.0 * open_bins_count as f64;

    score
}

