    // Nonlinear penalty on wasted fraction of the bin after placement.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 30.0;

    // Tight fits are excellent: reward small post_residual relative to item.
    if item_size > 0 {
        let fit_ratio = post_residual as f64 / item_size as f64;
        score -= (1.0 - fit_ratio.min(1.0)) * 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins lightly,
    // but a last-chance bin (only fitting bin) must be strongly favored.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }
    score += open_bins_count as f64 * 0.35;

    // Lookahead: if the next item fits exactly in the post-residual,
    // this placement chains perfectly; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty unless residual is dead space anyway.
        score += 3.0;
    }

    // Mean-residual coupling: bins with residual far below the mean are
    // fragmenting the fleet; penalize choosing them.
    score += (mean_residual - bin_residual as f64).abs() * 0.15;

    // New-bin candidate (empty bin): prefer it only when the item fits badly
    // anywhere else, i.e. when post_residual here is a tiny unusable gap.
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: moderate, so it beats only bad fits.
        score = 45.0 + waste_frac * 0.0;
        // Late in the stream, slightly cheaper to reuse open bins.
        score += (step_index as f64 / total_items.max(1) as f64) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Dead-space avoidance: residuals too small for any plausible item are near-useless.
    if pr < 10.0 {
        score += (10.0 - pr) * 12.0;
    } else {
        score -= 6.0;
    }

    // Nonlinear waste penalty on the post-placement empty fraction.
    let waste_frac = pr / cap;
    score += waste_frac * waste_frac * 30.0;

    // Tight fits are excellent.
    if item_size > 0 {
        let fit_ratio = pr / item_size as f64;
        score -= (1.0 - fit_ratio.min(1.0)) * 20.0;
    }

    // Last-chance bin strongly favored.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }
    score += open_bins_count as f64 * 0.35;

    // Lookahead (borrowed & tightened): reward chains where the next item
    // fits snugly into the post-residual; penalize large unusable gaps.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            score -= 8.0 * (1.0 - slack / cap);
            if slack < nxt * 0.5 {
                score -= 1.5;
            }
        } else {
            let gap = nxt - pr;
            score += 10.0 * (gap / cap) * (gap / cap);
            if gap > cap * 0.2 {
                score += 2.0 * (gap / cap);
            }
        }
    }

    // Fragmentation coupling: choosing bins far below mean residual fragments the fleet.
    score += (mean_residual - bin_residual as f64).abs() * 0.15;

    // New-bin candidate: open a fresh bin only when reuse would leave a tiny
    // unusable gap; otherwise reuse open bins. Late stream slightly favors reuse.
    if bin_residual == bin_capacity {
        score = 45.0 + (step_index as f64 / total_items.max(1) as f64) * 5.0;
        // If next item is large and this item is large, a fresh bin chains well.
        if next_item_size > 0 && (next_item_size as u64 + item_size as u64) <= bin_capacity as u64 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let mut score = pr ;
    if next_item_size > 0 {
        let nxt = next_item_size as f64 ;
        if pr >= nxt {
            let slack = pr - nxt ;
            score -= 8.0 * (1.0 - slack / cap) ;
            if slack < nxt * 0.5 { score -= 1.5 ; }
            // reward bins that can also host the next item snugly
            if slack >= nxt * 0.9 && slack <= nxt * 1.4 { score -= 1.0 ; }
        } else {
            let gap = nxt - pr ;
            score += 10.0 * (gap / cap) * (gap / cap) ;
            if gap > cap * 0.2 { score += 2.0 * (gap / cap) ; }
        }
    }
    if pr < cap * 0.05 { score -= 3.0 ; }
    // penalize near-full crowding when few alternatives exist
    if pr < cap * 0.02 && fitting_bins_count > 1 { score -= 0.5 ; }
    // prefer bins whose residual sits near mean residual (keeps variance low)
    let dev = (pr - mean_residual).abs() / cap ;
    score += 0.6 * dev ;
    // mild lookahead: opening a new empty bin is only attractive early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64) ;
        score += 2.0 + 3.0 * progress ;
        if next_item_size > 0 && pr >= next_item_size as f64 { score -= 1.0 ; }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0 - (post_residual as f64) * 10.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= (50.0 * (1.0 - slack / 100.0)).max(0.0);
        } else {
            // Next item cannot use the leftover; penalize wasted space proportionally.
            score += 0.3 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize creating dead space that is too small for typical items (1..100 unknown,
    // but small leftovers below ~10 are hard to fill).
    if post_residual > 0 && post_residual < 5 {
        score += 150.0;
    }

    // Prefer fuller bins relative to the fleet's mean residual.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Late in the stream, consolidate aggressively into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 100.0 * progress;
    }

    // Mild penalty for opening a new bin when many bins are already open,
    // unless the fit is perfect (post_residual small) — then new-bin is fine.
    if bin_residual == bin_capacity {
        score += 50.0 + 5.0 * open_bins_count as f64 * (1.0 - progress);
        if post_residual <= 20 {
            score -= 120.0;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            score -= 8.0 * (1.0 - slack / cap);
            if slack < nxt * 0.5 {
                score -= 1.5;
            }
            // prefer bins whose post-fit slack matches the next item tightly
            score -= 2.0 * (1.0 - (slack / nxt).min(1.0));
        } else {
            let gap = nxt - pr;
            score += 10.0 * (gap / cap) * (gap / cap);
            if gap > cap * 0.2 {
                score += 2.0 * (gap / cap);
            }
        }
    }

    // dead-space pressure: bins with tiny residual are nearly closed; reward closing them
    if pr < cap * 0.05 {
        score -= 3.0;
    } else if pr < cap * 0.12 {
        score -= 1.0 * (1.0 - pr / (cap * 0.12));
    }

    // when many bins can fit the item, prefer the tightest fit more aggressively
    if fitting_bins_count > 3 {
        score -= (fitting_bins_count as f64).min(8.0) * 0.15 * (1.0 - pr / cap);
    }

    // discourage opening a new bin when open bins have healthy mean residual
    if bin_residual == bin_capacity {
        let mr = if mean_residual.is_finite() { mean_residual } else { cap };
        if mr > cap * 0.25 {
            score += 6.0;
        } else {
            score += 2.0 * (1.0 - mr / (cap * 0.25));
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let mut score = pr ;

    if next_item_size > 0 {
        let nxt = next_item_size as f64 ;
        if pr >= nxt {
            let slack = pr - nxt ;
            score -= 8.0 * (1.0 - slack / cap) ;
            if slack < nxt * 0.5 {
                score -= 1.5 ;
            }
            // bonus if this bin can also host the item after next (chain fit)
            if slack >= nxt * 2.0 && slack - nxt * 2.0 < nxt * 0.3 {
                score -= 1.0 ;
            }
        } else {
            let gap = nxt - pr ;
            score += 10.0 * (gap / cap) * (gap / cap) ;
            if gap > cap * 0.2 {
                score += 2.0 * (gap / cap) ;
            }
        }
    }

    // penalize near-empty bins only when alternatives exist (avoid dead space)
    if pr < cap * 0.05 && fitting_bins_count > 1 {
        score -= 3.0 ;
    }

    // when many bins can fit the item, prefer tighter fits more aggressively
    if fitting_bins_count > 2 {
        score -= 0.5 * (1.0 - pr / cap) ;
    }

    // discourage opening a new bin when open bins still have usable mean space
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let mean_ok = mean_residual >= item_size as f64 * 0.9 ;
        if mean_ok {
            score += 2.0 ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: prefer tight fits (quadratic penalty on large post_residual).
    // Later: residual waste dominates, so amplify penalty super-linearly.
    let coupling = pr_norm * pr_norm * (1.0 + 3.0 * progress) + pr_norm * (1.0 - progress);
    score += 40.0 * coupling * cap;

    // Reward near-perfect fits smoothly, stronger as stream progresses.
    let tightness = 1.0 - pr_norm;
    score -= 15.0 * tightness * tightness * (0.5 + progress) * cap;

    // Last-chance bin: strong smooth reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: reward bins whose post-residual matches the next item.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let gap_norm = gap / cap;
        score += 12.0 * gap_norm * gap_norm * cap * (0.5 + 0.5 * progress);
    }

    // Mild penalty for spreading across many open bins relative to mean residual.
    let mean_gap = (pr - mean_residual).abs();
    score += 0.05 * mean_gap * (1.0 + progress);

    // New-bin candidate: baseline score so it loses only when fits are decent.
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr == nxt {
            // Perfect 2-step match: item + next item exactly fills the bin.
            score -= 200.0;
        } else if pr >= nxt {
            let slack = pr - nxt;
            score -= 8.0 * (1.0 - slack / cap);
            if slack < nxt * 0.5 {
                score -= 1.5;
            }
        } else {
            // Next item cannot use the leftover: quadratic dead-space penalty.
            let gap = nxt - pr;
            score += 10.0 * (gap / cap) * (gap / cap);
            if gap > cap * 0.2 {
                score += 2.0 * (gap / cap);
            }
        }
    }

    // Penalize residual far below mean residual (unusable gap vs pool).
    if pr < mean_residual {
        score += (mean_residual - pr) * 0.6;
    } else {
        score -= (pr - mean_residual) * 0.2;
    }

    // Last-chance bin: reward using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Nearly-closed bin: tiny leftover is cheap to sacrifice.
    if pr < cap * 0.05 {
        score -= 3.0;
    }

    // New-bin candidate: prefer it only when no open bin gives a tight fit.
    if bin_residual == bin_capacity {
        let tightness = 100 - item_size;
        score += 40.0 + (tightness as f64) * 0.3;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
    }

    // Late in stream: consolidate harder, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 25.0;
    }

    // Reward large fill ratio of the bin.
    score -= (item_size as f64 / cap) * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity fractions /8.
    // Residuals in [1,12] are "dead" slivers -> heavy penalty unless zero.
    let post = post_residual;
    if post == 0 {
        score -= 40.0; // perfect fit is always great
    } else if post <= cap / 8.0 as u32 {
        score += 18.0; // dead space sliver
    } else if post <= cap / 4.0 as u32 {
        score += 6.0;
    } else if post <= cap / 2.0 as u32 {
        score -= 4.0; // half-ish space still reusable
    }

    // Modulo-10 harmonic class of post_residual: multiples of 10 align
    // with typical item granularity, so they are more reusable.
    if post % 10 == 0 && post > 0 {
        score -= 5.0;
    }
    // Odd/awkward residuals are harder to fill later.
    if post % 2 == 1 && post > 0 {
        score += 1.5;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 25.0;
        } else if next_item_size < post {
            let nxt = next_item_size as f64;
            let fill_ratio = nxt / (post as f64);
            if fill_ratio > 0.7 {
                score -= 8.0 * fill_ratio;
            } else if post - next_item_size <= cap as u32 / 8 {
                score += 10.0; // next item would create a new sliver here
            }
        }
        // Harmonic class of next item vs post: same decade -> good pairing
        if next_item_size / 10 == post / 10 && post >= next_item_size {
            score -= 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // this bin's fit is poor (large post_residual) and the stream is young.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_badness = (post_residual as f64) / cap;
        // A fresh bin costs ~1 unit of "waste potential"; accept it only if
        // placing into an existing bin would waste more.
        let mut new_bin_score = 45.0 + 30.0 * (1.0 - progress);
        // With lookahead: a fresh bin gives full room for the next item.
        if next_item_size > 0 && (next_item_size as f64) / cap > 0.6 {
            new_bin_score -= 10.0;
        }
        // Many open bins with high mean residual -> prefer reusing them.
        new_bin_score += (open_bins_count as f64).sqrt() * 2.0
            + (mean_residual / cap).max(0.0) * 15.0;
        // If fit into this (new) bin is trivially perfect for small items,
        // slightly prefer it over badly fragmented bins.
        if fit_badness > 0.5 {
            new_bin_score -= 5.0;
        }
        score = new_bin_score;
    } else {
        // Mild preference for tighter bins when several fit.
        if fitting_bins_count > 1 {
            score += (post_residual as f64) * 0.15;
        }
        // Encourage filling bins whose residual is close to mean (balance).
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Two-step lookahead: exact fill of item + next item is ideal.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr == nxt {
            score -= 220.0;
        } else if pr >= nxt {
            let slack = pr - nxt;
            // Reward leaving just enough room for the next item.
            score -= 8.0 * (1.0 - slack / cap);
            if slack < nxt * 0.5 {
                score -= 1.5;
            }
        } else {
            // Next item cannot use leftover: quadratic penalty on gap.
            let gap = nxt - pr;
            score += 10.0 * (gap / cap) * (gap / cap);
            if gap > cap * 0.2 {
                score += 2.0 * (gap / cap);
            }
        }
    }

    // Penalize residual far below mean residual (unusable gap vs pool).
    if pr < mean_residual {
        score += (mean_residual - pr) * 0.4;
    } else {
        score -= (pr - mean_residual) * 0.15;
    }

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: prefer only when no open bin gives a tight fit.
    if bin_residual == bin_capacity {
        let tightness = 100 - item_size;
        score += 40.0 + (tightness as f64) * 0.3;
        if next_item_size > 0 && pr >= next_item_size as f64 {
            score -= 30.0;
        }
        // Late in stream, resist opening new bins even more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Late in stream: consolidate harder, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 25.0;
    }

    // Nearly-full bins are excellent: reward tiny post-residuals.
    if pr < cap * 0.05 {
        score -= 3.0;
    }

    // Reward large fill ratio of the bin.
    score -= (item_size as f64 / cap) * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1)
    // can use are pure waste, but small-but-usable gaps are the real danger
    // zone. Penalize gaps that are too small for typical items yet nonzero.
    let pr = post_residual as f64;
    if pr > 0.0 {
        // "Awkward gap" penalty: gaps in (0, 30) are hard to fill.
        let awkward = ((30.0 - pr) / 30.0).max(0.0);
        score += 12.0 * awkward * awkward;
        // Reward tight fits strongly.
        if pr <= 10.0 {
            score -= 10.0 * (1.0 - pr / 10.0);
        }
    } else {
        // Perfect fit: heavily favored.
        score -= 25.0;
    }

    // Dead-space ratio term relative to capacity.
    score += 0.15 * (pr / bin_capacity as f64) * 100.0;

    // Open bins pressure: prefer reusing bins when many are open,
    // but allow opening a new bin when few bins are open.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * pressure;

    // New-bin candidate handling: a fresh empty bin has zero dead space
    // potential; make it attractive when the fit into open bins is poor
    // or when this bin is the last chance.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline: slightly worse than a perfect fit, better than an
        // awkward gap. Tune with mean residual context.
        score -= 8.0 + 0.05 * mean_residual;
        if fitting_bins_count <= 1 {
            // Opening a new bin avoids wasting the last-chance bin's
            // remaining space? No: last chance means we should USE it.
            score += 20.0;
        }
        // When many bins are open, discourage proliferation.
        score += 2.5 * pressure;
    } else if fitting_bins_count == 1 {
        // Last chance: strongly favor using this bin to avoid opening one.
        score -= 15.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0;
    } else if next_item_size > 0 {
        // Next item won't fit here; mild penalty for stranding space.
        score += 2.0 * (1.0 - pr / bin_capacity as f64);
    }

    // Early in the stream, be more willing to spread items (keep options open).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 {
        score -= 1.0 * (1.0 - progress / 0.2);
    }

    // Deviation from mean residual: prefer bins whose residual is above
    // average (large bins absorb big items later).
    score -= 0.02 * (bin_residual as f64 - mean_residual);

    score
}

