            if slack < nxt * 0.5 { score -= 1.8 ; }
            // bonus if the leftover after next item is small (near-perfect chaining)
            if slack < cap * 0.02 { score -= 2.0 ; }
        } else {
            let gap = nxt - pr ;
            let ratio = gap / cap ;
            score += 10.0 * ratio * ratio ;
            if gap > cap * 0.2 { score += 2.2 * ratio ; }
            // penalize less if this bin is one of few options (must use it anyway)
            if fitting_bins_count <= 1 { score -= 6.0 * ratio ; }
        }
    }

    // dead-space control: tiny residual is valuable, reward keeping bins tight
    if pr < cap * 0.05 { score -= 3.5 ; }
    else if pr < cap * 0.12 { score -= 1.0 ; }

    // prefer filling bins whose residual is far below the mean (compact them)
    if pr < mean_residual * 0.5 { score -= 1.2 ; }

    // new-bin candidate: discourage unless nothing fits well
    if bin_residual == bin_capacity {
        score += 4.0 ;
        if fitting_bins_count == 0 { score -= 10.0 ; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;

        // Perfect 2-step match: next item exactly fills this bin afterward.
        if (post_residual as u32) == next_item_size {
            score -= 500.0 + 200.0 * (1.0 - progress);
        } else if post_residual > next_item_size {
            // Next item fits after this one: reward closeness of the pair fit.
            let slack = pr - nxt;
            score -= 100.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item will NOT fit here: penalize proportionally to how
            // "wasted" the leftover is relative to the next item's size.
            let miss = nxt - pr;
            score += 2.0 * miss.min(60.0) * (0.5 + progress);
        }

        // Bonus if the pair (item + next) would exactly fill the bin.
        let pair = item_size as f64 + nxt;
        if (pair - (bin_capacity as f64 - pr)).abs() < f64::EPSILON && post_residual == next_item_size {
            score -= 50.0;
        }
    }

    // --- Mean residual coupling ---
    // Prefer bins whose post_residual sits near the mean residual of open bins
    // (keeps the fleet balanced and reusable); penalize outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.5 * dev;

    // --- Dead-space penalty ---
    // Small but nonzero post_residual (unusable for typical items) is bad.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // --- Last-chance bin pressure ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // This is the only bin that fits; strongly favor using it over
        // opening a new bin, unless the fit is terrible.
        let waste = post_residual as f64;
        score -= 150.0 - 0.5 * waste;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh bin: neutral-ish baseline; attractive when existing bins are
        // all poor fits (high mean residual means open bins are crowded).
        score = 0.5 * bin_capacity as f64
            - 1.5 * mean_residual
            + 10.0 * (open_bins_count as f64).ln().max(0.0)
            + 30.0 * progress;
        if next_item_size > 0 && next_item_size == bin_capacity {
            score -= 300.0; // reserve fresh bin for a full-capacity item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Two-step lookahead ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr == nxt {
            // Next item exactly fills this bin: near-perfect pair completion.
            score -= 400.0 + 150.0 * (1.0 - progress);
        } else if pr > nxt {
            let slack = pr - nxt;
            score -= 8.0 * (1.0 - slack / cap);
            if slack < nxt * 0.5 {
                score -= 1.5;
            }
            // Reward exact pair fill (item + next == residual before item).
            if (item_size as f64 + nxt - (cap - pr)).abs() < f64::EPSILON {
                score -= 40.0;
            }
        } else {
            let gap = nxt - pr;
            score += 10.0 * (gap / cap) * (gap / cap);
            if gap > cap * 0.2 {
                score += 2.0 * (gap / cap);
            }
        }
    }

    // --- Tight fit reward: prefer minimal post residual (best-fit core) ---
    if pr > 0.0 {
        score -= 2.0 * (1.0 - pr / cap);
    }

    // --- Dead-space penalty for tiny unusable leftovers ---
    if post_residual > 0 && post_residual < 8 {
        score += 35.0;
    }

    // --- Mean residual coupling: keep fleet balanced but weak ---
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev;

    // --- Last-chance pressure: only fitting bin should usually win ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0 - 0.4 * pr;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh bin baseline: attractive only if open bins are crowded/poor.
        score = 0.45 * cap
            - 1.2 * mean_residual
            + 8.0 * (open_bins_count as f64).ln().max(0.0)
            + 25.0 * progress;
        // Reserve fresh bin for a full-capacity item.
        if next_item_size as u32 == bin_capacity {
            score -= 300.0;
        }
        // Never open a fresh bin when a decent fit exists in an open bin.
        if pr < cap {
            score += 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
