        if (post_residual as u32) == next_item_size {
            // Perfect follow-up fill: strong reward, stronger early.
            score -= 400.0 + 200.0 * (1.0 - progress);
        } else if pr >= nxt {
            let slack = pr - nxt;
            score -= 8.0 * (1.0 - slack / cap);
            if slack < nxt * 0.5 {
                score -= 3.0;
            }
        } else {
            let gap = nxt - pr;
            score += 10.0 * (gap / cap) * (gap / cap);
            if gap > cap * 0.2 {
                score += 2.0 * (gap / cap);
            }
        }
    }

    // --- Small-dead-space shaping: tiny leftovers are hard to reuse ---
    if post_residual > 0 && pr < cap * 0.05 {
        score -= 3.0;
    }
    if post_residual > 0 && post_residual < 4 {
        score += 25.0;
    }

    // --- Mean-residual deviation: mild balance pressure only ---
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev;

    // --- Last-chance bin pressure ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0 - 0.5 * pr;
    }

    // --- New-bin candidate: open fresh bin only when open bins are crowded ---
    if bin_residual == bin_capacity {
        score = 0.5 * cap
            - 2.0 * mean_residual
            + 8.0 * (open_bins_count as f64).ln().max(0.0)
            + 20.0 * progress;
