pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 14.0 * tightness * tightness;

    // Penalize dead space that is too small for typical items but nonzero
    if post_residual > 0 && post_residual < item_size {
        score += 8.0 * (1.0 - post_residual as f64 / item_size as f64);
    }

    // Lookahead: bonus if next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual >= next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 3.0; // next item won't fit here; mild penalty
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins have poor fits
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mean_fit = (mean_residual - item_size as f64).max(0.0);
        // penalize new bin when existing bins fit reasonably well
        score += 30.0;
        // discount the penalty when open-bin residuals are large (fragmented state)
        score -= 0.35 * mean_residual;
        // early in stream, opening bins is cheap; late, prefer consolidation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * progress;
        // many open bins -> discourage more sprawl
        score += 1.5 * open_bins_count as f64;
        let _ = mean_fit;
    } else {
        // mild preference for bins below mean residual (balance / larger holes first)
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Dead-space avoidance: slivers below the smallest plausible item are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    if post_residual == 0 {
        score -= 40.0;
    } else if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            // Reward gaps that fit the lookahead item, scaled by tightness.
            let slack = pr - nxt;
            score -= 8.0 * (1.0 - slack / cap);
            if slack < nxt * 0.5 {
                score -= 1.5;
            }
        } else {
            // Quadratic penalty for gaps that cannot hold the next item.
            let gap = nxt - pr;
            score += 10.0 * (gap / cap) * (gap / cap);
            if gap > cap * 0.2 {
                score += 2.0 * (gap / cap);
            }
        }
    }

    // Last-chance bin: strongly prefer the only fitting bin over a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when the open pool is strained
        // or late in the stream with poor residual spread.
        score += 30.0 - 0.6 * open_bins_count as f64 - 20.0 * progress;
        if next_item_size > 0 && (next_item_size as f64) <= cap {
            score += 5.0;
        }
        // Extra penalty early on: opening bins early wastes capacity.
        if open_bins_count > 2 && progress < 0.5 {
            score += 10.0;
        }
    } else {
        // Mild penalty for bins whose residual deviates from the pool mean.
        score += 0.1 * (mean_residual - pr).abs();
    }

    // Fragmentation coupling: penalize residuals hovering near the mean.
    if pr > 0.0 && (pr - mean_residual).abs() < 5.0 {
        score += 6.0;
    }

    // Small residual bonus: near-full bins are good compaction targets.
    if pr < cap * 0.05 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) + norm_pr * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tight = 1.0 - norm_pr;
    score -= 30.0 * tight * tight * (0.5 + progress);

    // Penalize dead space relative to mean residual (smooth interaction)
    let dev = norm_pr - mean_residual / cap;
    score += 15.0 * dev * dev * (1.0 - progress);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 + progress);
    }

    // Lookahead: reward bins whose post_residual can fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 20.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            let gap = (nx - pr) / cap;
            score += 25.0 * gap * (0.5 + progress);
        }
    }

    // Mild penalty for bin proliferation early in the stream
    score += 2.0 * open_bins_count as f64 * progress * norm_pr;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
