            score -= 8.0 * (1.0 - slack / cap) ;
            if slack < nxt * 0.5 { score -= 1.5 ; }
            // bonus if bin can also host the item after next (chained fit)
            if slack >= nxt * 2.0 { score -= 1.0 ; }
        } else {
            let gap = nxt - pr ;
            score += 10.0 * (gap / cap) * (gap / cap) ;
            if gap > cap * 0.2 { score += 2.0 * (gap / cap) ; }
            // penalize near-miss gaps that waste residual on dead space
            if gap <= cap * 0.05 { score += 2.5 ; }
        }
    }

    if pr < cap * 0.05 { score -= 3.0 ; }

    // new-bin candidate: prefer keeping item in an open bin unless residuals are bloated
    if bin_residual == bin_capacity {
        let avg = if open_bins_count > 0 { mean_residual } else { 0.0 } ;
        if avg > cap * 0.35 { score += 4.0 ; } else { score += 1.0 ; }
    }

    // when many bins can fit, favor tighter fits more strongly
    if fitting_bins_count > 3 {
        score -= 0.5 * (pr / cap) ;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Dead-space classification of post_residual via harmonic residue classes.
    // Class 0: perfectly full -> strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Harmonic thresholds: unusable slivers (cannot hold even the smallest item).
        if post_residual < 10 {
            score -= 25.0; // dead space, but only if bin was "used up" well
        } else {
            // Integer-division classes of post_residual relative to capacity.
            let class = post_residual / 25; // 0..3 harmonic quarters
            let mod_pen = match post_residual % 25 {
                0 => -6.0,
                1..=5 => 2.0,
                6..=15 => 0.0,
                _ => 3.0,
            };
            score += class as f64 * 4.0 + mod_pen;
        }
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward, scaled by how snugly next item fits (small leftover again)
            let next_left = post_residual - next_item_size;
            let snug = if next_left == 0 { 18.0 } else if next_left < 10 { 12.0 } else { 6.0 };
            score -= snug;
        } else {
            score += 8.0; // this bin likely dies after current item
        }
    }

    // Last-chance bin: if only one fitting bin, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current fit is bad (large post_residual) and many bins are open.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 30.0;
        // cheaper to open new bin late in stream or when many bins open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        score -= 0.5 * open_bins_count as f64;
        // if mean residual is large, prefer filling existing bins instead
        score += 0.3 * mean_residual;
        // if the item is small, a fresh bin wastes its room
        score += (cap - item_size as f64) * 0.2;
    } else {
        // reward tight fits in existing bins
        score -= (cap - post) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
