    score += 5.0 * (pr / cap - mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create capacity-fraction bands.
    let r = post_residual % 10;
    // Dead-space classes: post residuals in [1,9] are hard to fill; multiples of 10 are reusable.
    match r {
        0 => score -= 12.0,                       // perfectly harmonic residual
        1 | 2 | 8 | 9 => score += 6.0,            // worst dead-space classes
        3 | 4 | 6 | 7 => score += 2.0,            // mediocre classes
        _ => {}                                   // class 5: half-capacity, still useful
    }

    // Integer-division thresholds on post_residual: can it host harmonic item classes?
    let can_host_next = next_item_size > 0 && post_residual >= next_item_size;
    if next_item_size > 0 {
        if can_host_next {
            // Reward proportional to how tightly next item nests.
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 - slack.min(8.0);
        } else {
            score += 10.0; // post residual cannot fit lookahead -> wasted space
