        score += 25.0;
    }
    // late-stream urgency
    if step_index + 1 >= total_items.saturating_sub(50) && bin_residual != bin_capacity {
        score -= 20.0;
    }
    // penalize new bins when many open bins still have room
    if bin_residual == bin_capacity && open_bins_count > 3 {
        score += 15.0 + open_bins_count as f64 * 0.5;
    }
    // new-bin softening: only when existing fits are loose or chain breaks
    if bin_residual == bin_capacity {
        if item_size > bin_capacity / 2 {
            score -= 60.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 30.0;
        }
        // extra: opening a bin is bad if next item could still fit current residual
        if next_item_size > 0 && bin_residual >= next_item_size {
            score += 40.0;
        }
    }
    // waste-aware penalty: residual space that fits nothing plausible is dead weight
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits (small post_residual)
    score -= 2.0 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    // 2-step lookahead: reward exact match of next item into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect two-item completion
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64); // near-perfect chain
        } else {
            // next item won't fit here; penalize leaving large dead space
            let dead = (post_residual as f64) / bin_capacity as f64;
            score += 8.0 * dead * dead;
        }
    }

    // Relative-to-mean residual: prefer bins tighter than average
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mild penalty for opening new bins when many bins are already open
    if bin_residual == bin_capacity {
        score += 5.0 + 0.3 * open_bins_count as f64;
        // But allow new bin if lookahead suggests it will be filled well
        if next_item_size > 0 && (next_item_size + item_size as u32) as f64 >= 0.9 * bin_capacity as f64 {
            score -= 12.0;
        }
    }

    // Late in the stream: prefer closing bins out (smaller residual preferred)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space (small but non-zero post residual).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Reward perfect or near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: a fresh empty bin should only win when open bins
    // would be badly fragmented or when the lookahead item needs the fresh space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 18.0 + 20.0 * progress;
        if fitting_bins_count > 2 {
            new_bin_penalty += 15.0;
