    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 6.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    }

    // Global state coupling: when mean residual is high, prefer consolidating
    // into bins with large residuals; when low, prefer tight fits even more.
    let mr = mean_residual.max(0.0);
    score += 0.05 * (post_residual as f64 - mr);

    // Late in the stream, minimize bin count: favor existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_residual < bin_capacity) as i32 as f64;

