pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post-residual, with non-linear polynomial shaping
    let mut score = post * (1.0 + 0.5 * norm_post * norm_post);

    // Smooth coupling with stream progress: late in stream, tighten packing harder
    let progress_coupling = 1.0 + progress * progress * (1.0 - norm_post);
    score *= progress_coupling;

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_post);
    }

    // Penalize bins whose post-residual becomes dead space relative to mean residual
    let dead = (norm_post * cap - mean_residual).max(0.0);
    score += 0.3 * dead * dead / cap;

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 2.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 3.0 * (nxt - post) / cap;
        }
    }

    // Slight preference for consolidating into fewer bins
    score += 0.05 * open_bins_count as f64 * norm_post;

    score
}

