pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: reward residuals in "usable" classes ---
    // Class A: post_residual == 0 (perfect fit) -> strong reward
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Class B: post_residual too small for the smallest plausible item (< 10)
        // is dead space -> penalize proportionally to how dead it is.
        if post_residual < 10 {
            score += 25.0;
        } else {
            // Class C: residual in low harmonic bands (10..=30) is still reusable
            // by many item classes; reward mildly.
            let band = post_residual / 10; // integer division: harmonic band index
            score -= (4 - band.min(4)) as f64 * 3.0;
        }
    }

    // --- Modulo arithmetic on post_residual: residuals that are multiples of
    // common item sizes (10, 20, 25, 50) are "harmonic" and highly reusable ---
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // --- Lookahead coupling: if next item fits exactly in the post residual,
    // this placement sets up a perfect follow-up ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // next item fits but leaves another residual: mildly good
            score -= 8.0;
            let post2 = post_residual - next_item_size;
            if post2 < 10 {
                score += 12.0; // but creates dead space afterwards
            }
        } else {
            // next item will NOT fit here: this bin becomes dead for lookahead
            score += 10.0;
            // but if post_residual is tiny, bin is effectively closed anyway
            if post_residual < 10 {
                score -= 8.0;
            }
        }
    } else {
        // Last item: prefer to close bins as tightly as possible
        score -= 20.0;
    }

    // --- Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // --- New-bin candidate handling: brand-new empty bin gets a neutral-ish
    // score; prefer it only when the fit into open bins would be poor ---
    if bin_residual == bin_capacity {
        score = 0.5 * post_residual as f64;
        // Penalize opening new bins when many bins are already open and lightly used
        score += open_bins_count as f64 * 4.0;
        // Encourage new bin when mean residual is small (open bins nearly full)
        score -= (cap - mean_residual) * 0.3;
        // Late in the stream, opening new bins is more costly
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // --- Prefer filling bins that are already mostly full (small residual) ---
    let fill_ratio = 1.0 - (bin_residual as f64 / cap);
    score -= fill_ratio * 12.0;

    // --- Mean-residual coupling: placing into a bin far below mean residual
    // helps balance residual distribution ---
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.05;
    } else {
        score += (-dev) * 0.05;
    }

    score
}

