    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open-bin pressure,
        // but relax if this bin is the only fitting option elsewhere.
        score += pressure * 4.0;
        if fitting_bins_count <= 1 {
            score -= pressure * 3.0;
        }
    } else if fitting_bins_count == 1 {
        // Last chance bin: strongly favor using it to avoid a new bin.
        score -= 30.0 + pressure * 2.0;
    }

    // Lookahead: if the next item would fit into the post-residual,
    // reward leaving that gap; otherwise penalize leaving a gap that
