pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly: squashed residual.
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strong preference to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize new bins more when many bins are already open and item is small.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = post_residual as f64;
        score += 20.0 + waste * 0.5 + open_bins_count as f64 * 2.0 * (1.0 - progress);
        // If next item could pair with the leftover, slightly soften.
        if next_item_size > 0 && (next_item_size as f64) <= waste {
            score -= 15.0;
        }
    } else {
        // Reward using bins whose residual is far from mean (diversity of gap sizes).
        let gap = (bin_residual as f64 - mean_residual).abs();
        score -= gap * 0.1;
    }

    // Lookahead: penalize placements that leave a residual awkwardly just below next item size.
    if next_item_size > 0 && post_residual > 0 {
        let d = post_residual as i64 - next_item_size as i64;
        if d < 0 && d > -10 {
            score += 12.0; // dead space trap for next item
        } else if d == 0 {
            score -= 20.0; // next item fits perfectly
        }
    }

    // Late stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

