    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let post_norm = post / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    // Base: minimize wasted space, weighted more heavily as stream progresses.
    let poly = post_norm * (1.0 + 0.8 * progress + 0.6 * post_norm * progress);

    // Quadratic dead-space penalty: small residuals (unusable slivers) penalized.
    let dead = if post_norm > 0.0 && post_norm < 0.1 {
        (0.1 - post_norm) * (0.1 - post_norm) * 60.0 * (0.5 + progress)
    } else {
        0.0
    };

    // Perfect-fit reward (smooth trough at zero post residual).
    let fit_reward = -8.0 * (1.0 - post_norm).powi(6);

    // Lookahead: reward residual that can accommodate the next item smoothly.
    let look = if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post as u32 >= next_item_size {
            -3.0 * (1.0 - (post - nxt) / cap).abs().powi(2)
        } else {
            2.0 * (nxt - post) / cap
        }
    } else {
        0.0
    };

    // Last-chance bonus: strongly favor using the only fitting bin.
    let last_chance = if fitting_bins_count == 1 { -5.0 } else { 0.0 };

    // Mild pressure toward consolidating into fewer bins.
    let consolidation = 0.05 * open_bins_count as f64 * post_norm;

    // Deviation from mean residual: prefer bins near the mean (balanced packing).
    let dev = 0.3 * (post - mean_residual).abs() / cap;

    // New-bin candidate: penalize opening a new bin slightly, more so early on,
    // but allow it when the item leaves a large unusable residual elsewhere.
    let new_bin = if bin_residual == bin_capacity {
        4.0 + 3.0 * (1.0 - progress)
    } else {
        0.0
    };

    poly * cap * 0.1 + dead + fit_reward + look + last_chance + consolidation + dev + new_bin
}

