pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo 10: prefer residuals that are
    // "friendly" (0, 10, 20...) i.e. divisible by common item sizes (10,20,25,50).
    let pr = post_residual;
    let harmonic_class = match pr {
        0 => 0.0,
        x if x % 50 == 0 => 1.0,
        x if x % 25 == 0 => 2.0,
        x if x % 20 == 0 => 3.0,
        x if x % 10 == 0 => 4.0,
        x if x % 5 == 0 => 5.0,
        _ => 6.0,
    };
    score += harmonic_class * 2.5;

    // Penalize very small dead space (< 10) unless it's exactly zero:
    // unusable for typical items.
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 3.0;
    }

    // Lookahead: if next item fits the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - slack * 0.15;
    } else if next_item_size > 0 {
        // Next item won't fit: penalize proportionally to how far off it is.
        score += (next_item_size - post_residual) as f64 * 0.4;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when item is large or no
    // good open bin exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Penalize opening new bins mildly; more so early in the stream.
        score += 8.0 + progress * 10.0 - item_frac * 6.0;
        // If next item is large, a fresh bin is valuable.
        if next_item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Coupling with mean residual: bins far from mean residual are
    // slightly deprioritized (keep bin states homogeneous).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Tight fit reward: post residual small but >= next item or zero.
    if pr == 0 {
        score -= 10.0;
    }

    // Integer division threshold: residuals in [10,25) are awkward.
    if pr >= 10 && pr < 25 {
        score += 4.0;
    }

    score
}

