pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post-residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let next_leftover = post_residual - next_item_size;
            // Reward if the pair leaves almost nothing behind.
            score -= 10.0 * (1.0 - (next_leftover as f64) / (bin_capacity as f64));
        } else {
            // Next item won't fit here anyway; slight penalty if we leave a big gap.
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Time horizon: early in stream, encourage consolidation; late, allow new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * (1.0 - progress) * tightness;

    // Global state: many open bins with high mean residual -> discourage new bins,
    // encourage filling existing ones.
    let mean_res_norm = mean_residual / (bin_capacity as f64);
    score += 6.0 * mean_res_norm * (open_bins_count as f64).ln().max(0.0) * (1.0 - tightness);

    // New-bin candidate handling: empty bin should only win when the fit is poor
    // and alternatives are scarce.
    if bin_residual == bin_capacity {
        // Opening a new bin is costly; penalize unless this bin would be nearly wasted.
        let waste = (post_residual as f64) / (bin_capacity as f64);
        score += 20.0 * (1.0 - waste);
        // If item is large, a fresh bin is more attractive.
        score -= (item_size as f64) * 0.08;
        // When few bins fit the item, new bin becomes more acceptable.
        if fitting_bins_count <= 1 {
            score -= 18.0;
        }
    }

    // Mild non-linear coupling of item size and residual fragmentation.
    let frag = (post_residual as f64) * (item_size as f64) / (bin_capacity as f64);
    score += 0.05 * frag;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

