    // classes (multiples of common item sizes) are preferred.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        40.0 // perfect fit is king
    } else if pr % 10 == 0 {
        15.0 // aligns with decimal item classes
    } else if pr % 5 == 0 {
        8.0
    } else if pr < 10 {
        -12.0 // tiny dead space, unusable
    } else {
        0.0
    };
    score -= class_bonus;

    // Integer-division threshold: leftover that can still host the lookahead item
    // is valuable.
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 10.0 + (pr - next_item_size) as f64 * 0.15;
        } else {
            score += (next_item_size - pr) as f64 * 0.3; // near-miss penalty
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless current bins are crowded
    // or this is a perfect-fit-friendly large item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 * mean_residual / (cap * (open_bins_count.max(1) as f64));
        score += 30.0 - 25.0 * crowding - 10.0 * progress;
        if item_size >= bin_capacity / 2 {
            score -= 12.0; // large items pair well in fresh bins
        }
    } else {
        // Slight preference for fuller bins (tight packing).
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // Mean-residual coupling: if open bins are generally slack, be pickier.
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
