    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no open bin offers a decent fit (i.e., when we would create dead space).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // Pressure: the more bins already open, the worse opening another is.
        score += (open_bins_count as f64) * 3.0;
        // But if the item is large and would leave a big residual in any bin,
        // a fresh bin may still win; keep base moderate for large items.
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Mild stream-progression adaptation: later in the stream, be greedier
    // about consolidation (dead space matters more once committed).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64) / (bin_capacity as f64);

