    // Harmonic class of the post residual: residues modulo 10 define
    // "usable" vs "dead" space classes. Residues near 0 (multiples of 10)
    // are valuable because typical item sizes (10..80) nest into them.
    let pr = post_residual as i64;
    let residue = (pr % 10) as f64;
    let harmonic_penalty = match (pr % 20) as i64 {
        0 => -6.0,                 // perfect multiple of 20: excellent
        10 => -4.0,                // multiple of 10: good
        1 | 9 => -1.5,             // near-multiple: still usable
        2 | 8 => 0.0,
        3 | 7 => 2.0,              // awkward class
        4 | 6 => 4.0,
        _ => 6.0,                  // 5 | 15: worst residue class
    };
    score += harmonic_penalty * (1.0 - residue / 20.0);

    // Integer-division threshold: post_residual / smallest item (10)
    // counts how many minimum items still fit; reward deeper nesting.
    let min_item = 10u32.max(1);
    let nesting = (post_residual / min_item) as f64;
    score -= 2.5 * nesting.sqrt();

    // Perfect fit: zero post residual is ideal.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post
    // residual, strongly reward this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size < post_residual {
            let nres = (post_residual - next_item_size) as i64;
            // harmonic class of the double-placement leftover
            let cls = (nres % 10) as f64;
            score -= 4.0 * (1.0 - cls / 10.0);
        } else {
            // next item cannot follow: penalize proportionally to waste
            score += 1.0 + (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin; reward strongly unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Opening a new bin is only attractive when all open bins are crowded
    // (low mean residual) and this item would leave a bad harmonic class.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin, softened when stream is early
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 30.0 - 10.0 * progress;
        // crowded state makes new bin cheaper
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
        score += (mean_residual / bin_capacity as f64) * 20.0;
        // if item fills a large fraction of a fresh bin, prefer new bin
        let fill = item_size as f64 / bin_capacity as f64;
        score -= fill * 25.0;
        // bad post-residual class in existing bins pushes toward new bin
        if pr > 0 && pr < 10 {
            score -= 5.0;
        }
    }

    // Mild pressure against hoarding many open bins when this bin fits well.
    score += (open_bins_count as f64) * 0.02;

    // Penalize wasteful placements relative to mean residual slack.
    let slack = mean_residual - post_residual as f64;
    if slack > 0.0 {
        score += slack * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1) are impossible,
    // but small residuals that can fit only tiny items are near-dead. Penalize heavily.
    if post_residual > 0 {
        // residual smaller than typical item sizes -> dead space
        if post_residual < 10 {
            score += 40.0; // completely unusable-ish gap
        } else if post_residual < 20 {
            score += 18.0;
        } else if post_residual < 35 {
            score += 6.0;
        }
    } else {
        // perfect fill: strong reward
        score -= 60.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Lookahead: reward if the next item fits exactly into post_residual (chained packing)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving a residual it can't use
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // encourage consolidation when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more when open bins exist and could consolidate
        score += 12.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= pressure.min(20.0);
    }

    // Deviation from mean residual: prefer bins whose residual is already small
    // (consolidate into nearly-full bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Mild penalty for wasteful large leftover when mean residual suggests bins are filling
    if (post_residual as f64) > mean_residual && mean_residual > 0.0 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
