pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: zero waste is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward if the next item fits exactly
    // into the post residual (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            // Reward proportional to how tightly the next item fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 300.0 * (1.0 - slack / bin_capacity as f64);
            // Penalize leaving a residual too small for typical items (dead space).
            if post_residual < 10 {
                score += 150.0;
            }
        } else {
            // Next item cannot fit here: post residual becomes dead space
            // unless small enough to be negligible.
            if post_residual > 0 && post_residual < next_item_size {
                score += 40.0 + post_residual as f64 * 0.5;
            }
        }
    }

    // Compare post_residual against the mean residual across open bins:
    // prefer leaving residuals near the mean (balanced packing), penalize
    // extremes that fragment capacity.
    let pr = post_residual as f64;
    let dev = (pr - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // this placement would waste a lot (large dead space) or when the open
    // bin pool is already fragmented.
    if bin_residual == bin_capacity {
        // Base mild penalty so good fits into existing bins win.
        score += 60.0;
        // But if this item is large relative to capacity, a fresh bin is fine.
        score -= 0.4 * item_size as f64;
        // If many bins are open and residuals are scattered, prefer consolidation.
        if open_bins_count > 3 && mean_residual > item_size as f64 {
            score += 80.0;
        }
    }

    // Slight preference for filling bins more deeply as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // Mild penalty for very small post residuals that waste capacity.
    if post_residual > 0 && post_residual < 5 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the residual so large waste is heavily penalized.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead-space penalty: leftover space too small for any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item could still fit in the post-residual, this bin
    // remains valuable; reward it. If it cannot fit, penalize slightly so we
    // prefer bins whose leftovers are useless anyway.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 6.0;
        } else {
            score += 3.0;
        }
        // Chain fit: next item exactly fills what remains.
        if next_item_size == post_residual {
            score -= 15.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large relative to capacity or no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / bin_capacity as f64;
        let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
