            score += 40.0;                 // never open a bin when a last-chance exists
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score += 5.0;                  // avoid wasting fresh bins on small items
        }
    }

    // Time horizon: late in the stream, consolidate more aggressively to avoid
    // leaving many nearly-empty bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (mean_residual / bin_capacity as f64).min(1.0);

    // Mild preference for filling bins below the mean residual (balance avoidance
    // of fragmentation across the open set).
    if bin_residual as f64 > mean_residual && bin_residual < bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual in [0,1]
    let p = progress;
    let coupling = prn * prn * (1.0 - p) - prn * p * p;
    score += 20.0 * coupling;

    // Penalize large post residual late in the stream (dead space)
    score += 10.0 * prn * prn * p;

    // Reward tight fits: small post residual gets extra discount
    score -= 5.0 * (1.0 - prn) * (1.0 - prn);

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: penalize if next item could fit better in the residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 3.0 * (1.0 - (nxt / pr).abs().min(1.0));
        } else {
            score += 4.0;
        }
    }

    // Slight preference for filling bins with low mean residual
    score += 0.5 * (mean_residual / cap - prn).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

