    // fractions and reward the "half-full" sweet spot band.
    let half = cap / 2;
    if post >= half && post <= half + 25 {
        score -= 6.0;
    } else if post > half + 25 {
        score += (post - half - 25) as f64 * 0.05;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - gap / cap as f64).max(0.0);
