            if gap < 10.0 {
                score += 12.0 * (1.0 - gap / 10.0); // near-dead space after next
            }
        } else {
            // next item won't fit here: mild penalty, worse if this was last chance
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets baseline cost so it wins
    // only when all open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 55.0 + open_bins_count as f64 * 0.5;
    }

    // Stream progression: early on, be more willing to open bins (spread items);
    // later, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * progress;

    // Mean residual context: if open bins are already loose, penalize adding
    // to a loose bin slightly (prefer filling tighter ones).
    if mean_residual > 50.0 {
        score += (post_residual as f64 - mean_residual).abs() * 0.1;
    }

    score
}

