            score -= 30.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0; // gap still useful for lookahead
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 12.0; // gap too small for the next item
        }
    }

    // Reward tight fits relative to residual capacity.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins when few
    // alternatives exist, but allow new bins when this one is a poor fit.
    let pressure = (open_bins_count as f64).ln() + 1.0;
    score += 3.0 * pressure * (pr / bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid forcing a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish baseline; only chosen when open bins
    // score badly (poor fits / dead space). Slight penalty so we prefer
    // reusing bins with decent fits.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * mean_residual;
    }

    // Mild stream-position coupling: later in the stream, consolidate more
    // aggressively (dead space matters more as fewer items remain).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * pr * 0.3;

    score
