pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect two-step match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if diff == 0.0 {
            score -= 40.0; // chain placement: bin then next item perfectly
        } else if diff <= 5.0 {
            score -= 20.0 * (1.0 - diff / 6.0);
        } else if diff <= 15.0 {
            score -= 6.0 * (1.0 - diff / 16.0);
        }

        // Penalize leaving dead space that the next item cannot use.
        if post_residual < next_item_size {
            score += 8.0 * (post_residual as f64 / next) * (post_residual as f64 / next);
        }
    } else {
        // Last item: just minimize waste directly.
        score -= 5.0;
    }

    // Tight fits are good: reward small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness * tightness;

    // Compare against mean residual: placing into a bin with residual far
    // above the mean wastes the small-residual bins' potential.
    if post_residual as f64 > mean_residual {
        score += 0.35 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

