    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 12.0;
        if post_residual > 0 {
            score -= 4.0;
        }
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Opening a bin is cheap early, expensive late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 + 25.0 * progress;
        // A fresh bin wastes capacity equal to what's left unplaced... but
        // it's the natural home for items that would leave big dead space.
        if next_item_size > 0 && (bin_capacity as f64 - item_size as f64 - next_item_size as f64).abs() < 1.0 {
            score -= 30.0; // perfect 2-step chain in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let res = bin_residual as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;

    let mut score = post;

    // Reward tight fills: the fuller the bin becomes, the better.
    score -= 30.0 * (1.0 - post / cap);

    // Perfect fit bonus.
    if post == 0.0 {
        score -= 50.0;
