            score += 0.10 * nxt * (post / cap);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: default penalty so existing bins are preferred.
    if bin_residual == bin_capacity {
        score += 60.0;
        // Opening a bin is fine for large items that would leave bad fragmentation elsewhere.
        if item > 0.5 * cap {
            score -= 40.0;
        }
        // No open bins at all: must open.
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, consolidation matters more; slightly discourage new bins.
        let t = step_index as f64 / (total_items.max(1) as f64);
