    score -= (mean_residual - pr) / cap * 2.0;

    // Mild penalty for spreading across many open bins, eased by progress
    score += open_bins_count as f64 * (1.0 - progress) * 0.3;

    // New-bin candidate: penalize slightly so it only wins when fits are poor,
    // with the penalty relaxing as the stream progresses.
    if bin_residual == bin_capacity {
