    // Prefer bins whose residual is below mean residual (denser bins) when fit is good
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize moderately so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if no open bin can fit, opening new bin is fine
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Large items waste less in a fresh bin
        if item_size >= 50 {
            score -= 10.0;
        }
    }

    // Penalize very small post residuals that create unusable dead space (< 10)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
