    if progress > 0.85 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 8.0 + progress * 12.0 ;
    }
    // residual far above mean wastes space
    if post_residual > 0 && (post_residual as f64) > mean_residual * 1.5 && bin_residual != bin_capacity {
        score += 6.0 + progress * 4.0 ;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small post_residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
