        if post_residual < next_item_size && post_residual < 10 {
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 4 {
        // Many options: prefer tight fits even more, mild penalty against loose ones.
        if post_residual > 25 {
            score += 8.0;
        }
    }

    // Prefer bins below mean residual (consolidating emptier space),
    // penalize consuming bins that are already very full relative to mean.
    if mean_residual > 0.0 {
        let diff = bin_residual as f64 - mean_residual;
        score += diff * 0.15;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a bin
