            let best_possible = 30.0;
            if post_residual as f64 > best_possible && fitting_bins_count > 1 {
                score += 25.0; // discourage abandoning open bins when decent fits exist
            } else if post_residual > 50 {
                score -= 30.0; // fresh bin keeps large capacity for future big items
