        score -= 150.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use the leftover: leftover becomes dead space.
        score += 25.0 * (post_residual as f64 / 100.0);
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: prefer consolidating into existing bins when many
    // bins are already open; encourage new bins only when few are open.
