    // New-bin candidate (empty bin): discourage opening new bins unless current
    // placement would create severe fragmentation or bins are very full overall.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        // If open bins are already tight on average, a new bin is reasonable.
        let tightness = 1.0 - (mean_r / bin_capacity as f64);
        score += 25.0 - 30.0 * tightness;
        // Early in the stream, avoid bin proliferation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * (1.0 - progress);
