    if bin_residual == bin_capacity {
        score += 45.0 * (1.0 - progress * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: bins whose leftover falls into
    // "small" integer-division classes are nearly closed -> reward them.
    let small_class = post_residual / 10; // 0..=9 harmonic band
    score -= (10 - small_class as i32).max(0) as f64 * 2.0;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: leftover too small for the smallest plausible item (1..100 unknown,
    // so treat < 5 as dead) but not zero.
    if post_residual > 0 && post_residual < 5 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how tight the pair fit is.
            score -= 20.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item cannot use this leftover: penalize large unusable leftovers
            score += 0.15 * (post_residual as f64 - next_item_size as f64).min(post_residual as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening fresh bins, more so early in the stream
    // and when many bins are already open (consolidation pressure).
    if bin_residual == bin_capacity {
        score += 40.0 + 3.0 * open_bins_count as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    }

    // Mild pressure to prefer bins below mean residual (filling emptier bins first
    // keeps tighter bins available).
    score -= 0.05 * (mean_residual - bin_residual as f64);

    // Modulo-5 harmonic bonus: residuals divisible by 5 pair better with common sizes.
    if post_residual % 5 == 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never hold a plausible
    // item (<= 10) are pure waste; penalize them super-linearly.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual <= 20 {
        // Small risky gaps: mildly penalize proportionally to uselessness.
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits (post_residual small but usable).
    if post_residual > 0 {
        score -= (bin_capacity as f64 / post_residual as f64).min(30.0) * 0.4;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage scattering across many bins; encourage
    // filling existing bins when many are open.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strongly prefer using the only bin that fits,
    // otherwise a new bin gets opened.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current placement
    // would create severe dead space or no bin fits well.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Allow new bin if placing here would waste most of an existing bin.
        if post_residual < 10 && bin_residual > item_size {
            score -= 45.0;
        }
    }

    // Lookahead coupling: if the next item fits the post-residual, reward
    // this placement (chains items nicely).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for next item: slight penalty.
        score += 6.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (fill fuller bins
    // first), keeping larger residuals for harder future items.
    let mean_gap = mean_residual - post_residual as f64;
    if mean_gap > 0.0 {
        score -= mean_gap * 0.3;
    } else {
        score += (-mean_gap) * 0.15;
    }

    // Stream progression: early on be conservative about new bins, later
    // accept slightly worse fits to close out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect two-item packing: heavily reward
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item can still fit here: mild reward, scaled by tightness
            let tight = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.3 * tight;
        } else {
            // Next item will NOT fit after placement: penalize dead space
            let dead = (next_item_size - post_residual) as f64;
            score += 0.8 * dead;
            // Very small unusable residue is extra bad
            if post_residual < 10 {
                score += 15.0;
            }
        }
    } else {
        // Last item: prefer fullest packing
        score -= 20.0;
    }

    // Compare against mean residual across open bins:
    // prefer bins whose post-residual stays near the mean (balanced load)
    let pr = post_residual as f64;
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are nearly full / fragmented
    if bin_residual == bin_capacity {
        let mean_fill_gap = bin_capacity as f64 - mean_residual;
        // penalize opening new bin when mean residual is large (wasteful)
        score += 10.0 + 0.5 * mean_residual;
        // but reward opening when existing bins are tight (little room left overall)
        if mean_residual < 25.0 {
            score -= 25.0;
        }
        // discourage new bin early in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * (1.0 - progress);
        let _ = mean_fill_gap;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
