    if fitting_bins_count <= 1 && bin_residual != bin_capacity { score -= 25.0 ; }
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 { score -= 30.0 ; }
    // dead-space penalty: residual far above mean residual is likely wasted
    if post_residual > 0 && (post_residual as f64) > mean_residual * 1.5 && bin_residual != bin_capacity { score += 6.0 + progress * 4.0 ; }
    // endgame: prefer filling existing bins tightly
