        if leftover_after_next > 0 && leftover_after_next < next_item_size / 2 { score -= (next_item_size / 2 - leftover_after_next) as f64 * 0.8 ; }
        if leftover_after_next >= next_item_size && leftover_after_next < 2 * next_item_size { score -= 18.0 ; }
