pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    let mut score = post;

    // Reward tight fits (high fill ratio of the residual space used).
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post residual that cannot host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            // dead space until next item arrives; worse if gap is small (wasted nearly-fitting space)
            score += (nxt - post) * 0.8;
        } else {
            // post residual can host next item: reward
            score -= 6.0;
        }
        // Bonus if this placement leaves exactly room for the next item (perfect chaining)
        if post == nxt {
            score -= 12.0;
        }
    } else {
        // Last item: pure tightness matters
        score -= 20.0 * fit_ratio;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins are crowded (mean residual small) or item is large.
    if bin_residual == bin_capacity {
        let crowd = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let large_item = item_size as f64 / cap;
        // Penalize new bins early / when many bins open; reward when crowded or item huge.
        score += 18.0 + 2.0 * open_bins_count as f64 * 0.5;
        score -= 35.0 * crowd * crowd;
        score -= 25.0 * large_item * large_item;
        // As stream progresses, be more willing to open new bins (horizon effect).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * progress;
    }

    // Mild preference for bins whose residual deviates below mean (consolidate emptier space).
    score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    // Small penalty for leaving very small unusable slivers.
    if post > 0 && post < 10.0 {
        score += 8.0;
    }

    score
}

