pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post-residual with smooth non-linear shaping (dead space penalty grows quadratically)
    let mut score = pr + 12.0 * pr_norm * pr_norm * cap;

    // Polynomial coupling with stream progress: early on, prefer tight fills less aggressively;
    // later, penalize waste more strongly (quadratic in progress).
    let progress_coupling = (0.5 + progress) * pr_norm * pr_norm * 20.0;
    score += progress_coupling;

    // Cubic interaction: mid-stream, reward near-full bins (smooth valley around pr_norm ~ 0.1)
    let tightness = (1.0 - pr_norm).clamp(0.0, 1.0);
    score -= 8.0 * tightness * tightness * tightness;

    // Reward bins that also fit the lookahead item (smooth lookahead match)
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        score -= 6.0 * (1.0 - fit_ratio) * (1.0 + progress);
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize scattering across many open bins relative to mean residual
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev * (1.0 + open_bins_count as f64 / 10.0);

    // New-bin candidate: make empty bins moderately attractive only when current bin leaves bad residue
    if bin_residual == bin_capacity {
        score = pr + 10.0 - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes of post_residual modulo 10: dead space in small
    // remainders is nearly unusable for items >= 10, so penalize classes
    // 1..=9 lightly, with class 9 (worst) penalized most.
    let r = post_residual % 10;
    let class_penalty: f64 = match r {
        0 => -8.0,           // decade-aligned residual: very reusable
        1 => 6.0,
        2 => 5.0,
        3 => 4.5,
        4 => 4.0,
        5 => 3.0,            // half-decade: moderately reusable
        6 => 4.0,
        7 => 4.5,
        8 => 5.0,
        _ => 5.5,
    };
    score += class_penalty * (post_residual as f64 / bin_capacity as f64);

    // Integer-division threshold: residuals >= 50 can host half-capacity items.
    if post_residual / (bin_capacity / 2) >= 1 {
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= 2.0 + (post_residual - next_item_size) as f64 * 0.05;
        } else {
            // residual too small for next item: penalize proportionally to waste
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: prefer it only when no open bin is a decent fit
    // (item fills > 60% of a fresh bin) or late in the stream.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if fill > 0.6 {
            score -= 25.0 + 10.0 * fill;
        } else if fitting_bins_count > 0 {
            score += 15.0 - 10.0 * progress;
        } else {
            score -= 50.0; // no alternative: must open new bin
        }
    }

    // Slight preference for bins with residual close to mean (balanced packing).
    score += (bin_residual as f64 - mean_residual).abs() * 0.02;

    // Mild tie-break: prefer more-filled bins early.
    score -= (bin_residual as f64) * 0.01 * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.09;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item (1..100) are pure waste.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 200.0; // unusable dead space: severe penalty
    } else if post_residual < 25 {
        score += 40.0; // risky small gap
    } else if post_residual < 50 {
        score += 8.0;
    }

    // Tightness reward: fraction of residual consumed by this item.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            // gap won't serve the next item; mild penalty scaled by gap smallness
            if post_residual < next_item_size && post_residual < 30 {
                score += 25.0;
            }
        }
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin wastes existing residual mass.
    if bin_residual == bin_capacity {
        // Prefer new bin only when no open bin fits well and mean residual is high.
        let pressure = open_bins_count as f64;
        score += 120.0 + 5.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open new bin
        } else if mean_residual < 20.0 {
            score -= 80.0; // open bins are nearly full anyway
        }
    }

    // Open-bin count pressure: mildly discourage scattering into many bins.
    score += 0.5 * open_bins_count as f64;

    // Progress coupling: later in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins with less residual than average
    // (fill the fuller bins first, keeping large gaps available).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step match: this bin's residual after
    // placing the item exactly fits the next arriving item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Partial lookahead credit: closeness of post_residual to next_item_size
    // (normalized), so near-perfect matches are also preferred.
    if next_item_size > 0 {
        let diff = (post_residual as f64 - next_item_size as f64).abs();
        let norm = diff / bin_capacity as f64;
        score -= 50.0 * (1.0 - norm.min(1.0));
    } else {
        // Last item: minimize leftover waste only.
        score += post_residual as f64 * 0.5;
    }

    // Penalize post_residual that is small but unusable (dead space below the
    // minimum plausible item size of 1..10): anything in 1..=9 is likely waste.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Compare against mean residual across open bins: bins tighter than the
    // mean (small post_residual relative to mean_residual) are good targets.
    let mean_post_gap = mean_residual - post_residual as f64;
    score -= mean_post_gap.clamp(-bin_capacity as f64, bin_capacity as f64) * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Its post_residual is huge, so the base score already penalizes it, but
    // add an explicit penalty that grows with how many open bins could fit
    // the item (opening a new bin wastes those opportunities).
    if bin_residual == bin_capacity {
        let fit_factor = if fitting_bins_count > 1 { fitting_bins_count as f64 } else { 1.0 };
        score += 25.0 * fit_factor;
        // Exception: if the next item pairs perfectly with this item in a
        // fresh bin, opening a new bin is attractive (item + next fill it).
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 120.0;
        }
    }

    // Mild stream-progression term: late in the stream, tighten packing and
    // avoid opening bins unnecessarily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    // Slight preference to keep the number of open bins bounded.
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post-residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space that the next item cannot use
    if next_item_size > 0 {
        if post_residual < next_item_size {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.8 * waste;
        } else {
            // Reward residuals that exactly or nearly fit the next item
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (-gap / 12.0).exp();
        }
    } else {
        // Last item: only tightness matters; avoid opening needless bins
        score += 40.0;
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // When many bins can fit the item, prefer the one with smallest residual
    if fitting_bins_count > 1 {
        score += 0.5 * (bin_residual as f64 - mean_residual);
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when a reasonable fit exists among open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fit_quality = (post_residual as f64) / (bin_capacity as f64);
        score += 30.0 + 50.0 * (1.0 - progress) + 20.0 * fit_quality;
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= next_item_size {
            score += 15.0; // an open bin could serve the next item too
        }
    } else {
        // Mild reward for consolidating into already-open bins
        score -= 5.0 + 0.3 * (open_bins_count as f64).ln();
    }

    // Time-horizon modulation: late in stream, be greedier about tight fits
    let horizon = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * horizon * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post-residual in [0,1]

    // Base: penalize wasted space non-linearly (quadratic in post-residual)
    let mut score = x * x * cap + 0.5 * pr;

    // Smooth coupling: as stream progresses, prefer tighter fits more strongly
    let tightness = 1.0 - x;
    score -= (1.0 + 2.0 * progress) * tightness * tightness * cap * 0.6;

    // Cubic interaction: mid-range residuals are less valuable late in stream
    let mid = 4.0 * x * (1.0 - x);
    score += progress * mid * 8.0;

    // Lookahead: reward residuals that can still host the next item (smoothly)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fits_next = (pr / n).min(1.0);
        score -= 6.0 * fits_next * fits_next;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else {
        // mild penalty when many bins fit, to keep packing tight
        score += 0.3 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Mean-residual coupling: prefer bins near the mean residual (smooth)
    let dev = (pr - mean_residual).abs() / cap;
    score += 4.0 * dev * dev;

    // Prefer consolidating into fewer bins when many open
    score += 0.05 * open_bins_count as f64 * (1.0 - tightness);

    // New-bin candidate: neutral-ish baseline with slight penalty unless residuals are tiny
    if bin_residual == bin_capacity {
        score = cap * 0.55 + 10.0 * progress;
        if next_item_size > 0 && (next_item_size as f64) <= cap {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of common small item sizes) are favored.
    let post = post_residual;
    let useful = |r: u32| -> f64 {
        if r == 0 { return -8.0; }                       // perfect fit, strongly reward
        if r % 10 == 0 { return -3.0; }                  // round residual, reusable
        if r % 5 == 0 { return -1.5; }
        if r < 5 { return 6.0; }                         // dead space penalty
        if r < 10 { return 4.0; }
        0.0
    };
    score += useful(post);

    // Integer-division thresholds: residual buckets via post/10
    let bucket = post / 10;
    score -= (bucket as f64) * 0.4;                      // larger usable residual preferred

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate handling: only open a new bin when the current bin's
    // post-residual would be small dead space AND next item cannot use it.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity >= 100;
    if is_new_bin {
        // opening a new bin wastes the residual this bin would leave
        score += 4.0;
        if post >= 10 && (next_item_size == 0 || next_item_size > post) {
            // residual would be unusable by next item anyway -> new bin OK
            score -= 9.0;
        }
        if next_item_size > 0 && next_item_size <= bin_residual && next_item_size > post {
            // next item fits this bin but not after placement -> keep bin viable
            score += 6.0;
        }
    }

    // Lookahead: if next item exactly fills the post residual, big reward
    if next_item_size > 0 && next_item_size == post {
        score -= 7.0;
    } else if next_item_size > 0 && next_item_size <= post {
        score -= 1.0;
    }

    // Modulo coupling between item_size and capacity: items in "harmonic"
    // fractions of capacity (25, 50, 20, 10...) pair well with round residuals
    if item_size % 25 == 0 || item_size % 20 == 0 {
        score -= 0.5;
    }

    // Late in stream: consolidate, discourage new bins and large leftovers
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post as f64) * 0.15;

    // Prefer bins below mean residual (tighter bins) slightly
    score += ((post as f64) - mean_residual) * 0.05;

    // Many open bins: favor filling existing ones over spreading
    score -= (open_bins_count as f64).ln().max(0.0) * 0.3 * (post as f64 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (< 10, minimum item size) are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 50.0 + (10 - post_residual) as f64 * 5.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize residuals too small to hold the lookahead item (dead for next item).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward residuals that exactly accommodate the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Tightness reward: the fuller the bin relative to residual, the better.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 10.0;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // discourage opening new bins unless residual is large but awkward.
    let pressure = open_bins_count as f64 / 8.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when item is large and no good fit exists.
        score += 25.0 + pressure * 10.0;
        if item_size >= 60 {
            score -= 20.0;
        }
    } else {
        score += pressure * (bin_residual as f64 - post_residual as f64) * 0.05;
    }

    // Prefer bins below mean residual (leave big gaps in emptier bins).
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Early stream: be more conservative about wasting space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the leftover space exactly matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for next item is heavily rewarded.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
