    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly, more when good existing fits exist or many bins open.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        // But if no open bin fits well (post_residual large waste), allow opening.
        if post_residual < item_size as f64 * 0.2 + 5.0 {
            score -= 15.0;
        }
    }

    // Prefer bins with residual above mean (larger bins) for big items; tighter bins for small items.
    let residual_f = bin_residual as f64;
    if item_size as f64 > mean_residual {
        score += 5.0 * (mean_residual - residual_f).max(0.0) / bin_capacity as f64;
    } else {
        score -= 5.0 * (mean_residual - residual_f).abs().min(20.0) / bin_capacity as f64;
    }

    // Slight preference for filling bins tighter as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.1;

    score
}

