pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit core: reward tight fits.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;

    // Penalize small dead space that no future item can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    } else if post_residual >= 10 {
        // Reward residuals that could still host typical items.
        score -= 2.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead: if the next item fits perfectly in the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 4.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty for wasting the gap.
            score += 3.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: discourage opening a new bin unless current fit is poor
    // or few bins are open (early stream / spreading load).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = fit_ratio < 0.5;
        let pressure = open_bins_count as f64 * item_size as f64 / bin_capacity as f64;
        if poor_fit || progress < 0.1 {
            score -= 8.0 + 4.0 * (1.0 - progress);
        } else {
            score += 10.0 + pressure;
        }
    }

    // Global state coupling: prefer filling bins above the mean residual
    // (i.e., bins with less space than average) to consolidate load.
    let residual_gap = mean_residual - bin_residual as f64;
    score += 1.5 * residual_gap;

    // Time horizon: as the stream nears its end, tighten packing harder.
    let horizon = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * horizon * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Tight-fit reward: strongly favor small post residuals (quadratic).
    score -= 2.5 * (1.0 - pr / cap).powi(6) * cap * 0.2;

    // Penalize dead space that no plausible item could fill.
    let dead = (pr as i64 - next_item_size as i64).max(0) as f64;
    score += 0.35 * dead * (1.0 + progress);

    // Lookahead coupling: reward if next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 3.0 * (-gap * 0.08).exp();
    }

    // Last-chance bin: strong bonus to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open fits are bad.
    if bin_residual == bin_capacity {
        score += 4.0 + 3.0 * (1.0 - progress);
    }

    // Mild penalty when bin residual deviates from mean residual (balance load).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs() * (1.0 - progress);

