    score += 0.02 * pr * progress * (open_bins_count as f64).ln();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap; // 0..1 fraction of capacity wasted

    // Integer-division threshold classes on post_residual (harmonic buckets).
    let post_class = post_residual / 10; // 0..10 bucket
    score += (post_class as f64) * 1.5;  // mild penalty growing with bucket index

    // Non-linear waste penalty: strongly punish residuals that are too small
    // for typical future items (unusable dead space) but reward near-full bins.
    if post_residual == 0 {
        score -= 25.0; // perfect fill
    } else if post_residual < 10 {
        score -= 12.0; // nearly perfect, effectively unusable anyway
    } else {
        // Harmonic penalty: waste weight scales with 1/(1+usable fraction)
        let usable = frac;
        score += 20.0 * usable * usable;
        // Modulo arithmetic: residuals that are multiples of common item sizes
        // (10, 20, 25, 50) are more likely to be filled later -> reward.
        let r = post_residual;
        if r % 10 == 0 { score -= 6.0; }
        if r % 20 == 0 { score -= 3.0; }
        if r % 25 == 0 { score -= 3.0; }
        if r % 50 == 0 { score -= 4.0; }
    }

    // Lookahead coupling: if next item fits exactly or well in post_residual,
    // reward this bin strongly (chain placements).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 18.0; // perfect chain
        } else if slack < 15 {
            score -= 9.0;  // good chain
        } else {
            score -= 3.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot follow into this bin: penalize proportionally.
        score += 4.0 + 0.05 * (next_item_size as f64);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large (little residual left) or all existing fits are bad.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        // Base cost of a new bin; large items leave little waste so cheaper.
        score = 60.0 - 40.0 * item_frac;
        if next_item_size > 0 {
            // If next item would pair with the leftover of this item, reward.
            let left = bin_capacity - item_size;
            if next_item_size <= left {
                score -= 8.0;
            }
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // Many open bins: discourage opening yet another.
        score += (open_bins_count as f64).sqrt() * 2.0;
    }

    // Mean-residual coupling: when open bins are on average quite full
    // (low mean residual), slightly favor using this bin.
    score -= 0.05 * (cap - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
