    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    }

    // Penalize bins with residual far below the mean (fragmentation indicator).
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev.max(0.0);

    score
