        } else if (6..10).contains(&mod10) {
            score += 4.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 90.0;
        } else if next_item_size < post {
            let slack = (post - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / cap);
            if (post - next_item_size) % 10 == 0 {
                score -= 10.0; // chained harmonic fit
            }
        } else {
            score += 10.0; // next item cannot follow here
        }
    } else {
        // Last item: closing a bin is free win
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 55.0;
    }

    // Many open bins: encourage tightening the widest bins (balance residuals
    // toward harmonic multiples of 25).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score -= open_pressure * 15.0 * (mean_residual / cap - (post as f64 / cap));

    // Slight preference for filling large fractions of the bin early/mid stream.
    let fill = 1.0 - post as f64 / cap;
    score -= 20.0 * fill * (1.0 - progress);

    score
}

