pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps (< 10)
    if post_residual > 0 && post_residual < 10 {
        score += 100.0;
    }

    // Reward perfect fits strongly
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward tight fits relative to bin residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Open-bins pressure: prefer using existing bins when many are open
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly prefer it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it less attractive unless existing fits are bad
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    // Lookahead: if next item fits well in the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 3.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
