    if bin_residual == bin_capacity {
        score += 120.0;
        // Opening a new bin is more attractive when it enables a clean 2-item pairing
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0;
        }
    }

    // Slight preference for bins tighter than the current mean residual
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Late-stream: consolidate into existing bins more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
