pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let t = progress.clamp(0.0, 1.0);
    let pr_norm = pr / cap;
    // Polynomial kernel: peaks mid-stream, dampens early/late waste tolerance.
    let poly = 2.0 * t * t - 2.0 * t + 0.5; // smooth U-shape (min at t=0.5)
    score += poly * pr_norm * 20.0;

    // Reward tight fits (small post residual) increasingly at later stages.
    let tight = (1.0 - pr_norm).powi(3);
    score -= tight * 15.0 * (0.3 + 0.7 * t);

    // Lookahead coupling: bonus if next item fits the post-residual.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - (next_item_size as f64 / pr).powi(2));
    } else if next_item_size > 0 {
        // Penalize wasted residual that next item cannot use.
        score += 4.0 * (1.0 - (pr / (next_item_size as f64)).min(1.0));
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Slight penalty when bin residual deviates from mean residual (balance).
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: keep neutral-high so it's only chosen when open bins score badly.
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: dead-space quality classes ---
    // Class A: post_residual == 0 (perfect fit) -> huge reward.
    if post_residual == 0 {
        score -= 500.0;
    }
    // Class B: post_residual <= 10 (near-perfect, unusable sliver) -> strong reward.
    else if post_residual <= 10 {
        score -= 200.0;
    }
    // Class C: post_residual in (10, 20] -> small dead zone, mild reward.
    else if post_residual <= 20 {
        score -= 60.0;
    }
    // Class D: post_residual in (20, 40] -> medium dead zone, mild penalty.
    else if post_residual <= 40 {
        score += 15.0;
    }
    // Class E: post_residual > 40 -> large residual, penalize unless next item can use it.
    else {
        score += 40.0;
    }

    // --- Modulo arithmetic on post_residual: residues that pair well with
    // common item sizes (multiples of 5 / 10) are more reusable. ---
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 30.0; // residue multiple of 10: highly reusable
        } else if pr % 5 == 0 {
            score -= 15.0; // residue multiple of 5: reusable
        } else if pr % 2 == 0 {
            score -= 5.0; // even residue: mildly reusable
        } else {
            score += 8.0; // odd awkward residue
        }
    }

    // --- Lookahead coupling: does next_item_size fit into post_residual? ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits here: reward proportionally to tightness.
            let tightness = 1.0 - (pr - next_item_size) as f64 / bin_capacity as f64;
            score -= 80.0 * tightness;
            if pr - next_item_size <= 10 {
                score -= 40.0; // chain of near-perfect fits
            }
        } else {
            // Next item does not fit: penalize proportionally to overshoot.
            let overshoot = (next_item_size - pr) as f64;
            score += 0.5 * overshoot.min(80.0);
        }
    }

    // --- Last-chance logic: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin. ---
    if fitting_bins_count == 1 {
        score -= 120.0;
    } else if fitting_bins_count > 1 {
        // More competition: mild penalty to break ties toward best fit.
        score += 5.0 * (fitting_bins_count as f64 - 1.0).min(10.0);
    }

    // --- New-bin candidate handling: bin_residual == bin_capacity means
    // post_residual == capacity - item_size. Only open a new bin when the
    // current item is large (would leave big unusable gaps in existing bins)
    // or when no good existing option exists. ---
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 150.0;
        // Large items justify new bins (they leave little choice anyway).
        if item_size >= 60 {
            score -= 100.0;
        } else if item_size >= 40 {
            score -= 40.0;
        }
        // If next item is large, a fresh bin is attractive (room for both).
        if next_item_size >= 50 && next_item_size <= pr {
            score -= 60.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 50.0 * progress;
    }

    // --- Mean residual context: if open bins are generally tight, avoid
    // wasting this bin's space; if loose, tighter fits matter less. ---
    if mean_residual < 20.0 && bin_residual > 40 {
        score += 10.0; // scarce space overall: discourage loose placement
    } else if mean_residual > 50.0 {
        score -= 5.0; // plenty of slack: any fit is fine
    }

    // --- Integer division threshold: post_residual / item_size ratio classes. ---
    if item_size > 0 {
        let ratio = pr / item_size; // integer division
        if ratio == 0 {
            score -= 20.0; // item dominates bin: good consolidation
        } else if ratio >= 2 {
            score += 10.0; // item is tiny vs residual: wasteful use of a big gap
        }
    }

    // Small preference for filling fuller bins (lower residual before placement).
    score += 0.1 * (bin_capacity as f64 - bin_residual as f64) * -1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (10)
    // are pure waste; penalize quadratically as they approach 0.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Tightness ratio: favor bins where the item fills a large share of residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 30.0;

    // Open-bin pressure: with many open bins, prefer reusing existing bins
    // over opening new ones (penalize the new-bin candidate).
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item can use the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual is dead space for the known next item.
        score += 10.0;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it's a "small" bin best consolidated now.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.5;
    } else {
        score += (-dev) * 0.2;
    }

    // Early in the stream, be slightly more willing to open bins to build
    // a diverse residual portfolio; later, consolidate.
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

