                score += gap * 0.5;
            }
        } else {
            // next item won't fit here: mild penalty scaled by how badly
            score += (nxt - post) * 0.1;
        }
    }

    // Relative-to-mean coupling: a bin with residual well below the mean
    // is already "used up" — packing it is good (consolidates waste).
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        score -= (mean_residual - post_f) * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: discourage opening a new bin unless the item is
    // large relative to capacity (big items deserve fresh space).
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / bin_capacity as f64;
        score += 20.0 * (1.0 - size_frac);
    }

    // Late in the stream, tighten packing more aggressively (less room
    // to amortize open bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_f * 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
