        if next_item_size as f64 == dead {
            score -= 150.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // New-bin candidate handling: discourage opening new bins unless
    // the item fits poorly everywhere (fitting_bins_count==0 means only
    // the new bin was called, or this IS the new bin).
    if bin_residual == bin_capacity {
