        score += 4.0 + 0.3 * open_bins_count as f64 * (1.0 - progress);
    }

    // Smooth fragmentation penalty: cubic in normalized residual.
    score += 5.0 * norm_pr.powi(3) * (0.5 + 0.5 * progress);

    score
}

