            let gap = (post_residual as i64 - next_item_size as i64) . max (0) as f64 ;
            score += gap * 0.3 ;
        }
    }
    if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual > 0 { score -= 40.0 ; }
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size && post_residual < next_item_size * 3 {
        score -= 15.0 + (next_item_size * 3 - post_residual) as f64 * 0.5 ;
    }
    if post_residual > 0 && post_residual <= 10 {
        let tightness = 1.0 - (mean_residual / bin_capacity as f64) . min (1.0) ;
        score -= (10 - post_residual) as f64 * (1.0 + tightness * 2.0) ;
    }
    if step_index + 1 >= total_items . saturating_sub (50) && bin_residual != bin_capacity { score -= 20.0 ; }
    if bin_residual == bin_capacity && open_bins_count > 3 { score += 15.0 + open_bins_count as f64 * 0.5 ; }
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6 ;
    }
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size / 2 {
        score += (next_item_size - post_residual) as f64 * 0.9 * (1.0 - progress) * 20.0 ;
    }
    if next_item_size > 0 && post_residual >= 2 * next_item_size { score -= 10.0 + open_bins_count . min (10) as f64 ; }
    if fitting_bins_count <= 1 && bin_residual != bin_capacity { score -= 25.0 ; }
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 { score -= 30.0 ; }
    // refined dead-space penalty: residual smaller than next item is wasted
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let dead_frac = post_residual as f64 / next_item_size . max (1) as f64 ;
        score += (1.0 - dead_frac) * next_item_size as f64 * 0.12 * (0.6 + progress) ;
    }
    // reward near-full bins that still leave a usable remainder
    if post_residual > 0 && next_item_size > 0 {
        let fill = 1.0 - (bin_residual as f64) / bin_capacity . max (1) as f64 ;
        if fill > 0.75 && post_residual >= next_item_size { score -= 6.0 + fill * 8.0 ; }
    }
    // two-step lookahead: exact fit for next two items
    if post_residual > 0 && next_item_size > 0 && item_size <= post_residual {
        let twice_left = (post_residual - item_size) as i64 - next_item_size as i64 ;
        if twice_left == 0 { score -= 35.0 ; }
        else if twice_left > 0 && (twice_left as u32) < item_size / 3 { score -= 22.0 - twice_left as f64 * 0.3 ; }
    }
    // discourage leaving residual far above mean (dead space hoarding), stronger late
    if post_residual > 0 && (post_residual as f64) > mean_residual * 1.8 && bin_residual != bin_capacity {
        score += 5.0 + progress * 8.0 ;
    }
    // late-phase compaction: prefer filling existing bins
    if progress > 0.85 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 8.0 + progress * 12.0 ;
    }
    // usable leftover after placing next item
    if post_residual > 0 && next_item_size > 0 {
        let leftover_after_next = (post_residual as i64 - next_item_size as i64) . max (0) as u32 ;
        if leftover_after_next > 0 && leftover_after_next < next_item_size / 2 {
            score -= (next_item_size / 2 - leftover_after_next) as f64 * 0.8 ;
        }
        if leftover_after_next >= next_item_size && leftover_after_next < 2 * next_item_size { score -= 18.0 ; }
    }
    // opening a new bin is only good if next item is large and fits are scarce
    if bin_residual == bin_capacity && open_bins_count > 2 && next_item_size > 0
        && next_item_size <= bin_capacity / 2 && fitting_bins_count <= 2 {
        score += 25.0 + progress * 10.0 ;
    }
    // small residual relative to mean is precious
    if post_residual > 0 && mean_residual > 0.0 && (post_residual as f64) < mean_residual * 0.4 { score -= 10.0 ; }
    // reuse ratio bonus
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let reuse = post_residual as f64 / next_item_size . max (1) as f64 ;
        if reuse >= 2.0 { score -= 6.0 + (reuse - 2.0) * 4.0 ; }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "slot band" it lands in.
    // Bands of 10 (capacity 100 => 10 harmonic slots).
    let band = (post_residual / 10) as f64;
    let band_center = band * 10.0 + 5.0;
    let within_band = post_residual as f64 - band * 10.0;

    // Penalize residuals that are "just off" a harmonic slot center (dead space).
    score += 1.5 * (within_band - 5.0).abs();

    // Reward exact small residuals: a residual of 0..=5 is nearly perfect packing.
    if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 15 {
        score -= 6.0;
    }

    // Lookahead coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let nmod = next_item_size % 10;
            // Harmonic alignment: next item divisible by 10 fits slot bands cleanly.
            if nmod == 0 {
                score -= 8.0;
            } else if post_residual % 10 >= nmod {
                score -= 4.0;
            }
            // Reward when post_residual is a tight shell around next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / cap).min(1.0);
        } else {
            // Next item cannot use this residual: residual likely becomes dead space.
            score += 5.0 + (post_residual as f64) * 0.05;
        }
    } else {
        // Last item: just minimize residual.
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral baseline slightly above good fits,
    // but preferable when mean residual across open bins is fragmented.
    if bin_residual == bin_capacity {
        let frag = mean_residual / cap;
        score = 10.0 + 8.0 * frag;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // Fresh bin guarantees a clean harmonic slot for next item.
            score -= 4.0 * (1.0 - (next_item_size as f64 % 10.0) / 10.0);
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64) * 0.15;

    // Progress-aware tiebreak: early in stream, prefer tight fits (low post_residual);
    // late in stream, allow slight preference for filling bins toward closure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let cap = bin_capacity . max (1) as f64 ;
    if post_residual == 0 { score -= 1000.0 ; }
    if next_item_size > 0 {
        if post_residual == next_item_size { score -= 600.0 ; }
        else if next_item_size <= post_residual {
            let chain_waste = post_residual - next_item_size ;
            if chain_waste <= 12 { score -= 240.0 - chain_waste as f64 * 1.2 ; }
            else { score -= 200.0 - chain_waste as f64 * 0.8 ; }
        } else {
            let gap = (post_residual as i64 - next_item_size as i64) . max (0) as f64 ;
