    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size && post_residual < next_item_size * 3 {
        score -= 15.0 + (next_item_size * 3 - post_residual) as f64 * 0.5 ;
    }
    if post_residual > 0 && post_residual <= 10 {
        let tightness = 1.0 - (mean_residual / cap) . min (1.0) ;
        score -= (10 - post_residual) as f64 * (1.0 + tightness * 2.0) ;
    }
    if step_index + 1 >= total_items . saturating_sub (50) && bin_residual != bin_capacity { score -= 20.0 ; }
    if bin_residual == bin_capacity && open_bins_count > 3 { score += 15.0 + open_bins_count as f64 * 0.5 ; }
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6 ;
    }
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size / 2 {
        score += (next_item_size - post_residual) as f64 * 0.9 * (1.0 - progress) * 20.0 ;
    }
    if next_item_size > 0 && post_residual >= 2 * next_item_size { score -= 10.0 + open_bins_count . min (10) as f64 ; }
    if fitting_bins_count <= 1 && bin_residual != bin_capacity { score -= 25.0 ; }
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 { score -= 30.0 ; }

    // --- new complementary terms (dead-space / residual shaping) ---
    if post_residual > 0 && next_item_size > 0 {
        // dead space that cannot hold the next item is penalized progressively
        if (post_residual as f64) < next_item_size as f64 {
            let dead = post_residual as f64 / cap ;
            score += dead * 90.0 * (0.4 + progress) ;
        }
        // reward nearly-full bins that still leave a usable sliver
        let fill = 1.0 - (bin_residual as f64) / cap ;
        if fill > 0.75 && post_residual > 0 { score -= 6.0 + fill * 8.0 ; }
        // leftover after placing next item: prefer compact remainders
        let leftover_after_next = (post_residual as i64 - next_item_size as i64) . max (0) as u32 ;
        if leftover_after_next > 0 && leftover_after_next < next_item_size / 2 {
            score -= (next_item_size / 2 - leftover_after_next) as f64 * 0.8 ;
        }
        if leftover_after_next >= next_item_size && leftover_after_next < 2 * next_item_size { score -= 18.0 ; }
        // two-step lookahead: item then next_item exactly exhausting the bin
        if item_size <= post_residual {
            let twice_left = (post_residual - item_size) as i64 - next_item_size as i64 ;
            if twice_left == 0 { score -= 35.0 ; }
            else if twice_left > 0 && (twice_left as u32) < item_size / 3 { score -= 22.0 - twice_left as f64 * 0.3 ; }
        }
        // discourage splitting bins whose residual exceeds mean by a wide margin late
        if (post_residual as f64) > mean_residual * 2.0 && progress > 0.5 { score += 10.0 + progress * 10.0 ; }
        // residual too small relative to mean is a good tight fit
        if mean_residual > 0.0 && (post_residual as f64) < mean_residual * 0.4 { score -= 10.0 ; }
        // next item plus residual would exceed capacity (next must go elsewhere): mild penalty
        if post_residual + next_item_size > bin_capacity { score += 4.0 + open_bins_count . min (8) as f64 * 0.5 ; }
        // reusable residual worth multiple next-items
        let reuse = post_residual as f64 / next_item_size . max (1) as f64 ;
        if reuse >= 2.0 { score -= 6.0 + (reuse - 2.0) * 4.0 ; }
        // dead fraction vs next item
        let dead_frac = post_residual as f64 / next_item_size . max (1) as f64 ;
        if dead_frac < 1.0 { score += (1.0 - dead_frac) * next_item_size as f64 * 0.12 * (0.6 + progress) ; }
        if fitting_bins_count <= 1 && post_residual >= next_item_size { score -= 8.0 ; }
    }
    // late-stage: strongly prefer using open bins over opening new ones
    if progress > 0.85 && bin_residual != bin_capacity && post_residual > 0 { score -= 8.0 + progress * 12.0 ; }
    // small residual bonus window widened slightly
    if post_residual > 0 && post_residual <= 20 { score -= (20 - post_residual) as f64 * 0.4 ; }
    // residual close to item size: near-perfect fit
    if post_residual > 0 && post_residual <= item_size && item_size > 0 {
        let ratio = post_residual as f64 / item_size as f64 ;
        score += (1.0 - ratio) * 5.0 * progress ;
    }
    // new-bin guard: only open a fresh bin when few fits exist and next item is large
    if bin_residual == bin_capacity && open_bins_count > 2 && next_item_size > 0
        && next_item_size <= bin_capacity / 2 && fitting_bins_count <= 2 {
        score += 25.0 + progress * 10.0 ;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps heavily (dead space archetype)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits
    score -= (item_size as f64 / bin_capacity as f64) * 30.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open bins pressure: discourage spreading when many bins open
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // New-bin candidate: make it moderately attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score -= 10.0 + mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if nxt <= post {
            // Next item fits here afterwards: strong reward scaled by closeness.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item would NOT fit after this placement: penalize wasted space.
            score += 15.0 + gap / bin_capacity as f64 * 20.0;
        }
    } else {
        // Last item: purely minimize post_residual.
        score -= 5.0;
    }

    // Compare against mean residual across open bins: prefer bins tighter than average.
    let post = post_residual as f64;
    score += (post - mean_residual) * 0.5;

    // Last chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        if fit_ratio > 0.5 {
            score -= 40.0;
        } else {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // existing bin gives a good fit (high waste everywhere).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 60.0;
        // If current item leaves large dead space in a new bin AND lookahead
        // won't fill it, opening a new bin is wasteful.
        if next_item_size > 0 && post_residual > next_item_size + 30 {
            score += 25.0;
        }
        // If the current bin barely fits the item anywhere (many bins fit),
        // a new bin is more acceptable.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // Early in stream, new bins are cheaper (more items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    } else {
        // Reward tight fits in existing bins.
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 20.0 * tightness;
        // Penalize leaving awkward residuals (hard to fill: small odd gaps).
        if post > 0 && post < 10.0 {
            score += 12.0; // tiny unusable slivers
        }
        // Reward post_residuals that are "nice" sizes (common item sizes).
        if post >= 10.0 && post <= 80.0 {
            score -= 3.0;
        }
    }

    // Slight preference to spread load when many bins are open and residuals high.
    if open_bins_count > 0 {
        score += mean_residual / (bin_capacity as f64) * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.02;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Reward tight fits: post_residual near zero gets strong bonus.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Penalize leaving residual that is too small for the smallest possible item (dead space).
    if post_residual < 1 {
        score -= 5.0; // perfect fill bonus
    } else if post_residual < 10 {
        score += 8.0; // unusable sliver
    } else if post_residual < 20 {
        score += 4.0;
    }

    // Lookahead coupling: reward if post_residual fits the next item well,
    // penalize if post_residual is just barely too small for next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 >= nx {
            let slack = post_residual as f64 - nx;
            // bonus decays with slack beyond next item
            score -= 10.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            // near-miss residual: wasted capacity relative to next item
            let miss = nx - post_residual as f64;
            if miss <= 10.0 {
                score += 6.0 * (1.0 - miss / 10.0);
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // mild penalty for spreading across many candidate bins
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: opening a new bin is expensive early/late depending on load.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64 / (1.0 + mean_residual.max(0.0));
        // New bins discouraged when existing bins have plenty of average residual,
        // more acceptable when open bins are nearly full or few bins exist.
        let open_cost = 40.0 + 10.0 * progress - 5.0 * open_pressure.min(3.0);
        // If no other bin fits, opening is the only option; soften cost.
        if fitting_bins_count == 0 {
            score = 5.0 + open_cost * 0.2;
        } else {
            score = open_cost + post_residual as f64;
        }
        // Late in stream, prefer filling existing bins more strongly.
        score += 15.0 * progress;
        return score;
    }

    // Prefer bins whose residual is close to the item (best-fit flavor) with nonlinear shaping.
    let fit_gap = (bin_residual - item_size) as f64;
    score += 0.05 * fit_gap;

    // Global state: if mean residual is high, prefer consolidating into bins below mean
    // (fills them down), which reduces fragmentation.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Mild reward for keeping number of open bins stable by using existing bins.
    score -= 1.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: prefer small post_residual, with non-linear sharpening over time.
    let mut score = post * (1.0 + 1.5 * progress * progress);

    // Smooth polynomial coupling of post_residual with stream progress:
    // wasted-space penalty grows super-linearly as the stream matures.
    let waste = norm_post * norm_post;
    score += 40.0 * waste * (0.4 + 1.2 * progress);

    // Dead-space cliff: tiny residuals are nearly useless; penalize smoothly.
    let tiny = (1.0 - norm_post.min(1.0)).max(0.0);
    score -= 25.0 * tiny * tiny * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Mild penalty for spreading across many open bins relative to mean residual.
    score += 0.05 * (open_bins_count as f64).sqrt() * (post - mean_residual).abs();

    // Lookahead: reward leaving room close to the next item size (smooth kernel).
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score -= 15.0 * (-gap / 20.0) * (1.0 - 0.5 * progress);
    }

    // New-bin candidate: keep it slightly attractive only when residual is full
    // and the fit is otherwise poor; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        score += 10.0 - 8.0 * (norm_post - 1.0).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
