pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Residuals divisible by common item sizes (or small) are more valuable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 1: perfect or near-perfect fit -> strongly reward
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    }

    // Harmonic class via modulo: leftover that is a multiple of a common size
    // (e.g. divisible by 10/20/25) can be filled by typical items later.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 5.0;
    }
    // Odd "dead zone" residuals (e.g. 11..19, 21..24 style gaps) are penalized
    let dead = post_residual > 10 && post_residual < 20;
    if dead {
        score += 6.0;
    }

    // Fraction-of-capacity thresholds on post_residual
    if pr > 0.5 * cap {
        score += 5.0; // leaving more than half empty is wasteful
    } else if pr < 0.25 * cap {
        score -= 5.0; // compact bins are good
    }

    // Lookahead coupling: if next item fits the post residual, reward strongly
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 + 10.0 * (1.0 - slack / cap);
    } else if next_item_size > post_residual {
        // next item won't fit here; penalize proportionally to how close it is
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / cap);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Many open bins: encourage consolidation onto existing bins
    score += 0.5 * open_bins_count as f64;

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.3 * (mean_residual - pr);

    // New-bin candidate: make it unattractive unless it would be a clean start
    if bin_residual == bin_capacity {
        // new bin is fine for big items or when nothing fits well elsewhere
        if item_size >= 60 || fitting_bins_count == 0 {
            score -= 12.0;
        } else {
            score += 25.0;
        }
    }

    // Progress-based nudge: later in stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space avoidance: residuals too small for the smallest plausible
    // item (1..100 interface range) are nearly worthless. Penalize gaps
    // that cannot fit the next item (or a small item in general).
    let min_item = 1u32;
    if post_residual < min_item {
        // cannot happen for valid bins, but keep safe
        score += 100.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // gap unusable by the lookahead item: dead space penalty scaled by
        // how close the gap is to being useful (small gaps are worst).
        let gap = post_residual as f64;
        score += 25.0 * (1.0 - gap / (next_item_size as f64 + 1.0));
    }
    // Very small leftover gaps (< 15) are almost certainly dead space.
    if post_residual > 0 && post_residual < 15 {
        score += (15 - post_residual) as f64 * 2.0;
    }

    // If this bin is the last chance (only fitting bin), avoid forcing a
    // bad fit that creates dead space; prefer it only if the fit is clean.
    if fitting_bins_count == 1 && post_residual > 0 && post_residual < 10 {
        score -= 20.0; // still better than opening a new bin for a near-perfect fit
    } else if fitting_bins_count == 1 {
        score -= 8.0; // mild last-chance preference to avoid bin proliferation
    }

    // Open-bin pressure: penalize opening new bins when many bins exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 0.4 * open_bins_count as f64 + 10.0 * progress;
