        // (handled implicitly since open-bin scores carry dead-space penalties)
    }

    // Slight preference for filling bins below mean residual (balancing).
    if !is_new_bin {
        score -= 0.05 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        // Perfect match bonus
        if post_residual == next_item_size {
            score -= 50.0;
        }
        // Penalize dead space that next item cannot use
        if post_residual < next_item_size {
            score += 10.0;
        }
    } else {
        // Last item: prefer tightest fit
        score += 5.0;
    }

    // Reward closeness to mean residual (keep bins balanced)
    score -= 2.0 * (1.0 - ((post_residual as f64 - mean_residual).abs() / bin_capacity as f64));

    // Last-chance bin before opening a new one: strong bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless residuals of open bins are very small
    if bin_residual == bin_capacity {
        let tight = mean_residual / bin_capacity as f64;
        score += 40.0 * (1.0 - tight);
    }

    // Slight preference for filling larger fraction of bin
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less post-residual relative to capacity is better.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 30.0;

    // Penalize wasting a large residual on a small item (dead space).
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // nearly perfect fit bonus
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into this bin's post-residual,
    // reward chaining placements; otherwise penalize awkward leftovers.
    if next_item_size > 0 {
