    // late in the stream, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.3 * progress;

    // Global state coupling: many open bins with high mean residual suggests
    // fragmentation; prefer bins below the mean residual (denser bins).
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // Penalize opening new bins when many bins already exist but are fragmented.
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64 * 0.5;
        // But if nothing fits well, new bin may win via low post_residual.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Mild penalty proportional to item size to discourage poor large-item placement.
    score += item_size as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
