pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are preferred (tight fits).
    let frac = post_residual as f64 / bin_capacity as f64;
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    }

    // Penalize residues that no plausible future item (1..=100) can use well:
    // residues in the "dead zone" (just above half) are hard to fill.
    if post_residual > 40 && post_residual <= 50 {
        score += 8.0;
    }

    // Modulo-class coupling with lookahead item: reward residues that the
    // next item can exactly or nearly fill.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 40.0;
        } else if gap <= 10 {
            score -= 15.0;
        } else {
