    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // current item is large or open bins are already fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / (bin_capacity as f64);
        // Prefer new bin if item is big (would leave tiny residue elsewhere anyway)
        // or existing bins are too full to be useful.
        if item_size >= 70 {
