pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: neutral baseline
    if bin_residual == bin_capacity {
        let mut nb = bin_capacity as f64 * 0.95;
        // Prefer new bin if no open bin fits well (last-chance logic)
        if fitting_bins_count <= 1 {
            nb -= 30.0;
        }
        // Late in stream, discourage opening bins unless really needed
        let progress = step_index as f64 / total_items.max(1) as f64;
        nb += progress * 10.0;
        // If next item is large, opening a fresh bin is safer
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            nb -= 15.0;
        }
        return nb;
    }

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 1.0 {
            score -= 40.0; // perfect chain: next item exactly fills this bin
        } else if post_residual >= next_item_size {
            // slack after placing next item — penalize proportional to waste
            let waste = post_residual as f64 - nxt;
            score -= 20.0;
            score += waste * 0.6;
        } else {
            // next item won't fit here; penalize dead space
            score += (nxt - post_residual as f64) * 0.5;
        }
    }

    // Reward tight fits relative to mean residual
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.4;
    } else {
        score += (res - mean_residual) * 0.3;
    }

    // Last-chance bonus: only fitting bin, use it to avoid new bin
    if fitting_bins_count == 1 && post_residual < 10 {
        score -= 25.0;
    }

    // Penalize leaving tiny unusable slivers
    if post_residual > 0 && post_residual < 5 {
        score += 15.0;
    }

    // Mild preference to keep bins balanced early on
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 - mean_residual).abs() * (1.0 - progress) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio in [0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: fraction of bin filled by this item
    let tightness = item_size as f64 / bin_capacity as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    // Reward tight fits strongly (non-linearly)
    score -= 40.0 * tightness * tightness;

    // Penalize large dead space after placement, worse as stream progresses
    score += 25.0 * post_frac * post_frac * (0.5 + 0.5 * progress);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New empty bin candidate: penalize mildly so it wins only when fits are poor
    if bin_residual == bin_capacity {
        score += 35.0 + 20.0 * progress;
        // But if item is large and mean residual of open bins is small, new bin is fine
        if (item_size as f64) > mean_residual {
            score -= 45.0;
        }
        // Early stream: opening bins is cheap and useful
        if progress < 0.2 {
            score -= 20.0;
        }
    } else {
        // Prefer bins whose residual is closest to item size (best fit coupling)
        let gap = (bin_residual as f64 - item_size as f64).abs();
        score += 0.15 * gap;
        // Reward bins with residual above mean (keep balanced usage)
        if bin_residual as f64 > mean_residual {
            score -= 8.0;
        }
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0;
    }
    // If next item would waste this bin's dead space, penalize small post residual
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Many open bins: prefer consolidating into existing ones
    if open_bins_count > 3 {
        score += 2.0 * open_bins_count as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_norm = (post_residual as f64 / cap).clamp(0.0, 1.0);

    // Base: waste after placement, with non-linear penalty on tiny residuals
    let mut score = pr + 12.0 * (1.0 - fit_norm) * (1.0 - fit_norm) * pr;

    // Smooth progress coupling: late in stream, penalize large residuals more
    score += pr * pr / cap * (0.5 + 1.5 * progress);

    // Exact fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: prefer only early or when all fits are terrible
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0 && item_size == 0 || (bin_residual == bin_capacity);
    if is_new_bin {
        let newbin_base = cap * 0.85 + 10.0 * progress * cap;
        // penalize opening new bin more when many bins can fit
        let crowd = (fitting_bins_count as f64).max(1.0);
        score = newbin_base + 2.0 * crowd;
        // but if current best-fit would leave huge dead space, allow opening
        if pr > 0.0 && pr < 20.0 {
            score += 15.0;
        }
    }

    // Lookahead: reward bins whose post-residual matches next item
    if next_item_size > 0 && !is_new_bin {
        let gap = (pr - next_item_size as f64).abs();
        score -= 8.0 * (1.0 - gap / cap).max(0.0);
    }

    // Mild penalty for too many open bins with high mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap).max(0.0);

    score
}

