pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: fraction of capacity remaining
    let frac = post_residual as f64 / cap;

    // Reward near-perfect fits strongly (non-linear)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // Dead-space penalty: residuals in awkward middle classes are hard to fill
    // (sizes 1..100 unknown distribution, but mid residuals ~30-60 are semi-usable,
    //  tiny residuals 1..9 are dead). Penalize tiny-but-nonzero residuals extra.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Harmonic coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits: reward proportional to how snugly
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here: mild penalty proportional to leftover class
            score += 20.0 * frac;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: neutral baseline; open a new bin only when existing fits are poor
    if bin_residual == bin_capacity {
        // Baseline score = full capacity; attractive when alternatives leave much dead space
        score = cap * 0.75;
        // Early in stream, prefer consolidation slightly; late, fresh bins are fine
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * (1.0 - progress);
        // If many bins open, prefer spreading (new bin) slightly
        score -= open_bins_count as f64 * 1.5;
        // If lookahead item is large, a fresh bin is valuable
        if next_item_size > 50 {
            score -= 30.0;
        }
    } else {
        // Prefer bins whose residual is above mean (use the emptier ones first)
        score += 10.0 * ((bin_residual as f64 - mean_residual) / cap);
    }

    // Modulo harmonic classes on post_residual (capacity fractions 1/4, 1/2, 3/4)
    let quarter = bin_capacity / 4;
    if post_residual == quarter || post_residual == 2 * quarter || post_residual == 3 * quarter {
        score -= 25.0; // exact quarter classes are reusable targets
    }

    score
}

