pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near match: next item fits snugly into the post-residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 40.0 * snug * snug;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot use this residual: penalize dead space proportionally.
        let dead = (post_residual as f64).max(1.0);
        score += 0.5 * dead * dead / bin_capacity as f64;
    }

    // Reward tight fits relative to the bin's current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize leaving residuals that are hard to fill (small awkward gaps).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Compare against mean residual across open bins: prefer bins that reduce spread.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate (empty bin): only attractive when existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let base = 0.5 * bin_capacity as f64;
        // If the current bin would leave a large awkward residual, opening a new bin is fine.
        if post_residual > 0 && post_residual < item_size && next_item_size > post_residual {
            score = base - 20.0;
        } else {
            score = base + 15.0;
        }
        // Fewer open bins -> slightly prefer opening fresh bins early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.83;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item leaves little waste.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 0.9 * fit_ratio * (bin_residual as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // Penalize dead space that is too small to host typical future items.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let dead_threshold = 10.0 + 8.0 * progress;
        if (post_residual as f64) < dead_threshold {
            score += 0.8 * (dead_threshold - post_residual as f64);
        }
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0 + 0.25 * next_item_size as f64;
        } else {
            score += 2.0;
        }
        // Penalize leaving a residual that wastes the next item's potential pairing.
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin before opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate logic: only attractive when current open bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin, softened when few bins fit well.
        let mut penalty = 12.0;
        if fitting_bins_count == 0 {
            penalty -= 20.0;
        } else {
            // Compare best possible fit among open bins: if all fits are loose, allow new bin.
            let loose = (bin_residual - item_size) as f64;
            if loose > 40.0 {
                penalty -= 6.0;
            }
        }
        // Late in the stream, avoid opening bins for marginal gains.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        penalty += 6.0 * progress;
        // Many open bins with large mean residual: prefer reusing them.
        penalty += 0.15 * open_bins_count as f64 + 0.05 * mean_residual;
        score += penalty;
    } else {
        // Mild preference to spread load when mean residual is high.
        score += 0.02 * (mean_residual - post_residual as f64).abs();
    }

    // Global balance: prefer bins whose post-residual approaches the mean residual.
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: waste after placement, softly compressed
    let mut score = post * (1.0 + 0.02 * post / cap);

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on tolerate slack; late, punish large residuals harder
    let w = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 40.0 * w * (post / cap).powi(3) * cap / 100.0;

    // Reward tight fits (small post_residual) non-linearly
    score -= 30.0 * (1.0 - post / cap).powi(4);

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 15.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // next item won't fit: penalize proportionally to wasted potential
        score += 8.0 * (1.0 - post / cap) * w;
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin, more so when other bins fit
    if bin_residual == bin_capacity {
        let penalty = 35.0 + 20.0 * (1.0 - w) + 10.0 * (fitting_bins_count as f64).min(5.0) / 5.0;
        score += penalty;
        // but if item is huge, opening a fresh bin is less bad
        score -= 12.0 * (item / cap);
    }

    // Mild bonus for bins with below-average residual (keeps bins homogeneous)
    score += 3.0 * ((bin_residual as f64 - mean_residual) / cap).tanh();

    // Slight preference for using existing bins as stream progresses
    if bin_residual < bin_capacity {
        score -= 5.0 * w;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual mod small moduli
    // captures "chunk-friendliness" of leftover space.
    let pr = post_residual;
    let m3 = (pr % 10) as f64;
    let m4 = (pr % 20) as f64;
    let m5 = (pr % 25) as f64;

    // Reward residuals that are harmonic with common item classes
    // (multiples of 10/20/25 leave room for typical item sizes).
    score -= 0.35 * (10.0 - m3).abs() * -1.0; // neutralize, then explicit below
    score += 0.0; // keep base

    // Penalize awkward residuals: near-misses just below typical sizes.
    for k in [10u32, 20, 25, 30, 40, 50, 80] {
        if pr > 0 && pr < k && pr >= k.saturating_sub(6) {
            score += 6.0 - (k - pr) as f64; // dead-space penalty
        }
    }

    // Reward exact harmonic residuals (perfectly reusable chunks).
    if pr == 0 { score -= 12.0; }
    else if pr % 10 == 0 { score -= 4.0; }
    else if pr % 5 == 0 { score -= 2.0; }

    // Lookahead coupling: if next item fits the post residual exactly or harmonically.
    if next_item_size > 0 {
        if next_item_size == pr { score -= 15.0; }
        else if next_item_size < pr && pr % next_item_size == 0 { score -= 6.0; }
        else if next_item_size > pr { score += 2.0; } // next item won't fit here anyway
        if pr >= next_item_size {
            score -= 3.0 * (pr - next_item_size) as f64 / 100.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // current fits are poor (large post_residual or awkward class).
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.9 + 5.0;
        // Cheap new bin if current placements are all bad.
        if fitting_bins_count >= 1 {
            let worst = (bin_capacity - item_size) as f64;
            if worst > 45.0 { score -= 10.0; }
        }
        if next_item_size > 0 && (bin_capacity - item_size) < next_item_size {
            score -= 5.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Progress-aware tightness bonus: tighter fits matter more early on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mean-residual deviation: prefer bins close to mean residual (balanced packing),
    // unless a very tight fit is possible.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * dev;
    if post_residual <= 5 { score -= 5.0; }

    // Small tie-breaker on m4/m5 harmonic classes.
    score += 0.02 * m4 + 0.02 * m5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size)
    // are worthless; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        // Gaps of 10..25 are only usable by small items; mild penalty scaled
        // by how "dead" the gap is relative to the mean residual.
        score += (25.0 - post_residual as f64) * 0.8;
    }

    // Reward tight fits (small waste relative to bin).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; discourage opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 12.0 + 2.5 * open_bins_count as f64 + 10.0 * progress;
    } else {
        score -= 1.5 * open_bins_count as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && !new_bin {
        score -= 20.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this
    // placement (chaining placements).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item would leave a dead gap after placement, penalize slightly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let nr = post_residual - next_item_size;
        if nr > 0 && nr < 10 {
            score += 10.0;
        }
    }

    // Prefer bins with below-mean residual (compact nearly-full bins first).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead: reward exact / near-exact match with next item ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as u32 >= next_item_size {
            // next item can also fit here -> strong reward, tighter match = better
            score -= 40.0 - diff.min(40.0);
        } else {
            // residual too small for next item: penalize proportional dead space
            let waste = post_residual as f64;
            score += 5.0 + waste * 0.3;
        }
    } else {
        // last item: only exact fill matters
        if post_residual == 0 {
            score -= 100.0;
        }
    }

    // --- dead-space penalty: tiny unusable leftovers ---
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // --- compare against mean residual of open bins ---
    // bins with residual below mean are "dying" bins: prefer filling them
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.1;
    }

    // --- last-chance bin: if this is the only fitting bin, strongly prefer it ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // --- new-bin candidate handling ---
    if bin_residual == bin_capacity {
        // opening a new bin: default is worse than a decent fit,
        // but attractive if no good fit exists (all fits would leave big waste)
        // baseline penalty, relaxed when many open bins are already fragmented
        let mut new_bin_score = 60.0;
        // if next item is large, a fresh bin is valuable for it
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            new_bin_score -= 20.0;
        }
        // late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += progress * 15.0;
        score = score.min(1e9); // sanity
        return new_bin_score.max(score.min(new_bin_score + f64::MAX)) * 0.0 + new_bin_score;
    }

    // --- fragmentation pressure: many open bins -> prefer tight fills ---
    score += open_bins_count as f64 * 0.5;

    // prefer smaller post residual overall (tight packing)
    score += post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (low post-residual) with a non-linear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio).powi(3);

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: if the next item fits into the post-residual, this placement
    // chains nicely — reward it proportionally to how snugly it fits.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_waste = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - chain_waste / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't chain here; slight penalty scaled by how close it was.
        score += 4.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate handling: empty bin should only win when existing bins
    // are poor fits. Penalize the fresh bin, more so when many bins are open.
    if bin_residual == bin_capacity {
        score += 35.0 + 2.0 * open_bins_count as f64;
        // But late in the stream, avoid proliferating bins with leftover space.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * (1.0 - progress);
    }

    // Prefer filling bins that are already well-used (below mean residual),
    // encouraging consolidation of open bins.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.25 * dev;

    // Mild pressure to close out bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let next = next_item_size as f64;
    let mean_r = mean_residual / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p = progress;
    score += 18.0 * norm_pr * norm_pr * (1.0 + p) - 14.0 * norm_pr * (1.0 - p);

    // Cubic coupling: penalize mid-range residual waste more as stream progresses
    score += 25.0 * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + p);

    // Reward tight fits (small post_residual) with smooth exponential term
    score -= 12.0 * (-(pr / 10.0)).exp();

    // Lookahead: reward if next item fits smoothly into post_residual
    if next > 0.0 && pr > 0.0 {
        let fit_gap = (pr - next).abs();
        score -= 10.0 * (-(fit_gap / 20.0)).exp();
        if next <= pr {
            score -= 6.0 * (next / pr);
        } else {
            score += 4.0 * ((next - pr) / cap);
        }
    }

    // Mean residual coupling: penalize bins far from the mean residual state
    score += 8.0 * (norm_pr - mean_r) * (norm_pr - mean_r) * (1.0 + p);

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it moderately attractive early, less so late
    if bin_residual == bin_capacity {
        score = pr + 15.0 * (1.0 - p) + 30.0 * p * p;
    }

    // Slight penalty for many open bins to encourage consolidation
    score += 0.15 * open_bins_count as f64 * (0.5 + p);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals that are multiples of common
    // item sizes are reusable, others are dead space.
    let pr = post_residual;
    let class_penalty: f64 = if pr == 0 {
        -60.0 // perfect fit
    } else if pr % 10 == 0 {
        -8.0 // highly reusable residual
    } else if pr % 5 == 0 {
        -3.0
    } else if pr >= 10 && pr <= 9 {
        0.0
    } else if pr < 10 {
        12.0 // unusable sliver
    } else {
        4.0
    };
    score += class_penalty;

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this residual: penalize small residuals more
            score += 6.0 * (1.0 - pr as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer opening a fresh bin when all open
    // fits would leave large fragmented waste relative to mean residual.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let waste = post_residual as f64; // = capacity - item
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 15.0 + 0.3 * fragmentation;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        } else if waste < mean_residual * 0.5 {
            score -= 10.0; // fresh bin leaves less waste than typical open bin
        }
        // avoid hoarding bins early in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 8.0 + open_bins_count as f64 * 1.5;
    } else {
        // mild bonus for filling bins tightly when many bins are open
        score -= 0.05 * open_bins_count as f64 * (item_size as f64 / bin_capacity as f64);
    }

    // Integer-division threshold: bins whose residual falls in [40,60] band
    // are the most flexible for mid-size items; keep them flexible.
    if pr / 20 == 2 {
        score -= 5.0;
    } else if pr / 20 == 0 && pr > 0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item (min size 1..10)
    // can ever use are pure waste. Penalize them quadratically.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0 * (10.0 - post_residual as f64);
        } else if post_residual < 20 {
            score += 12.0 * (20.0 - post_residual as f64);
        }
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Tightness of the fit relative to the item: reward placing into a bin
    // where the item fills a large fraction of the residual.
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 25.0 * fill_ratio;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 40.0;
            } else {
                score -= 8.0;
            }
        } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
            // next item cannot use this dead space either
            score += 15.0;
        }
