        if diff == 0.0 {
            score -= 60.0;
        } else {
            // Proximity bonus: closer match gets bigger reward, saturating.
            let prox = (next_item_size as f64 / (next_item_size as f64 + diff)).ln();
            score -= 12.0 * prox.max(0.0);
        }
        // Penalize post_residual slightly larger than next item (wasted single-digit space)
        if post_residual > next_item_size && post_residual - next_item_size < 5 {
            score += 8.0;
        }
        // Penalize leaving a sliver that nothing can use (next item won't fit)
        if post_residual < next_item_size && post_residual < 10 {
            score += 10.0;
        }
    } else {
        // Last item: just minimize residual (already the base), tiny extra pressure
        score += 0.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate penalty: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let good_fit_exists = next_item_size > 0
            && (post_residual as i64 - next_item_size as i64).abs() <= 3;
        if !good_fit_exists {
            // New bin gets a mild edge over bad fits but loses to tight fits
            score -= 5.0;
        } else {
            score += 40.0;
        }
        // Fewer open bins => opening new is cheaper
        if open_bins_count > 4 {
            score += 10.0;
        }
    }

    // Progress-based pressure: later in stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

