pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: classify post_residual by integer division into slack bands
    let band = post_residual / 10; // 0..=10 harmonic class
    match band {
        0 => score -= 50.0,            // tiny dead space, nearly perfect
        1 | 2 => score -= 20.0,        // small residual, likely reusable by small items
        3 | 4 => score += 10.0,        // awkward mid residual
        5 | 6 => score += 25.0,        // classic dead zone (50-70): hard to fill
        7 | 8 => score += 15.0,
        _ => {}                        // large residual: bin still flexible
    }

    // Modulo arithmetic: residuals congruent to small values mod 10 pair well with
    // item sizes in the 10..80 range which are multiples of 10 in classic streams
    let m = post_residual % 10;
    if m == 0 {
        score -= 8.0; // aligns with typical item granularity
    } else {
        score += m as f64 * 0.5;
    }

    // Lookahead coupling: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0; // chained perfect fit
        } else if next_item_size <= post_residual {
            score -= 40.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use residual: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // New-bin candidate handling: empty bin gets neutral-ish score unless current
    // fits are terrible; discourage opening new bins when a decent fit exists.
    if bin_residual == bin_capacity {
        score = 60.0 - 10.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 5.0;
        }
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative, must open
