pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: strongly reward exact match between
    // post_residual and the next item size (perfect follow-up placement).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: this bin is ideal for next item too
        } else if post_residual > next_item_size {
            // next item fits here afterwards; reward proportionally to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item would NOT fit after this placement; mild penalty scaled
            // by how far off we are, but only if this bin could have hosted it.
            if next_item_size <= bin_residual {
                let miss = (next_item_size - post_residual) as f64;
                score += 8.0 * (miss / bin_capacity as f64);
            }
        }
    }

    // Compare against mean residual across open bins: prefer bins that are
    // already more filled than average (below-mean residual), penalize
    // placements into unusually empty bins.
    let dev = mean_residual - post_residual as f64;
    score -= 0.3 * dev;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Penalize opening a new bin when open bins exist and fit is poor.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // New-bin candidate: only attractive if it enables a great 2-step chain.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 30.0;
        } else {
            score += 35.0;
        }
    }

    // Mild early-stream encouragement to consolidate (fewer bins early).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * fit_ratio;

    score
}

