    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Dead-space penalty: post residual too small for likely future items (1..100)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + 0.05 * next_item_size as f64;
        } else {
            // penalize leaving a gap that just barely fails the next item
            let miss = (next_item_size - post_residual) as f64;
            if miss < 20.0 {
                score += 0.4 * miss;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        let base = 20.0 + 30.0 * (1.0 - fit_ratio);
