    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let fit = fitting_bins_count as f64;
    let mean_r = mean_residual / cap;

    // Base: prefer small post_residual (tight fits), with non-linear sharpening.
    let mut score = pr + 40.0 * pr_norm * pr_norm * cap;

    // Late in the stream, tighten packing more aggressively (smooth coupling).
    score += 30.0 * progress * pr_norm * pr_norm * cap;

    // Penalize bins with many alternatives slightly less; last-chance bins get a reward.
    score -= 6.0 / fit;
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * progress;
    }

    // Reward placing into bins whose residual is far below mean (good utilization).
    score -= 5.0 * (mean_r - pr_norm);

    // Lookahead: penalize leaving a residual that barely fails to fit the next item.
    if next_item_size > 0 {
