            score -= 12.0 * (1.0 - (gap / cap).min(1.0)) * (1.0 - progress);
        } else {
            // Dead space relative to next item: penalize smoothly.
            score += 8.0 * (1.0 - (gap / cap).min(1.0)) * (1.0 - progress);
        }
    }

    // Mild penalty for proliferating bins early.
    score += 2.0 * open_bins_count as f64 * (1.0 - progress) * 0.05;

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (1.0 + fit) };
        score = cap as f64 * (0.6 + 0.4 * progress) - 15.0 * scarcity;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits strongly favored.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    } else {
        // dead-space classes: residues that few item sizes can use are bad
        // small residues (1..10) are nearly unusable -> penalize via class
        let class = post_residual % 10;
        score += (10 - class) as f64 * 1.5;
    }

    // Tightness ratio reward: prefer bins where item fills a large fraction.
    let fill = item_size as f64 / bin_residual as f64;
    score -= fill * 40.0;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // fraction of next item that post_residual can absorb
            let absorb = next_item_size as f64 / post_residual as f64;
            score -= absorb * 15.0;
            // harmonic compatibility: post_residual % next_item_size small => good
            if post_residual % next_item_size == 0 {
                score -= 25.0;
            }
        } else {
            // next item cannot use this residue: mild penalty scaled by wasted space
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        score += 55.0 + 0.2 * open_bins_count as f64;
        // but if item is large and mean residual is small, new bin is fine
        score -= (item_size as f64 / cap) * 30.0;
    }

    // Prefer bins with below-mean residual (consolidate nearly-full bins).
    score += (mean_residual - bin_residual as f64).max(-50.0) * 0.15;

    // Early stream: keep bins open, slightly prefer spreading into emptier bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64 / cap) * 10.0;

    score
}

