pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/chain fits with next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual == 0 {
            score -= 60.0; // perfect fill
        } else if (post_residual as f64 - n).abs() < 0.5 {
            score -= 55.0; // next item exactly fills this bin
        } else if post_residual >= next_item_size {
            // next item fits: reward small remaining gap after chain
