            score -= 30.0 - (chain_residual as f64) * 0.35;
        } else {
            // next item won't fit: penalize leftover dead space
            score += (n - post_residual as f64).min(n) * 0.25;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when decent fits exist, unless it enables
    // a perfect chain with the next item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let chain_bonus = if next_item_size > 0 && bin_capacity >= item_size + next_item_size { 25.0 } else { 0.0 };
