        // more open bins => new bins slightly cheaper to justify
        score -= open_bins_count as f64 * 0.5;
    }

    // Mild late-stream tightening: keep residuals low toward the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: squared post-residual penalty normalized.
    score += (post_residual as f64 / cap) * (post_residual as f64 / cap) * 40.0;

    // Penalize bins that are already nearly empty (bad targets unless nothing else).
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when no good fit exists or item is large.
        let tightness = item_size as f64 / cap;
        score = cap * 0.6 + post_residual as f64 - tightness * 30.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
        if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            score -= 10.0; // new bin leaves room for lookahead
        }
    } else {
        // Existing bin: reward using it, especially if it's the last fitting bin.
        if fitting_bins_count == 1 {
            score -= 25.0;
        } else if fitting_bins_count > 1 {
            score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
        }

        // Lookahead: reward if post-residual accommodates next item exactly-ish.
        if next_item_size > 0 {
            let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
            if post_residual as i64 >= next_item_size as i64 {
                score -= 15.0 / (1.0 + gap);
            } else {
                score += 5.0 + gap * 0.1; // next item won't fit; dead space risk
            }
        }

        // Prefer bins whose residual is close to the mean (balanced packing).
        score += (bin_residual as f64 - mean_residual).abs() * 0.15;

        // Early in stream: slightly favor filling bins fully; late: keep flexibility.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 5.0 * (1.0 - post_residual as f64 / cap);

        // Mild penalty for accumulating too many open bins.
        score += (open_bins_count as f64).ln() * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
