    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - pr_norm);
    }

    // mild penalty for spreading across many open bins late in the stream
    score += (open_bins_count as f64) * progress * 0.3;

    // smooth coupling: post_residual curvature interacting with mean residual
    let mr_norm = mean_residual / cap;
    score += (pr_norm - mr_norm).abs() * cap * 0.25;

    // quadratic dead-space penalty
    score += pr_norm * pr_norm * cap * 0.6 * (0.5 + progress);

    score
}

