pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "useful" sizes.
    // Class 0: post_residual is a multiple of 10 (clean slot) -> strong reward.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else {
        let class = pr % 10;
        if class == 0 {
            score -= 25.0;
        } else if class >= 7 {
            score += 12.0; // awkward dead space
        }
        // Small residuals are less valuable; compress score for tiny residuals
        if pr < 10 {
            score -= 15.0;
        }
    }

    // Lookahead coupling: reward if the next item fits exactly or tightly in post_residual.
