            if npr % 10 == 0 && npr > 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot use this residual: mild penalty scaled by wasted space
            score += 5.0 + pr as f64 / 20.0;
        }
    } else {
        // Last item: prefer any bin that closes waste
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin is expensive unless the current
    // fit is bad (large post_residual) or many bins already exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (bin_capacity - item_size) as f64;
        score = waste * 1.2 + 20.0 * (1.0 - progress);
        // If no open bin fits well (this is a fallback), make new bin attractive
