    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // Mild load balancing over time: more open bins -> prefer filling existing ones.
    score += 1.5 * open_bins_count as f64 * 0.01;

    score
