        score += 40.0 + (10 - post_residual) as f64 * 5.0;
    }
    // Perfect fit is the ideal outcome.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward leaving room for the lookahead item if it can fit in the gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
