pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    if post_residual > 0 {
        if post_residual <= 10 {
            // Tiny unusable gap: heavy penalty.
            score += (11 - post_residual) as f64 * 12.0;
        } else if post_residual < 20 {
            score += (20 - post_residual) as f64 * 3.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size > post_residual {
            // Dead space that the next item cannot use: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.6;
        } else {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize opening new bins when many are open;
    // the empty-bin candidate has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 1.5;
    } else {
        score -= open_bins_count as f64 * 0.3;
    }

    // Slight preference for bins tighter than average (better consolidation).
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Late-stream urgency: consolidate more aggressively near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0;

    score
}

