pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    let tightness = (bin_residual as f64 - item_size as f64).max(0.0);
    score -= (1.0 - tightness / bin_capacity as f64).powi(3) * 30.0;

    // Penalize dead space that no future item (min size 1..10 typical) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0; // hard-to-fill zone
    }

    // Lookahead coupling: reward bins whose post-residual matches next item well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= (1.0 - gap / bin_capacity as f64) * 12.0;
        } else {
            // next item won't fit here; mild penalty scaled by how much overflows
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score -= pressure * 2.0;

    // Time horizon: early in stream, be conservative about new bins;
    // late in stream, prefer finishing bins cleanly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.8 {
        // Endgame: penalize leaving large residuals spread across bins.
        score += (post_residual as f64 / bin_capacity as f64) * 10.0 * progress;
    } else {
        // Early: slight penalty for opening new bins when others fit.
        if bin_residual == bin_capacity {
            score += 15.0 * (1.0 - progress);
        }
    }

    // New-bin candidate scoring: only attractive when item is large relative to
    // capacity or no good existing fit exists.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score = bin_capacity as f64 - post_residual as f64; // = 0 baseline
        score += 20.0 * (1.0 - fill_ratio); // big items justify new bins
        if fitting_bins_count > 2 {
            score += 25.0; // plenty of alternatives; deprioritize new bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // new bin can also chain next item
        }
    }

    // Mean-residual alignment: prefer bins near the mean residual (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

