    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prog = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_n = pr / cap;
    let fill = 1.0 - (item_size as f64) / cap;

    // non-linear reward for tight fits
    score -= 18.0 * (1.0 - pr_n) * (1.0 - pr_n);

    // stream-progress coupling: tighter packing valued more as stream advances
    score -= prog * 12.0 * (1.0 - pr_n * pr_n);

    // penalty when post-residual is awkwardly small but nonzero (dead space)
    if pr > 0.0 {
        score += 8.0 * pr_n * (1.0 - pr_n) * (1.0 - (next_item_size as f64) / cap).max(0.0);
    }

    // lookahead: reward if next item fits into post-residual
    if next_item_size > 0 {
        let fits_next = (pr >= next_item_size as f64) as f64;
        score -= 15.0 * fits_next * (1.0 - pr_n);
    }

    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // mild penalty for many open bins with high mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);

    // smooth saturating squeeze on score
    score = score * (1.0 - 0.1 * prog * fill);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
