pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong best-fit core: exact fit is heavenly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class logic: classify post_residual into modulo classes of capacity.
    let pr = post_residual;
    let class = pr / 10; // integer division threshold classes: 0..10
    // Small dead space (class 0-2) is fine; mid classes are wasteful.
    match class {
        0 => score -= 40.0,
        1 => score -= 25.0,
        2 => score -= 12.0,
        3 | 4 => score += 15.0,
        5 | 6 => score += 8.0,
        _ => {}
    }

    // Reward if next item fits into post_residual (chain packing).
    if next_item_size > 0 && next_item_size <= pr {
        score -= 30.0 + 0.5 * (pr - next_item_size) as f64;
    } else if next_item_size > pr && pr > 0 {
        // post_residual too small for next item: dead space unless tiny.
        score += 0.3 * pr as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Many open bins: prefer consolidating (higher mean residual pressure).
    score += 0.05 * open_bins_count as f64;
    score -= 0.1 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let tight_exists = fitting_bins_count > 0 && post_residual as f64 <= 0.2 * cap;
        score += if tight_exists { 500.0 } else { -20.0 + 0.2 * open_bins_count as f64 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible item (<= 1) are pure loss; residuals that cannot
    // hold the NEXT item are also heavily penalized (dead gap).
    if post_residual == 0 {
        // perfect fit: strongly reward
        score -= 60.0;
    } else if post_residual < 10 {
        // unusable sliver: severe penalty
        score += 45.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // gap cannot host the lookahead item: dead space risk
        score += 18.0 + 0.25 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // gap can host the next item: reward tight chains
        score -= 8.0 + 0.10 * (post_residual - next_item_size).min(20) as f64;
    }

    // Tightness reward: prefer bins where the item fills a large fraction
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Open-bin pressure: with many open bins, discourage spreading into
    // yet another bin; encourage closing bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 1.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // If this bin is the ONLY fitting bin, strongly prefer using it
    // (last chance before opening a new bin).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin has a high baseline so it is
    // only chosen when open bins offer genuinely bad fits (large dead space).
    if bin_residual == bin_capacity {
        score += 55.0 + 0.5 * open_bins_count as f64;
        // late in the stream, opening new bins is even less attractive
        score += 20.0 * progress;
    } else {
        // mild preference for bins already below mean residual
        // (consolidating space)
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Slight overall preference for larger post_residual among good fits,
    // but capped so dead-space penalties dominate.
    score += 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
