    // Base: strongly prefer tight fits (small post-residual dead space)
    let cap = bin_capacity as f64;
    let frag = post_residual as f64 / cap;
    score += frag * frag * 40.0; // quadratic penalty on wasted fraction

    // Reward bins whose residual after placement could still host the next item
