            score -= (12.0 / (1.0 + chain_gap)).min(8.0);
        } else {
            // bin becomes dead for the next item; penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // last item: pure tightness matters most
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
        // even more attractive if the fit is decent
        if post_residual as f64 <= mean_residual {
            score -= 4.0;
        }
    }

    // New-bin candidate handling: opening a new bin is wasteful when other bins fit
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // penalize new bin, more so early in the stream when consolidation pays off
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 18.0 + 10.0 * (1.0 - progress);
            // extra penalty if an existing bin fits near-perfectly
            if let Some(_) = None::<u32> {} // no-op placeholder
            if item_size <= bin_residual {
                score += 2.0;
            }
        } else {
            // no open bin fits: opening a new bin is necessary, make it attractive
            score -= 8.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins to consolidate; few bins -> be pickier about fits
    let openness = open_bins_count as f64;
    score -= (openness / (openness + 5.0)) * 6.0; // mild consolidation pressure

