    match pr {
        10 | 20 | 30 | 40 => score -= 60.0,
        50 => score -= 20.0,
        _ => {}
    }

    // Dead space: tiny residuals (< 10) are unusable dead space.
    if pr > 0 && pr < 10 {
        score += 80.0;
    }

    // Modular coupling: if next item exactly consumes post_residual, big reward.
    if next_item_size > 0 && next_item_size == pr {
        score -= 500.0;
    }
    // Next item fits with a harmonic remainder.
    if next_item_size > 0 && pr >= next_item_size {
        let r2 = pr - next_item_size;
        if r2 % 10 == 0 {
            score -= 50.0;
        }
        if r2 == 0 {
            score -= 300.0;
        }
    } else if next_item_size > 0 && next_item_size > pr {
        // Next item cannot follow in this bin: penalize proportionally.
        score += 25.0;
    }

    // Integer division thresholds on post_residual vs capacity quarters.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if pr <= quarter && pr > 0 {
        score += 15.0; // cramped bin, mildly discourage unless harmonic
    } else if pr > half {
        score -= 10.0; // roomy bin, encourage filling
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: prefer existing bins generally; make new bin attractive
    // only when item is large and fits poorly anywhere.
    if bin_residual == bin_capacity {
        score += 120.0;
        if item_size > (bin_capacity * 3) / 4 {
            score -= 60.0; // big items: fresh bin reasonable
        }
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative
        }
    }

    // Stream progression: late in stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 80.0 * progress;
    } else {
        score -= 20.0 * progress;
    }

    // Mean residual coupling: if this bin is far below mean residual (tight bin),
    // prefer filling it to consolidate.
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.3;
    }

    score
}

