            }
        } else {
            // next item cannot fit here; penalize wasted potential proportional to overshoot
            let over = next_item_size - post_residual;
            score += 5.0 + (over as f64) * 0.25;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should only win when existing
    // residuals are harmonically poor relative to item_size
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score = (bin_capacity - item_size) as f64;
        // prefer new bin if item is large and would wreck a small residual elsewhere
        if item_size > 50 {
            score -= 15.0;
        }
        if next_item_size > 0 && next_item_size > item_size && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // stacking potential in fresh bin
