    score += (open_bins_count as f64) * 0.3;

    // Small penalty for large absolute deviation from mean residual (balance seeking)
    score += ((post_residual as f64) - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // are heavily penalized. Anything <= 9 is essentially dead space.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0;
    } else if post_residual > 9 && post_residual <= 20 {
        score += 18.0;
    }

    // Perfect fit bonus: strongly reward zero post_residual.
    if post_residual == 0 {
        score -= 45.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins
    // to avoid fragmentation; penalize opening yet another bin.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 4.0);
    score += 0.35 * pressure;

    // New-bin candidate (empty bin): penalize mildly so it only wins when
    // existing fits are very poor (its post_residual is large, so base score
    // already disfavors it; add a small extra penalty to break ties).
    if bin_residual == bin_capacity {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 9 {
            score -= 30.0;
        } else if slack <= 20 {
            score -= 10.0;
        }
    }

    // Mean residual coupling: if this bin's post_residual is far below the
    // mean residual, it's a good consolidation; reward it.
    let mean_gap = mean_residual - post_residual as f64;
    if mean_gap > 0.0 {
        score -= 0.15 * mean_gap.min(50.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly (non-linear).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward if the next item fits snugly into the post-residual.
    if next_item_size > 0 {
