        score += 40.0;
    }

    // Bonus for very tight fits (wasting almost nothing).
    if post_residual <= 5 {
        score -= 15.0;
    }

    // Penalize leaving a gap that is unusable for the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward gaps that exactly accommodate the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 3.0;
    } else {
        score -= open_bins_count as f64 * 0.5;
    }

    // Mild preference for bins tighter than the average residual.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Early-stream: allow new bins more freely; late-stream: consolidate.
