    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward an exact or near-exact
    // match between post_residual and the next item's size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
