        if gap == 0.0 {
            score -= 60.0;
        } else if gap <= 5.0 {
            score -= 25.0 - 3.0 * gap;
        } else {
            // Progressive penalty for residual the next item cannot use well.
            score += (gap - 5.0).min(60.0) * 0.35;
        }
        // If next item could instead fit this bin too after placement,
        // mild extra reward for keeping the bin chain alive.
        if next_item_size as u32 <= post_residual {
            score -= 4.0;
        }
    }

