    // Prefer placing into already-open bins over opening new ones,
    // scaled by how many bins are open (bin fragmentation pressure).
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Late in the stream, tighten packing: penalize loose residuals more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * progress * 0.20;

    // New-bin candidate: make an empty bin unattractive unless it is the only option;
    // the lookahead gap penalty above already handles poor fits into open bins.
    if bin_residual == bin_capacity {
        score += 10.0;
        // If the next item exactly fills what this item leaves, opening a fresh bin
        // is actually great (perfect 2-item chain).
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 70.0;
        }
    }

    score
}

