pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = post / cap; // normalized post residual in [0,1]

    // Base: penalize wasted space, with non-linear (quadratic/cubic) shaping
    let mut score = post * (1.0 + 0.5 * x * x);

    // Smooth stream-progress coupling: later in the stream, waste is costlier
    score += 40.0 * x * x * (0.5 + 0.5 * progress);

    // Reward tight fits (small post residual), smoothly
    score -= 20.0 * (1.0 - x) * (1.0 - x);

    // Lookahead: if next item fits the post residual, reward this bin smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let slack = (post - nx) / cap;
            score -= 15.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            let gap = (nx - post) / cap;
            score += 10.0 * gap * gap;
        }
    }

    // Last-chance bonus: only one bin fits; avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - x);
    }

    // Mild pressure to prefer bins below mean residual (consolidate fullness)
    score += 0.1 * (mean_residual - post).abs();

    // New-bin candidate: penalize mildly so it wins only when fits are poor
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "usable" residue classes.
    // Residuals that are multiples of small divisors pair well with typical item sizes.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0;
        if pr % 10 == 0 { harmony += 6.0; }
        if pr % 20 == 0 { harmony += 4.0; }
        if pr % 25 == 0 { harmony += 3.0; }
        if pr % 50 == 0 { harmony += 4.0; }
        // Small dead-space classes are bad
        if pr < 10 { harmony -= 12.0; }
        else if pr < 20 { harmony -= 5.0; }
        score -= harmony;
    } else {
        // Perfect fill: strongly favored
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        score -= 8.0;
        if slack as u32 % 10 == 0 { score -= 4.0; }
        if slack < 10.0 { score -= 6.0; }
    } else if next_item_size > 0 && next_item_size > pr {
        // Next item won't fit here; penalize trapping space
        score += (next_item_size - pr) as f64 * 0.15;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate: penalize slightly so we only open when open bins are bad,
    // but relax as stream progresses and mean residual grows (fragmentation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let new_bin_penalty = 5.0 + 8.0 * (1.0 - progress) + (mean_residual / 20.0).min(6.0);
        score += new_bin_penalty;
    }

    // Mild preference for tighter existing bins relative to mean residual
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Tie-break: prefer bins with residual close to a harmonic multiple of item_size
    if item_size > 0 && pr % item_size == 0 && pr > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..10)
    // are pure waste; penalize small unusable gaps super-linearly.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    } else if post_residual < 20 {
        // Medium-dead zone: still likely hard to fill.
        score += (20 - post_residual) as f64 * 2.0;
    } else {
        // Larger residual gaps are flexible: mild reward for keeping space.
        score -= 3.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 18.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > post_residual && post_residual < 10 {
        // Next item cannot use the tiny dead space: extra penalty.
        score += 12.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; encourage
    // filling existing bins, but allow a new bin when residuals are large
    // and fragmented (mean residual high means bins are mostly empty).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * progress);
    score += bin_pressure;

    // New-bin candidate logic: an empty bin has full residual; make it
    // attractive only when current bins would leave bad dead space or when
    // open-bin count is low (early stream). Otherwise make it costly.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        } else if post_residual > 20 && open_bins_count < 4 {
            score -= 5.0; // early stream: fresh bin is fine
        } else {
            score += 15.0 + mean_residual * 0.3; // prefer existing bins
        }
    }

    // Slight preference for bins whose residual is close to the mean
    // (keeps the pool of usable gaps homogeneous).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: prefer bins where the item leaves little dead space.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness;

    // Perfect match: post_residual exactly equals next_item_size => two items packed perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Next item fits exactly into post_residual region: strong lookahead reward.
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 20.0 * (-gap / 10.0);

        // Penalize leaving a residual that is too small for the next item (dead space).
        if post_residual < next_item_size {
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just minimize residual.
        score -= 15.0 * tightness;
    }

    // Compare against mean residual: bins with residual below mean are scarcer;
    // filling a small-residual bin tightly is good, but wasting a large-residual bin is fine.
    if (bin_residual as f64) < mean_residual {
        score += 5.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    } else {
        score -= 3.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are all poor fits.
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual.max(0.0);
        // Open new bin only if existing bins would leave large dead space.
        let existing_waste = post_residual as f64; // what we'd leave if we placed in an open bin
        if avg_waste > item_size as f64 + 5.0 {
            score -= 20.0; // open bins are roomy; new bin is fine too
        } else {
            score += 15.0 + existing_waste * 0.2;
        }
    }

    // Mild preference to consolidate into fewer bins as stream progresses.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
