    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Prefer filling bins with larger residuals when many bins are open
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Time horizon: early on, be more open to spreading; late, pack tightly
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 20.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: only attractive if no good fit exists
    if bin_residual == bin_capacity {
        if open_bins_count == 0 || fitting_bins_count == 0 {
            score -= 150.0;
        } else {
            // discourage opening new bins when existing bins can fit
            score += 90.0 + 2.0 * open_bins_count as f64;
            // but if the fit would leave a big unusable gap, allow new bin
            if post_residual < 15 {
                score -= 100.0;
            }
        }
    }

    score
}

