pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes of 10 (capacity decile)
    let pr = post_residual as i64;
    let cap = bin_capacity as f64;
    let class = (pr % 10) as f64;
    let quotient = (pr / 10) as f64;

    // Reward residuals that are "harmonic" multiples of common item sizes
    // Perfect-fit reward
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // penalize dead space below 10 (unusable given min item size 1..100 unknown,
        // so weight by class: residuals in {0 mod 25, 0 mod 20, 0 mod 50} are reusable)
        if pr % 25 == 0 || pr % 20 == 0 || pr % 50 == 0 {
            score -= 30.0;
        }
        // small dead-space penalty grows for tiny unusable leftovers
        if pr < 10 {
            score += 60.0;
        } else if pr < 20 {
            score += 15.0;
        }
        // class penalty: residuals just above a common size boundary waste space
        score += class * 0.8;
        score -= quotient * 2.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            score -= 20.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad,
    // but reward it early in the stream when few bins are open
    if bin_residual == bin_capacity {
        score += 40.0;
        if open_bins_count <= 2 {
            score -= 25.0;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Tight-fit bonus: item fills most of the bin
    let fill = item_size as f64 / cap;
    score -= fill * fill * 25.0;

    // Slight preference for bins below mean residual (balance)
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A post_residual below the minimum item size (1..100 stream => treat <8 as dead)
    // is wasted space; scale penalty nonlinearly.
    if post_residual > 0 {
        if post_residual < 8 {
            score += 60.0 * (8.0 - post_residual as f64);
        } else if post_residual < 15 {
            score += 12.0;
        }
    } else {
        // Perfect fit is ideal
        score -= 40.0;
    }

    // Reward filling a bin tightly relative to its residual before placement
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Pressure from number of open bins: discourage opening/spreading when many bins open
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if current item would leave dead space
        // in every fitting bin or no bin fits well.
        let dead_risk = if post_residual == 0 { 0.0 } else if post_residual < 8 { 1.0 } else { 0.4 };
        let pressure = open_bins_count as f64 * 2.5;
        score += 30.0 + pressure - 35.0 * dead_risk;
    } else {
        // Existing bin: slight reward when it is the last chance
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Prefer bins whose residual is close to item (best-fit coupling)
        score += 0.15 * (bin_residual as f64 - item_size as f64).abs();
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0;
    }
    if next_item_size > 0 && next_item_size as f64 > post_residual as f64 && post_residual > 0 && post_residual < 8 {
        score += 25.0; // next item can't use this dead gap
    }

    // Late-stream tightening: as stream progresses, favor tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * fill_ratio;

    // Mean residual coupling: prefer bins below mean residual (tighter bins first)
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

