    let mut score = post_residual as f64;

    // Strong reward when the leftover exactly accommodates the next item (2-step lookahead match).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= (bin_capacity as f64 - diff).max(0.0) * 0.5;
        // Exact match bonus: next item fills this bin completely afterward.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leftover that is too small for anything useful (dead space).
        if post_residual < next_item_size && post_residual < 10 {
            score += 25.0;
        }
    } else {
        // Last item: prefer tightest fit only.
        score -= 5.0;
    }

    // Prefer bins whose residual is already below average (consolidating large holes).
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.3;
    } else {
        score += (res - mean_residual) * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when good open bins exist, unless residual is tiny.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight_open = (bin_capacity as f64 - mean_residual).max(0.0);
        score += 15.0 + tight_open * 0.2 - progress * 5.0;
        // New bin is attractive if no open bin leaves room for the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Mild penalty for very large post-residual (wasted capacity).
    if post_residual > bin_capacity / 2 {
        score += (post_residual - bin_capacity / 2) as f64 * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

