    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Mild preference for bins with larger current residual when many
    // bins are open (consolidate load).
    score -= 0.02 * bin_residual as f64 / open_bins_count.max(1) as f64;

    score
}

