pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let min_item = 1u32;
    if post_residual < min_item && post_residual > 0 {
        score += 1000.0; // perfect fit bonus handled by low post_residual anyway
    }
    // Small gaps (below typical smallest item) are dead space
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += (30.0 - post_residual as f64) * 0.8;
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open bins pressure: discourage opening new bins when stream is long
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_penalty = (1.0 - progress) * 30.0 + open_bins_count as f64 * 1.5;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
    } else {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item nearly fits, slight reward
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size.saturating_sub(5) {
        score -= 4.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Slight preference for filling fuller bins
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 500.0; // perfect chain: next item exactly fills remainder
