    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize slightly unless current bins are crowded or fit is perfect
    if bin_residual == bin_capacity {
        score += 80.0 + open_bins_count as f64 * -5.0;
        if item_size > 60 {
            score -= 30.0; // big items may justify a fresh bin
