pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual via non-linear squash
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for any plausible item (1..=100)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual fits the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // extra reward for near-exact chain fit
            let chain_gap = post_residual - next_item_size as u32;
            score -= 8.0 * (1.0 - chain_gap as f64 / cap).max(0.0);
        } else {
            // next item can't follow here: mild penalty scaled by how far off
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / cap;
        }
    } else {
        // last item: prefer filling as much as possible
        score -= 20.0 * tightness;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Many open bins: discourage spreading; few open bins: encourage consolidation
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / cap);
    score += 2.0 * pressure * (post_residual as f64 / cap);

    // Time horizon: late in the stream, be conservative and fill existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 15.0 * progress * (bin_residual == bin_capacity) as i32 as f64;

    // New-bin candidate: must be worse than any reasonable fit unless residual is huge
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.3;
        // but early on with many items ahead, allow opening when current bins are crowded
        score -= 10.0 * (1.0 - progress) * (mean_residual < 20.0) as i32 as f64;
    } else {
        // prefer bins with below-mean residual (use up the emptiest-but-fitting bins)
        score += 0.15 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

