    score += dead_penalty;

    // Modulo-10 harmonic class: remainders congruent to small residues
    // (r % 10 in 1..=5) pair poorly with typical item sizes.
    let m = (r % 10) as f64;
    if r > 5 {
        if m >= 1.0 && m <= 5.0 {
            score += 4.0 + m;   // awkward class
        } else {
            score -= 1.0;       // friendly class (multiple of 10 or large residue)
