    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource; prefer it
    // only when the current bin would leave a very awkward residue.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset by how bad the alternative is.
        score = 35.0 + mean_residual * 0.15;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // a fresh bin always fits the next item; slight discount
            score -= 5.0;
