pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits (small post_residual) are worth more.
    let tight = (pr / cap).powi(2);
    score += tight * cap * (0.25 + 0.75 * progress);

    // Penalize mid-range residuals (awkward dead space) with smooth cubic term.
    let norm = pr / cap;
    score += 8.0 * norm * (1.0 - norm) * (norm - 0.5).abs() * (1.0 + progress);

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - tight);
    }

    // Lookahead: reward if next item fits well in the post-residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 12.0 * (1.0 - slack * slack);
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty for leaving residual far below mean residual (fragmentation).
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * (0.5 + 0.5 * progress);

    // Slight preference to keep fewer open bins when residuals are large.
    score += (open_bins_count as f64).sqrt() * norm * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the leftover space (integer division thresholds) ---
    // Classify post_residual into capacity-fraction bands; small leftovers are golden.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = post_residual / 10; // harmonic class 0..=10
    match class {
        0 => score -= 60.0,                 // near-perfect fill (0-9 dead space)
        1 => score -= 45.0,                 // excellent
        2 => score -= 30.0,                 // good
        3 => score -= 18.0,                 // decent
        4 => score -= 8.0,                  // fair
        5 => score -= 2.0,                  // half-empty: mediocre
        6 | 7 => score += 6.0,              // wasteful
        8 => score += 12.0,
        9 => score += 20.0,
        _ => {}                             // 100: the empty new-bin candidate
    }

    // Modulo coupling: leftovers that are friendly to common size classes (multiples of 10)
    // are more reusable than awkward leftovers.
    if post_residual > 0 && post_residual < bin_capacity {
        let friendly = (post_residual >= 10 && post_residual % 10 == 0)
            || (post_residual >= 20 && post_residual % 20 == 0);
        if friendly { score -= 5.0; }
        // leftover too small for the minimum item size is dead space
        if post_residual < 10 { score += 40.0; }
    }

    // Tight-fit bonus: relative waste of the placement
    let waste_frac = pr / cap;
    score += 25.0 * waste_frac * waste_frac;

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here: slight penalty for blocking
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or bins are getting very full on average.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap; // high => open bins nearly full
        let late = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_bonus = 18.0
            - 10.0 * pressure
            - 15.0 * (1.0 - pressure)
            - 5.0 * late;
        score += new_bin_bonus.max(-10.0);
        // never prefer a fresh bin if the item would leave a nice residual here anyway
        if post_residual <= 30 { score += 50.0; }
    } else {
        // prefer filling already-open bins; mild penalty grows with bin count
        score -= 3.0 + (open_bins_count.min(20) as f64) * 0.4;
    }

    // Prefer bins below mean residual (more room used already) when residuals are large
    if (bin_residual as f64) > mean_residual && post_residual > 40 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 12] are nearly unusable
    // (smallest conceivable future item is small, but gaps this tiny waste space).
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 * (1.0 - (post_residual as f64) / 12.0);
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward filling large fraction of the bin's residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than opening new ones.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin is attractive early (few open
    // bins, large lookahead item that won't fit leftovers) but costly when
    // many bins are already open.
    if bin_residual == bin_capacity {
        let prog = step_index as f64 / (total_items.max(1) as f64);
        let early_bonus = 30.0 * (1.0 - prog);
        score += 55.0 - early_bonus + 3.0 * open_bins_count as f64;
        // If the next item would fit in this fresh bin alongside current item,
        // opening is more justified.
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 20.0;
        }
    }

    // Lookahead synergy: if the leftover post_residual can still hold the next
    // item, this bin stays useful.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // leftover too small for next item -> dead space risk
        score += 10.0;
    }

    // Prefer bins whose residual is below average (compact the emptier bins
    // less, keep large residuals available for big future items).
    if (bin_residual as f64) < mean_residual {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits in the post residual -> reward proportional to lookahead size
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (next_item_size as f64 / 20.0);
    } else if next_item_size > 0 {
        // Dead space relative to the next item: penalize unusable remainder
        let waste = (next_item_size - post_residual) as f64;
        score += waste * 0.5;
    }

    // Tight fit reward: small post residual is good (unless it blocks next item, handled above)
    score -= (bin_capacity - post_residual) as f64 * 0.15;

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize spreading across many open bins slightly; encourage consolidation
    score += open_bins_count as f64 * 0.05;

    // Compare against mean residual: bins with residual far below mean are tight -> prefer them
    score += (mean_residual - post_residual as f64) * 0.2;

    // New-bin candidate: keep it neutral-to-slightly-high so it's chosen only when
    // no open bin offers a good fit (rewards above can still override)
    if bin_residual == bin_capacity {
        score += 15.0;
        // late in the stream, opening a new bin is less attractive
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.94;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let fit_frac = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * fit_frac * fit_frac;

    // Penalize dead space that no plausible future item can use:
    // residual below the minimum item size is pure waste.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 22.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Next item won't fit here; slightly penalize leaving awkward gaps.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Time horizon: later in the stream, consolidation matters more —
    // prefer filling existing bins over opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress;

    // Many open bins: encourage closing them out by using existing capacity.
    if open_bins_count > 4 {
        score += 0.8 * (open_bins_count as f64).ln();
    }

    // Global residual pressure: if mean residual is low, existing bins are
    // precious; prefer bins whose residual is near the mean (balanced use).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: make it attractive only when nothing fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when the item is large
        // or many bins are open (better to spread load).
        let mut new_bin_cost = 14.0;
        if item_size > 60 { new_bin_cost -= 6.0; }
        if open_bins_count > 6 { new_bin_cost -= 4.0; }
        if fitting_bins_count == 0 { new_bin_cost = 0.0; }
        score += new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer tight fits (low post_residual)
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, dead space matters more as we learn; later, keep bins flexible.
    let flex_penalty = 4.0 * norm_post * norm_post * (0.5 + progress)
        + 8.0 * norm_post.powi(3) * (1.0 - progress);
    score += flex_penalty * cap * 0.25;

    // Smooth interaction: large post_residual is worse when many bins are open
    let crowding = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += 6.0 * norm_post * crowding * cap;

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead coupling: reward post_residual that still fits the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 10.0 * (1.0 - slack).max(0.0);
        } else {
            // post_residual can't host next item -> smooth penalty
            let miss = (nxt - post) / cap;
            score += 8.0 * miss * miss * cap;
        }
    }

    // Slight reward for filling bins near mean residual alignment
    score -= 2.0 * (1.0 - ((post - mean_residual) / cap).abs().min(1.0));

    // Mild new-bin discouragement unless residual is truly tight
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * (1.0 - progress) + 4.0 * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward (subtract).
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of post_residual: classify residual into capacity fractions.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity left over

    // Dead-space penalty: residuals that are too small to be useful are bad.
    // Class boundaries via integer division on capacity (harmonic classes: /8).
    let class = post_residual / (bin_capacity / 8).max(1); // 0..8 class index
    let class_penalty = match class {
        0 => 120.0, // 1..12 residual: nearly dead space
        1 => 80.0,  // 13..24
        2 => 45.0,  // 25..36
        3 => 20.0,  // 37..49
        _ => 0.0,
    };
    score += class_penalty;

    // Lookahead: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward keeping room for the next item, scaled by how snugly it fits.
            let snug = 1.0 - ((post_residual - next_item_size) as f64 / cap);
            score -= 30.0 + 40.0 * snug;
        } else {
            // Post residual cannot host next item: penalize more if residual is small.
            score += 10.0 + 25.0 * (1.0 - frac);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate (empty bin) should only win when the current bin would
    // leave a very poor residual. Penalize empty-bin choice mildly otherwise.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.5 * mean_residual;
        // But if item is large relative to mean residual of open bins, opening
        // a fresh bin is less bad.
        if (mean_residual < item_size as f64) || open_bins_count == 0 {
            score -= 70.0;
        }
    }

    // Prefer filling bins when many bins are open (consolidation pressure).
    score += 0.3 * open_bins_count as f64;

    // Stream progression: late in the stream, be more aggressive about closing
    // bins tightly (small residuals are acceptable late).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item (<=10) are wasted.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open-bin pressure: penalize spreading across many bins mildly, so tight fits
    // into existing bins beat opening new ones.
    score += open_bins_count as f64 * 0.5;

    // Tightness coupling: reward filling bins that already have low residual.
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.1;

    // New-bin candidate handling: an empty bin gets a moderate default score so it
    // only wins when open-bin fits are genuinely poor (large dead space).
    if bin_residual == bin_capacity {
        score = 45.0 + open_bins_count as f64 * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits the next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item still fits, reward proportional to tightness.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + slack);
    }
    // Next item cannot follow into this bin: penalize creating dead space.
    else if next_item_size > 0 {
        let waste = next_item_size as f64 - post_residual as f64;
        score += 0.5 * waste.min(60.0);
    }

    // Penalize very small unusable residuals (dead space) harder.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Relative residual coupling: prefer bins below mean residual (tighter packing).
    score += 0.3 * (post_residual as f64 - mean_residual);

    // New-bin candidate: neutral baseline, slightly discouraged unless it beats
    // genuinely poor fits; encourage early in stream when few bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 70.0 + 40.0 * (1.0 - progress) - 5.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // Penalize dead space that likely cannot be reused: if next item cannot
    // fit in the post residual, the leftover is likely wasted.
    if next_item_size > 0 {
        if (post_residual as f64) < next_item_size as f64 {
            score += 0.35 * (post_residual as f64);
        } else {
            // Reward bins whose leftover can still host the next item.
            score -= 3.0 * (1.0 - (post_residual as f64) / (next_item_size as f64 + 1.0));
        }
        // Extra penalty if leftover is small but nonzero (worst dead space).
        if post_residual > 0 && (post_residual as u32) < next_item_size {
            score += 2.0 * ((next_item_size - post_residual as u32) as f64);
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 + 0.1 * (bin_residual as f64);
    }

    // New-bin candidate handling: an empty bin gets a mild exploration bonus
    // early, but a penalty late in the stream to force consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 6.0 + 18.0 * progress;
        // Discourage opening a new bin when decent open bins exist.
        if open_bins_count > 0 && post_residual as f64 > mean_residual {
            score += 4.0;
        }
    } else {
        // Favor bins with residual below the mean (denser bins) slightly.
        if (bin_residual as f64) < mean_residual {
            score -= 1.5;
        } else {
            score += 1.0;
        }
    }

    // Encourage filling nearly-full bins strongly as the stream progresses.
    score -= (1.0 - progress) * 0.0 + progress * (bin_capacity - post_residual) as f64 * 0.05;

    // Mild penalty for leaving residuals in the awkward 1..=9 dead zone.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let fit_ratio = item_size as f64 / cap;
    let post_norm = post / cap;

    // Base: prefer tight fits (low post residual), amplified quadratically.
    let mut score = post + 12.0 * post_norm * post_norm * cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap; late, dead space is heavily penalized.
    let late = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 30.0 * late * post_norm * (1.0 - fit_ratio);

    // Reward filling bins nearly exactly, stronger as stream progresses.
    score -= 20.0 * (1.0 - post_norm) * (1.0 - post_norm) * (0.5 + late);

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * late;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 8.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 5.0 * (nxt - post) / cap;
        }
    }

    // Mild penalty for spreading across many open bins when mean residual is small.
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);

    // New-bin candidate: keep it competitive only when open bins are nearly full.
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - late);
    }

    score
}

