pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity divided into 10 classes of 10
    let class = post_residual / 10;
    // Reward small classes (tight fits) nonlinearly
    score -= (10 - class) as f64 * 3.0;

    // Dead-space penalty: residual that cannot hold even the smallest item (<=9)
    if post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // next item cannot use this leftover; penalize proportionally to waste
            let waste = post_residual as f64 / bin_capacity as f64;
            score += waste * 20.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Modulo/harmonic thresholds on post_residual: residues near multiples of 25
    let m = post_residual % 25;
    if m == 0 {
        score -= 10.0; // clean harmonic split
    } else if m < 10 {
        score += (10 - m) as f64; // small unusable fringe
    }

    // Prefer filling bins that are already relatively full
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * 12.0;

    // New-bin candidate handling: empty bin gets a mild handicap unless stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 20.0 * progress;
    }

    // Spread pressure: many open bins with high mean residual -> prefer consolidating
    if open_bins_count > 1 && (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Dead space = post_residual that is too small to fit even the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver
    } else if post_residual < 25 {
        score += 25.0; // likely dead space for most item sizes
    } else if post_residual < 50 {
        score += 8.0; // moderately risky gap
    } else {
        score -= 6.0; // large remaining space is reusable
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize leaving a gap that just barely fails to fit the next item (near-miss waste)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 * 1.0 as f64 {
        // gap exists but next item won't fit: dead space confirmed
        score += (next_item_size as f64 - post_residual as f64).min(20.0);
    } else if next_item_size > 0 && post_residual >= next_item_size as f64 {
        score -= 12.0; // next item fits here: strong chaining reward
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing ones
    let pressure = open_bins_count as f64 / (mean_residual.max(1.0) / bin_capacity as f64).max(0.05);
    score += pressure * 1.5;

    // Last-chance bin: strongly prefer using the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Slight early-stream bias toward filling bins tightly (build compact bins early)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    // Mild preference relative to mean residual: bins with below-average residual are more "packed"
    score -= (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: neutral baseline, slightly above tight fits.
    if bin_residual == bin_capacity {
        return 100.0 + 0.5 * mean_residual;
    }

    // Core: reward bins where the next item also fits (2-step lookahead match).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits: strong reward proportional to how well it nests.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - 0.3 * slack;
        } else {
            // Next item won't fit: penalize wasted lookahead potential,
            // scaled by how close we came (near-miss is less wasteful).
            let miss = (next_item_size - post_residual) as f64;
            score += 0.4 * miss;
        }
    } else {
        // Last item: just minimize post residual.
        score -= 20.0;
    }

    // Reward tight fits relative to current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Compare post_residual against mean residual: prefer leaving typical space.
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Early in stream: be more conservative with dead space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

