pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared waste penalty.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize creating dead space too small for any item (min item size 1... use 10-ish threshold).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= (next_item_size as f64) * 0.5;
        } else {
            // Next item won't fit here; penalize blocking a large residual usage.
            score += (next_item_size as f64 - post_residual as f64).max(0.0) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 150.0;
    } else if fitting_bins_count > 1 {
        // Many alternatives: mild penalty to prefer the tightest among them via post_residual already.
        score += 10.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate logic: empty bin gets a baseline penalty so we prefer existing bins,
    // but relax it as the stream progresses or when mean residual is low.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 120.0 - 60.0 * progress;
        if mean_residual < 5.0 {
            score -= 50.0;
        }
        // If next item is huge, opening a fresh bin now may be wise.
        if next_item_size > bin_capacity as u32 / 2 {
            score -= 30.0;
        }
    }

    // Global pressure: many open bins with high mean residual -> prefer filling existing bins.
    if open_bins_count > 0 {
        score -= (mean_residual / open_bins_count as f64) * 0.1;
    }

    // Time horizon: early in the stream, keep bins flexible (mild penalty for small post residual);
    // late in the stream, cram aggressively.
    if progress < 0.5 {
        if post_residual > 0 && post_residual <= 15 {
            score += 25.0 * (1.0 - progress * 2.0);
        }
    } else {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
