pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Smooth polynomial base: prefer small post_residual, with non-linear sharpening.
    let mut score = post
        + 30.0 * norm_post * norm_post * (1.0 - norm_post)
        + 20.0 * norm_post * norm_post * norm_post;

    // Stream-progress coupling: late in the stream, dead space hurts more.
    score += 40.0 * progress * norm_post * norm_post;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mean-residual coupling: if this bin is below-average residual (tighter),
    // reward using it; smooth quadratic term.
    let diff = (mean_residual - bin_residual as f64) / cap;
    score -= 15.0 * diff * diff * (1.0 - 2.0 * diff);

    // Lookahead: penalize if post_residual cannot fit next item.
    if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
        score += 8.0 * (next_item_size as f64 - post) / cap * (1.0 + progress);
    }

    // Mild penalty for opening a new bin when many bins are open.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (open_bins_count as f64 / (1.0 + open_bins_count as f64));
        // But reward new bin if post_residual would be very tight for next item.
        if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are multiples of
    // common item sizes are more likely to be reused later.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Reward residuals lying in "harmonic" residue classes (multiples of 10/20/25)
    let harmonic_bonus = if post_residual % 10 == 0 {
        8.0
    } else if post_residual % 20 == 0 {
        6.0
    } else if post_residual % 25 == 0 {
        5.0
    } else if post_residual % 5 == 0 {
        2.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Penalize tiny dead space (< 10) which is unusable
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Perfect fit: zero post-residual is ideal
    if post_residual == 0 {
        score -= 40.0;
    }

    // Coupling with next item lookahead: if next item fits exactly in post_residual
    if next > 0.0 {
        if post_residual as u32 == next_item_size {
            score -= 18.0;
        } else if post_residual as u32 > next_item_size {
            // next item fits, good chain
            score -= (next / cap) * 6.0;
        } else {
            // next item cannot use this residual; penalize proportionally
            score += (1.0 - (pr / cap)) * 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no open bin offers a good fit. Make empty bin score ~capacity + penalty.
    if bin_residual == bin_capacity {
        // baseline: new bin is mediocre; slightly better when many bins open
        // and mean residual is low (existing bins nearly full)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * 0.9 + (1.0 - progress) * 5.0 - (mean_residual / cap) * 10.0;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Tightness reward: prefer bins where item fills a large fraction of residual
    let fill_ratio = item / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Slight preference for bins below mean residual (consolidating fullness)
    if (bin_residual as f64) < mean_residual && bin_residual < bin_capacity {
        score += 3.0;
    }

