                score -= 8.0;
            }
            if post_residual == 0 {
                score -= 20.0;
            }
        }
    } else {
        // perfect fit: zero waste, strongly favored
        score -= 30.0;
    }

    // Prefer tighter fits relative to bin residual (best-fit flavor)
    score += 0.3 * (bin_residual as f64 - item_size as f64).abs();

    // Open-bins pressure: with many open bins, discourage opening new ones
    // and encourage consolidating into existing bins.
