    let pressure = open_bins_count as f64 / (1.0 + progress * 5.0);
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more when many bins are already open
        score += 25.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * pressure.min(15.0);
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (i.e., fuller bins), keeping emptier bins flexible for large items.
    if bin_residual as f64 > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }

