    // Penalize dead space that cannot fit typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would leave this bin stranded anyway, mild penalty
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening new bins early / when open bins exist and fit
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 15.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 18.0;
        }
        // fewer open bins relative to items -> opening a bin is cheaper
        score -= (open_bins_count as f64).ln().max(0.0) * 3.0;
    }

    // Prefer bins with residual below mean (filling tighter bins first)
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Slight preference for larger residual bins when item is large
    score -= (item_size as f64 / bin_capacity as f64) * (bin_residual as f64 - item_size as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post-residual in [0,1]

    // Base: prefer tight fits (low post-residual), with non-linear shaping
    let mut score = pr as f64;
    score += 30.0 * x * (1.0 - x);          // penalize mid-range residuals (awkward dead space)
    score -= 25.0 * x * x * x;              // reward very small residuals extra

    // Stream-progress coupling: late in the stream, tighten further (smooth polynomial)
    let p2 = progress * progress;
    score *= 1.0 + 0.6 * p2 * (1.0 - progress);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - x);
    }

    // Lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let compat = (pr - n).abs();
        score -= 15.0 * (1.0 - compat / cap).max(0.0);
        // exact fit for next item is highly desirable
        if pr >= n && (pr - n) as u32 <= 5 {
            score -= 20.0;
        }
    }

