    let congestion = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (mean_residual / cap);
    score += 20.0 * congestion * (1.0 - x);

    // New-bin candidate: neutral-ish but slightly penalized so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 10.0 + 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: exact / small / medium / large dead space.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap;

    // Reward near-exact fits strongly (residual in {0, 1..5} is ideal).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 250.0;
    } else if post_residual <= 15 {
        score -= 80.0;
    } else {
        // Large leftovers: penalize proportionally above the raw residual.
        score += 40.0 * frac * frac;
    }

    // Harmonic residue classes: leftover mod 10 (typical item granularity).
    // A leftover that is a multiple of 10 is reusable by common item sizes.
    let r10 = post_residual % 10;
    if r10 == 0 && post_residual > 0 {
        score -= 60.0;
    } else {
        score += 10.0 * r10 as f64;
    }

    // Lookahead: does the next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect class match: next item exactly consumes the leftover.
            if next_item_size == post_residual {
                score -= 300.0;
            } else {
                score -= 120.0 * (next_item_size as f64 / post.max(1.0));
            }
        } else {
            // Leftover can't host the next item: penalize dead space relative to next item.
            score += 0.5 * (next_item_size as f64 - post).max(0.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, softened when the stream is early
        // (many future items justify fresh bins) or many bins are open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 150.0 + 100.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 50.0; // fresh bin trivially hosts next item
        }
        if item_size >= 60 {
            score -= 30.0; // big items pair well in fresh bins
        }
    }

    // Mild pressure against proliferating bins when mean residual is high.
    score += 0.05 * mean_residual * (open_bins_count as f64).sqrt();

    score
}

