        } else {
            // Dead space relative to next item: penalize small unusable leftovers.
            score += 40.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Penalize creating tiny unusable gaps (waste < 10, the minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward tightening bins relative to the current mean residual.
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it before opening a new bin.
