        score -= 80.0;
    }

    // New empty bin candidate: must not win unless open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 150.0 + 0.5 * item_size as f64;
    }

    // Late in the stream: prefer consolidating into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (open_bins_count as f64 / (fitting_bins_count.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable sliver
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits into post-residual (chaining), penalize otherwise.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.1 * next_item_size as f64;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 0.08 * (next_item_size - post_residual) as f64;
        }
        // Perfect pairing: post-residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: opening a bin is expensive early, cheaper late.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // Penalize new bins, but less as stream progresses or when open bins are fragmented.
        score += 20.0 - 12.0 * progress;
        if mean_residual > item_size as f64 {
            score += 5.0; // existing bins have room; avoid opening new one
        }
    } else {
        // Slight preference for bins below mean residual (consolidate large gaps).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    // Late-stream pressure: fill existing bins harder as the stream ends.
    score -= 6.0 * progress * tightness;

    // Mild penalty for spreading across many open bins when item is large.
    if item_size > bin_capacity / 2 {
        score += 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
