    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in small "unusable" residue classes is penalized
    let pr = post_residual;
    // Residues that are hard to fill (very small leftovers) get extra penalty
    if pr > 0 {
        let class = pr % 10;
        let dead_penalty = match class {
            0 => 0.0,          // perfectly divisible, reusable
