        score += dead_penalty;

        // Integer-division threshold: post_residual below 10 is almost dead space
        if pr < 10 {
            score += 15.0;
        }
    }

    // Perfect fit reward (harmonic zero class)
    if pr == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
