        if item_size >= 60 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size > item_size {
            score += 5.0;
        }
    } else {
        // Reward tight fills (small post_residual relative to capacity fraction classes)
        let fill_frac = item_size as f64 / cap;
        score -= 20.0 * fill_frac;

        // Phase of the stream: early on, be conservative with tight bins
        let progress = step_index as f64 / total_items.max(1) as f64;
