if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 && progress > 0.3 {
    score -= 6.0 + progress * 6.0;
}
if post_residual > 0 && post_residual <= 5 {
    score -= (6 - post_residual) as f64 * 1.5 * (0.5 + progress);
}
if bin_residual == bin_capacity && open_bins_count > 5 && next_item_size > 0 && next_item_size <= bin_capacity / 3 {
    score += 12.0 + open_bins_count as f64 * 0.4;
}
score }

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness;

    // Aggressive 2-step lookahead: if the next item fits exactly (or well) into
    // the post_residual, strongly reward this placement.
    if next_item_size > 0 {
        let next_fits = (next_item_size as f64) <= (post_residual as f64);
        if next_fits {
            // Perfect match: post_residual == next_item_size is ideal.
            let match_gap = ((post_residual as i64) - (next_item_size as i64)).abs() as f64;
            score -= 40.0 * (1.0 - match_gap / (bin_capacity as f64));
        } else {
            // Next item cannot use this bin's leftover space: penalize dead space.
            score += 12.0 * (post_residual as f64) / (bin_capacity as f64);
        }
    }

    // Compare against mean residual: placing into a bin whose residual is far
    // above the mean (a large leftover) is preferable to fragmenting small ones.
    let residual_gap = (bin_residual as f64) - mean_residual;
    score -= 8.0 * residual_gap / (bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that can fit the item, use it
    // rather than opening a new bin (avoid penalizing it toward new-bin choice).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it unattractive unless open bins are all poor fits.
    // Penalize proportional to stream progression (late in stream, prefer reuse).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 40.0 * progress;
        // If no existing bin fits, new bin is the only option: soften penalty.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild penalty for leaving very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

