pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post-residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space that no future item (>=1) can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers
    }

    // Last-chance bonus: only one bin can fit the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: reward if next item fits exactly into the post-residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty for wasting residual
            score += 6.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Time horizon: early on, prefer spreading into new bins; late, pack tight
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 12.0 * (bin_residual as f64 / bin_capacity as f64);

    // Global state coupling: many open bins with high mean residual -> discourage new-bin-like behavior
    let openness = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += openness * (mean_residual / bin_capacity as f64) * 10.0;

    // New-bin candidate handling: empty bin has residual == capacity
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer new bin when item is large relative to capacity or few fitting bins
        score += 30.0
            - 25.0 * (item_size as f64 / bin_capacity as f64)
            - 10.0 * (fitting_bins_count as f64).recip()
            + (1.0 - progress) * 8.0;
    } else {
        // Favor using existing bins generally
        score -= 5.0;
    }

    // Nonlinear coupling: prefer bins whose residual is close to item size
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * fit_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: penalize leftover space, with non-linear (quadratic) dead-space cost
    let mut score = pr + 12.0 * fit_norm * fit_norm * cap;

    // Smooth stream-progress coupling: early on, prefer tight fits more strongly
    let tightness = 1.0 - fit_norm;
    score -= 8.0 * (1.0 - progress) * tightness * tightness * cap * 0.1;

    // Reward filling bin almost exactly when lookahead can use remainder
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score -= 6.0 * (1.0 - gap / cap) * (1.0 - progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - progress);
    }

    // Mild penalty when bin residual deviates from mean residual of open bins
    score += 0.05 * (pr - mean_residual).abs();

    // Prefer consolidating into fewer bins
    score += 0.5 * open_bins_count as f64 * (1.0 - fit_norm);

    // New-bin candidate: make empty bin mildly attractive only when current bin leaves large waste
    if bin_residual == bin_capacity {
        score = pr + 10.0 - 4.0 * (1.0 - progress) * (1.0 - tightness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo-10 residue class
    let class = post_residual % 10;
    // Residues 0 (perfect fit) and small residues are the most reusable
    let class_bonus = match class {
        0 => 12.0,
        1 => 8.0,
        2 => 5.0,
        3 => 3.0,
        4 => 1.5,
        5 => 2.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Dead-space penalty: post residual too small for any item (sizes >= 1)
    if post_residual == 0 {
        score -= 25.0; // perfect fit, strongly favored
    } else if post_residual < 10 {
        score += 15.0; // unusable dead space
    }

    // Integer division threshold: can the next item fit here?
    let next_fits = next_item_size > 0 && post_residual >= next_item_size;
    if next_fits {
        // Reward chains where the leftover exactly matches the next item class
        if post_residual == next_item_size {
            score -= 20.0;
        } else {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // Leftover cannot host the next item: penalize proportionally
        score += (next_item_size as f64) * 0.15;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // New-bin candidate: only open a new bin when no open bin is a good fit
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 20.0;
        // If many bins can fit the item, discourage opening a new one
        if fitting_bins_count > 0 {
            score += 30.0;
        }
        // If no other bin fits (fitting_bins_count counts only open bins),
        // opening is unavoidable; soften the penalty late in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * (1.0 - 0.3 * progress);
    }

    // Prefer tighter bins overall: compare against mean residual
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Fraction-of-capacity coupling: reward filling bins past half capacity
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    if fill_frac > 0.5 {
        score -= 4.0 * (fill_frac - 0.5);
    }

    score
}

