pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in the "unusable gap" band
    // (small slivers that few future items can fill) is heavily penalized.
    let dead_threshold = 12u32;
    if post_residual > 0 && post_residual <= dead_threshold {
        let severity = (dead_threshold - post_residual + 1) as f64;
        score += 40.0 + 8.0 * severity;
    }
    // Perfect or near-perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Reward tight fits relative to the item itself.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Penalize wasting a large residual on a small item.
    if (post_residual as f64) > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or late in stream.
        score += 25.0 + 2.0 * open_bins_count as f64 + 20.0 * progress;
        // If no other bin fits, opening a new bin is acceptable.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it to avoid a new bin.
        score -= 45.0 + 1.5 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Post residual too small for next item: mild penalty.
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead coupling ---
    if next_item_size > 0 {
        let next_fits = (post_residual as u32) >= next_item_size;
        if next_fits {
            // Reward bins that can also host the next item (perfect chain).
            let slack_after_next = post_residual as f64 - next_item_size as f64;
            score -= 12.0 + 0.35 * (bin_capacity as f64 - slack_after_next) * 0.1;
        } else {
            // Penalize leaving a gap the next item cannot use (dead space).
            let gap = post_residual as f64;
            score += 0.25 * gap;
            // Extra penalty if the gap is small and unusable.
            if gap < next_item_size as f64 * 0.5 {
                score += 8.0;
            }
        }
    }

    // --- Tight-fit reward: small post_residual is good (when not dead space) ---
    score -= 0.15 * (bin_capacity as f64 - post_residual as f64);

    // --- Relative-to-mean residual coupling ---
    let residual_f = post_residual as f64;
    if residual_f < mean_residual {
        score -= 0.20 * (mean_residual - residual_f);
    } else {
        score += 0.10 * (residual_f - mean_residual);
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // Strongly favor the only bin that fits, avoiding a new bin.
        score -= 15.0;
    }

    // --- New-bin candidate handling (empty bin: residual == capacity) ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly
        // (post_residual is small/dead) or many bins are already open.
        let poor_fit = if next_item_size > 0 && post_residual < next_item_size { 10.0 } else { 0.0 };
        let dead = if post_residual > 0 && post_residual < 10 { 12.0 } else { 0.0 };
        let crowding = 0.30 * open_bins_count as f64 * (1.0 - progress);
        score += 18.0 - poor_fit - dead - crowding;
    }

    // --- Late-stream tightening: prefer fuller bins as stream progresses ---
    score -= 4.0 * progress * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
