        if mean_residual >= item_size as f64 {
            score += 10.0;
        }
    } else {
        // Reward using existing bins with above-average residual (balance load).
        if bin_residual as f64 > mean_residual {
            score -= 2.0;
        }
    }

    // Mild penalty for creating very small unusable residuals (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Encourage consolidation: fewer open bins -> prefer filling existing bins.
    score -= (open_bins_count as f64).ln().max(0.0) * 0.5;

