pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: reward small post-residual, with non-linear (quadratic) coupling
    let mut score = pr * (1.0 + pr_norm * pr_norm);

    // Smooth interaction of post-residual with stream progress:
    // late in the stream, dead space matters more (bins close to final)
    let progress_coupling = pr_norm * (1.0 - progress) * 20.0;
    score += progress_coupling * pr_norm * cap * 0.1;

    // Penalize wasted capacity when item leaves a hole too small for typical items
    let hole_penalty = if post_residual > 0 {
        let usable = ((post_residual as f64) / 10.0).floor() / 10.0; // fraction usable in 10-units
        (1.0 - usable) * (1.0 - usable)
    } else { 0.0 };
    score += hole_penalty * 15.0;

    // Perfect fit reward (smooth exponential decay of residual)
    if post_residual == 0 {
        score -= 25.0;
    } else {
        score -= 10.0 * (-pr_norm * 6.0).exp();
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * (1.0 - pr_norm);
    }

    // Lookahead: if next item fits exactly into post-residual, big reward
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let tight = (post_residual - next_item_size) as f64 / cap;
            score -= 18.0 * (-tight * 8.0).exp();
        } else {
            // next item won't fit here; slight penalty proportional to overflow
            score += ((next_item_size - post_residual) as f64 / cap) * 8.0;
        }
    }

    // Encourage balancing residuals toward the mean (smooth dispersion control)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / (cap * cap) * 100.0;

    // Mild preference for keeping number of open bins low early on
    score += open_bins_count as f64 * 0.02 * (1.0 - progress);

    // New-bin candidate bias: empty bin should only win when nothing fits well
    if bin_residual == bin_capacity {
        score += 12.0 + 15.0 * (1.0 - progress);
        if fitting_bins_count == 0 { score -= 30.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

