    // Residuals in {0} perfect, {1..9} dead space, small classes worse.
    let pr = post_residual;
    let class = pr % 10;
    score += match class {
        0 => -6.0,
        1..=3 => 4.0 + 2.0 * (3 - class) as f64,
        4..=9 => 1.5 * class as f64,
        _ => 0.0,
    };

    // Perfect-fit bonus scaled by how much slack is eliminated
    if pr == 0 {
        score -= 12.0;
    }

