    if pr >= bin_capacity / 2 {
        score -= 3.0;
    } else if pr >= bin_capacity / 4 {
        score -= 1.0;
    } else if pr > 0 {
        score += 2.0; // tiny dead space
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if next_item_size < pr {
            let nr_post = pr - next_item_size;
            // harmonic class of the chained residual
            score += match nr_post % 10 {
                0 => -4.0,
                1..=5 => 1.0,
                _ => 3.0,
            };
        } else {
            // next item won't fit here: bin becomes dead after this placement
            score += 5.0 + (next_item_size - pr) as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // fits are all poor (large post_residual relative to capacity)
    if bin_residual == bin_capacity {
        let avg_badness = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 18.0 - 10.0 * avg_badness;
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
