pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    score = post_residual as f64 * 0.5;

    // Strong reward if the next item fits exactly into post_residual (2-step chain)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // next item fits but leaves leftover: mild reward scaled by how well it chains
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - slack * 0.3;
        } else {
            // next item does NOT fit: penalize proportionally to the wasted gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.4;
        }
    }

    // Reward matching against mean residual: bins with residual near mean are "typical",
    // prefer bins whose residual is below mean (tighter bins) for big items
    let residual_f = bin_residual as f64;
    let mean_dev = residual_f - mean_residual;
    score += mean_dev * 0.1;

    // Last-chance bin (only fitting bin): strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize creating dead space below the minimum item size (unusable residual)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // New-bin candidate: empty bin should only win when nothing fits well.
    // Make it slightly unattractive by default, but attractive late in the stream
    // or when the item is large and would leave a poor residual in open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item_bonus = if item_size > bin_capacity / 2 { 15.0 } else { 0.0 };
        score += 20.0 - large_item_bonus - progress * 10.0;
        // If next item is huge, opening a fresh bin helps chain both
        if next_item_size >= bin_capacity / 2 && item_size + next_item_size <= bin_capacity {
            score -= 30.0;
        }
    }

    score
}

