pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squash post_residual so small leftovers dominate.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 * (next_item_size as f64 / 100.0);
        } else if post_residual > 0 {
            score += 10.0; // leftover too small for lookahead item
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        score = 60.0 + 40.0 * crowding - 20.0 * (1.0 - progress);
    }

    // Slight preference for filling fuller bins as stream progresses.
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.3;

    // Penalize opening many bins when mean residual is high (fragmentation guard).
    score += 0.15 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly damped
    let mut score = pr * (0.9 + 0.2 * progress);

    // Non-linear polynomial coupling of normalized post residual with progress
    let t = progress;
    score += 30.0 * norm_pr * norm_pr * (1.0 + t);
    score -= 12.0 * norm_pr * norm_pr * norm_pr * (1.0 + 2.0 * t);

    // Tight fit reward (smooth quadratic near zero residual)
    let tight = (1.0 - norm_pr).min(1.0);
    score -= 20.0 * tight * tight;

    // Penalize residuals that cannot fit the average next demand
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 15.0 * gap * gap;
        // lookahead synergy: reward leaving exactly room for next item
        let match_fit = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        if match_fit > 0.0 {
            score -= 8.0 * match_fit * match_fit;
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Penalize scattering across many open bins late in stream
    score += (open_bins_count as f64).ln() * (2.0 + 4.0 * t);

    // Deviation from mean residual: prefer balanced bins early, divergent late
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 10.0 * (1.0 - t);

    // New-bin candidate: neutral baseline with slight late-stream penalty
    if bin_residual == bin_capacity {
        score = pr + 3.0 + 6.0 * t - (fitting_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes on post_residual: classify leftover space into
    // "dead" classes (too small for typical future items) vs "usable" classes.
    let pr = post_residual;
    // Class via integer division thresholds: 0..=10 dead, 11..=30 poor,
    // 31..=60 medium, 61..=100 good.
    let class = if pr == 0 { 4 } else if pr <= 10 { 3 } else if pr <= 30 { 2 } else if pr <= 60 { 1 } else { 0 };

    // Reward exact-tight fits strongly (post_residual near 0 is perfect only
    // if it is 0; tiny dead space 1..=10 is worst since nothing fits later).
    match class {
        4 => { score -= 40.0; }              // perfect fill
        3 => { score += 25.0; }              // 1..=10 dead space penalty
        2 => { score += 5.0; }               // mild penalty
        1 => { score -= 5.0; }               // medium leftover fine
        0 => { score -= 12.0; }              // large leftover keeps bin flexible
        _ => {}
    }

    // Lookahead: if next item fits exactly in post_residual, huge reward.
    if next_item_size > 0 && next_item_size <= pr {
