        score -= 30.0 - slack * 0.3;
    }
    // If next item leaves this bin unusable anyway, small penalty for wasting.
    if next_item_size > 0 && next_item_size > pr && pr > 0 && pr <= 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large relative to capacity or current bins are crowded.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Prefer new bin when few fitting bins exist and item is big.
        let item_frac = item_size as f64 / cap;
        score -= (fitting_bins_count as f64) * 20.0;
        score += item_frac * 30.0 - progress * 10.0;
        score += (open_bins_count as f64) * 2.0;
    } else {
        // Prefer reusing bins when they are already sparse relative to mean.
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 4.0;
        }
    }

    score
