pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: tight fit reward — lower post_residual is generally better,
    // but with a nonlinear penalty for "unusable" dead space gaps.
    let pr = post_residual as f64;
    if post_residual == 0 {
        // Perfect fit: strongest reward.
        score -= 200.0;
    } else {
        // Dead space penalty grows super-linearly for small unusable gaps.
        // Gaps below ~20 are hard to fill with items (sizes 1..100 unknown,
        // but small gaps waste capacity).
        if pr < 20.0 {
            score += (20.0 - pr) * 8.0; // penalize tiny unusable gaps
        } else {
            score += pr * 0.5; // moderate penalty for larger leftovers
        }
    }

