        // already give it a high score. Add explicit pressure scaled by
        // how many bins are open and how much mean residual is idle.
        let idle = mean_residual.max(0.0);
        score += 120.0 + (open_bins_count as f64) * 6.0 + idle * 0.4;
    } else {
        // Reward using existing bins, more so when bins are plentiful.
        score -= (open_bins_count as f64) * 1.5;
    }

