    // opening a new bin at almost any cost.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 150.0;
    }

    // Lookahead coupling: if the next item fits in the post_residual,
    // this placement chains nicely — reward it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else if next_item_size <= bin_residual && post_residual < next_item_size {
            // Placing here breaks a potential fit of the next item elsewhere
            // only mildly; slight penalty proportional to wasted chain.
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
