    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // 2-step lookahead: reward bins whose post-residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0; // perfect chain: next item exactly fills the bin
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            // reward proportional to how tight the follow-up fit is
            score -= 120.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this bin's remainder; penalize dead space
            score += 30.0 + 0.3 * post_residual as f64;
        }
    }

    // Compare against mean residual: prefer bins that are more filled than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize the brand-new empty bin candidate mildly, so it's only chosen
    // when all open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 60.0;
    }

    // Early in the stream, opening bins is cheaper; later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill;

    // Penalize small unusable dead space (post_residual below smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Penalize leaving a gap that blocks the next item, scaled by gap size.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Global state: many open bins with slack -> favor filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let openness = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += openness * 0.5 * (0.5 + progress);

    // Mean residual coupling: prefer bins below mean residual (tighter than average).
    score += (mean_residual - bin_residual as f64) * 0.1;

    // New-bin candidate: penalize opening a new bin unless existing fit is very poor.
    if bin_residual == bin_capacity {
        score += 45.0 - 40.0 * (post_residual as f64 / bin_capacity as f64);
        // Early stream: opening bins is cheaper (reserve flexibility).
        score -= 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let progress_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    let mut score = post * (1.0 + 0.35 * progress_poly);

    // Non-linear penalty for small dead space relative to smallest plausible item
    let dead = (norm_post * norm_post) * cap;
    score += 0.5 * dead * (1.0 - norm_post);

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_post;
    score -= 12.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // Lookahead: reward if next item fits into resulting post_residual
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if post >= ns {
            score -= 6.0 * (1.0 - ((post - ns) / cap).abs());
        } else {
            score += 4.0 * ((ns - post) / cap);
        }
    }

    // Mild penalty when this bin is far below mean residual (keeps big bins available)
    score += 0.15 * (mean_residual - post).max(0.0) * (1.0 - progress_poly);

    // New-bin candidate: discourage opening a new bin unless residuals are tight
    if bin_residual == bin_capacity {
        score += 25.0 + 0.4 * mean_residual * (1.0 - progress) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
