pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // host a realistic future item (below the minimum plausible size band)
    // are heavily penalized.
    let dead_threshold = 9.0; // residual <= 9 is effectively dead space
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 40.0 * (dead_threshold - post_residual as f64);
    }

    // Softly penalize "awkward" residuals that only fit tiny items:
    // gaps in [10, 25) are wasteful for typical item sizes.
    if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post
    // residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 - 0.2 * slack;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; mild penalty proportional to overflow.
        score += 0.1 * (next_item_size - post_residual) as f64;
    }

    // Open-bin pressure: discourage proliferation of bins when many are open.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that fits, using it avoids
    // opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Mean-residual context: prefer bins whose post residual stays close to
    // the fleet mean (keeps residuals balanced and reusable).
    score += 0.15 * ((post_residual as f64) - mean_residual).abs();

    // New-bin candidate handling: an empty bin has post_residual = capacity - item.
    // Only prefer opening a new bin when the item is large and fits poorly
    // everywhere else (post residual would be small/dead in existing bins).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Neutral baseline offset so open bins usually win unless they'd
        // create dead space or this is a big item with no good home.
        score += 10.0;
        if item_size >= 60 && fitting_bins_count <= 1 {
            score -= 20.0;
        }
    } else {
        // Favor reusing bins that are already partially filled (tighter packing).
        let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 10.0 * fill_ratio;
    }

    // Slight stream-progression term: later in the stream, closing gaps
    // tightly matters more since fewer items remain to use slack.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

