    // leaving a residual well below mean creates isolated dead space -> penalize
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += 0.4 * (mean_residual - pr);
    } else {
        score -= 0.2 * (pr - mean_residual);
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New empty bin candidate: penalize moderately unless it enables a great
    // 2-step chain (next item fits almost exactly after this placement)
    if bin_residual == bin_capacity {
        let chain_bonus = if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            1.0 - ((bin_capacity - item_size - next_item_size) as f64 / bin_capacity as f64)
        } else {
            0.0
        };
        score += 120.0 - 60.0 * chain_bonus;
        // early in the stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
    }

    // Mild penalty for many open bins (encourage consolidation)
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
