    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tight * tight * tight;

    // Penalize dead space that no realistic item can use (items <= 80).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }
    if post_residual > 80 {
        score -= 5.0; // large leftover still broadly reusable
    }

    // Lookahead (k=2): bonus if next item fits exactly in post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
