    // New-bin candidate handling: only attractive when no open bin fits well
    // or residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - (bin_capacity as f64)) / (bin_capacity as f64);
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let late = progress;
        let bonus = 20.0 * desperation + 15.0 * fragmentation.max(0.0) + 10.0 * late;
        // base cost of opening a new bin
        score += 35.0 - bonus;
    }

    score
}

