            score -= 6.0;
        }
        if fitting_bins_count > 0 && mean_residual > item_size as f64 + 5.0 {
            score += 15.0; // discourage opening when open bins have ample room
        }
    }

    // Mild pressure to consolidate: fewer open bins is better at same residual.
    score += (open_bins_count as f64) * 0.35;

    // Progress-aware: later in stream, tolerate slivers less (less time to fill them).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if pr > 0 && pr < 10 {
        score += 20.0 * progress;
    }

    // Nudge toward bins whose residual is close to mean (keep residuals balanced).
    score += ((bin_residual as f64 - mean_residual) / cap as f64).abs() * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving space usable by the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0; // dead space relative to next item
    }

    // Last-chance bin: strongly favor using it over wasting it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 30.0 + 4.0 * open_bins_count as f64;
        // But allow new bin if all existing residuals are small (poor fits).
        if mean_residual < item_size as f64 {
            score -= 45.0;
        }
    } else {
        // Slight preference for tighter existing bins.
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // Late in the stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core 2-step lookahead: reward when post_residual matches next item size exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + gap);
        // Perfect 2-chain: residual after placing next item is ~0
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Penalize dead space (post_residual too small for the smallest plausible item)
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 + 2.0 * (10 - post_residual) as f64;
    }

    // Compare against mean residual: prefer bins tighter than average
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless it is genuinely needed
    if bin_residual == bin_capacity {
        // New bin is attractive only if item is large relative to capacity
        score = (bin_capacity - item_size) as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits, must open
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 5.0; // room for the next item in a fresh bin
        }
        // Early in stream, slightly prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
