pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        score -= 25.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Next item cannot follow here; penalize leaving awkward space.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize opening a new bin when existing bins fit reasonably.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = mean_residual / (bin_capacity as f64);
        score += 12.0 + 20.0 * waste * (1.0 - progress);
    }

    // Penalize creating dead space below the minimum item size (1..100, assume ~10 typical).
    if post_residual < 10 {
        score -= 10.0; // dead space anyway; prefer filling fully
    }

    // Mild pressure to prefer bins with larger residuals among equals.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_n = pr / cap;
    let base = pr_n * pr_n * pr_n; // cubic: strongly penalize large leftover
    // smooth coupling of dead-space with stream progress: later, waste matters more
    let progress_coupling = base * (1.0 + 2.0 * progress * progress);
    // reward tight fits: penalize score when post_residual is small (subtract)
    let tightness = -3.0 * (1.0 - pr_n).powi(4);
    // lookahead: reward bins whose residual can still fit the next item
    let next_bonus = if next_item_size > 0 && (pr as u32) >= next_item_size {
        -0.5 * (next_item_size as f64 / cap)
    } else {
        0.15 * (next_item_size as f64 / cap) // penalize if next item can't use the leftover
    };
    // last-chance bonus: if this is the only fitting bin, prefer it
    let last_chance = if fitting_bins_count == 1 { -1.0 } else { 0.0 };
    // mild penalty for spreading across many open bins
    let spread = 0.02 * open_bins_count as f64 * pr_n;
    // deviation from mean residual: prefer bins near mean to keep balance
    let dev = 0.5 * (pr - mean_residual) / cap;
    base + progress_coupling + tightness + next_bonus + last_chance + spread + dev
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
