pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: zero post-residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the post-residual: residuals that are "nice" fractions
    // of capacity (multiples of 10) are more reusable.
    let harmonic = post_residual % 10 == 0;
    if harmonic {
        score -= 8.0;
    }

    // Penalize dead space: post_residual smaller than the smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 50.0;
    }

    // Reward leaving room for the lookahead item: if next item fits exactly
    // in the post-residual, this is a strong chain placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let chain = post_residual - next_item_size;
            // Bonus decays with leftover after the chain placement.
            score -= 20.0 * (1.0 - (chain as f64 / bin_capacity as f64));
            if chain == 0 {
                score -= 20.0;
            }
        } else {
            // Next item cannot use this bin's leftover; slight penalty for
            // small unusable leftovers relative to next item.
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a neutral-ish baseline;
    // prefer it only when the current bin would leave a bad residual.
    if bin_residual == bin_capacity {
        // Opening a new bin is cheap when many bins are open and mean residual
        // is small (open bins are nearly full anyway).
        score = 40.0 + mean_residual * 0.5 + (open_bins_count as f64).sqrt() * 2.0;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score += 100.0; // next item needs a full bin anyway
        }
        if post_residual == 0 {
            // never open a new bin when a perfect fit exists elsewhere
            score += 500.0;
        }
    }

    // Waste-proportionality: penalize residual relative to item size.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64) * 0.1;

    // Slight preference to fill earlier bins as stream progresses.
    score += (step_index as f64 / (total_items.max(1) as f64)) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..10 zone)
    // are pure waste; penalize small unusable gaps super-linearly.
    if post_residual < 10 {
        let gap = 10 - post_residual;
        score += (gap as f64) * (gap as f64) * 3.0;
    }
    // Small residuals that only fit tiny items are semi-dead space.
    if post_residual < 20 {
        score += (20.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits (low post_residual) non-linearly.
    score -= (100.0 - post_residual as f64).powi(2) * 0.02;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize new-bin usage / low utilization spread).
    let pressure = (open_bins_count as f64) / 8.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 15.0 + pressure * 10.0;
    } else {
        // Reward using existing bins, scaled by how many fit.
        score -= pressure * 2.0;
        if fitting_bins_count == 1 {
            // Last-chance bin: strongly favor using it to avoid opening a bin.
            score -= 12.0;
        }
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = post_residual - next_item_size;
        if diff < 5 {
            score -= 8.0;
        } else {
            score -= 2.0;
        }
    }
    // If next item cannot fit anywhere after this placement, avoid wasting residual.
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 5.0;
    }

    // Early in the stream, be slightly more willing to open new bins for good anchors.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 8.0;
    }

    // Mean residual coupling: if open bins are already loose, prefer tightening them.
    if bin_residual != bin_capacity && (mean_residual - post_residual as f64) > 10.0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size > post_residual {
            // dead space for the next item: penalize proportionally
            score += 0.5 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;
            if post_residual < 10 {
                score += 50.0; // unusable sliver
            }
        } else {
            // next item fits: mild reward scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize unless open bins are badly fragmented
    if bin_residual == bin_capacity {
        let base = 150.0;
        let fragmentation = (mean_residual - post_residual as f64).max(0.0);
        score = base + fragmentation;
        if fitting_bins_count > 1 {
            score += 100.0; // prefer existing bins when alternatives exist
        }
    }

    // Prefer bins with residuals below mean (tighter packing)
    score += 0.3 * ((post_residual as f64) - mean_residual);

    // Late in stream: be greedier about filling bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 40.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: waste ratio penalization (quadratic in post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.05 * next_item_size as f64;
        } else {
            // Penalize dead space that blocks the next item.
            score += 0.12 * (post_residual as f64).powi(2);
        }
    } else {
        // End of stream: just minimize waste.
        score += 0.05 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Time horizon: early on, be picky (penalize mediocre fits); late, accept more.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - t) * 6.0 * (1.0 - fit_ratio);

    // Global state coupling: many open bins with high mean residual -> prefer filling existing bins.
    if open_bins_count > 0 {
        let pressure = mean_residual / bin_capacity as f64;
        score -= 10.0 * pressure * (open_bins_count as f64).ln().max(1.0);
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * (1.0 - fit_ratio);
        // Late in stream with many open bins, opening new bins is worse.
        score += 15.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) matter more.
    let tight = (1.0 - norm_pr).powi(3);
    score -= tight * (20.0 + 60.0 * progress);

    // Penalize dead space quadratically, scaled by progress.
    score += norm_pr * norm_pr * cap * (0.2 + 0.8 * progress);

    // Perfect-fit bonus (post_residual == 0), stronger later.
    if post_residual == 0 {
        score -= 50.0 + 50.0 * progress;
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 10.0 * (gap / cap).powf(0.5);
        } else {
            score += 8.0 * (-gap / cap);
        }
    }

    // Mean-residual coupling: prefer bins deviating from mean toward tighter fits.
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev - 5.0 * dev;

    // New-bin candidate: penalize mildly unless open bins are crowded.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * open_bins_count as f64 - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes on post_residual: residual classes that combine well
    // with common item sizes (which are often multiples of 10) are favored.
    let pr = post_residual;
    let class = pr / 10; // integer division harmonic bucket
    match class {
        0 => score -= 60.0,            // tiny dead space, nearly perfect
        1 => score -= 45.0,            // fits small items (10..20)
        2 => score -= 35.0,            // fits medium items
        3 => score -= 25.0,
        4 => score -= 15.0,
        5 => score -= 10.0,            // half-full bin, still flexible
        6 | 7 => score += 5.0,
        8 => score += 10.0,
        9 => score += 20.0,            // nearly empty, wasteful placement
        _ => {}
    }

    // Modulo-10 coupling: residuals that are multiples of 10 tile better
    // with integer item sizes drawn from a lumpy distribution.
    if pr % 10 == 0 {
        score -= 12.0;
    } else {
        // penalize odd residues slightly, worse the further from a multiple of 10
        let off = (pr % 10).min(10 - pr % 10);
        score += off as f64 * 0.8;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            // reward tight lookahead fits, penalize leaving awkward slack
            score -= 25.0 * (1.0 - slack as f64 / bin_capacity as f64);
            if slack % 10 == 0 {
                score -= 8.0;
            }
        } else {
            // next item won't fit here: this bin becomes dead unless residual is tiny
            if pr >= 10 {
                score += 15.0;
            }
        }
    } else {
        // last item: prefer filling any bin as fully as possible
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are large (poor fits everywhere) or stream is early
    // and we have few bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_penalty = mean_residual / bin_capacity as f64;
        // new bin baseline: slightly worse than a decent existing fit
        score = 100.0 - 30.0 * waste_penalty - 20.0 * (1.0 - progress) * (open_bins_count as f64 / 10.0).min(1.0);
        // if item is large, a fresh bin is more attractive (large items fit anywhere later)
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
        // perfect fit elsewhere beats new bin always
        if post_residual == 0 && false { score -= 0.0; }
    }

    // Mild penalty for spreading across many bins when residuals are healthy.
    if !is_new_bin && open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 0.3;
    }

    // Mean-residual anchoring: prefer bins whose post residual tracks the mean
    // (keeps the bin pool homogeneous and combinable).
    let mean_dev = (post_residual as f64 - mean_residual).abs();
    score += mean_dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Mid-range gaps (10..20) are mildly penalized since few items fit them.
    if post_residual >= 10 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Reward very tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item cannot use this gap: penalize proportionally to wasted space.
            score += ((post_residual as f64) * 0.5).min(15.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing ones.
    score -= (open_bins_count as f64) * 1.2;

    // Deviation from mean residual: prefer bins that keep residuals balanced.
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Early in the stream, tolerate opening new bins slightly more (better long-run structure).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;

    // New-bin candidate: only attractive when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else {
            // Deter opening a new bin when alternatives exist; scale with how many fit.
            score += 15.0 + (fitting_bins_count as f64) * 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer smallest post residual, but blend with residual-relative tightness.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let diff = (post_residual as f64 - next_item_size as f64).abs();
        // Perfect chain match: strong reward.
        if diff < 0.5 {
            score -= 25.0;
        } else {
            // Penalize mismatch scaled by how far next item misses the leftover.
            score += 0.35 * diff;
            // If next item fits into post_residual (partial chain), mild reward.
            if next_item_size <= post_residual {
                score -= 6.0;
            }
        }
        // If next item can't fit anywhere after this placement, penalize wasted space.
        if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
            score += 5.0; // tiny dead space that nothing can use
        }
    } else {
        // Last item: just minimize post residual strongly.
        score += 0.5 * post_residual as f64;
    }

    // Relative-to-mean coupling: bins below mean residual are "loose"; favor filling them.
    let rel = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score -= 4.0 * rel;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 40.0
            || (next_item_size > 0 && next_item_size > post_residual);
        if poor_fit && open_bins_count > 0 {
            score -= 20.0; // open a fresh bin rather than fragmenting
        } else {
            score += 18.0; // discourage new bins when existing bins fit decently
        }
    }

    // Early stream: be slightly conservative about fragmenting bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: squashed post-residual reduces score strongly.
    let fit_ratio = post_residual as f64 / cap;
    score -= 18.0 * (1.0 - fit_ratio).powi(3);

    // Penalize dead space in partially-filled bins (not a fresh/new bin).
    let is_new_bin = bin_residual == bin_capacity;
    if !is_new_bin {
        let waste = post_residual as f64;
        score += 0.35 * waste * (waste / cap);
    }

    // Lookahead: if the next item fits the post-residual exactly-ish, reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let slack = post_residual as f64 - nxt;
            score -= 14.0 * (1.0 - slack / cap).max(0.0);
        } else if (post_residual as f64) < nxt && post_residual > 0 {
            // next item won't fit here; small penalty for leaving awkward gap
            score += 4.0 * (post_residual as f64 / nxt.max(1.0));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 12.0;
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if !is_new_bin {
        score -= 3.0 * (mean_residual / cap) * (1.0 + open_bins_count as f64 / 10.0);
    } else {
        // New-bin candidate: penalize more when open bins are underutilized
        // or when we're early in the stream.
        score += 6.0 * (mean_residual / cap);
        score += 8.0 * (1.0 - progress);
    }

    // Mild time-horizon term: later in stream, tighten preference for best fit.
    score -= 5.0 * progress * (1.0 - fit_ratio);

    // Prefer bins whose residual is close to item size (perfect fill).
    let overhang = (bin_residual as f64 - item_size as f64).abs();
    score += 0.08 * overhang;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on (progress ~ 0): mild preference for tight fits (post_residual dominates).
    // Late (progress ~ 1): strongly penalize large residuals to avoid waste.
    let progress_curve = progress * progress * (3.0 - 2.0 * progress); // smoothstep-like
    score += 12.0 * progress_curve * pr_norm * pr_norm * cap;

    // Reward tight fits smoothly: quadratic in item_norm, modulated by progress.
    score -= 20.0 * item_norm * item_norm * (0.5 + 0.5 * progress_curve) * cap * 0.1;

    // Dead-space penalty: interaction of post_residual with mean residual.
    score += 0.5 * (pr - mean_residual).abs() * (1.0 + progress_curve);

    // Last-chance bonus: if this is the only fitting bin, favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - pr_norm);
    }

    // Lookahead: penalize leaving a residual that neither fits the next item well
    // nor is small (awkward gap), smoothly weighted.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap_mismatch = (pr_norm - nx).abs();
        score += 8.0 * gap_mismatch * gap_mismatch * cap * (0.3 + 0.7 * progress_curve);
        // Reward when next item fits exactly into post_residual.
        if (next_item_size as u32) <= post_residual {
            score -= 5.0 * (next_item_size as f64 / cap) * (1.0 - gap_mismatch);
        }
    }

    // Mild penalty for bin proliferation early in the stream.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress_curve);

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is ideal.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    } else if post_residual <= 30 {
        score -= 2.0;
    }

    // Harmonic class penalty: dead space that no plausible item (1..100) can use.
    // post_residual in (50,100) after placement is dangerous dead space unless small.
    if post_residual > 50 {
        score += (post_residual as f64 - 50.0) * 0.8;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: penalize placements that leave residual that can't fit next item
    // while this bin could have; reward leaving space exactly usable by next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 15.0; // next item chains perfectly here
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 5.0; // blocks next item from using this leftover
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is fine when the stream is early or many bins open,
        // but penalize slightly so tight existing fits win.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 - 8.0 * progress;
        // If next item is large and current item is small, opening a fresh bin
        // preserves flexibility.
        if next_item_size > 60 && item_size < 40 {
            score -= 10.0;
        }
    }

    // Mild pressure to consolidate: prefer bins with below-average residual
    // (filler bins) so mean residual shrinks.
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    // Modulo-class tuning on residual: residuals that are multiples of 10
    // remain usable by typical item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

