    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 18.0; // hard-to-fill zone given min item size 1..100 unknown
    }

    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward fitting the next item too (lookahead chaining).
