pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual exactly
    // matches the next item's size (perfect chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let exact = (post_residual - next_item_size) as f64;
        // Small gap to next item => strong reward.
        score -= 60.0 - 4.0 * exact.min(15.0) as f64;
    } else if next_item_size > 0 {
        // Next item cannot follow into this bin: penalize proportional dead space.
        score += (next_item_size as f64) * 0.35;
    }

    // Penalize large unusable leftovers (dead space below the minimum item size).
    if post_residual < 10 && post_residual > 0 {
        score -= 25.0; // nearly-closed bin is good
    } else if post_residual == 0 {
        score -= 40.0; // perfectly closed bin
    }

    // Compare against mean residual: bins tighter than average are preferred.
    score += 0.15 * (mean_residual - bin_residual as f64).max(-50.0);

    // Last-chance bin before opening a new bin: strong reward to avoid waste.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Discourage opening a brand-new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 15.0 * progress;
        // But if next item is huge and this residual is exactly next item size,
        // a fresh bin is a perfect pre-fit.
        if next_item_size > 0 && (bin_capacity - next_item_size) >= item_size {
            score -= 10.0;
        }
    }

    // Mild preference for tighter fits overall.
    score += 0.05 * (item_size as f64);

    score
}

