pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact fills are ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 40.0 * fit_ratio * fit_ratio;
    }

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead: bonus if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size > post_residual {
            // Next item won't fit here anyway; slight penalty for wasting a big residual.
            score += 0.15 * (next_item_size - post_residual) as f64;
        } else {
            score -= 0.1 * next_item_size as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Prefer bins with below-average residual (keep big residual bins flexible).
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Mild penalty for spreading across many open bins when progress is early.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 0 && (post_residual as f64) < 0.35 * bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: opening is fine
        } else if poor_fit {
            score -= 120.0; // existing fit would create dead space; prefer new bin
        } else {
            score += 150.0 + 2.0 * open_bins_count as f64; // keep using open bins
        }
    }

