}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap;
    let mut score = post * (1.0 + 0.8 * progress * (1.0 - progress) * 4.0);
    score -= (x * (1.0 - x) * 4.0) * cap * 0.35;
    score += (x - mean_residual / cap).powi(2) * cap * 0.25;
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let d = (x - nx).abs();
        score -= (1.0 - d).max(0.0) * cap * 0.2;
    }
    if fitting_bins_count == 1 {
        score -= cap * 0.3;
    }
    score += open_bins_count as f64 * 0.05;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

