    let fits_count = post_residual / 10;
    score -= fits_count as f64 * 2.0; // reward leftovers that can host more items

    // Lookahead chaining: if the next item fits into post_residual, this is a great pair.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + (post_residual - next_item_size) as f64 * 0.3;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to lookahead: leftover smaller than next item.
        let dead = post_residual.min(next_item_size.saturating_sub(1));
        score += dead as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Congestion pressure: many open bins -> prefer tightening existing ones.
    score += open_bins_count as f64 * 0.4;

    // Mean-residual coupling: placing into a bin far below mean residual
    // (large bin) is favored to balance the pool.
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Stream progression: early on, be picky (tight fits matter over long horizon);
    // later, accept decent fits more eagerly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    // New-bin candidate handling: an empty bin is a costly last resort.
    if bin_residual == bin_capacity {
        // Opening a new bin is good only if the item is large (would leave
        // awkward residue elsewhere) or nothing else fits well.
        let large_item = item_size >= bin_capacity * 6 / 10;
        let poor_alternatives = fitting_bins_count == 0
            || (fitting_bins_count == 1 && next_item_size > 0 && next_item_size > post_residual);
        if large_item || poor_alternatives {
            score -= 20.0; // allow new bin
        } else {
            score += 40.0; // prefer existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (non-linear).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }
    // Reward perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Dead space relative to what the next item could use.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
