pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize dead space that can never be used by typical items
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable slivers
    }

    // Lookahead coupling: if next item fits in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0 + 0.3 * next_item_size as f64;
        } else {
            // penalize leaving a gap slightly larger than the next item (wasted)
            let waste = (post_residual as f64 - next_item_size as f64).max(0.0);
            score += waste * 0.2;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // with many options, favor bins where item is proportionally large
        score += (item_size as f64 / bin_residual.max(1) as f64) * 20.0;
    }

    // Global state: many open bins -> prefer consolidation into existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
