    score += consolidation * (bin_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin is emptier than average, mild penalty early, reward late
    let rel = bin_residual as f64 - mean_residual;
    score += rel * (0.3 - 0.4 * progress);

    // New-bin candidate: penalize opening a new bin unless the item is large
    // or current open bins have poor fit potential
    if bin_residual == bin_capacity {
        let new_bin_penalty = 70.0
            - (item_size as f64 - 50.0).max(0.0) * 0.5
            + (open_bins_count as f64) * 1.5
            - mean_residual * 0.2;
        score += new_bin_penalty.max(-20.0);
    }

    // Slight preference to fill emptier bins first when few bins open
    if open_bins_count <= 2 {
        score += bin_residual as f64 * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear (quadratic/cubic) shaping
    let mut score = pr + 40.0 * norm_pr * norm_pr + 25.0 * norm_pr * norm_pr * norm_pr;

    // Smooth coupling with stream progress: tight fits matter more early on
    let progress_coupling = 30.0 * (1.0 - progress) * norm_pr * (1.0 - norm_pr);
    score -= progress_coupling;

    // Penalize post_residual that neither fits the lookahead item nor is near zero
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        let norm_gap = gap / cap;
        score += 20.0 * norm_gap * norm_gap;
        // Reward when lookahead item fits exactly-ish
        let fit_quality = 1.0 - (nxt / pr.max(1.0)).min(1.0);
        score -= 15.0 * (1.0 - fit_quality) * (1.0 - norm_pr);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 35.0 + 20.0 * (1.0 - norm_pr);
    }

    // Mild penalty when many bins are open and this placement wastes space
    let open_pressure = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)).sqrt();
    score += 10.0 * open_pressure * norm_pr;

    // Mean-residual deviation coupling: prefer bins whose post-residual aligns with fleet mean
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: penalize opening a fresh bin unless residual is unusable
    if bin_residual == bin_capacity {
        let unusable = ((norm_pr - 0.5) * 2.0).abs(); // 0 when half full, 1 when empty
        score += 45.0 * (1.0 - unusable * (1.0 - progress));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes of post_residual: residues mod 10 and integer-division bands.
    let pr = post_residual;
    let band = pr / 10; // harmonic band of the leftover space
    let residue = pr % 10;

    // Dead-space penalty: small nonzero leftovers are nearly unusable.
    if pr > 0 && pr < 10 {
        score += 40.0 - 3.0 * pr as f64;
    }

    // Reward exact fits strongly.
    if pr == 0 {
        score -= 100.0;
    }

    // Reward leftovers that can host the lookahead item (harmonic pairing).
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 15.0 + 0.3 * (pr - next_item_size) as f64;
        } else {
            score += 10.0 + 0.5 * (next_item_size - pr) as f64;
        }
        // Reward leftovers in the same "harmonic class" as the next item
        // (integer-division threshold on next item size).
        let nb = next_item_size / 10;
        if band as u32 == nb && pr >= next_item_size {
            score -= 12.0;
        }
    } else {
        // Last item: prefer filling as much as possible.
        score -= 20.0;
    }

    // Penalize residue classes that historically waste space (odd/tiny residues).
    if residue == 1 || residue == 3 || residue == 7 || residue == 9 {
        score += 4.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0);
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 30.0;
        // If other bins can fit this item, discourage new bin mildly.
        if fitting_bins_count > 0 {
            score += 10.0;
        }
        // If the item is large relative to capacity, a fresh bin is fine.
        if item_size * 2 >= bin_capacity {
            score -= 25.0;
        }
    } else {
        // Prefer fuller bins (tightness reward), scaled by stream progress.
        let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= tight * 20.0 * (0.5 + step_index as f64 / (total_items.max(1) as f64 * 2.0));
    }

    // Mild preference for bins below mean residual (keeps residual spread tight).
    score += 0.1 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never fit even the
    // smallest future item (min size ~1) are wasted; residuals in the
    // awkward "too small for typical items" band are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver -> strong penalty
    } else if post_residual >= 10 && post_residual < 25 {
        score += 25.0; // awkward gap band
    }

