    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and favor consolidating into existing bins.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 8.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost + pressure so it's only chosen when
        // existing bins score poorly (poor fits / dead space).
        score += 55.0 + open_pressure;
    } else {
        // Filling an existing bin reduces pressure slightly.
        score -= open_pressure * 0.5;
    }

    // Lookahead: if the next item fits exactly in this bin's post_residual,
    // reward this placement (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 20.0;
        } else {
            score -= 8.0;
        }
    }
    // If next item cannot fit anywhere after this placement, penalize
    // leaving a large dead gap.
    if next_item_size > post_residual && post_residual < next_item_size && post_residual > 0 {
        score += 5.0;
    }

    // Prefer bins tighter than the mean residual (consume the fullest bins first).
    let mean_diff = mean_residual - bin_residual as f64;
    score += mean_diff * 0.3;

    // Slight stream-position scaling: late in the stream, be more conservative
    // about opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: zero post residual is ideal.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post residual can
    // exactly or nearly host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let gap = post_residual as f64 - nxt;
            if gap == 0.0 {
                score -= 400.0; // exact 2-chain: post residual fits next item exactly
            } else {
                // smoother is better; penalize large leftover after the pair
                score -= 150.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            // post residual cannot host next item: dead-space penalty scaled by tightness
            let dead = nxt - post_residual as f64;
            score += 0.5 * dead;
        }
    }

    // Tight fit reward: prefer bins where the item fills a large fraction.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 80.0 * fill;

    // Compare against mean residual: prefer using bins with less residual
    // (consolidate waste) when they still fit well.
    if (bin_residual as f64) < mean_residual {
        score -= 30.0;
    } else {
        score += 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless post residual is huge waste).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
        if post_residual > 40 {
            score += 100.0; // but avoid stuffing if it leaves big dead space
        }
    }

    // New-bin candidate handling: make empty bin attractive only when the
    // item is large and no good fit exists among open bins.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64; // waste if opened now
        if item_size >= 60 && fitting_bins_count == 0 {
            score -= 200.0; // large item with no fit: open new bin
        }
        if next_item_size > 0 && (bin_capacity - item_size) as f64 >= next_item_size as f64 {
            score -= 20.0; // fresh bin can also host next item
        }
    }

    // Mild stream-progression pressure: later in stream, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 50.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize small dead space that nothing can fill later
        let t = step_index as f64 / total_items.max(1) as f64;
        let min_item = 1.0;
        if (post_residual as f64) < min_item {
            score -= 100.0;
        }
        // Waste relative to capacity
        score += (post_residual as f64 / bin_capacity as f64) * 20.0;

        // Lookahead: reward bins whose leftover can host the next item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0 * (next_item_size as f64 / bin_capacity as f64);
        } else if next_item_size > 0 {
            score += 10.0;
        }

        // Last-chance bin: strongly favor using it to avoid opening a bin
        if fitting_bins_count == 1 {
            score -= 30.0;
        }

        // Tight fit reward: item fills most of the bin
        let fill = item_size as f64 / bin_residual.max(1) as f64;
        score -= fill * 25.0;

        // Prefer bins tighter than the average residual
        score += (bin_residual as f64 - mean_residual) * 0.15;

        // Early in stream: be pickier about waste; late: just fill anything
        score *= 1.0 + 0.5 * (1.0 - t);

        // Too many open bins: discourage spreading
        if open_bins_count > 10 {
            score += 0.05 * (open_bins_count as f64 - 10.0);
        }
    }

    // New-bin candidate: only attractive when nothing fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let desperate = fitting_bins_count == 0
            || (next_item_size > 0 && post_residual < next_item_size && fitting_bins_count <= 1);
        if desperate {
            score -= 40.0;
        } else {
            score += 60.0 + (open_bins_count as f64).sqrt() * 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
