pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize stream progress smoothly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with progress.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Smooth interaction: post-residual penalty grows with progress.
    let coupling = pr_norm * (1.0 + 2.0 * progress * pr_norm + 1.5 * progress * progress);
    score += 30.0 * coupling;

    // Reward tight fits with a smooth quadratic bonus.
    let tightness = 1.0 - (pr / cap);
    score -= 10.0 * tightness * tightness;

    // Penalize large residuals relative to mean residual (dead space risk), smoothly.
    score += 0.5 * (pr - mean_residual).abs();

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: smooth reward if the next item fits the post-residual.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fit_next = if pr >= ns { 1.0 } else { 0.0 };
        let gap = (pr - ns).abs() / cap;
        score -= 12.0 * fit_next * (1.0 - gap);
        score += 8.0 * (1.0 - fit_next) * pr_norm;
    }

    // Mildly discourage proliferating open bins as stream progresses.
    score += 0.3 * open_bins_count as f64 * progress;

    // New-bin candidate: penalize opening a new bin unless residual is very large.
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * (1.0 - progress);
        // Allow new bin if the item would leave huge dead space in existing bins.
        if pr_norm > 0.6 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose post_residual falls into
    // "small" residue classes (mod 10) are near-perfect fits and deserve reward.
    let residue_class = (post_residual % 10) as f64;
    if post_residual > 0 {
        // Reward tiny leftovers strongly (they pack well with small items).
        score -= 12.0 * (1.0 - residue_class / 10.0);
    } else {
        // Perfect closure: best possible outcome.
        score -= 40.0;
    }

    // Integer-division threshold: post_residual <= 9 is effectively dead space
    // (min item is 1); penalize proportionally to how unusable it is.
    if post_residual > 0 && post_residual <= 9 {
        score += 6.0;
    }

    // Coupling with lookahead: if next item fits exactly into post_residual,
    // this bin is a harmonic pair with the stream — strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair_slack = post_residual - next_item_size;
        if pair_slack == 0 {
            score -= 25.0;
        } else if pair_slack % 10 == 0 {
            // leftover lands on a clean capacity fraction (decile)
            score -= 10.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this bin anyway; mild penalty for wasting space now.
        score += 3.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over
    // opening a new bin (penalize new-bin alternative implicitly).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Brand-new empty bin candidate: only attractive when the item is large
    // relative to capacity or the stream is early and open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_fraction = item_size as f64 / bin_capacity as f64;
        score = 55.0 - 30.0 * item_fraction - 15.0 * (1.0 - progress) * (open_bins_count as f64 / 10.0).min(1.0);
        // If current open bins are mostly full (low mean residual), new bin is fine.
        score -= (mean_residual / bin_capacity as f64) * 5.0;
    }

    // Mild penalty when this bin's residual deviates far from the mean residual:
    // keep residual distribution balanced (harmonic balancing across bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Next item can't use this gap; penalize dead space more.
        score += 10.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open bins pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 20.0 + 5.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Stream progression: as stream advances, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively for large items.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * item_size as f64 * 0.5;

    // 2-step lookahead: perfect match where next item exactly fills post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + gap);
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize leaving residual that wastes capacity.
        let waste = if post_residual < next_item_size {
            (next_item_size - post_residual) as f64
        } else {
            0.0
        };
        score += waste * 0.3;
    }

    // Compare post_residual against mean residual: leaving more than average is wasteful.
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.2;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Early in stream: prefer opening fresh bins less (keep bins consolidated).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless item is large or residual is near-zero anyway.
        score += 15.0 + 20.0 * (1.0 - item_size as f64 / 100.0);
        // Late stream, fewer open bins -> new bin is cheaper.
        score -= 10.0 * progress * (1.0 - open_bins_count as f64 / 20.0);
    }

    // Small dead-space penalty scaled by how unusable the residual is for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual relative to item size.
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 12.0 / (1.0 + tightness);

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        let usable = if next_item_size > 0 && next_item_size <= post_residual { 1.0 } else { 0.0 };
        score += (1.0 - usable) * (post_residual as f64) * 0.35;
