    // and existing bins would be badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (open_bins_count as f64) / (1.0 + mean_residual / cap);
        score += 15.0 + fragmentation * 4.0;
        // If the next item is large, opening a fresh bin now is cheap.
        if next_item_size > 0 && (next_item_size as f64) > 0.6 * cap {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
