            score -= 20.0 - (slack as f64).min(20.0);
            // penalize if the leftover after next item is a dead sliver
            if slack > 0 && slack < 10 {
                score += 8.0;
            }
        } else {
            // next item cannot fit here; slight penalty for wasting the slot
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
