    // New-bin candidate handling: neutral-ish baseline, but prefer opening a
    // fresh bin when current fit is poor (large post_residual with bad class)
    if bin_residual == bin_capacity {
        // fresh bin score anchored near mid; beats bad fits, loses to good fits
        score = 40.0 + frac * 10.0;
        // if the item is large relative to capacity, opening fresh is attractive
        if item_size as f64 / bin_capacity as f64 > 0.6 {
            score -= 8.0;
