    }

    // Stream progression: late in the stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0 * (post_residual as f64 / bin_capacity as f64);

    // Many open bins with high mean residual: discourage fragmenting further
    if open_bins_count > 3 && mean_residual > (item_size as f64) {
        score += 2.0;
    }

    score
