        score -= 15.0;
    }

    // New-bin candidate handling: fresh bin has large residual.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized, more so when many bins are open.
        score += 30.0 + 2.0 * open_bins_count as f64;
        // But if no open bin fits well (this bin is last chance), allow it.
