    // Prefer bins whose residual is below the mean (use up fragmented bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Lookahead: avoid leaving a gap that exactly blocks the next item while
    // wasting space; if next item fits the post residual, bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 5.0;
    }

    score
}

