        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0; // leaves room for the next item: chain placement
        }
    }

    // Perfect fill is ideal
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bin before opening a new one: strong reward
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0); // plenty of alternatives, be picky
    }

    // Prefer bins below mean residual (consolidate fullness)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Late in the stream: prefer closing bins tightly, avoid spreading
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 6.0 * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: encourage filling existing ones rather than opening new
    score += 0.4 * open_bins_count as f64;

    // New-bin candidate: penalize unless current bin residuals are poor fits
    if bin_residual == bin_capacity {
        let poor_alternatives = fitting_bins_count == 0
            || (post_residual as f64) < 0.5 * item_size as f64;
        if poor_alternatives {
            score -= 18.0;
        } else {
            score += 10.0 + 3.0 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
