pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // base: penalize post residual, with polynomial shaping
    let mut score = norm_pr.powf(1.7) * 30.0 + 0.35 * pr;

    // tight fits rewarded: quadratic coupling of post_residual with item size
    score -= (norm_item * (1.0 - norm_pr)) * 12.0;
    score -= norm_item * norm_item * 8.0;

    // smooth stream-progress coupling: later in stream, prefer tighter packing
    let pterm = progress * progress;
    score += pterm * norm_pr * 14.0;
    score -= pterm * norm_item * 5.0;

    // dead space penalty: post residual too small for mean-size future items
    let next = next_item_size as f64;
    if next > 0.0 {
        let gap = (next - pr).max(0.0) / cap;
        score += gap * gap * 10.0;
        // lookahead fit reward
        if next <= pr {
            score -= 6.0 * (1.0 - (pr - next) / cap);
        }
    }

    // last-chance bin: strong reward to use it rather than open new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // new-bin candidate handling: prefer open bins early, allow new bin when residuals are large
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / cap;
        score = 25.0 - progress * 10.0 + mean_norm * 20.0 - norm_item * 5.0;
    }

    // mild dispersion penalty: avoid fragmenting when many bins open
    score += (open_bins_count as f64).ln().max(0.0) * 0.8 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
