pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that are "dead space"
    // (too small for the smallest plausible item) are penalized hard.
    let dead_threshold = 10u32.min(bin_capacity / 10);
    if post_residual < dead_threshold {
        score += 40.0; // near-perfect fit, but useless remainder -> great
        score -= 25.0;
    }

    // Classify post_residual by integer-division buckets of capacity/4.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter;
    score += match class {
        0 => -18.0,               // residual < 25: tight fit, excellent
        1 => -6.0,                // residual in [25,50): decent
        2 => 4.0,                 // residual in [50,75): wasteful
        _ => 10.0,                // residual >= 75: nearly untouched bin
    };

    // Lookahead: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect pairing: next item exactly fills leftover space.
            let gap = post_residual - next_item_size;
            score -= 30.0 - (gap as f64).min(30.0);
        } else {
            // Next item won't fit here regardless; slight bonus for
            // leaving a small residual another future item may use.
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of a fresh bin; offset when few bins are open or
        // stream is early (more future structure to exploit).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 55.0;
        new_bin_score -= 20.0 * (1.0 - progress);
        new_bin_score -= 8.0 * (open_bins_count.min(8) as f64) / 8.0;
        // If mean residual is large, open bins are underfilled -> avoid new bin.
        new_bin_score += (mean_residual / bin_capacity as f64) * 15.0;
        score = score.max(0.0) * 0.5 + new_bin_score;
    }

    // Modulo-flavored dead-space penalty: residuals that are awkward
    // (not multiples of common item sizes) are less likely to be filled.
    let mod_penalty = (post_residual % 10) as f64;
    score += mod_penalty * 0.3;

    // Prefer bins whose residual is close to the item (tight packing).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 12.0;

    // Mild preference for fuller bins when many bins are open.
    score += (open_bins_count as f64).ln() * (1.0 - bin_residual as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    // Gap below the minimum item size is pure dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }
    // Gap that cannot fit the lookahead item (k=2) is likely dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 60.0;
    }
    // Reward perfect fits and near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }
    // Reward gaps that exactly fit the next item (chain-friendly).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Open-bins pressure: discourage opening/spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 * (1.0 + 0.5 * progress);
    score += 0.05 * bin_pressure;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Mild alignment with mean residual: prefer bins tighter than average
    // (smaller residual than mean) to consolidate filling.
    if bin_residual < mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins exist,
    // unless the item is large relative to capacity (best-fit-new scenario).
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let large_item_bonus = if item_size > bin_capacity / 2 { 60.0 } else { 0.0 };
        score += 150.0 - large_item_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect or near-perfect match with next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward exact match strongly
        if post_residual == next_item_size {
            score -= 60.0;
        } else if gap <= 5.0 {
            score -= 40.0 - gap * 6.0;
        } else if gap <= 15.0 {
            score -= 10.0 - gap * 0.4;
        }
        // Penalize leaving residual that is slightly too small for next item
        // (dead space that neither fits next item nor is useful)
        if next_item_size > post_residual && next_item_size - post_residual <= 10 {
            score += (next_item_size - post_residual) as f64 * 2.0;
        }
    }

    // Tight fits are good: reward small post_residual relative to item size
    if post_residual <= 5 {
        score -= 25.0; // near-perfect packing, bin essentially closed
    } else {
        // smooth penalty for unusable dead space (residual below min item size)
        let dead = 5.0f64.min(post_residual as f64);
        score += (5.0 - dead) * 3.0;
    }

    // Relative to mean residual: prefer filling below-average-residual bins
    // (they are the fullest, keep them tight), but avoid wasting large residuals
    let residual_f = bin_residual as f64;
    if residual_f > mean_residual * 1.5 && open_bins_count > 0 {
        score += 8.0; // this bin is unusually empty; deprioritize unless lookahead matched
    } else if residual_f < mean_residual {
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: discourage opening a new bin unless it's a great
    // lookahead opportunity or existing fits are terrible
    if bin_residual == bin_capacity {
        let base_penalty = 45.0;
        let lookahead_bonus = if next_item_size > 0 {
            let gap = (bin_capacity as i64 - item_size as i64 - next_item_size as i64).abs() as f64;
            if gap <= 5.0 { 35.0 } else { 0.0 }
        } else { 0.0 };
        let late_stream = step_index as f64 / (total_items.max(1) as f64);
        score += base_penalty - lookahead_bonus - late_stream * 10.0;
    }

    // Mild pressure to close bins early in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * post_residual as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
