pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space relative to capacity, nonlinearly
        let dead_frac = post_residual as f64 / bin_capacity as f64;
        score += dead_frac * dead_frac * 60.0;
    }

    // Lookahead: reward if the next item fits the post residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 + 0.5 * next_item_size as f64;
        } else {
            score += 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Tightness reward: prefer bins that are already well filled
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * fill * 30.0;

    // Global state: many open bins with high mean residual -> prefer consolidating
    if open_bins_count > 2 {
        score -= 0.05 * mean_residual;
    }

    // Time horizon: early in stream, tolerate opening new bins; late, consolidate
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= t * 15.0;

    // New-bin candidate handling: penalize empty-bin opening unless item is large
    if bin_residual == bin_capacity {
        let large = item_size as f64 / bin_capacity as f64;
        if large > 0.6 {
            score -= 40.0 * (large - 0.6);
        } else {
            score += 35.0 * (0.6 - large);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
