pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: prefer small post-residual, with smooth polynomial shaping
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Stream-progress coupling: as stream advances, waste matters more (smooth ramp)
    let urgency = progress * progress;
    score *= 1.0 + 1.5 * urgency * norm_post;

    // Penalize post-residual that is large relative to mean residual (dead-space divergence)
    score += 0.35 * (post - mean_residual).abs();

    // Lookahead coupling: reward if next item fits the post-residual (smooth affinity)
    let next = next_item_size as f64;
    if next > 0.0 {
        let fit_affinity = (post - next).abs() / cap;
        score += 0.9 * fit_affinity * fit_affinity * cap;
        // bonus if next item exactly/nearly fits
        score -= 2.0 * (1.0 - fit_affinity.min(1.0)) * (1.0 - fit_affinity.min(1.0));
    }

    // Last-chance bin: strong smooth reward for using it
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.05 * open_bins_count as f64 * norm_post;

    // New-bin candidate: penalize unless current bins would leave big waste
    if bin_residual == bin_capacity {
        score = cap * (1.2 + 0.6 * progress) + 0.5 * open_bins_count as f64;
        if fitting_bins_count <= 1 {
            score -= 8.0;
        }
    }

    score
}

