pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Penalize residuals falling into "awkward" harmonic classes (small but unusable slivers)
    // Classes: (0,10] terrible, (10,25] bad, (25,50] ok, (50,100] good (half/full reuse)
    let class_penalty = if post_residual == 0 {
        -60.0 // perfect closure
    } else if post_residual <= 10 {
        25.0
    } else if post_residual <= 25 {
        12.0
    } else if post_residual <= 50 {
        0.0
    } else {
        -8.0
    };
    score += class_penalty;

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - slack * 0.15; // exact follow-up fit preferred
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item won't fit here; residual likely dead -> penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.10;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer reusing an open bin unless fit is poor (large post_residual) or
        // the item would leave a sliver AND next item could use a fresh bin better.
        let poor_fit = post_residual <= 10 || post_residual > 50;
        let mut nb = 45.0; // base cost of opening a new bin
        if next_item_size > 0 && next_item_size >= item_size {
            nb -= 10.0; // fresh bin pairs well with large next item
        }
        if open_bins_count == 0 {
            nb = -100.0; // must open
        }
        if poor_fit {
            nb -= 55.0; // reuse is unattractive -> new bin wins
        }
        score += nb;
    }

    // Mild preference for fuller bins overall (tie-break toward tightest fit).
    score += (mean_residual - post_residual as f64) * 0.02;

    // Progression-aware: late in stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += frac * progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

