    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Penalize leaving a gap that nothing can ever use but next item nearly fits (wasted).
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Open-bin pressure: discourage spreading when many bins are open; favor packing into
    // existing bins when the bin count is high relative to items processed.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Deviation from mean residual: prefer bins close to the mean (balanced packing),
    // but tolerate low-residual (nearly full) bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * 2.0 + mean_residual * 0.5;
        // A new bin is neutral-ish early, expensive when many bins are open.
        score += 25.0 + pressure;
        // But if this is the last item, a new bin is wasteful.
        if next_item_size == 0 {
            score += 200.0;
        }
        // If the item fits snugly into a new bin and few bins fit it, allow it.
        if fitting_bins_count <= 1 && bin_capacity - item_size <= 5 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
