        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Dead space risk: post residual too small for next item.
            score += 4.0 * (1.0 - (post_residual as f64 / next_item_size as f64));
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize spreading across many open bins slightly; encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    // Encourage filling bins whose residual is far below the mean residual (i.e., emptier bins
    // relative to average get penalized so fuller bins are preferred).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Time horizon: early in the stream, be more willing to open new bins (exploration);
    // later, prefer tight packing into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate handling: it has bin_residual == bin_capacity so post_residual == capacity - item.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying with progress but never free.
        score += 12.0 + 20.0 * progress;
        // If no open bin can fit the item, opening a new bin is necessary and cheap.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // If this is the only fitting candidate (i.e., new bin is the sole option), favor it.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
        // Large items in a fresh bin early: mild reward to start a dedicated bin.
        if item_size >= bin_capacity / 2 {
            score -= 6.0 * (1.0 - progress);
        }
    }

    // Small global smoothing term coupling mean residual to discourage waste overall.
    score += 0.02 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
