    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: quadratic in normalized post residual (dead space penalized super-linearly)
    let mut score = 2.0 * norm_post + 3.0 * norm_post * norm_post;

    // Non-linear coupling of post_residual with stream progress:
    // early: tolerate larger residuals; late: penalize them more (want tight packing)
    let progress_coupling = 1.0 + 2.5 * progress * progress;
    score *= progress_coupling;

    // Smooth interaction: small post residual is valuable when next item can use it
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = if post >= nxt { 1.0 } else { 0.0 };
        let slack_ratio = (nxt / cap).min(1.0);
