        let match_term = fit_next * (1.0 - ((post - nxt) / cap).abs());
        score -= 1.5 * match_term * (0.5 + 0.5 * progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 4.0 + 3.0 * progress;
    }

    // Penalize bins far below mean residual (fragmentation tendency) with smooth term
    let mean_dev = (post - mean_residual) / cap;
