    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // New-bin candidate: neutral baseline scaled by progress
    if bin_residual == bin_capacity {
        score = cap * (0.5 + 0.5 * progress) + 2.0 * (1.0 - progress);
    }

    score
}

