    }

    // Coupling with mean residual: bins below-average residual are near-full,
    // filling them is good (reward); above-average residual bins can wait.
    if bin_residual != bin_capacity {
        let diff = mean_residual - pr;
        if diff > 0.0 { score -= 0.3 * diff.min(50.0); } else { score += 0.15 * (-diff).min(50.0); }
    }

    // Integer-division threshold on item_size: large items (>50) should be
    // placed eagerly to avoid fragmentation.
    if item_size > 50 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below ~20 are nearly unusable
    // for future items (sizes 1..100, but small gaps waste capacity).
    let dead_zone = 20.0f64;
    if (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 8.0;
    }

    // Reward very tight fits (post_residual small relative to item size).
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score -= (1.0 - tightness.min(1.0)) * 15.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // over opening new bins (penalize new-bin candidate implicitly via
    // rewarding reuse when open_bins_count is high).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64) * (1.0 + 0.5 * progress);
    score += (bin_residual as f64 - item_size as f64) * 0.0; // no-op keep base
    score -= pressure * 0.3 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item could use the post-residual, reward leaving
    // that much space; penalize leaving space just above next item size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 4.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (i.e., fuller bins) to consolidate occupancy.
    score += (mean_residual - bin_residual as f64) * 0.4;

    // New-bin candidate: make it moderately attractive only when the item
    // is large and no tight fit exists; otherwise keep it unattractive.
    if bin_residual == bin_capacity {
        score += 25.0 - 0.2 * item_size as f64;
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post residual exactly fits next item -> strong reward
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 60.0;
        } else {
            // reward closeness of post_residual to next item
            score -= 20.0 * (-diff as f64 / 15.0).exp();
        }
        // penalize post residual too small for next item (dead space)
        if (post_residual as u64) < (next_item_size as u64) {
            score += 8.0 + (next_item_size as f64 - post_residual as f64) * 0.25;
        }
    } else {
        // last item: minimize waste
        score -= 5.0;
    }

    // Reward tight packing relative to mean residual
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.3;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.15;
    }

    // Last-chance bin: strong penalty for abandoning it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score += 25.0;
    }

    // Discourage opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        score += 15.0;
        // allow new bin if item is large and would leave big waste in existing bins
        if item_size > bin_capacity / 2 && fitting_bins_count > 0 {
            score -= 10.0;
        }
    }

    // slight preference for filling bins more fully
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize creating small unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score -= 6.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            score += 3.0;
        }
    } else {
        // Last item: prefer filling any existing bin fully.
        score -= 20.0 * tightness;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current bin would leave a large awkward residual, or few bins are open.
    if bin_residual == bin_capacity {
        let awkward = (post_residual as f64) / (bin_capacity as f64);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins generally; discount penalty late in stream or when open bins are crowded.
        score += 25.0 - 10.0 * progress - 5.0 * (open_bins_count.min(10) as f64 / 10.0);
        // If item nearly fills a fresh bin, new bin is great.
        score -= 10.0 * (1.0 - awkward);
        // If mean residual of open bins is large, opening new bin wastes that space.
        score += (mean_residual / bin_capacity as f64) * 8.0;
    }

    // Mild preference for bins below mean residual (balance load).
    if (bin_residual as f64) > mean_residual {
        score += 2.0;
    } else {
        score -= 1.0;
    }

    // Prefer larger residual bins slightly (use space before it fragments).
    score -= 0.02 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = base * (1.0 + 1.5 * progress * progress) + 0.35 * base * base * (1.0 - progress);

    // Reward tight fits (small post_residual) more strongly late in the stream
    score -= (1.0 - base) * (1.0 - base) * (0.8 + 1.2 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 1.5 + 0.02 * (nxt - pr) * (1.0 + progress);
        } else {
            score -= 0.4 * (1.0 - pr / (pr + nxt)) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 2.5 * (1.0 + progress);
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.1 * open_bins_count as f64 * base;

    // Penalize bins whose residual deviates from mean (fragmentation)
    score += 0.05 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: keep it competitive only when fits are poor
    if bin_residual == bin_capacity {
        score += 1.2 + 0.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: which capacity fraction does the item occupy?
    // Classes of 10 units: items in class k fill roughly k/10 of the bin.
    let item_class = item_size / 10;
    let post_class = post_residual / 10;

    // Reward placements whose post_residual lands on "harmonic" boundaries
    // (0, 10, 20, ...) where future items of common sizes can nest cleanly.
    let harmonic_bonus = if post_residual % 10 == 0 {
        6.0 + (post_class as f64) * 0.5
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Penalize dead space in awkward modulo classes (residuals that no
    // typical item 1..100 can use well, e.g. tiny leftovers 1..=5).
    if post_residual > 0 && post_residual <= 5 {
        score += 25.0;
    } else if post_residual > 5 && post_residual < 10 {
        score += 12.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead harmony: if the next item fits exactly into post_residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size && (post_residual - next_item_size) % 10 == 0 {
            score -= 15.0;
        } else if next_item_size > post_residual {
            // Next item won't fit here; slight penalty for stranding space.
            score += 3.0;
        }
    }

    // Prefer filling already-open bins when many are open (reduce bin count).
    score -= (open_bins_count as f64).sqrt() * 0.5;

    // Early in the stream, be more willing to open fresh bins (score new bin
    // relatively better); later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= 10.0 * progress;
    }

    // Tie-break with mean residual: placing into a bin with residual near the
    // mean keeps the bin pool homogeneous and flexible.
    score -= (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strong reward for zero or near-zero waste.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 500.0;
    }

    // Strict dead-space avoidance: post_residual in a small unusable gap
    // (below the minimum item size 1..10 zone) is pure waste; penalize heavily.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 40.0;
    }

    // Penalize mid-range residuals that are unlikely to fit typical items:
    // residual just below ~20 is often dead space too.
    if post_residual >= 10 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 8.0;
    }

    // Reward using a bin whose residual is "well consumed": tighter fit preferred.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open bins pressure: prefer reusing bins when many are open to avoid sprawl.
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate handling: only open a new bin when the current item is large
    // and would leave a bad residual in existing bins, or when no good fit exists.
    if bin_residual == bin_capacity {
        // Baseline attractiveness of a fresh bin: modest, so real bins usually win.
        score = 75.0 + open_bins_count as f64 * 1.5;
        // If the item would leave a large awkward residual in an average bin,
        // a fresh bin becomes more attractive.
        if (mean_residual - item_size as f64) < 25.0 {
            score -= 20.0;
        }
        // Early in stream, new bins are cheap; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 25.0;
        // If next item is large, a fresh bin with full capacity is valuable.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    }

    // Lookahead: if placing here leaves exactly room for the next item, reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    } else if next_item_size > 0 && post_residual > next_item_size && post_residual < next_item_size + 10 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
