pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Tightness ratio: relative fill quality of this bin.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * tightness;

    // Penalize leaving dead space that no typical item can fill.
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // small leftovers are fine
    } else if post_residual >= 10 && post_residual < 40 {
        score += 10.0; // medium dead zone is mildly bad
    } else if post_residual >= 40 {
        score += 25.0; // large waste
    }

    // Lookahead: if the next item fits exactly into the post residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            let next_fit_quality = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 30.0 * next_fit_quality;
        } else {
            // next item won't fit here; mildly penalize hoarding space.
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, use it before opening new.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only open a new bin when existing bins are crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = if open_bins_count > 0 {
            mean_residual / bin_capacity as f64
        } else {
            0.0
        };
        // Penalize new bin generally, less so when open bins are full and stream is late.
        score += 120.0 - 100.0 * crowding - 40.0 * progress;
        // If nothing fits anywhere, new bin becomes attractive.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Global state: many open bins with high mean residual -> favor consolidating
    // into bins below the mean residual (i.e., tighter bins).
    if open_bins_count > 0 {
        let below_mean = (bin_residual as f64) < mean_residual;
        if below_mean && !is_new_bin {
            score -= 15.0;
        }
        // Encourage closing out bins when too many are open.
        if open_bins_count > 8 && post_residual < 20 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) - norm_pr * (1.0 - progress);
    score += 8.0 * poly;

    // Reward tight fits more strongly late in the stream
    score -= (1.0 - norm_pr) * (1.0 + progress) * 6.0;

    // Penalize dead space relative to next item's need (smooth)
    if next_item_size > 0 {
        let gap = norm_pr - norm_next;
        score += 4.0 * gap * gap.abs() * (1.0 - progress);
        // Reward if next item fits exactly in the post residual
        let fit_next = (norm_next - norm_pr).abs();
        score -= 5.0 * (1.0 - fit_next).max(0.0) * (1.0 - norm_pr);
    }

    // Last-chance bonus: only fitting bin gets strong preference
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 * (1.0 - norm_item);
    }

    // Mild penalty for spreading across many open bins
    score += 0.15 * open_bins_count as f64 * norm_pr * progress;

    // Deviation from mean residual: prefer bins near mean (balance)
    score += 0.05 * (pr - mean_residual).abs();

    // Slight bias against opening new bins early
    if bin_residual == bin_capacity {
        score += 3.0 * (1.0 - progress);
        // but encourage new bin if current item is large relative to capacity
        score -= 10.0 * norm_item * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
