pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Class 0: post_residual divisible by 10 (aligns with typical item sizes)
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -30.0 // perfect fit
    } else if pr % 10 == 0 {
        -8.0
    } else if pr % 5 == 0 {
        -3.0
    } else if pr < 10 {
        10.0 // dead space below minimum item size
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Integer-division threshold: leftover large enough for a mid-size item
    if pr >= 50 {
        score -= 5.0;
    } else if pr >= 30 {
        score -= 2.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.15;
            // harmonic match: both in same capacity fraction class
            let frac_next = (next_item_size as f64 / cap * 4.0).floor();
            let frac_pr = (pr as f64 / cap * 4.0).floor();
            if frac_next == frac_pr && frac_next > 0.0 {
                score -= 4.0;
            }
        } else {
            // next item won't fit here: penalize based on wasted fraction
            score += (next_item_size - pr) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a bin unless current bins are nearly full
    if bin_residual == bin_capacity {
        score += 15.0;
        // allow new bin early in stream or when open bins are mostly exhausted
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < 20.0 && open_bins_count > 0 {
            score -= 25.0;
        }
        if progress > 0.9 {
            score -= 3.0;
        }
    }

    // Prefer fuller bins: reward small residual relative to mean
    score -= (mean_residual - post_residual as f64) * 0.1;

    // Modulo-3 tie-breaking on item size for diversity of packing classes
    score += (item_size % 3) as f64 * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps after placement.
    // A residual is "dead" if it is smaller than the smallest plausible item (1)
    // but more meaningfully if it's below the next item's size and tiny in general.
    if post_residual > 0 {
        let dead_threshold = (next_item_size.max(1)).min(bin_capacity / 2) as f64;
        if (post_residual as f64) < dead_threshold {
            // Dead space penalty grows as the gap becomes less usable.
            score += (dead_threshold - post_residual as f64) * 3.0;
        }
        // Perfect fit bonus: zero residual is ideal.
        if post_residual == 0 {
            score -= 25.0;
        }
    }

    // Prefer tighter fits: normalize post residual by capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Open bins pressure: mildly discourage spreading across many bins,
    // but reward using existing bins when this is the last chance to fit.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        score += (open_bins_count as f64) * 0.5;
    }

    // If the next item fits in the post residual, reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (post_residual - next_item_size) as f64 * 0.1;
    } else if next_item_size > 0 {
        // Next item won't fit here afterwards; slight penalty unless post_residual is 0.
        score += 5.0;
    }

    // Mean residual coupling: placing into a bin far below mean residual
    // (i.e., leaving it underfilled relative to others) is slightly penalized.
    score += ((mean_residual - post_residual as f64).abs()) * 0.2;

    // Slight preference to fill bins earlier in the stream to keep bin count low.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    // New-bin candidate handling: an empty bin should only win when the fit
    // elsewhere would create severe dead space.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but weight by stream progression.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.15 * post_residual as f64 * (0.5 + 0.5 * progress);

    // Exact fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain bonus scaled by how snugly the next item nests.
            let nest = 1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= 25.0 * nest * (1.0 + progress);
        } else {
            // Dead space: next item cannot use leftover space -> penalize.
            let waste = post_residual as f64;
            let dead = if waste < next_item_size as f64 { 1.0 } else { 0.0 };
            score += 12.0 * dead * (waste / bin_capacity as f64);
        }
    } else {
        // Last item: minimize residual as hard as possible.
        score += 0.5 * post_residual as f64;
    }

    // Penalize bins far from mean residual (keep residuals homogeneous).
    score += 0.8 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        // Opening a new bin is expensive; make it slightly unattractive by default.
        score += 30.0;
        // But if the current bin is nearly empty (item is huge relative to residual),
        // a fresh bin is fine.
        if item_size >= bin_residual {
            score -= 60.0;
        }
    }

    // Mild penalty for very large leftover residuals that likely become dead space.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // small slivers are near-useless; prefer using them up
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness;

    // Penalize dead space that is too small for typical future items
    // (residuals < 10 are pure waste; residuals just above a plausible item are fine).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual <= 30 {
        score -= 4.0; // usable pocket for small items
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (post_residual as f64 - next_item_size as f64).min(20.0) / 20.0;
        } else {
            // next item cannot use remaining space; mild penalty proportional to gap
            score += 0.15 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual <= 15 {
            score -= 15.0; // near-perfect last chance
        }
    }

    // New-bin candidate handling: empty bin gets a moderate base cost so we only
    // open new bins when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 18.0;
        // Early in the stream, opening bins is cheaper (build flexibility).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 12.0 * (1.0 - progress);
        // If next item is large and current item is small, a fresh bin pairs well.
        if next_item_size >= item_size && item_size <= 30 {
            score -= 8.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> consolidate,
    // favor filling existing bins (penalize new bins implicitly via open_bins_count).
    let open_f = open_bins_count as f64;
    score += 0.6 * open_f * (bin_residual as f64 / bin_capacity as f64 - 0.5).max(0.0);
    // Deviation from mean residual: prefer bins whose residual is near the item need
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild time decay: later in the stream, waste matters more (fewer chances to fix it).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress
    score += 8.0 * (pr_norm * pr_norm) * (0.5 + progress);
    score -= 6.0 * (pr_norm * (1.0 - pr_norm)) * (1.0 - progress);

    // Penalize dead space that can never host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (0.8 + 0.6 * progress);
        } else {
            score -= 2.0 * (1.0 - (pr - nxt) / cap);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - pr_norm);
    }

    // Slight preference for bins below mean residual (tighter packing)
    score += 0.05 * (pr - mean_residual);

    // New-bin candidate: mildly penalize opening bins early, more later
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: bins whose residual falls into a
    // "dead zone" (very small, unusable slivers) vs. reusable zones.
    let pr = post_residual;
    let class = pr / 10; // integer-division harmonic class 0..10
    match class {
        0 => score -= 25.0,               // perfect/near-perfect fit: reward heavily
        1 => score -= 8.0,                // small but often reusable
        2 | 3 => score += 4.0,            // awkward mid sliver: penalize mildly
        4 | 5 => score -= 3.0,            // half-capacity leftovers are useful
        6 | 7 | 8 => score += 2.0,        // large leftovers: mild penalty (wasteful bin)
        _ => {}
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this bin becomes doubly attractive.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow here: slight penalty for blocking chain
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = bin_capacity as f64 - 55.0 * pressure
            + 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
        if next_item_size > 0 && next_item_size > bin_residual {
            score += 50.0; // impossible for empty bin to be chosen here anyway
        }
    }

    // Mild progression term: late in the stream, consolidate harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (1.0 - (pr as f64) / bin_capacity as f64);

    // Tie-break toward filling fuller (lower-mean-residual) bins.
    score += 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host
    // typical future items are "dead space" -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward bins whose residual is exactly consumed by the item (tight coupling).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 10.0 * tightness;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current item is large and leaves a healthy residual, or when the
    // next item would not fit this bin's post-residual anyway.
    if bin_residual == bin_capacity {
        let mut new_bin_score = 25.0 + open_bins_count as f64;
        if post_residual >= 20 {
            new_bin_score -= 20.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            new_bin_score += 10.0;
        }
        score = score.max(new_bin_score) + (score - new_bin_score).abs() * 0.0 + new_bin_score;
        return score;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into
    // already-open bins rather than spreading items out.
    score += 0.5 * open_bins_count as f64;

    // Lookahead: if the next item fits exactly in the post-residual,
    // strongly favor this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 45.0;
        } else if gap < 10 {
            score -= 15.0;
        }
    }

    // Stream progression: late in the stream, be extra conservative with
    // residual capacity (fewer chances to fix dead space).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Mild preference for bins below mean residual (balancing load).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits heavily.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space quadratically (unusable slivers).
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += (10.0 - pr) * 20.0;
        }

        // 2-step lookahead: if next item fits into post_residual, reward strongly.
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover = post_residual - next_item_size;
            let tightness = (bin_capacity as f64 - leftover as f64) / bin_capacity as f64;
            score -= 40.0 + 30.0 * tightness;
        } else if next_item_size > 0 {
            // Next item won't fit here: penalize wasted lookahead opportunity.
            score += 15.0;
        }

        // Relative to mean residual: prefer bins tighter than average.
        score += (mean_residual - bin_residual as f64) * 0.5;

        // Last-chance bonus: only one bin can fit this item.
        if fitting_bins_count == 1 {
            score -= 60.0;
        }

        // Prefer bins with small residual relative to item size (tight packing).
        let ratio = item_size as f64 / bin_residual as f64;
        score -= ratio * 10.0;
    }

    // Mild new-bin penalty: discourage opening a new bin when reasonable fits exist,
    // but allow it when the item is large and residuals are fragmented.
    if bin_residual == bin_capacity {
        score += 30.0 - (item_size as f64 * 0.2);
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Penalize dead space that nothing small can use (min item ~1, but small items rare).
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * dead * dead;

    // Lookahead: if the next item fits exactly into the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            let waste_after_next = post_residual - next_item_size;
            score += 0.4 * waste_after_next as f64;
        } else {
            // Next item won't fit here regardless; slight penalty scaled by overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 0.15 * over.min(40.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over opening a new one,
    // unless the residual after placement is tiny-but-unusable.
    if fitting_bins_count <= 1 {
        score -= 20.0;
    }

    // Global state: many open bins with high mean residual -> prefer consolidating into bins
    // with below-average residual (tighter bins).
    let dev = mean_residual - bin_residual as f64;
    score += 0.5 * dev; // bin_residual > mean => lower score => favored

    // Time horizon: late in the stream, be more aggressive about filling bins tightly
    // and less willing to open new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * (post_residual as f64 / bin_capacity as f64);
    score += 10.0 * progress * (open_bins_count as f64).ln().max(0.0);

    // Mild penalty for opening a brand-new bin when decent fits exist.
    if bin_residual == bin_capacity {
        let decent_fit_exists = (bin_capacity - item_size) <= 40 && fitting_bins_count > 0;
        score += if decent_fit_exists { 35.0 } else { 8.0 };
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score += 5.0;
        }
    }

    // Tie-break: prefer bins with less remaining absolute space (tighter packing).
    score += 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Normalize post residual and couple non-linearly with stream progress
    let prn = pr / cap;
    let prog_term = prn * (1.0 + 2.0 * progress * progress);
    score += 12.0 * prog_term;

    // Penalize small dead space that is hard to reuse (smooth quadratic valley)
    let waste = prn * (1.0 - prn);
    score -= 30.0 * waste * waste * cap / 100.0;

    // Lookahead: reward residual that can fit the next item (smooth gaussian-ish)
    if next_item_size > 0 {
        let fits_next = if (post_residual as u32) >= next_item_size { 1.0 } else { 0.0 };
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score -= 25.0 * fits_next * (-gap * gap / 400.0).exp();
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress);
    }

    // Spread of bin residual vs mean: prefer bins below mean residual (tighter fills)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev;

    // Mild pressure toward reusing bins when many are open
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
