}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space classes via integer division thresholds.
    let post = post_residual as f64;
    let class = (post_residual / 10) as f64; // 0..10 harmonic classes
    // Reward small post_residual non-linearly (best-fit with emphasis).
    score -= 25.0 * (1.0 - post / cap).powi(3);

    // Penalize mid-range dead space classes (unusable gaps ~ 20..40).
    if post_residual >= 15 && post_residual <= 40 {
        score += 12.0 - 0.3 * class;
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Chain fit is valuable; reward, more if gap small.
        let chain_gap = post_residual - next_item_size;
        score -= 18.0 - 0.4 * chain_gap as f64;
    } else if next_item_size > 0 {
        // Next item won't chain; penalize proportionally to wasted potential.
        score += 0.15 * post;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when residuals are fragmented or bin is crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score = cap + 0.5 * open_bins_count as f64;
        if next_item_size > 0 {
            // Prefer new bin if next item is large and current residuals are tight.
            let tight = (mean_residual < (next_item_size as f64)).then(|| 1.0).unwrap_or(0.0);
            score -= 40.0 * tight;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.02 * open_bins_count as f64 * (post / cap);

    // Progress modulation: late in stream, waste hurts more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.1 * post;

    // Mean-residual alignment: prefer bins close to mean residual (keeps balance).
    score += 0.2 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize small unusable gaps (< 10) heavily; they are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Non-linear dead-space penalty: gaps that no typical item can use.
    let gap = post_residual as f64;
    score += (gap / bin_capacity as f64).powf(3.0) * 150.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Reward filling bins when many bins are open (bin count pressure).
    score -= open_bins_count as f64 * 5.0;

    // Reward bins tighter than the mean residual (good compaction).
    if (bin_residual as f64) < mean_residual {
        score -= 20.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 80.0;
    }
    // If next item would NOT fit the gap, penalize leaving that gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 60.0;
    }

    // Early in stream: prefer keeping bins open flexible (larger post_residual ok).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
