pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact 2-step lookahead match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Reward near matches: next item fits into post_residual with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.8;
    }
    // Penalize creating dead space the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Penalize large residual waste relative to mean residual across open bins.
    let resid_f = post_residual as f64;
    if resid_f > mean_residual {
        score += (resid_f - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - resid_f) * 0.1;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // With alternatives, prefer tighter fits (already encoded in post_residual).
        score += 2.0;
    }

    // New-bin candidate: only attractive when nothing fits well or stream is early.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0 || (next_item_size > 0 && post_residual < next_item_size && post_residual > 0);
        if poor_fit {
            score -= 10.0;
        } else {
            // Opening a new bin wastes the residual of existing bins; discourage mildly.
            score += 20.0 + (open_bins_count as f64).sqrt() * 5.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
