pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Penalize dead space: post_residual too small to fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    } else if post_residual < 20 {
        score += 6.0;
    }

    // Lookahead: bonus if the next item exactly fits post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Time horizon: early in the stream, be more selective (avoid fragmentation);
    // late in the stream, fill bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (post_residual as f64) * 0.4;

    // Global state: many open bins -> prefer filling existing bins over new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or mean residual is large.
        score += 30.0 + open_bins_count as f64 * 3.0 + mean_residual * 0.3;
    } else {
        // Existing bin: reward relative to mean residual (below-average residual = tight bin).
        score += (mean_residual - bin_residual as f64) * 0.25;
        score -= open_bins_count as f64 * 0.5;
    }

    // Item-size coupling: large items prefer roomier bins.
    if item_size > 50 {
        score -= (bin_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Quadratic penalty on waste: dead space hurts more as it grows.
    score += 0.9 * (pr / cap) * (pr / cap) * cap;

    // Strong reward for tight fits (small post_residual), non-linear.
    score -= 25.0 * (1.0 - pr / cap).powi(3);

    // Cubic coupling: prefer filling bins as stream progresses (close out bins).
    let fill = 1.0 - pr / cap;
    score -= 20.0 * progress * fill * fill * fill;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: penalize if post_residual is small but nonzero and next item
    // would not fit (creates stranded space); reward if next item fits snugly.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 8.0 * (1.0 - (pr - ni) / cap);
        } else if pr > 0.0 {
            score += 6.0 * (1.0 - pr / cap);
        }
    }

    // Prefer placing into bins already below mean residual (consolidate slack).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when existing bins fit well.
    if bin_residual == bin_capacity {
        let mut penalty = 18.0 + 25.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            penalty += 12.0;
        }
        score += penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create "dead space classes".
    let post_mod = post_residual % 10;
    // Penalize small nonzero residues (worst dead space: 1..9 units unusable by most items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    } else if post_mod != 0 {
        score += post_mod as f64 * 1.5;
    } else {
        // Perfect harmonic alignment (post_residual divisible by 10): reward.
        score -= 8.0;
    }

    // Integer-division thresholds: how many "standard item slots" of size 10 fit in post_residual.
    let slots = post_residual / 10;
    score -= slots as f64 * 2.0;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves residue: mild reward scaled by fit quality.
            let nr = post_residual - next_item_size;
            score -= 10.0 - (nr % 10) as f64;
        } else {
            // Next item won't fit here: penalize slightly, more if this bin was "reserved".
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits the item, prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity; make it costly
    // unless current bins are crowded (mean residual low relative to item size).
    if bin_residual == bin_capacity {
        let crowd = mean_residual / (bin_capacity as f64);
        score = 60.0 + (1.0 - crowd) * 40.0;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.min(bin_capacity) {
            score -= 10.0;
        }
    }

    // Prefer fuller bins: reward low residual relative to capacity fraction.
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * 12.0;

    // Late in the stream, tighten packing (less tolerance for loose residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    // Many open bins: discourage spreading; favor consolidation into existing bins.
    if open_bins_count > 3 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps (<10) are unusable waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight fit bonus: item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Penalize bins whose residual is already small (fragmented bins).
    if bin_residual < 30 {
        score += 10.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    score += 0.05 * open_bins_count as f64;

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item almost fits the post residual, slight penalty for wasting it.
    if next_item_size > post_residual && post_residual > 0 && next_item_size - post_residual <= 5 {
        score += 8.0;
    }

    // New-bin candidate (empty bin): must be chosen only when fits are bad.
    if bin_residual == bin_capacity {
        score += 18.0;
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer bins below mean residual (consolidate space).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact fits: near-zero post residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space quadratically (unusable gaps).
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 8.0;
        }
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0; // perfect 2-step chain
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // reward proportional closeness, but penalize leaving a tiny unusable remainder
            score -= (60.0 * (1.0 - gap / bin_capacity as f64)).max(0.0);
            if gap < 10 {
                score += (10.0 - gap) * 5.0; // small gap is dead space
            }
        } else {
            // next item won't fit here: mild penalty scaled by deficit
            let deficit = (next_item_size - post_residual) as f64;
            score += deficit * 0.5;
        }
    }

    // Relative to mean residual: prefer bins tighter (smaller residual) than average.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Late in the stream: consolidate, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 40.0 + 120.0 * progress + 2.0 * open_bins_count as f64;
    } else {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead waste).
    if next_item_size > 0 && post_residual > 0 {
        if (next_item_size as u32) > post_residual {
            score += 0.55 * (post_residual as f64);
        } else {
            // Reward residuals that can still host the lookahead item.
            score -= 0.35 * (post_residual as f64);
        }
    }

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 40.0 && fitting_bins_count > 0;
        score += if poor_fit { 0.0 } else { 30.0 };
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    // Global pressure: many open bins with high mean residual -> consolidate.
    if open_bins_count > 2 && mean_residual > (item_size as f64) {
        score -= 4.0;
    }

    // Mild penalty for very large residuals left behind (fragmentation).
    if post_residual > 60 {
        score += 0.25 * ((post_residual - 60) as f64);
    }

    // Reward bins whose residual is close to (but >=) the item size.
    let slack = (bin_residual - item_size) as f64;
    score -= 6.0 / (1.0 + slack * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits (small post-residual), non-linearly amplified.
    let mut score = pr * (1.0 + 1.5 * (pr / cap).powi(2));

    // Smooth stream-progress coupling: late in the stream, tight packing matters more.
    score *= 1.0 + 0.8 * progress * (pr / cap);

    // Reward when the next item fits into the post-residual (chained fit).
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let snug = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        score -= 8.0 * snug;
    } else if next_item_size > 0 {
        // Penalize residuals that waste space relative to the next item.
        score += 2.0 * (next_item_size as f64 - pr).min(cap) / cap * 6.0;
    }

    // Last-chance bonus: only one bin fits the item; strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Dampen preference for many open bins: encourage closing out existing bins.
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    // New-bin candidate: penalize mildly so it wins only when fits are terrible.
    if bin_residual == bin_capacity {
        score += 12.0 + 6.0 * progress;
    }

    // Dead-space penalty: residuals too small for the smallest plausible item.
    if pr > 0.0 && pr < 1.0 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue classes" (0,1,2,5,10) are near-perfectly packed.
    let pr = post_residual;
    let class_bonus: f64 = match pr {
        0 => 60.0,
        1..=2 => 45.0,
        3..=5 => 30.0,
        6..=10 => 18.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Harmonic class of the bin's fill level via integer division on capacity.
    let fill_class = (bin_residual * 4) / bin_capacity; // 0..=3 quarters
    score -= match fill_class {
        0 => 0.0,
        1 => 2.0,
        2 => 4.0,
        _ => 6.0,
    } as f64;

    // Lookahead: reward if next item fits exactly into the post residual
    // (harmonic pairing), penalize if next item cannot fit.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let pair_class = (pr % next_item_size.max(1)) as f64;
            score -= 20.0 - pair_class * 2.0;
        } else {
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize creating large dead space relative to mean residual of open bins.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.4;
    }

    // Late in the stream, prefer tight packing even more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    // New-bin candidate handling: opening a new bin should only win when no
    // open bin offers a decent fit. Make the empty bin moderately attractive
    // only if the item is large relative to capacity or few bins fit it.
    if bin_residual == bin_capacity {
        score = cap - item_size as f64; // waste of a fresh bin = capacity - item
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        } else if fitting_bins_count == 1 {
            score += 10.0; // discourage abandoning the last fitting bin
        }
        if item_size as f64 > 0.8 * cap {
            score -= 30.0; // large items deserve fresh space
        }
        score += open_bins_count as f64 * 0.5; // slight preference to reuse bins
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible
    // item are pure waste — penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 40.0;
    }

    // Penalize leaving a gap that is smaller than the next item if the next
    // item would otherwise fit here (lookahead-aware dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }
    // Reward leaving exactly enough room for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins; penalize spreading.
    score += 1.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Mean-residual coupling: prefer bins whose residual deviates below the
    // mean (i.e., this bin is tighter than average) to keep residuals bimodal.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: an empty bin has large post_residual, which
    // already scores high; add extra penalty so a new bin is opened only when
    // existing fits are truly bad, but relax late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 - 20.0 * progress;
        // If no open bin fits at all, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mild penalty for large leftover gaps relative to capacity (wasted space).
    if post_residual >= 10 {
        score += 0.1 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already does this).

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain: next item exactly fills this bin
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64); // near-chain bonus
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.6; // next item won't fit here: penalize leftover dead space
        }
    } else {
        // Last item: strongly prefer minimal waste
        score -= 50.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Compare against mean residual across open bins:
    // a bin below mean residual is "tighter" than average -> slightly favored.
    let resid = post_residual as f64;
    if mean_residual > 0.0 {
        score += (mean_residual - resid) * -0.15; // lower-than-mean residual gets bonus
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && post_residual <= bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has post_residual = capacity - item_size,
    // which is large; add a penalty so it only wins when open bins are genuinely bad.
    if bin_residual == bin_capacity {
