pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min size 1..=100, but realistically small gaps below
    // the typical item size are dead) are heavily penalized.
    // Treat gaps <= 10 as fully dead; scale penalty sharply.
    if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 40.0;
    } else if post_residual < 10 {
        // Unusable sliver: penalize hard.
        score += 60.0;
    } else {
        // Usable gap: mild reward for leaving large flexible space.
