    }

    // Reward leaving a gap that exactly fits the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize a gap that is just barely too small for the next item
    // (creates regret: the space is wasted for the known future demand).
    if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += 20.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few are open, opening a new bin is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure term.
        score += 55.0 + 2.0 * pressure;
    } else {
        // Reward using existing bins more when many are open.
        score -= 0.3 * pressure;
    }

    // Slight preference for bins with residuals above the mean
    // (consolidate space in emptier bins, keep tight bins tight).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // If post_residual can still fit the next item, mildly reward tight-but-viable leftovers
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Dead space: leftover smaller than next item (and small in absolute terms) is waste
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += waste * 0.6;
    }

    // Compare post_residual against mean residual of open bins:
    // leaving a residual close to the mean keeps bins homogeneous and reusable
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.25;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent fitting bins already exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0;
        // but if the new bin would be a perfect 2-item match, allow it
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 30.0;
        }
    }

    // Very large leftovers relative to capacity are fine (flexible bins)
    if post_residual >= 50 {
        score -= 5.0;
    }

    // Early in the stream, be more tolerant of spreading items across bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    score
