        score -= 1000.0;
    }

    // Harmonic classes: post_residual bucketed by integer division.
    // Buckets: [0], (0,10], (10,20], (20,40], (40,60], (60,100]
    let class = match post_residual {
        0 => 0u32,
        1..=10 => 1,
        11..=20 => 2,
        21..=40 => 3,
        41..=60 => 4,
        _ => 5,
    };
    // Prefer bins whose leftover class is large enough to be reusable;
    // small-but-usable leftovers get a mild bonus, big leftovers are just best-fit.
    score += match class {
        1 => -5.0,
        2 => -12.0,
        3 => -3.0,
        _ => 0.0,
    };

    // Lookahead coupling: reward if post_residual exactly (or closely) matches next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 30.0 * (1.0 - gap as f64 / 11.0);
            }
        } else {
            // next item cannot fit here: leftover must serve others; slight penalty
            // proportional to how far post_residual is from any usable class.
            score += 2.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: a fresh bin has residual == capacity.
    // Prefer open bins with tight fits; only favor new bin when open bins
    // would leave very wasteful residuals relative to mean residual.
    if bin_residual == bin_capacity {
        // New bin: baseline cost of opening it.
        score += 15.0;
        // Late in the stream, closing out tight is better: discourage new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If many bins are open and mean residual is small, opening new bins
        // fragments capacity; penalize more.
        if open_bins_count > 4 && mean_residual < 30.0 {
            score += 25.0;
        }
    } else {
        // Tightness reward relative to capacity.
        let tightness = 1.0 - post_residual as f64 / cap;
        score -= 10.0 * tightness;
    }

    // Modulo harmonic: residual divisible into nice chunks (multiples of 10/20)
    // are more reusable by typical item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.92;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use
    // (below the minimum size of 1 we assume tiny gaps are wasted) get a
    // strong nonlinear penalty, especially for gaps in the "dead zone"
    // (1..=10) where almost nothing fits.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64);
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Penalize leaving a gap that is larger than the next item needs
    // only mildly; but reward if next item exactly fits the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // gap too small for lookahead item -> likely dead space
            score += 25.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor
    // filling existing bins; few open bins -> opening new bins is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 3.0;

    // Prefer bins with residuals near the mean (keeps bin states uniform,
    // improving future pairing opportunities).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // New-bin candidate: only attractive when no good fit exists, i.e.
    // when existing best option would leave large dead space. Base cost
    // for opening a new bin grows with progress through the stream.
    if bin_residual == bin_capacity {
        score += 20.0 + 25.0 * progress;
        // But if the item is large, a fresh bin is natural.
        if item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
        // If existing bins are nearly full on average, new bin is fine.
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
