pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: post_residual slightly above next item size (wasted but still usable)
    if next_item_size > 0 && post_residual > next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 - gap * 0.6;
        if gap > 25.0 {
            score += (gap - 25.0) * 0.4; // too much slack left
        }
    }

    // Dead space: post_residual positive but smaller than next item size
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64;
        score += dead * 0.8; // penalize unusable sliver
    }

    // Last-chance bin: only bin that fits -> strong preference to use it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Compare against mean residual: bins with residual near mean are interchangeable,
    // prefer bins with tighter residual relative to item (better fit)
    let fit_tightness = (bin_residual - item_size) as f64;
    let mean_gap = (fit_tightness - mean_residual).abs();
    score += mean_gap * 0.15;

    // Reward filling bins that are already small-residual (consolidation)
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.1;

    // Late in stream: be more conservative, avoid opening sprawl
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    // Many open bins: discourage opening yet another bin
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
