pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward leaving residuals that can fit the lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // Penalize dead space that cannot host the next item
        score += 0.3 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Many open bins: prefer filling existing ones tighter
    let crowding = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * crowding * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins near the mean (balanced packing)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.2 * dev;

    // Time horizon: early in stream, allow looser fits; late in stream, be greedy
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    // New-bin candidate handling: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a new bin
        } else {
            // Opening a new bin is only good if this item is large and fits are tight
            let tight = (item_size as f64 / bin_capacity as f64) > 0.7;
            if tight {
                score -= 40.0;
            } else {
                score += 150.0 + 50.0 * (1.0 - progress); // discourage early bin opening
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = prn * prn * (1.0 - progress) + prn * progress * (1.0 - prn);
    score += 12.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - prn;
    score -= 8.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Penalize dead space relative to mean residual
    if pr > mean_residual {
        score += 0.3 * (pr - mean_residual);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 5.0;
    }

    // Lookahead: reward residual that can host next item
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if pr >= nr {
            score -= 3.0 * (1.0 - (pr - nr) / cap);
        } else {
            score += 2.0 * (nr - pr) / cap;
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * prn;

    // New-bin candidate: prefer only when fit is poor
    if bin_residual == bin_capacity {
        score += 6.0 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: which quarter of the bin does the post-residual fall in?
    let quarter = bin_capacity / 4; // 25
    let half = bin_capacity / 2;    // 50

    // Reward tight fits (small post_residual), with extra bonus for exact fill.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    } else if post_residual <= quarter {
        score -= 8.0;
    }

    // Penalize dead space that cannot fit the next item (waste).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward leaving room for the lookahead item.
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Modulo / integer-division thresholds on post_residual.
    let pd = post_residual as u32;
    if pd % 10 == 0 {
        // Residual aligned to a decade: still usable by common item sizes.
        score -= 4.0;
    }
    if pd < 10 && pd > 0 {
        // Tiny sliver: near-waste.
        score += 12.0;
    }
    if pd > half {
        // Bin still more than half empty after placement: fine, mild reward.
        score -= 2.0;
    }

    // Harmonic class of next item: if next item is large (> half), prefer bins
    // with large residuals so it can still fit later.
    if next_item_size > half {
        if bin_residual - item_size >= next_item_size {
            score -= 5.0;
        } else {
            score += 5.0;
        }
    }

    // New-bin candidate: prefer opening a fresh bin only when existing bins
    // are crowded (mean residual low) or fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let crowding = mean_residual / bin_capacity as f64;
        // New bin is penalized by how much room remains elsewhere.
        score += 30.0 * crowding;
        // Early in stream, opening bins is cheap; later, prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        // If many bins can fit, discourage opening another.
        score += 2.0 * fitting_bins_count as f64;
    }

    // Mild penalty for spreading across many bins when mean residual is high.
    if mean_residual > half as f64 && !is_new_bin {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Tight fit relative to residual: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins.
    score += 4.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else if post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual < 10 {
            // next item would leave dead space here too
            score += 15.0;
        }
    }

    // New-bin candidate: only attractive when existing bins would waste a lot
    // or there is nothing open; an empty bin starts with full flexibility.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 200.0;
        } else {
            let waste_existing = mean_residual - item_size as f64;
            if waste_existing > 20.0 {
                score -= 35.0 + 0.5 * waste_existing;
            } else {
                score += 40.0;
            }
            // late in the stream, avoid proliferating bins
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 30.0 * progress;
        }
    }

    // Mild alignment with mean residual: prefer bins whose residual is near mean
    // (balanced consolidation) unless it is a tight fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item fill
        } else if post_residual > next_item_size {
            // next item fits after this one: reward proportional to closeness of fit
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize dead space relative to mean residual
            score += 0.5 * (post_residual as f64 - mean_residual).abs();
            if post_residual < 10 {
                score += 15.0; // tiny unusable sliver
            }
        }
    } else {
        // last item: prefer tightest fill
        score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening new bins when open bins exist with reasonable residual
    if bin_residual == bin_capacity {
        score += 40.0 + 2.0 * open_bins_count as f64;
        // but if no open bin fits well, opening is fine
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    // Mild preference for bins tighter than average
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Early stream: slightly discourage fragmentation to preserve flexibility
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.2 * post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual waste
    let post_frac = post_residual as f64 / bin_capacity as f64;

    // Reward tight fits: strongly penalize large post-residual
    score += 40.0 * post_frac * post_frac;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: this is the only bin that fits -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening new bins when good fits exist elsewhere
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty that shrinks late in stream
        score += 12.0 * (1.0 - 0.5 * progress);
        // If many bins fit the item, opening a new bin is wasteful
        if fitting_bins_count > 0 {
            score += 8.0 * (fitting_bins_count as f64).min(5.0);
        }
        // If this bin is the last chance, allow opening a new bin
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Lookahead coupling: does the leftover space suit the next item?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            // leftover can host next item -> reward
            score -= 10.0 * (nxt / bin_capacity as f64);
        } else if post_residual > 0 {
            // leftover is dead space relative to next item -> penalize
            score += 6.0 * (1.0 - post_residual as f64 / nxt.max(1.0));
        }
    }

    // Global state: prefer filling bins with large residuals when mean residual is high
    let resid_gap = mean_residual - bin_residual as f64;
    score += 0.05 * resid_gap;

    // Slight preference for bins that are already substantially filled
    score -= 8.0 * (bin_residual as f64 / bin_capacity as f64);

    // Late stream: consolidate aggressively, fewer open bins is better
    score += 0.5 * open_bins_count as f64 * progress;

    // Small tie-breaker noise-free determinism: favor earlier bins implicitly via residual
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, non-linearly penalized residual
    let mut score = pr as f64 + 40.0 * norm_pr * norm_pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste matters less; later, tight packing dominates.
    let coupling = (0.5 + 0.5 * progress) * (norm_pr * (1.0 - norm_pr)) * 4.0;
    score -= 60.0 * coupling * (item_size as f64 / cap);

    // Penalize leaving residual close to small future items (dead space)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 8.0 * (-gap / 30.0) * (1.0 - progress);
    }

    // Last-chance bin: reward using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty when many bins are open and residual is large
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // New-bin candidate: keep it neutral-ish, slightly favored when open bins are fragmented
    if bin_residual == bin_capacity {
        score = pr + 10.0 + 0.3 * mean_residual - 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space?
    // Classes via integer division on capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_frac = post / cap;

    // Class A: residual is tiny -> excellent packing, reward strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_frac < 0.10 {
        score -= 25.0;
    } else if post_frac < 0.20 {
        score -= 10.0;
    } else if post_frac < 0.35 {
        score -= 3.0;
    } else if post_frac < 0.50 {
        // moderate leftover, neutral-ish
        score += 0.0;
    } else if post_frac < 0.70 {
        score += 12.0;
    } else {
        // large leftover: wasteful placement, penalize
        score += 25.0;
    }

    // Harmonic threshold classes on post_residual via modulo arithmetic:
    // residuals that are multiples of common small item sizes remain reusable.
    let reusable = |r: u32| -> bool {
        for m in [10u32, 20, 25, 30, 40, 50] {
            if r % m == 0 { return true; }
        }
        false
    };
    if reusable(post_residual) && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // this is a perfect chain — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let nfrac = next_item_size as f64 / post.max(1.0);
            if nfrac > 0.8 {
                score -= 15.0;
            } else if nfrac > 0.5 {
                score -= 6.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // competition: slight preference for tighter fits already in base term
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // New-bin candidate handling: opening a new bin wastes capacity equal to
    // residual of all open bins; penalize when open bins are still roomy.
    if bin_residual == bin_capacity {
        let waste = mean_residual * open_bins_count as f64;
        score += 20.0 + waste * 0.15;
        // but if nothing else fits well (this call is compared only against
        // fitting bins), a modest penalty suffices; late in the stream keep bins fewer.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Mild consolidation pressure: prefer bins with below-mean residual
    // (fills the emptiest-relative bins first, balancing closure).
    score += (mean_residual - bin_residual as f64) * 0.10;

    // Small tie-breaker toward filling larger items into tighter bins.
    score += item_size as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1)
    // are pure waste; here any tiny gap (< ~10) is effectively dead space
    // under the original regime, but with sizes 1..100 use a soft threshold.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64);
    }

    // Reward tight fits: post_residual near 0 is excellent.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Perfect fill of an existing bin is ideal (bin disappears).
    if post_residual == 0 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 30.0 + 8.0 * open_bins_count as f64;
        // But if no open bin fits well, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Lookahead: prefer leaving room for the next item if it fits snugly.
    if next_item_size > 0 {
        let next_fits = (post_residual as i64 - next_item_size as i64) >= 0;
        if next_fits {
            let gap = post_residual as f64 - next_item_size as f64;
            score -= 15.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            score += 5.0;
        }
    }

    // Mean residual coupling: bins far below the mean residual are
    // "waste candidates"; prefer filling them to consolidate.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Early stream: be slightly greedy to keep bin count low.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.18;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 500.0;
    } else {
        // Penalize dead space quadratically relative to capacity.
        score += (post_residual as f64 / bin_capacity as f64).powi(2) * 150.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits the post-residual exactly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            // Next item fits here: mild reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item does NOT fit here: penalize bins whose post-residual
            // is a stranded sliver (below the minimum item size ~1..100 range).
            if post_residual < next_item_size && post_residual < 10 {
                score += 300.0;
            }
            // Reward bins that could hold a future item combined with next item? no:
            // penalize leaving residual that neither fits next item nor is tiny.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    } else {
        // Last item: any bin works, prefer tightest fit (already via post_residual).
        score -= 50.0;
    }

    // Compare post-residual against mean residual across open bins:
    // prefer bins whose residual after placement stays near/below the mean
    // (balancing load) but heavily prefer below-mean when mean is large.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 1.5;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.5;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate (empty bin): make it attractive only when the item
    // is large or open bins are scarce; otherwise discourage spreading.
    if bin_residual == bin_capacity {
        if item_size >= 60 || open_bins_count == 0 {
            score -= 100.0;
        } else {
            score += 120.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Mild late-stream conservatism: fewer wasted slivers toward the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 20.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post residual.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tightness * tightness;

    // Perfect / near-perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item fits in the post residual (chaining),
    // penalize if next item barely misses.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            score -= 12.0 + 8.0 * (1.0 - (post_residual as f64 - nx) / cap);
        } else if post_residual > 0 {
            let gap = nx - post_residual as f64;
            if gap < 20.0 {
                score += 10.0 * (1.0 - gap / 20.0);
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Crowding pressure: when many bins are open, prefer filling existing ones
    // rather than opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = (open_bins_count as f64).ln_1p();
    score += 2.0 * crowding * (1.0 - tightness);
    score -= 4.0 * progress * tightness;

    // Mean-residual coupling: if the fleet's average residual is high,
    // discourage leaving more slack here; if low, allow slack.
    score += 0.05 * (mean_residual - post_residual as f64);

    // New-bin candidate calibration: an empty bin has post_residual == cap - item.
    // Make it attractive only when the current fit is bad (large post_residual)
    // and mean residual across open bins is already low (little room left overall).
    if bin_residual == bin_capacity {
        let bad_fit = (post_residual as f64) / cap; // large for poor fits
        let fleet_full = 1.0 - mean_residual / cap;
        score -= 70.0 * bad_fit * fleet_full;
        // Late in the stream, opening fresh bins is cheaper than scattering.
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;
    let fit_norm = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * (1.0 + 0.8 * progress - 0.5 * progress * progress);

    // Smooth waste penalty: dead space below typical item scale is costly
    let waste = if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let gap = (nxt - pr_norm).max(0.0);
        gap * gap * 2.0
    } else {
        0.0
    };

    // Reward tight fits, more so early when bins are scarce
    let tight = -2.0 * fit_norm * fit_norm * (1.0 - progress);

    // Last-chance bonus: strongly favor the only fitting bin
    let last_chance = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -3.0
    } else if bin_residual == bin_capacity {
        // New-bin candidate: penalize mildly unless current bin fit is bad
        1.5 + 2.0 * pr_norm
    } else {
        0.0
    };

    // Congestion coupling: spread load when many bins open
    let congestion = 0.3 * open_bins_count as f64 * pr_norm * pr_norm;

    let mut score = poly + waste + tight + last_chance + congestion
        - 0.5 * (mean_residual / cap - pr_norm).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is a "composable"
    // residue (small or divisible by common item classes) are rewarded.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        60.0 // perfect fit
    } else if pr <= 10 {
        40.0 // nearly perfect
    } else if pr % 10 == 0 {
        25.0 // composable residue (matches item granularity)
    } else if pr % 5 == 0 {
        15.0
    } else if pr >= 60 {
        20.0 // large residue still flexible
    } else if pr >= 30 {
        5.0
    } else {
        -10.0 // awkward dead space
    };
    score -= harmonic_bonus;

    // Integer-division threshold: penalize residues that cannot host the
    // next item (wasted lookahead opportunity).
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 12.0;
        } else {
            score += (next_item_size - pr) as f64 * 0.3;
        }
        // Reward leaving exactly a harmonic class matching next item
        if pr >= next_item_size && (pr - next_item_size) % 10 == 0 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer keeping it closed early, allow it late
    // or when the fit here is terrible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 45.0 - 25.0 * progress;
        if post_residual == 0 {
            score -= 60.0; // fresh bin perfectly filled
        }
    }

    // Coupling with mean residual: bins far below mean waste capacity.
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.4;

    // Small tie-breaker toward tighter bins.
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..100 unknown,
    // but smallest plausible item ~ 10 in classic setting; treat < 12 as dead).
    let dead_threshold = 12u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 + (dead_threshold - post_residual) as f64 * 4.0;
    }

    // Reward tight fits: post_residual small but usable.
    if post_residual > 0 {
        score -= (1.0 - post_residual as f64 / 40.0).max(0.0) * 15.0;
    } else {
        // Perfect fill is excellent.
        score -= 25.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }
    // Many fitting bins: mild pressure to keep options open elsewhere.
    if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0);
    }

    // Open-bin pressure: discourage spreading when many bins are open,
    // unless the fit is very tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * 0.5;

    // New-bin candidate logic: opening a fresh bin is attractive when the item
    // fits poorly everywhere (large post_residual in existing bins) or when
    // dead space would be created.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 55.0;
        let would_create_dead = post_residual > 0 && post_residual < dead_threshold;
        if poor_fit || would_create_dead || fitting_bins_count == 0 {
            score -= 30.0;
        } else {
            // Slight bias toward reusing existing bins for good fits.
            score += 10.0 + mean_residual * 0.05;
        }
    }

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual > 0 {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // Mild preference for balancing residuals toward the mean (fragmentation control).
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward when next item exactly matches post_residual.
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            score -= 60.0; // perfect two-item fill
        } else if diff > 0 {
            // next item fits in the residual: reward proportionally to how well it fills
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 50.0 * fill * fill;
        } else {
            // next item cannot fit: penalize dead space relative to gap
            score += (next_item_size as f64 - post_residual as f64) * 0.35;
        }
    }

    // Compare post_residual against mean residual: avoid creating outliers far below mean
    // (fragmented dead space) but also avoid leaving bins excessively full early.
    score += 0.8 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when all open
    // bins would leave very poor fits (large post_residual) or item is large.
    if bin_residual == bin_capacity {
        // Empty bin: its post_residual = capacity - item_size; penalize mildly so it is
        // chosen only when open bins score badly (poor fits / lookahead mismatch).
        score += 25.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0; // fresh bin can chain the next item too
        }
    }

    // Early in the stream, allow more bins to open (spreading keeps options open);
    // late in the stream, squeeze into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 10.0 * (open_bins_count as f64).sqrt().recip().min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: reward if the next item fits exactly or well in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving a residual that is
            // "useless" (too small for the smallest plausible item).
            if post_residual < 10 {
                score += 10.0;
            }
            // Penalize blocking a residual the next item would have consumed elsewhere.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.08 * overshoot;
        }
    } else {
        // Last item: only tightness matters; discourage opening new bins.
        if bin_residual == bin_capacity {
            score += 200.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer it only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream position and open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 55.0 + 25.0 * progress;
        if open_bins_count == 0 {
            new_bin_cost = -100.0; // must open
        }
        // If many bins are open with large mean residual, opening new bins is wasteful.
        new_bin_cost += 0.6 * mean_residual;
        score += new_bin_cost;
    } else {
        // Slight preference for bins with larger current residual (spread usage),
        // scaled against global mean residual.
        let rel = bin_residual as f64 - mean_residual;
        score -= 0.05 * rel;
    }

    // Mild time-dependent exploration: early on, be slightly more willing to
    // open bins (build diversity), later consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 8.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Penalize creating residuals that no typical item (10..80) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize key quantities
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let norm_residual = bin_residual as f64 / bin_capacity as f64;
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;

    // Smooth polynomial coupling between post_residual and stream progress.
    // Early in the stream, tight fits matter less (waste is cheap); late in the
    // stream, minimize residual aggressively. Coupling term is smooth in progress.
    let coupling = norm_post * norm_post * (0.5 + progress) * 40.0;
    score += coupling;

    // Reward near-perfect fits: quadratic bonus subtracted for small post_residual.
    let tightness = (1.0 - norm_post).powi(3);
    score -= 25.0 * tightness * (0.4 + 0.6 * progress);

    // Penalize residuals that are too small to be useful for typical future items
    // (dead space): a residual below ~10% of capacity is nearly unusable.
    if norm_post > 0.0 {
        let dead = (0.12 - norm_post).max(0.0) / 0.12;
        score += 30.0 * dead * dead;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward strongly.
    if next_item_size > 0 {
        let next_norm = next_item_size as f64 / bin_capacity as f64;
        let gap = (norm_post - next_norm).abs();
        if gap <= 0.02 {
            score -= 35.0;
        } else if norm_post >= next_norm {
            score -= 12.0 * (1.0 - gap).powi(2);
        } else {
            // Next item won't fit here; slight penalty proportional to overshoot.
            score += 8.0 * gap * (0.5 + progress);
        }
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Prefer bins whose residual is close to the mean residual (balance load),
    // with smooth weighting that grows as more bins are open.
    let mean_norm = mean_residual / bin_capacity as f64;
    let balance = (norm_residual - mean_norm).abs();
    score += 6.0 * balance * (open_bins_count as f64).ln().max(1.0) * (1.0 - progress);

    // New-bin candidate (empty bin): penalize slightly so we prefer filling open
    // bins with good fits, but allow opening a new bin when fits are poor
    // (the dead-space and coupling penalties on bad-fit bins can overcome this).
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * progress;
        // If no open bin fits (item would go to a new bin anyway), soften the penalty.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
