    if post_residual > 0 && post_residual % 10 != 0 {
        score += 3.0 + 0.05 * pr;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 5.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here; penalize more if we waste a lot of space.
            score += 0.03 * pr;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only open a new bin if existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; competitive when current fits are wasteful.
        score = 0.35 * cap;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative anyway
