        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin is attractive if the next item is large and would
            // otherwise be stranded.
            if next_item_size > 50 {
                score -= 8.0;
            }
        }
        // Early in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.05 * open_bins_count as f64;

    // Prefer bins whose residual is already below the mean (consolidation).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

