    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            // reward proportionally to how well next item fits
            let fit_ratio = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * fit_ratio;
        } else {
            // next item won't fit here: slight penalty scaled by waste
            let waste = (next_item_size - post_residual) as f64;
            score += 0.05 * waste;
        }
