pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness reward: squared waste penalty, normalized by capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 8.0; // near-perfect fit
    }

    // Lookahead coupling: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0 + 0.5 * (next_item_size as f64);
        } else {
            // Penalize leaving residual that no small follow-up can use.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap.min(60.0);
        }
    }

    // Last chance: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fit_quality = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        // Baseline cost of a fresh bin; becomes cheaper late in stream or when bins are fragmented.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = bin_capacity as f64 * (0.9 + 0.3 * progress)
            - 10.0 * avg_fit_quality
            + 0.2 * fragmentation;
        // Discourage opening new bins when many bins already open and mean residual is large.
        score += 0.5 * open_bins_count as f64;
        if mean_residual > item_size as f64 * 1.5 {
            score += 15.0;
        }
    } else {
        // Favor bins with residual close to mean (balanced usage) mildly.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Slight preference for opening stream with consolidation when few bins open.
    if open_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let is_new_bin = (bin_residual == bin_capacity) as f64;

    // Base: penalize wasted residual, with non-linear (quadratic/cubic) shaping
    let mut score = pr
        + 40.0 * norm_pr * norm_pr * cap
        - 25.0 * norm_pr * norm_pr * norm_pr * cap;

    // Smooth coupling: residual waste matters more late in the stream
    score *= 1.0 + 0.8 * progress * norm_pr;

    // Reward tight fits via smooth saturating term on item_size/capacity
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * (1.0 - norm_pr);

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (pr >= nx) as f64;
        score -= 20.0 * fits_next * (1.0 - (pr - nx).abs() / cap);
        // Penalize post-residual just below next item size (dead space)
        let gap = (nx - pr) / cap;
        score += 25.0 * gap.max(0.0) * (1.0 - gap.max(0.0)) * (pr < nx) as i32 as f64;
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Smooth penalty for opening new bins, stronger early and when many bins open
    score += is_new_bin * (35.0 + 12.0 * (open_bins_count as f64).ln().max(0.0)) * (1.0 - 0.5 * progress);

    // Mild diversity: prefer bins near mean residual (smooth quadratic)
    score += 5.0 * ((pr - mean_residual) / cap).powi(2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
