pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity quarters
    let q = post_residual / (bin_capacity / 4);
    let q_penalty = match q {
        0 => -6.0,   // post residual in (0,25): near-perfect fill
        1 => 0.0,
        2 => 2.0,
        3 => 4.0,
        _ => 6.0,    // nearly empty bin chosen: wasteful
    };
    score += q_penalty;

    // Reward tight fits with fractional coupling
    let fill = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fill * fill;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: penalize leaving residual that cannot host next item
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 4.0 * (next_item_size - post_residual) as f64 / 10.0;
        } else if post_residual >= next_item_size {
            score -= 3.0;
        }
    }

    // Prefer reusing bins when many are open (avoid bin proliferation)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 2.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) * (0.5 + progress);
    } else {
        // New bin candidate: only attractive if current bin would be badly fragmented
        score += 5.0 * mean_residual / bin_capacity as f64;
    }

    // Integer-division threshold on post_residual: dead space under 10 is ideal
    if post_residual < 10 {
        score -= 5.0;
    } else if post_residual / 10 > 6 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
