pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals too small to ever hold
    // another item (1..=9) are pure waste; penalize sharply.
    if post_residual >= 1 && post_residual <= 9 {
        score += 400.0;
    }

    // Residuals that cannot fit the known next item are semi-dead
    // if the next item is real and would otherwise need a new bin.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 120.0;
        // Extra penalty if this is the only fitting bin (last chance):
        // wasting it forces a new bin anyway.
        if fitting_bins_count == 1 {
            score += 150.0;
        }
    }

    // Reward snug fits: small but usable leftover (>= next item) is good.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0 + 0.5 * next_item_size as f64;
    }

    // Open-bin pressure: prefer reusing bins when many are open,
    // to avoid bin proliferation; new-bin candidate (full residual)
    // gets a base cost that grows with open_bins_count.
    if bin_residual == bin_capacity {
        score += 250.0 + 40.0 * open_bins_count as f64;
    } else {
        score -= 15.0 * open_bins_count as f64;
    }

    // Prefer bins whose residual is below the mean (tighter bins first),
    // keeping large-residual bins available for big future items.
    score += 0.8 * ((bin_residual as f64) - mean_residual);

    // Late in the stream, tighten up: discourage opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 200.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin completely.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post residual,
    // this placement sets up a perfect follow-up -> strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how snug the follow-up is.
            let snug = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - snug / bin_capacity as f64);
        } else {
            // Next item will NOT fit in leftover: penalize dead space.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Compare post_residual against mean residual of open bins:
    // leaving a residual below the mean means this bin becomes less reusable
    // than average -> mild penalty; above mean keeps bin useful.
    let cap = bin_capacity as f64;
    let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
    let post_norm = (post_residual as f64) / cap;
    score += 30.0 * (mean_norm - post_norm);

    // Last-chance bin: if this is the only bin that fits the item, strongly
    // prefer using it over opening a new bin (avoid proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a brand-new bin when decent open bins exist,
    // unless the item is large and would leave a tiny residual anyway.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap;
        score += 120.0 - 100.0 * tightness;
        if fitting_bins_count > 0 {
            score += 60.0;
        }
    }

    // Early in the stream, be slightly more conservative about fragmenting bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * (post_residual as f64 / cap);

    // Many open bins: encourage consolidating into existing bins.
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but penalize exact fill less than near-exact
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 12.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // dead space risk relative to next item
        score += 0.1 * (next_item_size as f64 - post_residual as f64).min(40.0);
    }

    // Penalize bins with large residuals when mean residual is low (outlier hoarding)
    score += 0.05 * ((bin_residual as f64) - mean_residual).abs();

    // Prefer filling bins with below-average residual (compact the bin set)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Time horizon: late in stream, be more conservative about leftover space
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * post_residual as f64 * 0.3;

    // New-bin candidate: only prefer opening when no open bin is decent
    if bin_residual == bin_capacity {
        let decent_exists = mean_residual > item_size as f64 + 15.0;
        if decent_exists || (fitting_bins_count > 2 && next_item_size <= mean_residual) {
            score += 30.0; // discourage new bin
        } else {
            score -= 5.0; // encourage new bin when open bins are poor
        }
        // early stream: opening bins is cheap
        score -= (1.0 - progress) * 8.0;
    }

    // Mild penalty for many open bins already (encourage consolidation)
    score += 0.05 * open_bins_count as f64;

    // Small bonus for placing large items into large-residual bins
    score -= 0.05 * item_size as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_frac = item_size as f64 / cap;

    // Base: prefer tight fits (low post_residual), smoothly amplified by progress.
    let mut score = pr * (1.0 + 1.5 * progress * progress);

    // Non-linear penalty on large dead space, cubic in normalized post-residual.
    let dead = pr / cap;
    score += 30.0 * dead * dead * dead * cap * 0.01;

    // Reward exact-ish fits with smooth exponential-like polynomial falloff.
    score -= 12.0 * (1.0 - fit_frac) * (1.0 - fit_frac);

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead coupling: if next item fits in post_residual, reward; else penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr as f64 {
            score -= 8.0 * (1.0 - (nx / cap));
        } else {
            let waste = (nx - pr) / cap;
            score += 10.0 * waste * waste;
        }
    }

    // Mild penalty when bin residual deviates far from mean residual (balance pressure).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: smooth penalty decaying as stream progresses (avoid proliferation early,
    // allow it late when residual fragmentation dominates).
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 6.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: how "reusable" is the leftover?
    // Residuals that are multiples of common item sizes (or large enough) are good.
    let cap_f = bin_capacity as f64;

