    if bin_residual == bin_capacity {
        // Neutral base; add penalty so we prefer decent existing fits,
        // but subtract when many open bins have fragmented residuals.
        score = cap_f * 0.5 + mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative: new bin is fine
        } else if mean_residual > (item_size as f64) * 1.5 {
            score += 150.0; // open bins have plenty of room; don't open new
        } else {
            score -= 60.0;
        }
    }

    // Stream progression: early on, be conservative about fragmenting bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 20 {
        score += (1.0 - progress) * 60.0;
    }

    // Slight penalty for proliferating open bins.
    score += open_bins_count as f64 * 0.5;

    // Tie-break: prefer bins whose residual is close to mean (balanced packing).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.93;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item (1..100 stream => gap < ~10 is nearly dead)
    // are heavily penalized, non-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Gaps in [10, 25) are "awkward" — usable only by tiny items.
    if post_residual >= 10 && post_residual < 25 {
        score += 8.0 * (25.0 - post_residual as f64) / 15.0;
    }

    // Perfect or near-perfect fills are strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward this bin; if next item cannot fit anywhere else well, keep gap usable.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item won't fit here anyway; slight penalty for wasting a big bin
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a tight
    // fit exists; encourage opening new bins early when stream is young.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    // Prefer bins with residual below the mean (consolidating emptier space
    // into fewer bins), i.e. favor filling the fullest bins.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate handling: an empty bin is attractive when the item is
    // large (would leave awkward gaps elsewhere) or when few bins fit the item.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let mut new_bin_score = 15.0
            - 55.0 * large_item
            - 20.0 * (fitting_bins_count as f64).recip().min(1.0)
            + 5.0 * progress;
        // If the item would leave a dead gap in an existing bin, new bin is better.
        if post_residual < 10 && post_residual > 0 {
            new_bin_score -= 20.0;
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64 * 0.5)).max(0.0);
        // Perfect chain: next item exactly fills the bin
        if post_residual == next_item_size {
            score -= 80.0;
        }
        // Post residual too small for next item: dead space risk
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * (post_residual as f64);
        }
    }

    // Penalize small unusable residuals (dead space) nonlinearly.
    if post_residual < 10 {
        score -= 30.0; // tight fit is actually good
    } else if post_residual < 25 {
        score += 10.0; // awkward mid-range gap
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Mild penalty for very full bins early (keep flexibility), strong reward late.
    if bin_residual as f64 > mean_residual * 1.5 && open_bins_count > 1 {
        score += 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: fraction of the bin consumed by placing this item
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    // Reward near-perfect fills strongly
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize large dead space: residual that no plausible item (10..80) can use well
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }
    if post_residual > 80 {
        score += 0.05 * (post_residual as f64 - 80.0); // fine, big space remains
    }
    // Mid dead zone: residual in 10..80 can be filled by some item, mild reward
    score -= 0.10 * post_residual as f64;

    // Lookahead coupling: if the next item fits into this bin's post_residual,
    // strongly reward keeping this bin; otherwise penalize blocking it.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, heavily favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Global state: many open bins -> prefer consolidation into existing bins
    score += 1.5 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual coupling: if this bin is much tighter than average, prefer it
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Late in the stream, squeeze every bin harder
    score -= 20.0 * progress * fill_ratio;

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item fits poorly everywhere else (big item, bad fit).
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = if fitting_bins_count == 0 {
            1.0
        } else {
            (item_size as f64 / bin_capacity as f64).powi(2)
        };
        // Base penalty so new bins are not opened casually
        score += 45.0;
        // Reward new bin when item is large and fits badly in open bins
        score -= 60.0 * poor_fit_elsewhere;
        // Early in stream, allow more exploratory bin openings
        score -= 10.0 * (1.0 - progress);
        // If next item is huge and wouldn't fit residual, a fresh bin helps
        if next_item_size > post_residual.max(1) && next_item_size > 50 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = pr / cap;

    // Base: prefer small post_residual, with smooth non-linear penalty growth
    let mut score = pr * (1.0 + 0.5 * fit_ratio * fit_ratio);

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, dead space matters more (fewer chances to fill it)
    let coupling = fit_ratio * fit_ratio * progress * (1.0 - progress) * 4.0;
    score += 30.0 * coupling * pr / cap;

    // Penalize bins that would leave residual too small for typical future items
    let tiny_waste = (fit_ratio * 20.0 - 1.0).powi(2);
    score += 8.0 * tiny_waste * (0.5 + progress);

    // Lookahead: reward residual that can fit the next item smoothly
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let snug = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 12.0 * snug * snug;
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Mild preference for bins with below-mean residual (tighter packing)
    score += 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate: smooth penalty scaled by how many bins are open and progress
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * (open_bins_count as f64).ln1p() + 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly favored
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residues that are hard to fill later are penalized.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty grows when post_residual falls into "awkward" classes
    // (small but nonzero, and not matching common item sizes).
    let residue_class = post_residual % 10;
    let awkward = match residue_class {
        0 => -0.5,          // multiple of 10: easy to fill
        1..=3 => 1.2,       // tiny slivers: likely dead space
        4..=6 => 0.3,
        _ => -0.2,          // 7..9: can absorb medium items
    };
    score += awkward * (post / cap) * 10.0;

    // Lookahead coupling: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // fraction of post_residual used by next item: reward tight reuse
            let frac = next_item_size as f64 / post.max(1.0);
            score -= 40.0 * frac;
        } else {
            // next item cannot use this bin's leftover: penalize proportionally
            score += 15.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    }

    // Integer-division threshold: post_residual / item_size ratio
    let ratio = post as f64 / item_size.max(1) as f64;
    if ratio < 0.5 {
        score += 10.0; // bin more than half consumed by this item: good, but avoid over-wasting
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        // Prefer new bin only if no tight fit exists elsewhere; base penalty high
        score += 250.0;
        // But if item is large and mean residual is small, new bin is reasonable
        if (item_size as f64) > 0.6 * cap && mean_residual < (item_size as f64) {
            score -= 260.0;
        }
        // Late in stream, avoid proliferation of open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 50.0 * (1.0 - progress) * (open_bins_count as f64 / 20.0);
    }

    // Mild preference for bins below mean residual (balance load)
    score += 0.05 * (mean_residual - post).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (1..=10) are unusable
    // for future items (min size 1, but typical streams leave awkward slivers).
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0 + 2.5 * (11.0 - post_residual as f64);
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving a gap that exactly accommodates the lookahead item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else {
            // Dead space relative to lookahead: penalize proportionally.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open-bin pressure: penalize placements that encourage bin proliferation;
    // when many bins are open, prefer filling existing ones tighter.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // If this bin is much emptier than average, mild penalty (save it for
    // larger future items); if tighter than average, mild reward.
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 60.0 * scarcity;
        // Early in stream, opening bins is cheaper; later, avoid it.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via post_residual (already minimal).

    // Aggressive 2-step lookahead: reward exact match of next item into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect follow-up: chain two items in one bin
        } else if next_item_size <= post_residual {
            // reward proportionally to how well next item fills the remainder
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill_ratio;
            // small dead-space penalty for what remains after the follow-up
            score += 0.15 * (post_residual - next_item_size) as f64;
        } else {
            // next item cannot fit here: penalize leaving large unusable residue
            score += 0.25 * post_residual as f64;
        }
    } else {
        // last item: just minimize waste
        score += 0.0;
    }

    // Compare against mean residual: bins with residual far above mean are
    // attractive targets for large items; penalize picking bins below mean
    // residual (they are already tight).
    let res = bin_residual as f64;
    if res > mean_residual {
        score -= 0.10 * (res - mean_residual);
    } else {
        score += 0.10 * (mean_residual - res);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make empty bins moderately expensive so we only open
    // a new bin when no open bin offers a decent fit (post_residual of an
    // empty bin is large, so lookahead mismatch penalty already applies).
    if bin_residual == bin_capacity {
        score += 15.0;
        // opening a new bin is fine if the next item is large and current
        // open bins are all tight
        if next_item_size >= 50 && mean_residual < next_item_size as f64 {
            score -= 20.0;
        }
    }

    // Slight stream-position adaptation: early on, be a bit more willing to
    // open bins (spread items); late, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
    }

    // Mild penalty proportional to open bin count to discourage bin sprawl.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post_residual), especially exact fills.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Dead-space penalty grows quadratically for small leftover space.
        let pr = post_residual as f64;
        score += (1.0 - pr / bin_capacity as f64) * 20.0;
    }

    // Penalize bins whose residual is much larger than the item (wasteful use of a big bin).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 15.0;

    // Lookahead: reward if next item fits into the post-residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
        } else {
            // Penalize creating residuals too small for typical next items.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are opened only when placements are poor.
        let pressure = if fitting_bins_count == 0 {
            -1.0e6 // must open a bin
        } else {
            // More open bins / high mean residual => prefer packing into existing bins.
            10.0 + open_bins_count as f64 * 2.0 + (mean_residual - item_size as f64).max(0.0) * 0.5
        };
        // Late in the stream, opening bins is less costly (fewer future items to serve).
        let horizon = step_index as f64 / (total_items.max(1) as f64);
        score += pressure * (1.0 - 0.4 * horizon);
    }

    // Mild exploration term coupling global state and progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (mean_residual - post_residual as f64) * 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_norm = pr / cap;

    // Base: reward small post_residual with non-linear polynomial shaping
    let mut score = pr * (1.0 + fit_norm * fit_norm);

    // Smooth stream-progress coupling: late in the stream, dead space matters more
    let late = progress * progress;
    score += late * pr * (1.0 - fit_norm);

    // Penalize large residuals relative to mean residual of open bins (smooth coupling)
    let mr = if mean_residual.is_finite() { mean_residual } else { cap };
    score += 0.3 * (pr - mr).abs() * (0.5 + 0.5 * progress);

    // Lookahead: reward leaving room for the next item (smooth kernel of fit)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let slack = (pr - nx) / cap;
        let kernel = (-slack * slack * 4.0).exp(); // peak when post_residual ~= next item
        score -= 8.0 * kernel;
        // penalize wasting space larger than next item needs
        if pr > nx {
            score += 0.1 * (pr - nx);
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty for spreading across too many open bins
    score += 0.05 * open_bins_count as f64 * fit_norm;

    // New-bin candidate: neutral-ish baseline, only preferred when fit is terrible
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * fit_norm * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by common item
    // granularities (e.g. multiples of 10 or 25) are "usable" dead space.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -60.0 // perfect closure
    } else if pr % 50 == 0 {
        -25.0
    } else if pr % 25 == 0 {
        -15.0
    } else if pr % 10 == 0 {
        -10.0
    } else if pr % 5 == 0 {
        -4.0
    } else {
        6.0 // awkward residue
    };
    score += class_bonus;

    // Lookahead: does the next item fit exactly in the post-residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            score -= 12.0;
        } else {
            score += 8.0; // next item can't use this bin anyway
        }
        // Harmonic coupling: next item shares divisor class with residual
        if next_item_size > 0 && pr % gcd_like(next_item_size, pr) == 0 && pr > 0 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when a decent fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.1 * open_bins_count as f64;
        if post_residual >= 50 {
            score += 10.0; // wasteful to open bin for small usage
        }
    }

    // Prefer tighter bins overall (relative tightness term).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * (mean_residual - post_residual as f64);
    score += 3.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

#[inline]
fn gcd_like(a: u32, b: u32) -> u32 {
    let mut a = a.max(1);
    let mut b = b.max(1);
    while b != 0 {
        let t = a % b;
        a = b;
        b = t;
    }
    a
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical items (below the minimum item size) are pure waste.
    if post_residual < 10 && post_residual > 0 {
        // Unusable sliver: heavily penalize proportionally to how useless it is.
        score += (10 - post_residual) as f64 * 12.0;
    }

    // Semi-dead zone: gaps that only fit very small items are risky.
    if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Reward tight fits: small post_residual relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 8.0;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bins pressure: when many bins are open, prefer consolidating
    // into existing bins (penalize the new-bin candidate).
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits into the post_residual,
    // reward leaving that much space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }
    // Penalize leaving a gap that neither closes the bin nor fits the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 4.0;
    }

    // Mean residual alignment: prefer bins whose residual is near the mean
    // to keep the open-bin pool homogeneous and packable.
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    // Early in the stream, be slightly more willing to open bins to build
    // a diverse residual pool; later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * 20.0;

    // Aggressive 2-step lookahead: reward when next item fits the post residual exactly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            // Perfect chaining: post_residual == next_item_size is ideal.
            let chain_quality = 1.0 - (slack_after_next as f64) / (bin_capacity as f64);
            score -= chain_quality * 35.0;
        } else {
            // Next item cannot follow in this bin; penalize proportionally to overshoot.
            let overshoot = (next_item_size - post_residual) as f64;
            score += overshoot * 0.15;
        }
    } else {
        // Last item: pure tight fit, no lookahead needed.
        score -= 10.0;
    }

    // Relative to mean residual: bins with residual far from mean are either
    // unusually full (good to fill) or unusually empty (save them for big items).
    let dev = (bin_residual as f64) - mean_residual;
    if dev > 0.0 {
        // Bin is emptier than average: mildly discourage using it unless fit is tight.
        score += dev * 0.05;
    } else {
        // Bin is fuller than average: encourage completing it.
        score += dev * 0.08; // dev negative => subtracts
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin offers a good fit. Penalize new bins by default.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: wasted capacity equal to item_size left over.
        score = (bin_capacity - item_size) as f64 + 30.0;
        // If lookahead chains well in a fresh bin (item + next item pair nicely),
        // relax the penalty.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let pair_slack = bin_capacity - item_size - next_item_size;
            score -= (pair_slack as f64).recip() * 60.0;
            if pair_slack == 0 {
                score -= 20.0;
            }
        }
        // Early in stream, opening bins is cheap; late in stream, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Mild penalty for spreading across too many open bins.
    score += (open_bins_count as f64) * 0.02;

    // Small dead-space nonlinearity: residual in the awkward 1..=9 range is bad.
    if post_residual >= 1 && post_residual <= 9 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward tight fits relative to capacity (small dead space fraction).
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - dead_frac) * 20.0;

    // Penalize leaving residuals that no typical item can use (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // tiny unusable sliver
    }

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            score -= 60.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty for wasting large residual
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: make empty bins less attractive unless
    // no open bin fits well or many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
        score += 150.0
            - 80.0 * open_pressure.min(2.0)
            + 100.0 * progress
            - 120.0 * (mean_residual / bin_capacity as f64).min(1.0);
        // If item is large, a fresh bin is more acceptable.
        score -= (item_size as f64 - 50.0).max(0.0);
    }

    // Prefer bins whose residual is close to item size (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.5;

    // Mild penalty for opening many bins relative to stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count as f64 > 2.0 + 20.0 * progress {
        score += 15.0;
    }

    // Global state coupling: if mean residual is high, prefer filling bins
    // with large residuals (consolidation).
    if mean_residual > bin_capacity as f64 * 0.5 {
        score -= 0.3 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post_residual as f64 / bin_capacity as f64;

    // Non-linear coupling: residual squared penalty grows with stream progress
    score += 40.0 * norm_post * norm_post * (0.4 + 0.6 * progress);

    // Reward tight fits (small post_residual) more strongly later in the stream
    let tightness = 1.0 - norm_post;
    score -= 15.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Cubic dead-space term: heavily penalize mid-range residuals that fit nothing
    let mid = norm_post * (1.0 - norm_post);
    score += 12.0 * mid * mid;

    // Lookahead: bonus if next item fits the post residual exactly-ish
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            score += 6.0 * gap / bin_capacity as f64;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Slight penalty for spreading across many bins when mean residual is high
    score += 0.05 * open_bins_count as f64 * mean_residual / bin_capacity as f64 * (1.0 - progress);

    // Mild preference for consolidating into emptier bins early
    score += 3.0 * (mean_residual - post_residual as f64) / bin_capacity as f64 * (1.0 - progress);

    // New-bin candidate: penalize slightly so we only open when genuinely needed,
    // but relax the penalty as the stream progresses
    if bin_residual == bin_capacity {
        score += 8.0 * (1.2 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
