pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) heavily rewarded,
    // "dead zones" penalized via modulo structure.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else {
        // dead space class: post_residual too small for the smallest plausible item
        if post_residual < 10 {
            score += 60.0 * (1.0 - post_residual as f64 / 10.0);
        }
        // modulo classes: residuals divisible by common item sizes are reusable
        let reusable = [2u32, 5, 10, 20, 25, 50];
        for d in reusable {
            if post_residual % d == 0 {
                score -= 12.0 + d as f64 * 0.4;
            }
        }
        // harmonic fraction: how close post_residual is to capacity fractions
        let frac = post_residual as f64 / bin_capacity as f64;
        score -= 30.0 * (std::f64::consts::PI * frac).sin().abs() * frac;
    }

    // Coupling with lookahead item: reward residuals that exactly or nearly fit next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0; // chained perfect fit
        } else if post_residual >= next_item_size {
            score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this residual: penalize proportionally to waste
            score += 15.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Prefer bins with low residual relative to mean (tightest fit first)
    score -= 20.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 150.0 - 80.0 * progress;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score += 40.0; // keep pairing potential in fresh bin only if worth it
        }
    }

    // Mild reward for consolidating when many bins are open
    score -= 2.0 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical future items are wasted.
    // Treat post_residual in (0, 10] as fully dead; scale penalty sharply.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward fits that leave room for the lookahead item if it would fit.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.25 * (post_residual - next_item_size) as f64;
        } else {
            // Penalize blocking the next item's placement.
            score += 8.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Reward bins that are already fairly full (small residual before placement).
    score -= 0.15 * (bin_capacity - bin_residual) as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor tighter bins.
    let pressure = open_bins_count as f64 / (1.0 + open_bins_count as f64);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 20.0;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 35.0 + 25.0 * progress;
        if fitting_bins_count == 0 {
            score -= 50.0; // forced new bin anyway
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin gives room for a big next item
        }
    }

    // Mild preference for bins below mean residual (consolidation).
    if (bin_residual as f64) > mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Perfect-fit bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: reward when next item matches post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 45.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item can't follow here; penalize proportionally to wasted look
            score += 18.0;
        }
    } else {
        // Last item: closing a bin is great
        score -= 20.0;
    }

    // Relative to mean residual: bins with more residual than average are
    // cheaper to fill (their space is less scarce)
    if post_residual as f64 > mean_residual {
        score -= (post_residual as f64 - mean_residual) * 0.6;
    } else {
        score += (mean_residual - post_residual as f64) * 0.6;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin offers a good (near-perfect) fit
    if bin_residual == bin_capacity {
        // default mild penalty; strong fits in open bins will beat this
        score += 15.0;
        // if next item is large, opening fresh may be good
        if next_item_size >= 60 && post_residual as f64 > mean_residual + 20.0 {
            score -= 35.0;
        }
    }

    // Late-stream pressure: consolidate as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: small post_residual is already good, amplify it.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: penalize if the next item cannot use this bin's post-residual.
    if next_item_size > 0 {
        if (next_item_size as u32) > post_residual {
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / 10.0;
        } else {
            // Bonus when next item fits snugly into the resulting residual.
            let gap = post_residual - next_item_size;
            score -= 4.0 * (1.0 - gap as f64 / 50.0).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins with high mean residual: discourage fragmenting further,
    // favor bins with residual far from mean (consolidation).
    if open_bins_count > 0 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 2.0 * dev / 100.0;
    }

    // Time horizon: early in stream, opening new bins is cheaper; late in stream,
    // prefer filling existing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 20.0 * (0.3 + 0.7 * progress);
        // But allow a new bin if current bin would leave large unusable residue
        // relative to next item.
        if next_item_size > post_residual && post_residual < 10 {
            score -= 10.0;
        }
    } else {
        // Existing bin: reward slightly more late in the stream.
        score -= 5.0 * progress * tightness;
    }

    // Waste penalty: dead space below the minimum plausible item size.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let mut score = post_residual as f64 ;
    if post_residual == 0 { score -= 1000.0 ; }
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 600.0 ;
        } else if next_item_size <= post_residual {
            let chain_waste = post_residual - next_item_size ;
            if chain_waste <= 12 { score -= 240.0 - chain_waste as f64 * 1.2 ; }
            else { score -= 200.0 - chain_waste as f64 * 0.8 ; }
        } else {
            let gap = (post_residual as i64 - next_item_size as i64) . max (0) as f64 ;
            score += gap * 0.3 ;
        }
    }
    if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual > 0 { score -= 40.0 ; }
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size && post_residual < next_item_size * 3 {
        score -= 15.0 + (next_item_size * 3 - post_residual) as f64 * 0.5 ;
    }
    if post_residual > 0 && post_residual <= 10 {
        let tightness = 1.0 - (mean_residual / bin_capacity as f64) . min (1.0) ;
        score -= (10 - post_residual) as f64 * (1.0 + tightness * 2.0) ;
    }
    if step_index + 1 >= total_items . saturating_sub (50) && bin_residual != bin_capacity { score -= 20.0 ; }
    if bin_residual == bin_capacity && open_bins_count > 3 { score += 15.0 + open_bins_count as f64 * 0.5 ; }
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6 * (0.5 + progress) ;
    }
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size / 2 {
        score += (next_item_size - post_residual) as f64 * 0.9 * (1.0 - progress) * 20.0 ;
    }
    if next_item_size > 0 && post_residual >= 2 * next_item_size { score -= 10.0 + open_bins_count . min (10) as f64 ; }
    if fitting_bins_count <= 1 && bin_residual != bin_capacity { score -= 25.0 ; }
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 { score -= 30.0 ; }
    // dead-space ratio penalty: residual too small to be reusable
    if post_residual > 0 && next_item_size > 0 {
        let cap = bin_capacity . max (1) as f64 ;
        let dead = (post_residual as f64) / cap ;
        if dead > 0.0 && post_residual < next_item_size {
            score += dead * 90.0 * (0.4 + progress) ;
        }
        let fill = 1.0 - (bin_residual as f64) / cap ;
        if fill > 0.75 && post_residual > 0 { score -= 6.0 + fill * 8.0 ; }
    }
    // leftover-after-next shaping
    if post_residual > 0 && next_item_size > 0 {
        let leftover_after_next = (post_residual as i64 - next_item_size as i64) . max (0) as u32 ;
        if leftover_after_next > 0 && leftover_after_next < next_item_size / 2 {
            score -= (next_item_size / 2 - leftover_after_next) as f64 * 0.8 ;
        }
        if leftover_after_next >= next_item_size && leftover_after_next < 2 * next_item_size { score -= 18.0 ; }
    }
    // two-item exact chain lookahead
    if post_residual > 0 && next_item_size > 0 && item_size <= post_residual {
        let twice_left = (post_residual - item_size) as i64 - next_item_size as i64 ;
        if twice_left == 0 { score -= 35.0 ; }
        else if twice_left > 0 && (twice_left as u32) < item_size / 3 { score -= 22.0 - twice_left as f64 * 0.3 ; }
    }
    // late-stage compaction: prefer filling nearly-full bins harder
    if progress > 0.85 && bin_residual != bin_capacity && post_residual > 0 { score -= 8.0 + progress * 12.0 ; }
    // discourage leaving oversized residuals relative to mean when bins are plentiful
    if post_residual > 0 && (post_residual as f64) > mean_residual * 2.0 && progress > 0.5 && bin_residual != bin_capacity {
        score += 10.0 + progress * 10.0 ;
    }
    // next item won't fit here at all: penalize more when many alternatives exist
    if post_residual > 0 && next_item_size > 0 && post_residual + next_item_size > bin_capacity {
        score += 4.0 + open_bins_count . min (8) as f64 * 0.5 ;
    }
    // multi-use residual bonus scaled by reuse count
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let reuse = post_residual as f64 / next_item_size . max (1) as f64 ;
        if reuse >= 2.0 { score -= 6.0 + (reuse - 2.0) * 4.0 ; }
    }
    if post_residual > 0 && mean_residual > 0.0 && (post_residual as f64) < mean_residual * 0.4 { score -= 10.0 ; }
    // small-residual fine bonus
    if post_residual > 0 && post_residual <= 20 { score -= (20 - post_residual) as f64 * 0.4 ; }
    // new-bin guard: only open a fresh bin when the item really can't pack tightly elsewhere
    if bin_residual == bin_capacity && open_bins_count > 2 && next_item_size > 0 && next_item_size <= bin_capacity / 2 && fitting_bins_count <= 2 {
        score += 25.0 + progress * 10.0 ;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post-residual (dead space), modulated by progress
    let mut score = pr * (1.0 + 1.5 * norm_pr * norm_pr);

    // Smooth non-linear coupling: post-residual value vs stream progress
    // Early stream: tolerate larger residuals (future items may fill them).
    // Late stream: penalize residuals heavily.
    let progress_coupling = 1.0 - 0.8 * progress * progress * (3.0 - 2.0 * progress);
    score *= progress_coupling;

    // Reward tight fits with smooth exponential term
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * tightness;

    // Penalize wasting the residual if the next item can't use it (smooth interaction)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let usable = (ni <= pr) as i32 as f64;
        let gap = ((pr - ni).abs()) / cap;
        score += 6.0 * (1.0 - usable) * (1.0 - gap) * (1.0 - progress);
        score -= 4.0 * usable * (1.0 - gap);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Slight penalty when many bins are open and residual far from mean (fragmentation)
    let dev = (pr - mean_residual).abs() / cap;
    score += 3.0 * dev * dev * (open_bins_count as f64).ln().max(1.0) * 0.2;

    // New-bin candidate: keep it neutral-slightly-high unless residuals are hopeless
    if bin_residual == bin_capacity {
        score = pr + 8.0 - 10.0 * (1.0 - mean_residual / cap) * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let frac = pr as f64 / cap;

    // Reward small post_residual, with harmonic (modular) tiers.
    let tier = pr % 10;
    match tier {
        0 => score -= 25.0,        // perfectly "harmonic" residual
        1 | 2 => score -= 10.0,
        3 | 4 | 5 => score -= 4.0,
        6 | 7 | 8 => score += 6.0, // awkward dead space
        _ => score += 12.0,
    }

    // Penalize residuals that no plausible future item can use well.
    // Items are 1..=100; small leftover slivers are dead space.
    if pr > 0 && pr < 10 {
        score += 30.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let leftover = pr - next_item_size;
            score -= 15.0 - (leftover as f64) * 0.2;
        } else {
            // next item cannot follow here: mild penalty proportional to gap
            score += ((next_item_size - pr) as f64) * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is bad
    // or many bins are open with high mean residual (fragmentation).
    if bin_residual == bin_capacity {
        let bad_fit = frac > 0.5; // large post residual from placing item here
        let fragmentation = mean_residual / cap;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base = 20.0 + open_bins_count as f64 * 1.5;
        if bad_fit {
            score -= 10.0 + fragmentation * 10.0;
        } else {
            score += base - progress * 5.0;
        }
    }

    // Prefer filling bins tighter than the mean residual (reduces spread).
    score += (mean_residual - frac * cap).clamp(-50.0, 50.0) * 0.1;

    // Slight preference for closing bins early in the stream.
    score -= (1.0 - frac) * (step_index as f64 / (total_items.max(1) as f64)) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for even the smallest item are "dead".
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) {
        score += 1000.0;
    }
    // Gap unusable by the next item is partially dead until stream end.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0 + (next_item_size - post_residual) as f64 * 0.5;
        } else {
            // Reward gaps that still fit the lookahead item.
            score -= 2.0;
        }
        // Perfect wrap: lookahead exactly fills the bin after placement.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += (open_bins_count as f64).powf(1.2) * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // this bin would leave a large awkward gap or few bins can fit the item.
    if bin_residual == bin_capacity {
        let spread = (open_bins_count as f64) * (item_size as f64) / (bin_capacity as f64);
        if fitting_bins_count <= 1 {
            score -= 5.0; // no good existing home -> new bin ok
        } else if spread > 8.0 {
            score += 6.0; // many bins open, keep consolidating
        } else {
            score += 3.0; // mild default preference for existing bins
        }
        // Never open a new bin for a tiny item.
        if item_size <= bin_capacity / 4 {
            score += 25.0;
        }
    }

    // Late-stream consolidation: as stream progresses, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize outliers that hoard space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Tightness of fit relative to bin capacity.
    let tightness = (post_residual as f64) / cap;
    score += tightness * 60.0;

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_waste = (post_residual - next_item_size) as f64;
        score -= 120.0 - 0.8 * chain_waste;
        // Bonus if the two items together nearly fill the bin.
        if post_residual - next_item_size <= 10 {
            score -= 100.0;
        }
    } else if next_item_size > 0 {
        // Penalize post_residual that cannot host the next item but is large
        // enough to be tempting dead space relative to mean residual.
        if post_residual as f64 > mean_residual {
            score += 0.5 * (post_residual as f64 - mean_residual);
        }
        // Small post_residual unusable by next item is dead space.
        if post_residual < 10 {
            score += 40.0;
        }
    }

    // Last-chance bin: strong penalty if we would waste it on a poor fit,
    // reward if the fit is good.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual <= 15 {
            score -= 60.0;
        } else {
            score += 30.0;
        }
    }

    // New-bin candidate handling: prefer reusing an open bin with good fit;
    // only allow opening a new bin when current fits are poor.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin.
        score += 150.0;
        // If no existing bin fits well (post_residual large everywhere),
        // opening a new bin becomes attractive.
        if post_residual + item_size as f64 == cap as f64 {
            // exact full-bin fit for a fresh bin is ideal (item == capacity)
            score -= 300.0;
        }
        // As stream progresses, discourage proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 50.0 * progress;
        // Many open bins with high mean residual: reuse them instead.
        if mean_residual > item_size as f64 * 1.5 {
            score += 40.0;
        }
    } else {
        // Reuse reward, stronger when open bins are few.
        score -= 20.0 / (open_bins_count as f64).max(1.0);
    }

    // Mild noise-free coupling: penalize leaving residuals in the "awkward"
    // band that few item sizes can use (11..=19).
    if post_residual >= 11 && post_residual <= 19 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
