pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tightness * tightness * bin_capacity as f64;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize leaving dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable slivers are wasteful
    }

    // Lookahead coupling: reward residual that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.1 * next_item_size as f64;
        } else {
            score += 0.5 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    } else {
        // Last item: just minimize leftover space aggressively.
        score -= 2.0 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: discourage spreading; prefer consolidating into fuller bins.
    let load_factor = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= load_factor * open_bins_count as f64 * 0.3;

    // Compare against mean residual: bins with residual well below mean are "fuller";
    // prefer filling fuller bins, penalize dumping into emptier-than-average bins.
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream, be more willing to open fresh bins
    // (keep flexibility); late in the stream, squeeze existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, increasingly penalized later.
        score += 10.0 * progress + 0.2 * open_bins_count as f64;
        if fitting_bins_count == 1 {
            score += 25.0; // never open a new bin when a last-chance bin exists
        }
    } else {
        score -= 4.0 * progress;
    }

    // Mild non-linear penalty on large post_residual to avoid stranding big gaps.
    let pr = post_residual as f64;
    score += 0.02 * pr * pr * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
