    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Reward tight fits more aggressively as stream progresses
    score -= 45.0 * tightness * tightness * (0.5 + progress);

    // Penalize residuals that are too small to be useful later
    let small = (pr / cap).powi(3);
    score += 30.0 * small * (1.0 - progress);

    // Lookahead: favor leaving room for the next item
    if next_item_size > 0 {
