    // Mild penalty for proliferating bins relative to mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap).powi(2);

    // New-bin candidate: penalize slightly so it is chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * progress;
    }

    score
}

