        };
        // base cost of a fresh bin, discounted by how poorly existing bins fit
        score += 18.0 - desperation.min(15.0);
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 6.0; // big item coming: fresh bin gives room
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
