pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr
        + 40.0 * norm_pr * norm_pr
        + 25.0 * norm_pr * norm_pr * norm_pr;

    // Smooth interaction: post_residual coupled with stream progress
    // Late in stream, residual waste matters more (less time to fill gaps)
    score += 60.0 * norm_pr * progress * (1.0 - progress) * 4.0;

    // Penalize residuals that can't hold typical future items, smoothly
    let next = next_item_size as f64;
    if next > 0.0 {
        let gap = (next - pr).max(0.0) / cap;
        score += 30.0 * gap * gap * (1.0 - progress);
    }

    // Reward near-perfect fits (low post_residual relative to item)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio * fit_ratio;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin mildly, more when
    // good fitting bins exist and stream is progressing
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - progress);
    }

    // Coupling with mean residual: prefer bins deviating from mean
    // (consolidate waste into few bins)
    let dev = (pr as f64 - mean_residual) / cap;
    score += 12.0 * dev * dev * dev * 10.0 * (pr as f64 - mean_residual).signum().min(0.0).abs();

    // Mild reward for keeping open bin count low
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: coarse dead-space classes (integer division)
    let class = post_residual / 10;
    score += match class {
        0 => -30.0,                       // near-perfect fit
        1 => -15.0,                       // small gap, may hold tiny item
        2 => -5.0,
        3 => 0.0,
        4 => 5.0,
        5 => 12.0,                        // half-empty: awkward zone
        6 => 10.0,
        7 => 6.0,
        8 => 3.0,
        _ => 0.0,
    };

    // Modulo arithmetic: post_residual divisible by common item sizes is reusable
    if post_residual > 0 {
        for d in [10u32, 20, 25, 50] {
            if post_residual % d == 0 {
                score -= 8.0;
            }
        }
    } else {
        score -= 40.0; // exact fill
    }

    // Lookahead: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= (next_item_size as f64) * 0.4; // reward chains
        } else {
            score += 6.0; // dead space for the known next item
        }
        // Harmonic pair: next_item_size + post_residual near capacity multiples
        let combo = next_item_size + post_residual;
        if combo >= bin_capacity {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New empty bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let tight = (item_size as f64 / bin_capacity as f64) > 0.6;
        if pressure > 0.0 || (tight && fitting_bins_count <= 1) {
            score = 5.0 - if pressure > 0.0 { 20.0 } else { 0.0 };
        } else {
            score = 200.0 + (open_bins_count as f64) * 2.0; // discourage wasting bins
        }
    }

    // Mild preference to fill bins with larger residuals as stream progresses
    score += mean_residual * 0.05 - (bin_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
