pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is too small to hold even the smallest plausible item.
    let dead_threshold = 10.0f64.min(next_item_size as f64);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Reward tight fits: post_residual near zero is ideal.
    score -= 8.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).exp();

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    score += (open_bins_count as f64).ln().max(0.0) * 2.5;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
        score -= 5.0;
    }
    // Penalize if next item would leave yet another tiny gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next > 0 && (gap_after_next as f64) < 10.0 {
            score += gap_after_next as f64 * 4.0;
        }
    }

    // New-bin candidate: make an empty bin attractive only when open bins have poor fits.
    if bin_residual == bin_capacity {
        // Base neutrality: slight penalty so existing good fits win.
        score += 6.0;
        // If existing bins are fragmented (high mean residual spread / many bins), favor a new bin.
        if (mean_residual / bin_capacity as f64) > 0.6 && open_bins_count > 2 {
            score -= 10.0;
        }
        // Big items (relative to capacity) prefer fresh bins to avoid fragmentation.
        if item_size > bin_capacity / 2 {
            score -= 4.0;
        }
    }

    // Mild stream-progression adaptation: late in the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits into post_residual exactly/well.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_waste = post_residual - next_item_size;
        score -= (post_residual as f64) * 0.6 + (next_waste as f64).max(1.0).recip() * 10.0;
    } else if next_item_size > post_residual {
        // next item cannot follow here: penalize leaving large unusable residue
        score += (post_residual as f64) * 0.3;
    }

    // Prefer bins whose residual is already below mean (tight bins)
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize slightly so we prefer existing bins unless fit is poor
    if bin_residual == bin_capacity {
        score += 30.0 - (mean_residual - post_residual as f64).abs() * 0.5;
    }

    // Early in stream: encourage filling bins fully to reduce bin count
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - post_residual) as f64 * 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is ideal.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Penalize small but unusable post-residuals (dead space).
    if post_residual > 0 {
        let next_fits = next_item_size > 0 && post_residual >= next_item_size;
        if !next_fits {
            score += 8.0 + 0.1 * post_residual as f64;
        } else {
            // Reward leaving space exactly useful for the next item.
            score -= 6.0 * (1.0 - (post_residual as f64 - next_item_size as f64).abs() / bin_capacity as f64);
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Many fitting bins: prefer the one with best utilization.
    if fitting_bins_count > 1 {
        score += 0.02 * (fitting_bins_count as f64 - 1.0) * post_residual as f64;
    }

    // Time horizon: early in stream, encourage filling bins densely;
    // late in stream, prefer reusing existing bins over opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 10.0 + 20.0 * progress;
        // Opening a new bin early is fine when mean residual is high (fragmentation).
        score += 0.05 * open_bins_count as f64;
    } else {
        // Reuse bonus grows with progress.
        score -= 5.0 * progress;
    }

    // Global fragmentation: if mean residual is high, prefer bins below mean residual
    // (consolidate small leftovers) to reduce fragmentation.
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.05 * dev;
    }

    // Lookahead: if next item cannot fit anywhere else, keep space for it.
    if next_item_size > 0 && next_item_size > post_residual && bin_residual >= next_item_size {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
