pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) + norm_pr * (0.5 + 2.0 * progress * (1.0 - progress));

    let mut score = pr + 40.0 * poly;

    // Penalize creating dead space that cannot fit the next item
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 15.0 * (next_item_size as f64 - pr) / cap;
    } else if next_item_size > 0 {
        score -= 5.0 * (1.0 - (pr - next_item_size as f64) / cap);
    }

    // Reward tight fits
    score -= (item_size as f64 / cap) * 10.0;

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: mildly discouraged early, more acceptable late
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) - 5.0 * progress;
    }

    // Coupling with mean residual across open bins
    score += 0.3 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
