pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod common capacity divisors
    let pr = post_residual as u32;
    let residue5 = (pr % 5) as f64;
    let residue10 = (pr % 10) as f64;
    let residue20 = (pr % 20) as f64;
    let residue25 = (pr % 25) as f64;

    // Reward residuals that are "harmonious": small residues mod 10/20/25
    // mean future items of standard sizes (10,20,25,50) can tile the leftover.
    score -= (10.0 - residue10) * 0.35;
    score -= (20.0 - residue20) * 0.15;
    score -= (25.0 - residue25) * 0.20;

    // Penalize awkward dead space: tiny-but-nonzero leftovers (1..9) are waste
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 1.5;
    }
    // Penalize the 11..19 band (too small for min item 10 in general streams)
    if pr >= 11 && pr <= 19 {
        score += 4.0;
    }
    if pr >= 21 && pr <= 24 {
        score += 2.5;
    }

    // Exact-fit bonus: harmonic tiling zero-waste
    if pr == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: does next_item_size harmonically divide post_residual?
    if next_item_size > 0 && next_item_size <= pr {
        let next = next_item_size as f64;
        let after_next = pr as f64 - next;
        // Reward if next item leaves a harmonic residue
        let nr = (pr % next.max(1)) as f64;
        score -= 6.0;
        score -= (next / cap) * 8.0;
        if (after_next as u32) % 10 == 0 {
            score -= 5.0;
        }
        if nr == 0.0 {
            score -= 4.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this bin's leftover: mild penalty for hoarding space
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate logic: only attractive when current bins are crowded
    // or residual spread is poor.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64).ln().max(0.0);
        let spread = (mean_residual - post_residual as f64).abs();
        // Default: opening new bin is slightly worse than a decent fit
        score += 8.0;
        // But if mean residual is low (bins nearly full), new bin is fine
        score -= (cap - mean_residual).max(0.0) * 0.08;
        score -= crowding * 1.2;
        // If item is large and would leave bad residue in any bin, prefer fresh bin
        let item_frac = item_size as f64 / cap;
        if item_frac > 0.5 {
            score -= item_frac * 6.0;
        }
        let _ = spread;
    }

    // Fractional residual term: prefer filling bins to high fraction
    let used_frac = 1.0 - (post_residual as f64 / cap);
    score -= used_frac * 3.0;

    // Progress-based adaptation: later in stream, be more conservative with
    // opening bins (tighter packing preferred).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    // Small harmonic tie-breaker on item size class
    let item_class = item_size % 10;
    score -= (item_class as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // accept future items (min item size 1, but practically < ~10) are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual == 0 {
        // Perfect fit is ideal: reward strongly.
        score -= 40.0;
    } else {
        // Usable residual: mildly prefer leaving room for the lookahead item.
        score -= 5.0;
    }

    // Reward residuals that exactly accommodate the next item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            // Would leave dead space after next item lands — mild penalty.
            score += 10.0;
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading items
    // into fresh-ish bins; keep filling existing ones.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only fitting bin, heavily penalize
    // rejecting it (opening a new bin costs a whole bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or
    // item is huge relative to residuals. Baseline cost of a new bin.
    if bin_residual == bin_capacity {
        score += 70.0;
        // If item nearly fills a fresh bin, opening is actually good.
        if item_size as f64 >= 0.8 * bin_capacity as f64 {
            score -= 60.0;
        }
        // With few open bins and large mean residual elsewhere, opening
        // early is wasteful.
        if open_bins_count > 0 && mean_residual > item_size as f64 {
            score += 25.0;
        }
    }

    // Prefer tight fits overall: closeness of item to residual.
    let tightness = 1.0 - (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= tightness * 10.0;

    // Late in the stream, consolidate: penalize leaving large residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 30 {
        score += progress * (post_residual as f64 - 30.0) * 0.5;
    }

    score
}

