        // Last item: never open a new bin if anything fits.
        if next_item_size == 0 {
            new_bin_penalty += 15.0;
        }
        score += new_bin_penalty.max(0.0);
    }

    // Mild preference for bins that are already relatively full (below-mean residual),
    // preserving large empty bins for future large items.
    score += (bin_residual as f64 - mean_residual) * 0.04;

    // Slight preference for keeping the number of open bins low early on.
    score += (open_bins_count as f64).sqrt() * 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with a smooth non-linear penalty
    // on very small residuals (dead space) that tightens as the stream progresses.
    let dead_space_penalty = norm_pr * norm_pr * (1.0 + 3.0 * progress);

    // Smooth coupling: residual fill ratio (how much of the bin's original
    // space this placement consumes) rewards tight fits non-linearly.
    let fill = (bin_residual as f64 / cap).max(0.0);
    let fill_reward = -2.0 * fill * fill * (1.0 - norm_pr);

    // Perfect fit bonus (smooth, near-zero residual strongly rewarded).
    let perfect = -(1.0 - norm_pr.min(1.0)).powi(6) * 4.0;

    // Lookahead: reward leaving room exactly for the next item (smooth kernel).
    let ni = next_item_size as f64;
    let lookahead = if ni > 0.0 {
        let d = (pr - ni).abs();
        -3.0 * (-d * d / 25.0) * (1.0 + progress)
    } else {
        0.0
    };

    // Last-chance bin: penalize opening new bins when this is the only fit.
    let last_chance = if fitting_bins_count <= 1 { -5.0 } else { 0.0 };

    // Fragmentation pressure: if bin residual is far below mean residual,
    // this bin is a straggler; encourage closing it out (smooth term).
    let frag = ((mean_residual - bin_residual as f64) / cap).max(0.0);
    let straggler = -1.5 * frag * frag * (0.5 + progress);

    // Mild penalty for spreading across many bins early on.
    let spread = 0.01 * open_bins_count as f64 * (1.0 - progress);

    let mut score = pr + dead_space_penalty + fill_reward + perfect + lookahead + last_chance + straggler + spread;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual relative to capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = (post_residual % (bin_capacity / 4)) as f64;
    let eighth = (post_residual % (bin_capacity / 8)) as f64;

    // Reward near-perfect fits: post_residual landing on fine harmonic classes
    if post_residual == 0 {
        score -= 200.0; // exact fill
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if quarter == 0.0 {
        score -= 40.0; // residual is a multiple of 25 -> reusable
    } else if eighth == 0.0 {
        score -= 20.0;
    } else if post_residual < 10 {
        score += 60.0; // tiny dead space, unusable
    }

    // Lookahead coupling: if next item cannot use the residual, penalize
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual > 0 && (next_item_size as u32) > post_residual {
            // dead residual unless next item is small enough to be split across bins
            score += 30.0 + 0.5 * pr;
        } else if next_item_size as u32 == post_residual {
            score -= 150.0; // perfect chain into next item
        } else if n <= pr {
            // next item fits here later; reward leaving harmonic room
            let gap = pr - n;
            if gap <= 5.0 {
                score -= 80.0;
            } else {
                score -= 20.0 * (1.0 - gap / cap);
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate: make it attractive only when current bin would leave bad residue
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 8.0;
        score = 100.0 + pressure - (mean_residual / cap) * 50.0;
        if post_residual == 0 { score -= 200.0; }
    }

    // Late-stream tightening: waste hurts more as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * 0.3 * progress;

    // Mild preference for balancing residuals against mean
    score += (pr - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be useful
    // are punished disproportionately (they are wasted capacity).
    let dead_threshold = 12.0; // smallest likely future item
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Non-linear coupling: penalize leaving a gap that neither fits the lookahead
    // item nor is large enough to be broadly reusable.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 + 0.5 * gap;
        } else if post_residual >= next_item_size {
            // Reward leaving room exactly for the next item (chained packing).
            score -= 6.0 * (1.0 - ((post_residual - next_item_size) as f64) / bin_capacity as f64);
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few bins,
    // opening a new one (empty candidate) is relatively cheaper.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; cheaper early, expensive late.
        score += 15.0 + pressure;
        // If the current item nearly fills a fresh bin, opening is attractive.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 20.0;
        }
    } else {
        // Filling an existing bin reduces mean residual imbalance: reward closeness
        // of post_residual to zero relative to mean residual.
        score -= 4.0 * (1.0 - (post_residual as f64 / bin_residual.max(1) as f64));
        // Slight penalty if bin is far below mean residual (fragmenting behavior).
        if (post_residual as f64) > mean_residual + 30.0 {
            score += 5.0;
        }
    }

    // Mild overall tightness reward: tighter fits always rank better.
    score += 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with non-linear sharpening
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Reward near-perfect fills
    if post_residual <= 2 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Aggressive 2-step lookahead: reward if next item matches the post residual
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 45.0; // perfect chain: item + next item fills bin exactly
        } else if post_residual >= next_item_size {
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leaving dead space
            score += 10.0 + 0.5 * (post_residual as f64 - (post_residual as f64 % 10.0)) * 0.0;
            score += 0.3 * post_residual as f64;
        }
    }

    // Compare against mean residual: prefer bins with less residual than average
    // (fills fuller bins first, leaving roomier bins for big items)
    score += 0.4 * (mean_residual - post_residual as f64).max(-50.0).min(50.0) * -1.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when current bin fit is bad
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > 40.0 && next_item_size > 0 && (post_residual as u32) < next_item_size;
        if bad_fit || fitting_bins_count == 0 {
            score -= 25.0;
        } else {
            score += 20.0 + 0.2 * open_bins_count as f64; // discourage opening new bins when a decent fit exists
        }
    }

    // Late in stream: consolidate aggressively, avoid spreading residual
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.2 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
