    let frac_used = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * frac_used * frac_used;

    // Lookahead: if the next item fits exactly into the post residual, big bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        let perfect = (post_residual == next_item_size) as f64;
        score -= 8.0 + 6.0 * perfect;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space that the next item cannot use: penalize proportionally.
        score += 3.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0;
    }

    // Penalize spreading across many open bins slightly; reward consolidation.
    score += 0.15 * open_bins_count as f64;

    // Bin whose residual is far from mean residual: mild penalty (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: late in the stream, avoid opening new bins even harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when no open bin fits well
        // (fitting_bins_count == 0 means only the new bin can hold the item).
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        } else {
            score += 20.0 + 25.0 * progress; // discourage opening new bins
        }
    } else {
        score -= 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Coupling of post_residual with stream progress: late in the stream,
    // dead space matters more, so amplify residuals super-linearly.
    let late = progress * progress;
    score += late * 12.0 * norm_pr * (1.0 - norm_pr);

    // Reward near-perfect fits smoothly (post_residual close to 0)
    score -= 6.0 * (-pr / 8.0).exp() * (1.0 + progress);

    // Lookahead coupling: if next item fits in post_residual, reward;
    // otherwise penalize proportionally to how far off it is.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 4.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 2.0 * ((nx - pr) / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - norm_pr);
    }

    // Many open bins with high mean residual: discourage spreading,
    // favor bins whose residual deviates below the mean (tight bins).
    if open_bins_count > 0 {
        let dev = (mean_residual - bin_residual as f64) / cap;
        score -= 3.0 * dev * (1.0 + progress);
        score += 0.05 * open_bins_count as f64 * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: quantize post_residual into capacity fractions (C/8 buckets)
    let bucket = (post_residual * 8) as f64 / cap;
    score += 15.0 * (bucket - bucket.floor());

    // Penalize small dead space that nothing (min size 1..10) can reuse
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward post_residual that is a harmonic multiple of common sizes
    for s in [10u32, 20, 25, 50] {
        if post_residual % s == 0 && post_residual > 0 {
            score -= 12.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, strong bonus
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0;
        if post_residual % next_item_size == 0 {
            score -= 20.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 10.0;
    }

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 25.0 + 0.3 * mean_residual;
        if post_residual > 50 {
            score += 10.0;
        }
    }

    // Prefer bins with residual already below mean (denser bins first)
    score += 0.2 * ((bin_residual as f64) - mean_residual).max(0.0);

    // Early stream: slightly prefer consolidation into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64 / 50.0).min(1.0);

    // Integer division threshold: reward leaving residual in reusable class
    if post_residual / 10 >= item_size / 10 && post_residual >= 10 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
