        score -= 5.0;
    }

    // --- Contextual modulation via mean residual ---
    // If this bin's residual is far below the mean, it is already "cramped";
    // filling it further is good (harvests nearly-full bins).
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f) * 0.15;
    } else {
        score += (resid_f - mean_residual) * 0.10;
    }

    // --- Last-chance bonus: only this bin can fit the item ---
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins would leave
