        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_fit = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
        // Default: new bin is worse than reusing (add a fixed opening cost).
        score += 30.0;
        // But under pressure (no fitting bin) or terrible fits elsewhere,
