        score -= 35.0 * pressure + 20.0 * poor_fit;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    // Slight preference to spread load when many bins are open but mostly full.
    if open_bins_count > 0 {
        score += mean_residual / (open_bins_count as f64) * 0.05;
    }

    score
}

