        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // If many bins can already fit, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            score += 25.0 * (fitting_bins_count as f64 - 1.0);
        }
        // If the only fitting bin would leave a very awkward sliver, new bin is fine.
        if fitting_bins_count == 1 {
            let sliver = (bin_residual - item_size) as f64;
            if sliver < 10.0 {
                score -= 35.0;
            }
        }
    }

    // Prefer bins whose residual is below the mean (consolidate fullness).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    // Mild penalty proportional to number of open bins to discourage bin sprawl.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let item_frac = item_size as f64 / cap;
    let next_frac = next_item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = pr_norm * pr_norm * (1.0 - progress) + pr_norm * progress * (1.0 - pr_norm);
    score += 12.0 * poly;

    // Reward tight fits more strongly as the stream progresses (smooth coupling).
    score -= 6.0 * item_frac * item_frac * (0.5 + progress);

    // Lookahead: reward post_residual that exactly matches the next item.
    let match_term = (pr - next_frac).abs() / cap;
    score -= 4.0 * (1.0 - match_term) * next_frac * (1.0 - next_frac);

    // Penalize dead space when few bins can fit the item (last-chance pressure).
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 - pr_norm) * (1.0 - progress);
    }

    // Mild penalty for residual far below the mean (fragmentation signal).
    score += 0.05 * (mean_residual - pr).abs();

    // Encourage consolidation when many bins are open.
    score += 0.02 * open_bins_count as f64 * pr_norm * (1.0 - pr_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
