pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover lands in
    // "useful" residue classes (multiples of common item sizes) are favored.
    let post = post_residual;
    if post > 0 {
        let class = post % 10;
        // residues 0 (exact fill) are perfect; residues near common sizes (10..80 mod 10)
        // pair well with future items; odd residues are dead space.
        let penalty = match class {
            0 => -12.0,
            5 => 4.0,
            2 | 8 => -3.0,
            4 | 6 => -1.0,
            1 | 3 | 7 | 9 => 6.0,
            _ => 0.0,
        };
        score += penalty;
    }

    // Perfect fit: huge reward.
    if post == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to capacity fractions.
    let fill = item_size as f64 / cap;
    if fill > 0.75 {
        score -= 10.0 * (fill - 0.75);
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post {
        // next item fits, but how harmonically?
        let nx_class = post % next_item_size.max(1);
        if nx_class == 0 {
            score -= 8.0;
        }
        score += 0.05 * (post - next_item_size) as f64;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity as u32 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity as u32 {
        let crowd = mean_residual / cap; // high crowd => open bins nearly full
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_penalty = 55.0;
        // If mean residual is small (bins nearly packed), opening a fresh bin is fine.
        new_penalty -= 60.0 * (1.0 - crowd).min(0.9);
        // Slightly cheaper to open bins late in the stream.
        new_penalty -= 10.0 * progress;
        // If nothing fits except new bin (fitting_bins_count==0), encourage it.
        if fitting_bins_count == 0 {
            new_penalty -= 80.0;
        }
        score += new_penalty.max(-70.0);
    }

    // Mild penalty for wasting large residuals on small items (bad harmonic pairing).
    if post > 60 && item_size < 30 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item are "dead" — penalize them heavily.
    let dead_threshold = 10u32.min(bin_capacity / 10);
    if post_residual < dead_threshold {
        score += 25.0 + (dead_threshold - post_residual) as f64 * 2.0;
    } else {
        // Softly prefer tight fits (low post_residual) with a quadratic term.
        let r = post_residual as f64;
        score += 0.05 * r * r / bin_capacity as f64;
    }

    // Reward near-perfect fills.
    if post_residual <= 2 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here after placement; slight penalty if this
        // wastes the bin's remaining usefulness.
        score += 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate score: baseline slightly above typical residuals.
        score = bin_capacity as f64 * 0.9 + open_bins_count as f64 * 3.0;
        // Allow new bin when existing bins are very fragmented.
        if mean_residual < 15.0 && open_bins_count > 2 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // new bin pairs well with upcoming larger items
        }
    } else {
        // Mild preference to spread load when few bins are open.
        score -= (open_bins_count.max(1) as f64).ln() * 1.5;
        // Penalize leaving residual far from mean (imbalance).
        score += 0.15 * ((post_residual as f64) - mean_residual).abs();
    }

    // Slight late-stream conservatism: tighten packing as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect / tight fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small unusable leftovers (dead space).
        if post_residual < 10 {
            score += 40.0;
        } else {
            score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact match for the next item is excellent.
            if post_residual == next_item_size {
                score -= 300.0;
            } else {
                let slack = (post_residual - next_item_size) as f64;
                score -= 120.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // Next item won't fit here; penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 60.0 * (gap / 100.0);
        }
    }

    // Prefer bins with residual below the mean (consolidate emptiness elsewhere).
    let dev = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 30.0 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when current bins are crowded
    // (high mean residual relative to item size).
    if bin_residual == bin_capacity {
        let crowdedness = mean_residual / bin_capacity as f64;
        score = bin_capacity as f64 - 150.0 * crowdedness;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 50.0;
        }
    }

    // Late in the stream: be slightly more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 80.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already the base; amplify near-perfect fits.
    if post_residual < 5 {
        score -= 40.0;
    } else if post_residual < 12 {
        score -= 18.0;
    }

    // Penalize creating dead space that no plausible item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits exactly into the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let waste_after_pair = post_residual - next_item_size;
            score -= 20.0 - waste_after_pair as f64 * 0.5;
        } else {
            // Next item cannot follow here; slight penalty proportional to overshoot.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin should only win when existing fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as the stream progresses
        // (early on, keeping bins open matters less; later, consolidation matters).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 70.0 + 40.0 * (1.0 - progress);
        // If many bins are open and mean residual is large, opening new bins is cheaper
        // relative to leaving fragments scattered.
        score -= (open_bins_count as f64).ln().max(0.0) * 4.0;
        if mean_residual > 40.0 {
            score += 15.0; // plenty of room exists elsewhere; avoid proliferation
        }
        // If next item is large, a fresh bin is attractive.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Global state coupling: prefer filling bins whose residual deviates below the mean
    // (concentrate waste in few bins rather than spreading it).
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.3;
    } else {
        score += (residual_f - mean_residual) * 0.2;
    }

    // Mild preference to keep the number of open bins from exploding.
    score += open_bins_count as f64 * 0.5;

    // Encourage placing into bins with moderate residual over nearly-full or nearly-empty ones
    // when residuals are comparable.
    if bin_residual >= 50 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling: post_residual^2 scaled by progress-dependent weight
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let progress_weight = 0.5 + 1.5 * progress;
    score += progress_weight * pr_norm * pr_norm * cap * 0.5;

    // Penalize new-bin candidate smoothly, more so early in the stream
    let is_new_bin = (bin_residual == bin_capacity) as f64;
    let new_bin_penalty = 20.0 + 60.0 * (1.0 - progress) + 2.0 * (open_bins_count as f64);
    score += is_new_bin * new_bin_penalty;

    // Reward tight fits: subtract a smooth function of item_size / residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio * fill_ratio;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward; else penalize
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 8.0 * (1.0 - nxt / cap);
        } else {
            score += 6.0 * (pr_norm * (nxt / cap));
        }
    }

    // Mild penalty for deviating from mean residual (avoid residual fragmentation)
    score += 0.1 * (pr - mean_residual).abs();

    // Small smooth progress tilt to prefer opening bins late
    score += 5.0 * progress * (1.0 - fill_ratio.min(1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
