pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: quarter-capacity bands via integer division
    let item_class = item_size / (bin_capacity / 4 + 1); // 0..3
    let post_class = post_residual / (bin_capacity / 8 + 1); // 0..12

    // Reward tight fits: dead space below a quarter-capacity is highly reusable
    if post_residual <= bin_capacity / 4 {
        score -= 12.0 + (bin_capacity / 4 - post_residual) as f64 * 0.5;
    } else if post_residual <= bin_capacity / 2 {
        score -= 4.0;
    } else {
        // large leftover: penalize unless bin was nearly empty
        score += (post_residual as f64 - cap * 0.5) * 0.3;
    }

    // Dead space that no plausible item (min size 1, typical mid) can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: does post_residual fit the next item exactly-ish?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 10.0 - slack.min(20) as f64 * 0.4; // perfect chain reward
            // harmonic class match bonus
            let next_class = next_item_size / (bin_capacity / 4 + 1);
            if next_class == item_class {
                score -= 3.0;
            }
        } else {
            // next item won't fit here; mild penalty scaled by how much it misses
            score += ((next_item_size - post_residual) as f64) * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many fitting bins: prefer the tightest (score already grows with post_residual)

    // New-bin candidate handling: opening a bin is only attractive when
    // no open bin offers a decent fit and item is large
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let good_alternative = mean_residual > item_size as f64 * 1.6 && fitting_bins_count > 0;
        if good_alternative {
            score += 20.0; // keep using open bins
        } else {
            // opening a fresh bin for a large item is fine
            score -= 8.0 * item_class as f64 - 4.0 * progress;
        }
    }

    // Modulo-flavored tiebreak: prefer residuals in friendly harmonic classes
    // (residuals divisible into halves/quarters of capacity pack well)
    if bin_capacity % 4 == 0 {
        let r = post_residual % (bin_capacity / 4);
        if r == 0 && post_residual > 0 {
            score -= 2.0;
        } else {
            score += r as f64 * 0.05;
        }
    }

    // Slight pressure against bin sprawl
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item are pure waste.
    // Minimum plausible item size is 1; but small gaps (<= 10) are highly likely dead.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 11.0); // tiny gaps penalized hardest
    } else if post_residual == 0 {
        // Perfect fill is ideal — strong reward.
        score -= 100.0;
    }

    // Reward tight fits: fraction of bin used by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
