            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / 50.0);
        } else {
            // Next item won't fit here: post residual may become dead space.
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins;
    // few open bins -> opening a new bin is less costly.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins are already open.
        score += 20.0 + 12.0 * pressure;
        // But if item is large, a fresh bin guarantees a good fit.
        score -= 10.0 * fill_ratio;
    } else {
