    // Mild preference for bins with residual close to item (best-fit core).
    let gap = (bin_residual - item_size) as f64;
    score += 0.05 * gap;

    // Slight late-stream tightening: keep scores stable but favor consolidation near end.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - gap / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
