    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: bins with large fill (small post_residual) are preferred;
    // amplify the reward as the item fills a larger fraction of the bin.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 20.0;

    // Dead-space penalty: residuals that are too small to hold even the
    // smallest plausible item are wasted; penalize super-fragmented leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only open bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate detection and penalty.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 35.0;
        // Opening a new bin is more attractive if the leftover would still
        // accommodate the next item (a good "foundation" bin).
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        }
        // Late in the stream, avoid opening bins aggressively; early on,
        // be more willing to spread out.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 15.0;
    }

    // Lookahead coupling: penalize placements that leave a residual which
    // cannot host the next item (blocking), reward those that can.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 6.0;
        } else {
            score -= 4.0;
        }
    }

    // Global pressure: when many bins are open with high mean residual,
    // encourage consolidation into existing bins rather than new ones.
    if !is_new_bin {
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 5.0;
    }

    // Mild penalty proportional to number of open bins to discourage sprawl
    // when alternatives exist.
    if !is_new_bin {
        score -= 0.0; // neutral; sprawl handled via new-bin penalty above
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.99;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Non-linear polynomial coupling of post residual with stream progress.
    let poly = x * x * (1.0 - x) * (1.0 + 2.0 * t) + x * (1.0 - x) * (1.0 - x) * (1.0 + t * t);
    score += 8.0 * poly;

    // Late-stream: penalize residual that cannot fit the lookahead item.
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 6.0 * (1.0 - t) * (1.0 + x);
    }
    // Reward when post residual exactly accommodates the next item.
    if next_item_size > 0 && post_residual as u32 == next_item_size {
        score -= 10.0 * (1.0 - t);
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 - t * 0.5);
    }

    // Penalize leaving many open bins with fragmented residuals early on.
    let frag = (mean_residual - pr).abs() / cap;
    score += 3.0 * frag * frag * (1.0 + t);

    // Slight preference for tight fits as stream progresses.
    score -= 4.0 * t * (1.0 - x);

    // New-bin candidate: keep it competitive only when it truly wastes less.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - x) * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify dead space by capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = cap / 4.0;
    let half = cap / 2.0;

    if pr < quarter {
        // Small residual: mostly dead space, mild penalty scaled by how dead
        score += 0.5 * (quarter - pr) / quarter;
    } else if pr < half {
        // Mid-low residual: usable for small items, small reward
        score -= 1.0;
        // Penalize if next item cannot use it
        if (next_item_size as f64) > pr {
            score += 3.0;
        }
    } else {
        // Large residual: keep bins flexible, reward
        score -= 2.0;
    }

    // Integer division thresholds on post_residual (harmonic classes of cap/8)
    let eighth = (bin_capacity / 8).max(1);
    let class = post_residual / eighth;
    match class {
        0 => score += 2.0,                    // tiny scraps
        1 => score -= 0.5,
        2 => score -= 1.0,
        3 => score -= 0.5,
        _ => score -= 1.5,                    // big residuals stay attractive
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 50.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fits
        score += fitting_bins_count as f64 * 0.2;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        score = cap * 0.5 - pressure * cap * 0.4;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // big lookahead favors fresh bin
        }
    }

    // Stream progression: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - pr).abs() * 0.1;

    // Mild penalty for spreading across many bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.88;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0, 10) are unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Near-perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // leftover too small for next item: penalize proportionally
        score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    if bin_residual == bin_capacity {
        score += 25.0 + 6.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins tighter than the mean residual (good fill density).
    score += 0.5 * (mean_residual - post_residual as f64);

    // Early stream: mild preference to consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    score
}
